-- ----------------------------------------------------------------------------
-- 0. The attempts and certifications that stand as issued.
-- ----------------------------------------------------------------------------
do $$
declare
  r record;
begin
  for r in
    select app_slug, tier, count(*) as n, string_agg(id::text, ', ' order by created_at) as ids
      from public.academy_capstone_attempts
     where (app_slug, tier) in (('cashflow', 'advanced'), ('fiscal', 'beginner'))
     group by 1, 2
  loop
    raise notice 'ec7 pia recut: % attempt(s) on %/% stand as graded (stored scores are not re-scored): %', r.n, r.app_slug, r.tier, r.ids;
  end loop;
  perform set_config('ec7.snapshot', md5(coalesce((select string_agg(md5(a::text), ',' order by a.id) from public.academy_capstone_attempts a where a.app_slug in ('cashflow', 'fiscal')), '') || '#' || coalesce((select string_agg(md5(c::text), ',' order by md5(c::text)) from public.academy_certifications c where c.app_slug in ('cashflow', 'fiscal')), '')), false);
end $$;

-- ----------------------------------------------------------------------------
