do $$
declare
  r         record;
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_done    integer := 0;
begin
  for r in
    select * from (values
      ('beginner', 'final', null::text, 3, 'A capex row carries both amount_usd and cost_usd. Under what condition does the engine refuse the file?', '["Only when the two hold different values; equal values are taken once, not doubled.", "Always, because a row may carry exactly one cost column and the engine will not pick between two preferred aliases.", "Never, because both are preferred aliases and the engine sums every column ending in _usd in that case.", "Only when one of them is prefixed total_, which the fallback excludes from its sum."]'::jsonb, 0, 'ambiguous_cost_aliases says which: different values, refused; the same value, accepted once, and the year''s capex is the value, not twice it.'::text, 'A capex row carries both amount_usd and cost_usd. Under what condition does the engine refuse the file?', '["Only when the two hold different values; equal values are taken once.", "Always, because a row may carry exactly one cost column and the engine will not pick between two preferred aliases.", "Never, because both are preferred aliases and the engine sums every column ending in _usd in that case.", "Only when one of them is prefixed total_, which the fallback excludes from its sum."]'::jsonb, 0, 'ambiguous_cost_aliases says which: different values, refused; the same value, accepted once, and the year''s capex is the value, counted once.'::text),
      ('beginner', 'final', null::text, 7, 'fiscal_regime picks one of three cascades from gross revenue to net cash flow. Which description is the JV cascade?', '["Cost recovered from a capped share of revenue and the remainder split, which is why psc_carryforward pays 27000000.00 of tax on 200000000.00 of revenue and nets -1000000.00.", "Five taxes on three bases, which on the published worked example collect 604809283.90 out of 1460000000.00 of revenue.", "One tax on gross revenue with no deductions, which is what the loss columns reading 0.00 on every row implies.", "Royalty, then deductions, then a single tax rate: 20000000.00 of royalty and 32500000.00 of tax out of 100000000.00 in 2030."]'::jsonb, 3, 'Every regime reports the same KPI set; what differs is the cascade between the one gross revenue and the net, and the JV is the flat one.'::text, 'fiscal_regime picks one of three cascades from gross revenue to net cash flow. Which description is the JV cascade?', '["Cost recovered from a capped share of revenue and the remainder split, which is why psc_carryforward pays 27000000.00 of tax on 200000000.00 of revenue and nets -1000000.00.", "Five taxes on three bases, which on the published worked example collect 617004738.36 out of 1460000000.00 of revenue.", "One tax on gross revenue with no deductions, which is what the loss columns reading 0.00 on every row implies.", "Royalty, then deductions, then a single tax rate: 20000000.00 of royalty and 32500000.00 of tax out of 100000000.00 in 2030."]'::jsonb, 3, 'Every regime reports the same KPI set; what differs is the cascade between the one gross revenue and the net, and the JV is the flat one.'::text),
      ('beginner', 'final', null::text, 19, 'With no deck, a flat 80 and the escalator typed as 0, what does the resolver return for the years 2028 through 2035 around a 2030 base year?', '["80.000000 from the base year onward and de-escalated values before it, since the base year is still the anchor for the years behind it.", "80.000000 from 2030 onward and the inflation rate applied before it, because a typed zero only switches off the forward escalation.", "Nothing, because an escalator of 0 is read as unset and falls back to the inflation rate.", "80.000000 in every year, before the base year as well as after it."]'::jsonb, 3, 'Zero means flat; it is a blank, not a zero, that falls back to inflation, and the same call with the escalator at 10 returns 72.727273 for 2029.'::text, 'With no deck, a flat 80 and the escalator typed as 0, what does the resolver return for the years 2028 through 2035 around a 2030 base year?', '["80.000000 from the base year onward and de-escalated values before it, since the base year is still the anchor for the years behind it.", "80.000000 from 2030 onward and the inflation rate applied before it, because a typed zero only switches off the forward escalation.", "Nothing, because an escalator of 0 is read as unset and falls back to the inflation rate.", "80.000000 in every year, before the base year as well as after it."]'::jsonb, 3, 'Zero means flat; only a blank escalator falls back to inflation, and the same call with the escalator at 10 returns 72.727273 for 2029.'::text),
      ('beginner', 'final', null::text, 31, 'The hand-derived case at a 25 percent working interest prints year 1 royalty 5000000.00 USD, tax 8125000.00 and net -3125000.00, each a quarter of the 100 percent figures. What does the same run report as its take?', '["95.1923 percent, because the partner''s scaled net is set against the field''s unscaled pre-take value.", "80.7692 percent, the same as at 100 percent, because the interest scales the government''s lines and the contractor''s together.", "A quarter of 80.7692 percent, since take is a money reading and every money reading scales with the interest.", "Null, because the engine declines a take on any run below a 100 percent interest."]'::jsonb, 1, 'NPV falls from 21590909.09 to 5397727.27 USD with the share while take does not move; until the 2026-09-15 repair the JV ledger kept revenue and costs at field level and the same run printed 95.1923 percent.'::text, 'The hand-derived case at a 25 percent working interest prints year 1 royalty 5000000.00 USD, tax 8125000.00 and net -3125000.00, each a quarter of the 100 percent figures. What does the same run report as its take?', '["95.1923 percent, because the partner''s scaled net is set against the field''s unscaled pre-take value.", "80.7692 percent, the same as at 100 percent, because the interest scales the government''s lines and the contractor''s together.", "A quarter of 80.7692 percent, since take is a money reading and every money reading scales with the interest.", "Null, because the engine declines a take on any run below a 100 percent interest."]'::jsonb, 1, 'NPV falls from 21590909.09 to 5397727.27 USD with the share while take does not move. A take that set the partner''s scaled net against the field''s unscaled value would climb as the interest fell, a reading about the partnership.'::text),
      ('beginner', 'final', null::text, 33, 'multiyear_jv_real and multiyear_pia_real both print payback "2.89 years". Do the two fields pay back at the same time?', '["Yes, because the label is the engine''s reading and payback_years is a diagnostic that carries extra digits.", "Yes, because both cross zero in their third row and payback is a year.", "No, because one is a JV field and the other a PIA field, and the regimes count from different rows.", "No. Their payback_years are 2.889357 and 2.892034, and the label is a rounding of each."]'::jsonb, 3, 'Two fields that cross in the same calendar year can be nearly a year apart in payback_years, and two that print the same label can differ in the third decimal.'::text, 'multiyear_jv_real prints payback "2.89 years" and multiyear_pia_real "2.84 years", and both cross zero in their third row. Do the two fields pay back at the same time?', '["Yes, because the two labels differ only in the second decimal, and a label is a display rounding of one shared crossing.", "Yes, because both cross zero in their third row and payback is a year.", "No, because one is a JV field and the other a PIA field, and the regimes count from different rows.", "No. Their payback_years are 2.889357 and 2.844931, and each label is a rounding of its own figure."]'::jsonb, 3, 'Both fields cross zero in their third row, yet payback_years reads 2.889357 on the JV field and 2.844931 on the PIA field: the fraction inside the crossing year differs, and each label rounds its own figure. Two fields that cross in the same row can still pay back at different times.'::text),
      ('beginner', 'final', null::text, 35, 'On the hand-derived case take is 65.3846 percent with the royalty at 0 and 30.7692 percent with the tax at 0. What do the two numbers together say?', '["A regime is a take, not a rate: each instrument moves the share on its own axis, and neither rate alone is the government''s share.", "That royalty is the larger instrument, since removing it moves the take further than removing the tax.", "That the two instruments add, so the take with both in force is their sum rather than the 80.7692 the engine prints.", "That take is undefined when either rate is zero, and the engine prints the other rate instead."]'::jsonb, 0, 'With both in force the take is 80.7692 percent; royalty shrinks the tax base, so the two do not simply add.'::text, 'On the hand-derived case take is 65.3846 percent with the royalty at 0 and 30.7692 percent with the tax at 0. What do the two numbers together say?', '["A regime is a take rather than a rate: each instrument moves the share on its own axis, and neither rate alone is the government''s share.", "That royalty is the larger instrument, since removing it moves the take further than removing the tax.", "That the two instruments add, so the take with both in force is their sum rather than the 80.7692 the engine prints.", "That take is undefined when either rate is zero, and the engine prints the other rate instead."]'::jsonb, 0, 'With both in force the take is 80.7692 percent; royalty shrinks the tax base, so the two do not simply add.'::text),
      ('beginner', 'module', 'm01-what-a-cash-flow-is'::text, 5, 'What does the Petroleum Economics Studio engine, version 3.10.0, read before it builds a ledger?', '["Three uploaded files, production, capex and opex, and a configuration carrying prices, escalators, inflation and fiscal terms; nothing else.", "A production file, a reservoir decline model and a facilities capacity file, from which it checks the volumes before believing them.", "A single combined spreadsheet of volumes and costs, with the price taken from the deck by default when the configuration is blank.", "The three files and a well log, which fixes the boe conversion for the field."]'::jsonb, 0, 'If the volumes are wrong the ledger is wrong, and the engine has no way to know: no reservoir, no facilities capacity, no decline.'::text, 'What does the Petroleum Economics Studio engine, version 3.12.0, read before it builds a ledger?', '["Three uploaded files, production, capex and opex, and a configuration carrying prices, escalators, inflation and fiscal terms; nothing else.", "A production file, a reservoir decline model and a facilities capacity file, from which it checks the volumes before believing them.", "A single combined spreadsheet of volumes and costs, with the price taken from the deck by default when the configuration is blank.", "The three files and a well log, which fixes the boe conversion for the field."]'::jsonb, 0, 'If the volumes are wrong the ledger is wrong, and the engine has no way to know: no reservoir, no facilities capacity, no decline.'::text),
      ('beginner', 'module', 'm01-what-a-cash-flow-is'::text, 7, 'multiyear_pia_nominal and multiyear_pia_real are one field with one set of rows, and they report total net cash flow 329879515.51 and 286158487.25. Which is wrong?', '["The nominal one, because inflation has been added to flows that were already escalated, which counts it twice.", "Neither: one is money of the day and the other money of the base year, and a total without its basis is not a number.", "The real one, because it has been discounted at the applied real rate of 6.796117 percent and is the NPV of 203250580.21 under another name.", "The nominal one, since only the real basis is a valid reading of a PIA ledger."]'::jsonb, 1, 'The ledger carries a net_cash_flow and a real_net_cash_flow column, and their totals part once inflation is set.'::text, 'multiyear_pia_nominal and multiyear_pia_real are one field with one set of rows, and they report total net cash flow 350425980.24 and 305105917.37. Which is wrong?', '["The nominal one, because inflation has been added to flows that were already escalated, which counts it twice.", "Neither: one is money of the day and the other money of the base year, and a total without its basis is not a number.", "The real one, because it has been discounted at the applied real rate of 6.796117 percent and is the NPV of 219158380.04 under another name.", "The nominal one, since only the real basis is a valid reading of a PIA ledger."]'::jsonb, 1, 'The ledger carries a net_cash_flow and a real_net_cash_flow column, and their totals part once inflation is set.'::text),
      ('beginner', 'module', 'm01-what-a-cash-flow-is'::text, 11, 'The hand-derived case sets gas_price_usd_mscf=0 and every row has gas_mscf 0.00. Does gas_price_unset fire?', '["Yes, because a gas price of 0 is the same as an unset price and the check reads the configuration, not the volumes.", "No, because the engine prices the gas at one sixth of the oil price of 100.000000 through the boe conversion.", "No, because gas_price_unset fires only when the production data has gas volumes, and there are none.", "Yes, and the run continues with a warning while gas revenue is booked at 0.00."]'::jsonb, 2, 'The refusal is about the pair: an unset gas_price_usd_mscf with gas volumes in the file, and the hand-derived case has neither.'::text, 'The hand-derived case sets gas_price_usd_mscf=0 and every row has gas_mscf 0.00. Does gas_price_unset fire?', '["Yes, because a gas price of 0 is the same as an unset price and the check reads the configuration and ignores the volumes.", "No, because the engine prices the gas at one sixth of the oil price of 100.000000 through the boe conversion.", "No, because gas_price_unset fires only when the production data has gas volumes, and there are none.", "Yes, and the run continues with a warning while gas revenue is booked at 0.00."]'::jsonb, 2, 'The refusal is about the pair: an unset gas_price_usd_mscf with gas volumes in the file, and the hand-derived case has neither.'::text),
      ('beginner', 'module', 'm02-from-rows-to-years'::text, 13, 'A capex file headed category, date, spend is refused. What single change lets it through?', '["Give the cost column a name ending in _usd, since the fallback sums *_usd columns and spend has no unit in its name.", "Rename spend to cost, because the word cost is on the preferred alias list as cost_usd and the engine matches on the word, not the suffix.", "Add a total_usd column holding the sum, which the fallback prefers as the rollup.", "Nothing short of the exact header amount_usd, which is the one name a capex file must carry."]'::jsonb, 0, 'The unit is in the header or the column is not a cost; Cost_USD in case_insensitive_headers was read as 30000000.00 because case is ignored but the suffix is not.'::text, 'A capex file headed category, date, spend is refused. What single change lets it through?', '["Give the cost column a name ending in _usd, since the fallback sums *_usd columns and spend has no unit in its name.", "Rename spend to cost, because the word cost is on the preferred alias list as cost_usd and the engine matches on the word and ignores the suffix.", "Add a total_usd column holding the sum, which the fallback prefers as the rollup.", "Nothing short of the exact header amount_usd, which is the one name a capex file must carry."]'::jsonb, 0, 'The unit is in the header or the column is not a cost; Cost_USD in case_insensitive_headers was read as 30000000.00 because case is ignored but the suffix is not.'::text),
      ('beginner', 'module', 'm02-from-rows-to-years'::text, 15, 'per_well_beats_total_rollup was run with no opex file at all. What does the refusal machinery do?', '["It refuses with opex_no_cost_column, because a missing opex file has no cost column to recognise.", "It refuses with no_production_rows, since a run needs all three files before it can build a ledger.", "Nothing: the run proceeds with total opex 0.00, because the refusals check that a recognised header exists, not that opex is present or that the number under it is right.", "It runs, but fills opex from unit_opex_usd_per_bbl times the annual volumes, the way the fallback sums *_usd parts when no preferred alias is present, so that the ledger is not left without a cost."]'::jsonb, 2, 'The same door lets an amount_usd column holding thousands of USD through at one thousandth of its value; after the door, the engine believes you.'::text, 'per_well_beats_total_rollup was run with no opex file at all. What does the refusal machinery do?', '["It refuses with opex_no_cost_column, because a missing opex file has no cost column to recognise.", "It refuses with no_production_rows, since a run needs all three files before it can build a ledger.", "Nothing: the run proceeds with total opex 0.00, because the refusals check only that a recognised header exists and leave the presence and size of opex unchecked.", "It runs, but fills opex from unit_opex_usd_per_bbl times the annual volumes, the way the fallback sums *_usd parts when no preferred alias is present, so that the ledger is not left without a cost."]'::jsonb, 2, 'The same door lets an amount_usd column holding thousands of USD through at one thousandth of its value; after the door, the engine believes you.'::text),
      ('beginner', 'module', 'm04-the-joint-venture-cascade'::text, 1, 'AKATA''s 2029 row reads gross revenue 186032000.00 USD, opex 24000000.00, capex 210000000.00 and net cash flow -121123680.00. What does the JV royalty at jv_royalty_pct 15 read on that row?', '["Nothing, because the row nets -121123680.00 and a royalty is a share of what the year made rather than of what it sold.", "Fifteen percent of 186032000.00 less the 24000000.00 opex, because a royalty is levied on the net operating income the field actually cleared.", "27904800.00, fifteen percent of the 186032000.00 of sales, before any cost is seen.", "Fifteen percent of the taxable income of 113127200.00, since royalty is deductible and so must be computed on the same base as tax."]'::jsonb, 2, 'Off the top means a share of sales, not of profit: 2035 pays 10998867.98 on 73325786.51 in exactly the same proportion, and 2029 pays 27904800.00 while it loses money.'::text, 'AKATA''s 2029 row reads gross revenue 186032000.00 USD, opex 24000000.00, capex 210000000.00 and net cash flow -121123680.00. What does the JV royalty at jv_royalty_pct 15 read on that row?', '["Nothing, because the row nets -121123680.00 and a royalty is a share of what the year made rather than of what it sold.", "Fifteen percent of 186032000.00 less the 24000000.00 opex, because a royalty is levied on the net operating income the field actually cleared.", "27904800.00, fifteen percent of the 186032000.00 of sales, before any cost is seen.", "Fifteen percent of the taxable income of 113127200.00, since royalty is deductible and so must be computed on the same base as tax."]'::jsonb, 2, 'Off the top means a share of sales, taken before profit: 2035 pays 10998867.98 on 73325786.51 in exactly the same proportion, and 2029 pays 27904800.00 while it loses money.'::text),
      ('beginner', 'module', 'm04-the-joint-venture-cascade'::text, 13, 'At a 25 percent working interest AKATA''s take reads 66.1723 percent, the same as at 100 percent, while the 2029 net falls from -121123680.00 to -30280920.00 USD. Why does the take not move?', '["The interest scales the government''s lines and the partner''s alike, so the ratio between them is unchanged and take is a property of the regime.", "The royalty rate falls with the interest, exactly offsetting the smaller net, which is how the engine holds the ratio steady at every interest a partner can hold.", "The pre-take value stays at the field''s 857602518.80 USD while only the net scales, and the two happen to cancel at this interest.", "Take is computed on a 100 percent run and copied onto every scaled run."]'::jsonb, 0, 'AKATA reports 66.1723 percent at 100, 75, 60, 40 and 25 percent alike; until the 2026-09-15 repair the JV ledger kept revenue, volumes and costs at field level while scaling royalty, tax and net, and printed 91.5431 percent at a 25 percent interest.'::text, 'At a 25 percent working interest AKATA''s take reads 66.1723 percent, the same as at 100 percent, while the 2029 net falls from -121123680.00 to -30280920.00 USD. Why does the take not move?', '["The interest scales the government''s lines and the partner''s alike, so the ratio between them is unchanged and take is a property of the regime.", "The royalty rate falls with the interest, exactly offsetting the smaller net, which is how the engine holds the ratio steady at every interest a partner can hold.", "The pre-take value stays at the field''s 857602518.80 USD while only the net scales, and the two happen to cancel at this interest.", "Take is computed on a 100 percent run and copied onto every scaled run."]'::jsonb, 0, 'AKATA reports 66.1723 percent at 100, 75, 60, 40 and 25 percent alike: every line of the JV ledger is printed at the share, so revenue, volumes and costs scale with royalty, tax and net, and the ratio between the government''s lines and the partner''s holds.'::text),
      ('beginner', 'module', 'm04-the-joint-venture-cascade'::text, 14, 'Under AKATA''s flat 15 percent royalty and 40 percent tax, scaling the volumes to the interest first would give the same net as scaling the results afterward. Why does the engine still insist on scaling inside?', '["Because the engine applies the interest to the uploaded volumes before the cascade runs, so a field-level rate tier would read the partner''s barrels rather than the field''s.", "Because a rate tier on the field''s daily production, a lifetime cumulative cap or a fixed lump sum is not proportional to revenue, and the two orders then part.", "Because the depreciation schedule is unit-of-production and follows the scaled barrels.", "Because the two orders never give the same answer, even under flat rates."]'::jsonb, 1, 'Under flat rates every line is proportional to revenue, so the habit is formed where it is cheap: interest is applied to results, not to inputs.'::text, 'Under AKATA''s flat 15 percent royalty and 40 percent tax, scaling the volumes to the interest first would give the same net as scaling the results afterward. Why does the engine still insist on scaling inside?', '["Because the engine applies the interest to the uploaded volumes before the cascade runs, so a field-level rate tier would read the partner''s barrels rather than the field''s.", "Because a rate tier on the field''s daily production, a lifetime cumulative cap or a fixed lump sum is not proportional to revenue, and the two orders then part.", "Because the depreciation schedule is unit-of-production and follows the scaled barrels.", "Because the two orders never give the same answer, even under flat rates."]'::jsonb, 1, 'Under flat rates every line is proportional to revenue, so the habit is formed where it is cheap: interest is applied to results and leaves inputs alone.'::text),
      ('beginner', 'module', 'm05-adding-up'::text, 8, 'multiyear_jv_real turns from -40339805.83 to 1742002.07 USD between 2031 and 2032, and the engine prints payback_years 2.889357. What does the size of that first positive cumulative say?', '["Nothing, because the interpolation inside 2032 already accounts for how narrowly the crossing was made.", "That the field is exposed for 40339805.83 at its worst, which is the trough the payback recovers.", "That 2032''s flow was only 1742002.07, so the field is close to its economic limit.", "The crossing clears zero by very little, so a modest price cut would move payback a whole year."]'::jsonb, 3, 'payback_years reports a decimal, not a margin: a crossing made by 1742002.07 and one made by tens of millions print the same kind of number.'::text, 'multiyear_jv_real turns from -40339805.83 to 1742002.07 USD between 2031 and 2032, and the engine prints payback_years 2.889357. What does the size of that first positive cumulative say?', '["Nothing, because the interpolation inside 2032 already accounts for how narrowly the crossing was made.", "That the field is exposed for 40339805.83 at its worst, which is the trough the payback recovers.", "That 2032''s flow was only 1742002.07, so the field is close to its economic limit.", "The crossing clears zero by very little, so a modest price cut would move payback a whole year."]'::jsonb, 3, 'payback_years reports a decimal and says nothing of the margin: a crossing made by 1742002.07 and one made by tens of millions print the same kind of number.'::text),
      ('beginner', 'module', 'm05-adding-up'::text, 9, 'AKATA''s total opex is 183899092.34 USD, not seven times the typed 24000000. Why?', '["The total is restated in 2029 money by the inflation rate of 3 percent, so it drifts from the typed amount.", "The 3 percent opex escalator carried the column from 24000000.00 in 2029 to 28657255.12 in 2035, and the total is the sum of the escalated column.", "The total includes the 45000000.00 second capex tranche, which the engine books in the opex lane.", "The total is scaled by the working interest, which AKATA carries at less than 100 percent."]'::jsonb, 1, 'The capex total is exactly 255000000.00 because its escalator is 0; each money total is the sum of its column in money of the day.'::text, 'AKATA''s total opex is 183899092.34 USD, more than seven times the typed 24000000. Why?', '["The total is restated in 2029 money by the inflation rate of 3 percent, so it drifts from the typed amount.", "The 3 percent opex escalator carried the column from 24000000.00 in 2029 to 28657255.12 in 2035, and the total is the sum of the escalated column.", "The total includes the 45000000.00 second capex tranche, which the engine books in the opex lane.", "The total is scaled by the working interest, which AKATA carries at less than 100 percent."]'::jsonb, 1, 'The capex total is exactly 255000000.00 because its escalator is 0; each money total is the sum of its column in money of the day.'::text),
      ('beginner', 'module', 'm05-adding-up'::text, 13, 'A press release quotes AKATA''s government share as royalty plus tax over the 857602518.80 USD of revenue. How does that compare with the engine''s take of 66.1723 percent?', '["It is the same, because royalty and tax are the only two government lines and total revenue of 857602518.80 is the only base a share of it can be quoted on.", "It is smaller, because take divides by revenue less capex 255000000.00 less opex 183899092.34, the value the field created, not by sales.", "It is larger, because the pre-take value adds back the depreciation of 174000000.00 that the tax base removed.", "It cannot be compared, because take is discounted and the press figure is not."]'::jsonb, 1, 'Take is over value, not sales; the rest of that value is the contractor''s total net cash flow.'::text, 'A press release quotes AKATA''s government share as royalty plus tax over the 857602518.80 USD of revenue. How does that compare with the engine''s take of 66.1723 percent?', '["It is the same, because royalty and tax are the only two government lines and total revenue of 857602518.80 is the only base a share of it can be quoted on.", "It is smaller, because take divides by revenue less capex 255000000.00 less opex 183899092.34, the value the field created.", "It is larger, because the pre-take value adds back the depreciation of 174000000.00 that the tax base removed.", "It cannot be compared, because take is discounted and the press figure is not."]'::jsonb, 1, 'Take is over value rather than sales; the rest of that value is the contractor''s total net cash flow.'::text),
      ('beginner', 'module', 'm06-the-associate-reading'::text, 3, 'The first step of working a ledger question is to check that the engine will accept the files. What is the reading of a run the engine refuses?', '["A ledger of zeros, from which the reader recovers the missing volumes by reading the annual totals the engine reports back.", "The same ledger the run would have produced, since a refusal only withholds the KPI block and not the rows.", "Whatever the engine produced on the last accepted upload, which it keeps until a new file replaces it.", "The refusal itself, with its reason."]'::jsonb, 3, 'A file that fails is refused with a message, not run with a zero; the only fix for a missing price is the price.'::text, 'The first step of working a ledger question is to check that the engine will accept the files. What is the reading of a run the engine refuses?', '["A ledger of zeros, from which the reader recovers the missing volumes by reading the annual totals the engine reports back.", "The same ledger the run would have produced, since a refusal only withholds the KPI block and not the rows.", "Whatever the engine produced on the last accepted upload, which it keeps until a new file replaces it.", "The refusal itself, with its reason."]'::jsonb, 3, 'A file that fails is refused with a message and never run with a zero; the only fix for a missing price is the price.'::text),
      ('beginner', 'module', 'm06-the-associate-reading'::text, 6, 'A ledger question is asked at a working interest below 100 percent. What does the Associate method do with the take?', '["Quotes what the engine prints on that run, 66.1723 percent, because the interest scales the government''s lines and the partner''s alike.", "Scales it by the interest, as it scales every other money reading in the KPI block.", "Goes back to a 100 percent run for it, because a scaled run sets the partner''s net against the whole field''s value and its take is not a fiscal statement.", "Leaves it out, because take is a field-level reading and cannot be stated for a partner."]'::jsonb, 0, 'Every money line and the volumes report the share, so take reads 66.1723 percent at 100, at 60 and at 25 percent alike; until the 2026-09-15 repair the same run printed 91.5431 percent at a 25 percent interest.'::text, 'A ledger question is asked at a working interest below 100 percent. What does the Associate method do with the take?', '["Quotes what the engine prints on that run, 66.1723 percent, because the interest scales the government''s lines and the partner''s alike.", "Scales it by the interest, as it scales every other money reading in the KPI block.", "Goes back to a 100 percent run for it, because a scaled run sets the partner''s net against the whole field''s value and its take is not a fiscal statement.", "Leaves it out, because take is a field-level reading and cannot be stated for a partner."]'::jsonb, 0, 'Every money line and the volumes report the share, so take reads 66.1723 percent at 100, at 60 and at 25 percent alike, and the figure on the run asked about is the one to quote.'::text),
      ('beginner', 'module', 'm06-the-associate-reading'::text, 11, 'Every Associate reading of AKATA treats the 30401798.05 USD earned in 2035 in one particular way. Which?', '["As 25461027.24, its value in 2029 money, since the run is on the real basis and every total follows it.", "As 17161022.43, its discounted value, because the readings are stated at the applied rate.", "As money the payback can see, because the cumulative includes it.", "As exactly 2029 money."]'::jsonb, 3, 'Nothing in this tier has a clock: payback, take and unit cost alike are undiscounted, and the real column is a restatement, not a valuation.'::text, 'Every Associate reading of AKATA treats the 30401798.05 USD earned in 2035 in one particular way. Which?', '["As 25461027.24, its value in 2029 money, since the run is on the real basis and every total follows it.", "As 17161022.43, its discounted value, because the readings are stated at the applied rate.", "As money the payback can see, because the cumulative includes it.", "As exactly 2029 money."]'::jsonb, 3, 'Nothing in this tier has a clock: payback, take and unit cost alike are undiscounted, and the real column is a restatement rather than a valuation.'::text),
      ('intermediate', 'final', null::text, 4, 'A summary table lists two projects at 203250580.21 and 196677221.27. What is a reader entitled to conclude from those two figures?', '["That the second project is worth less, since NPVs on the same ledger scale are directly comparable whatever their convention.", "Nothing until the conventions are attached: they are one field, multiyear_pia_real, read end-year and mid-year.", "That the second project carries the higher discount rate, since a lower NPV on a similar field is the mark of a harsher rate.", "That the two differ by a valuation year, since a shift of one year at 6.796117 percent is about the size of the gap."]'::jsonb, 1, 'At 5 percent their profiles read 222922734.92 and 217550313.27, and every difference between the two columns is the half-year shift.'::text, 'A summary table lists two projects at 219158380.04 and 212070544.45. What is a reader entitled to conclude from those two figures?', '["That the second project is worth less, since NPVs on the same ledger scale are directly comparable whatever their convention.", "Nothing until the conventions are attached: they are one field, multiyear_pia_real, read end-year and mid-year.", "That the second project carries the higher discount rate, since a lower NPV on a similar field is the mark of a harsher rate.", "That the two differ by a valuation year, since a shift of one year at 6.796117 percent is about the size of the gap."]'::jsonb, 1, 'At 5 percent their profiles read 239552507.28 and 233779309.33, and every difference between the two columns is the half-year shift.'::text),
      ('intermediate', 'final', null::text, 15, 'On multiyear_pia_real the profile point labelled 6.8, the headline at the applied rate, and the engine''s own npv() at 6.796117 percent all read 203250580.21. What makes the three agree?', '["The applied rate of 6.796117 percent rounds to 6.8 with a difference too small to move a field of this size, so the three agree to the cent by luck of scale.", "The profile is evaluated on the nominal flows and the headline on the real ones, and on this case the two bases happen to coincide exactly.", "The applied-rate point is labelled at the rate rounded to two decimals but evaluated at the exact rate, so the point and the headline are one computation.", "The headline is copied from the profile point rather than computed, which is why a recomputation by npv() can only ever reproduce it."]'::jsonb, 2, 'Until engines 3.10.0 the point was evaluated at its label and read 203209583.79, a gap of -40996.42, and the same defect cost -21759.68 on AKATA; the golden records no profile disagreement now.'::text, 'On multiyear_pia_real the profile point labelled 6.8, the headline at the applied rate, and the engine''s own npv() at 6.796117 percent all read 219158380.04. What makes the three agree?', '["The applied rate of 6.796117 percent rounds to 6.8 with a difference too small to move a field of this size, so the three agree to the cent by luck of scale.", "The profile is evaluated on the nominal flows and the headline on the real ones, and on this case the two bases happen to coincide exactly.", "The applied-rate point is labelled at the rate rounded to two decimals but evaluated at the exact rate, so the point and the headline are one computation.", "The headline is copied from the profile point rather than computed, which is why a recomputation by npv() can only ever reproduce it."]'::jsonb, 2, 'The label 6.8 is the applied 6.796117 percent rounded to two decimals for display, and the evaluation uses the exact rate, so the profile point and the headline are one computation and npv() at the exact rate reproduces both. Scale plays no part, the profile is read on the real flows like the headline, and the headline is computed in its own right.'::text),
      ('intermediate', 'final', null::text, 16, 'Before engines 3.10.0, jv_analytic_decision_kpis and multiyear_pia_nominal reported a profile gap of 0.00 at the applied point while AKATA''s was -21759.68. Why did those two escape?', '["Their flows are smaller, and the gap scales with the size of the field until it vanishes below the cent.", "Their applied points are computed by the oracle rather than by the engine, and the oracle carries the rate to six decimals.", "Their profiles are sampled at 10 percent, which is a sampled point, while AKATA''s 6.796117 lies between samples and is interpolated.", "Their basis is nominal, so the applied rate is the nominal 10.000000 percent, already a two-decimal number, and rounding it changes nothing."]'::jsonb, 3, 'The rounding only bit when the Fisher rate was not a round number; every case now reads the same at the point and at the headline, because the point is evaluated at the exact applied rate.'::text, 'The applied-rate points of jv_analytic_decision_kpis and multiyear_pia_nominal are labelled 10 and read their headlines, while AKATA''s is labelled 6.8 against an applied rate of 6.796117 percent. Why do label and rate agree to the digit on the two nominal cases?', '["Their flows are smaller, and a label only matches its rate once the field is small enough for any rounding of the rate to vanish below the cent.", "Their applied points are computed by the oracle rather than by the engine, and the oracle carries the rate to six decimals.", "Their profiles are sampled at 10 percent, which is a sampled point, while AKATA''s 6.796117 lies between samples and is interpolated.", "Their basis is nominal, so the applied rate is the nominal 10.000000 percent, already a two-decimal number, and rounding it changes nothing."]'::jsonb, 3, 'On a real basis the Fisher rate is rarely round, so the printed label rounds it; on a nominal basis the configured 10 percent is the applied rate. In every case the point is evaluated at the exact applied rate, so it reads the headline whatever the label shows.'::text),
      ('intermediate', 'final', null::text, 21, 'single_year_positive reports take 61.1111 percent and discounted take 61.1111. AKATA reports 66.1723 and 76.1610. Why do the two takes agree on one case and part on the other?', '["single_year_positive has no capex, and the discounted take only differs from the undiscounted where there is capex to discount, because the capex is the only outflow the government does not share and so the only row that can move the ratio between the two readings.", "single_year_positive is on the nominal basis, where discounting is at 10.000000 percent, and the two takes coincide whenever the applied rate is the nominal one, because the deflator and the discount are then the same factor and cancel between the numerator and the denominator of the share.", "The difference between the two takes is timing, and a one-row field has none: on AKATA the government''s share arrives from 2029 while the contractor''s is recovered in the tail years that discounting reduces most.", "AKATA''s royalty of 15 percent is discounted and its tax of 40 percent is not, and the split is what opens the gap: royalty is charged on revenue as it arrives, so it carries an exponent, while tax is settled on the year''s income and is carried at face value in both readings."]'::jsonb, 2, 'Every published case with a tail shows the same direction, multiyear_jv_real 69.2573 against 75.4578 and multiyear_pia_real 71.1024 against 77.4499.'::text, 'single_year_positive reports take 61.1111 percent and discounted take 61.1111. AKATA reports 66.1723 and 76.1610. Why do the two takes agree on one case and part on the other?', '["single_year_positive has no capex, and the discounted take only differs from the undiscounted where there is capex to discount, because the capex is the only outflow the government does not share and so the only row that can move the ratio between the two readings.", "single_year_positive is on the nominal basis, where discounting is at 10.000000 percent, and the two takes coincide whenever the applied rate is the nominal one, because the deflator and the discount are then the same factor and cancel between the numerator and the denominator of the share.", "The difference between the two takes is timing, and a one-row field has none: on AKATA the government''s share arrives from 2029 while the contractor''s is recovered in the tail years that discounting reduces most.", "AKATA''s royalty of 15 percent is discounted and its tax of 40 percent is not, and the split is what opens the gap: royalty is charged on revenue as it arrives, so it carries an exponent, while tax is settled on the year''s income and is carried at face value in both readings."]'::jsonb, 2, 'Both multi-year published fields show the same direction, multiyear_jv_real 69.2573 against 75.4578 and multiyear_pia_real 69.3025 against 75.6850; a large outflow late in life, as on jv_abandonment_two_irr_roots, can turn it the other way.'::text),
      ('intermediate', 'final', null::text, 22, 'At 60 percent working interest AKATA reports NPV 43520898.40, IRR 29.2361 percent and take 66.1723 percent, the same take as at 100 percent. Which of the three is a ratio rather than an amount, and why does it hold?', '["The NPV: 43520898.40 is the field''s value at the discount rate and the working interest is applied to it afterwards, which is why the take it implies does not move with the interest at all.", "The take: it is a ratio, and every monetary line and volume is scaled to your share, so 2029 gross revenue falls from 186032000.00 to 111619200.00 and both sides of it move together.", "The IRR: 29.2361 percent is a rate rather than an amount, and the take is an amount of government revenue that happens to be expressed in percent.", "None of the three: the take holds at 66.1723 because royalty at 15 percent and tax at 40 percent are unchanged, and not because any line of the ledger was scaled."]'::jsonb, 1, 'Until engines 3.10.0 revenue, volumes, opex, capex and depreciation stayed at field level while royalty, tax and net cash flow reported the share, so take counted the partners'' portion and read 79.7034 percent at 60 and 91.5431 at 25.'::text, 'At 60 percent working interest AKATA reports NPV 43520898.40, IRR 29.2361 percent and take 66.1723 percent, the same take as at 100 percent. Which of the three is a ratio rather than an amount, and why does it hold?', '["The NPV: 43520898.40 is the field''s value at the discount rate and the working interest is applied to it afterwards, which is why the take it implies does not move with the interest at all.", "The take: it is a ratio, and every monetary line and volume is scaled to your share, so 2029 gross revenue falls from 186032000.00 to 111619200.00 and both sides of it move together.", "The IRR: 29.2361 percent is a rate rather than an amount, and the take is an amount of government revenue that happens to be expressed in percent.", "None of the three: the take holds at 66.1723 because royalty at 15 percent and tax at 40 percent are unchanged, and not because any line of the ledger was scaled."]'::jsonb, 1, 'Every line of the ledger is printed at the share, so the government''s lines and the contractor''s scale by one factor and the ratio holds. NPV is an amount and scales, 72534830.66 at 100 percent against 43520898.40 at 60, and the IRR is a rate on flows scaled by one factor, so it holds for a different reason.'::text),
      ('intermediate', 'final', null::text, 24, 'two_roots_10_and_20, [-100, 230, -132], has roots at 10 and 20 percent, and its NPV reads -2.00 at 0 percent. What does the engine return, and what did it return before engines 3.10.0?', '["Null now, with irrStatus multiple-roots and both roots listed; 10.0000 percent before, because Newton starts at 10 percent and was already standing on a root.", "10.0000 percent both before and after, since the lower of two roots is the conservative reading and the contract keeps it.", "Null both before and after, since a vector with a negative last entry has never been given a rate by this engine.", "20.0000 percent now and 10.0000 before, because the contract prefers the crossing furthest from the start of the search."]'::jsonb, 0, 'The engine names a rate only where exactly one rate in the band from -99 to 1000 percent zeroes the NPV; two_roots_2_and_6 is null the same way, where it used to report 6.0000 against the oracle''s 2.0000.'::text, 'two_roots_10_and_20, [-100, 230, -132], has roots at 10 and 20 percent, and its NPV reads -2.00 at 0 percent. A Newton search started at 10 percent would stand on a root at its first step. What does the engine return?', '["Null, with irrStatus multiple-roots and both roots listed, because it counts the crossings in the band before naming any rate.", "10.0000 percent, since the lower of two roots is the conservative reading and the finder keeps the root it is already standing on.", "Null with irrStatus no-sign-change, since a vector with a negative last entry is never given a rate by this engine, whatever its signs.", "20.0000 percent, because the contract prefers the crossing furthest from the point where the search began."]'::jsonb, 0, 'The engine names a rate only where exactly one rate in the band from -99 to 1000 percent zeroes the NPV, so the starting point of a search never decides the answer. This vector changes sign twice, and two_roots_2_and_6 is null the same way, with 2.0000 and 6.0000 listed.'::text),
      ('intermediate', 'final', null::text, 25, 'all_positive [5, 5, 5], all_negative [-5, -5] and no_real_root [-1, 3, -3] each report IRR null. How far does irrStatus go towards telling the three apart?', '["All the way: each of the three carries a status of its own, so a reader never needs to look at the NPV beside the null.", "Two ways only: the first two both read no-sign-change and the third reads no-root, so the status separates no_real_root from the pair, and the NPV at 0 percent, 15.00 against -10.00, separates those.", "Not at all: the status reads the same on all three, and only the NPV at 0 percent, 15.00, -10.00 and -1.00, tells them apart.", "Two ways, but the other way round: no_real_root shares no-sign-change with all_negative because both of them are negative at 0 percent, and all_positive alone reads no-root, so the pair that shares a status is the pair that shares a sign."]'::jsonb, 1, 'no_real_root changes sign twice and still never crosses, which is why it earns no-root rather than no-sign-change; until engines 3.10.0 the null carried no status at all.'::text, 'all_positive [5, 5, 5], all_negative [-5, -5] and no_real_root [-1, 3, -3] each report IRR null. How far does irrStatus go towards telling the three apart?', '["All the way: each of the three carries a status of its own, so a reader never needs to look at the NPV beside the null.", "Two ways only: the first two both read no-sign-change and the third reads no-root, so the status separates no_real_root from the pair, and the NPV at 0 percent, 15.00 against -10.00, separates those.", "Not at all: the status reads the same on all three, and only the NPV at 0 percent, 15.00, -10.00 and -1.00, tells them apart.", "Two ways, but the other way round: no_real_root shares no-sign-change with all_negative because both of them are negative at 0 percent, and all_positive alone reads no-root, so the pair that shares a status is the pair that shares a sign."]'::jsonb, 1, 'no_real_root changes sign twice and still never crosses, which is why it earns no-root rather than no-sign-change. The status names the branch that failed, and the NPV beside the null does the rest.'::text),
      ('intermediate', 'final', null::text, 26, 'two_roots_minus73_and_173, [-12500000, 37500000, -9000000], changes sign between -75 and -50 percent, where its curve reads -6500000.000000 and 26500000.000000, and again between 150 and 175. What does the engine report?', '["173.6932 percent with a residual of 0.000000, the crossing Newton reaches walking down from 10 percent, the other lying outside the band.", "Null with irrStatus above-clamp, because 173.6932 percent sits above the top of the band the engine will report a rate from.", "Null, with irrStatus multiple-roots and the crossings listed as -73.6932 and 173.6932 percent, because both of them lie inside the band.", "-73.6932 percent, the crossing nearest the bottom of the band, which the contract prefers as the conservative of the two."]'::jsonb, 2, 'Until engines 3.10.0 it reported 173.6932 percent with a residual of 0.000000, which proved that rate was a root and said nothing about the crossing between -75 and -50.'::text, 'two_roots_minus73_and_173, [-12500000, 37500000, -9000000], changes sign between -75 and -50 percent, where its curve reads -6500000.000000 and 26500000.000000, and again between 150 and 175. What does the engine report?', '["173.6932 percent with a residual of 0.000000, the crossing Newton reaches walking down from 10 percent, the other lying outside the band.", "Null with irrStatus above-clamp, because 173.6932 percent sits above the top of the band the engine will report a rate from.", "Null, with irrStatus multiple-roots and the crossings listed as -73.6932 and 173.6932 percent, because both of them lie inside the band.", "-73.6932 percent, the crossing nearest the bottom of the band, which the contract prefers as the conservative of the two."]'::jsonb, 2, 'Both crossings lie inside the band from -99 to 1000 percent, so the engine names neither and lists both. A residual of 0.000000 at 173.6932 percent would prove that rate is a root and say nothing about the crossing between -75 and -50.'::text),
      ('intermediate', 'final', null::text, 27, 'A pre-3.10.0 report gives two_roots_2_and_6 an IRR of 6.0000 percent. Its NPV at a hurdle of 5 percent is 0.027211. Does the approval hold, and on what ground?', '["It holds because the NPV at 5 percent is positive, which is the sign the decision needs; the reported 6.0000 against 5 was not the ground.", "It holds because 6.0000 exceeds 5, and an IRR above the hurdle is the definition of approval on any vector.", "It fails because the oracle''s root is 2.0000, below the hurdle, and the lower root governs on a terminal-negative vector since it is the first rate at which the curve is zeroed.", "It fails because the NPV of 0.027211 is within the finder''s tolerance and cannot be told from zero."]'::jsonb, 0, 'On three_roots_0_7_33 the same IRR comparison, 7.3509 against 5, approves a vector whose NPV at 5 percent is -0.028075; the engine returns null on both vectors now, which removes the rate but not the question.'::text, 'A report from another tool gives two_roots_2_and_6 an IRR of 6.0000 percent. Its NPV at a hurdle of 5 percent is 0.027211. Does the approval hold, and on what ground?', '["It holds because the NPV at 5 percent is positive, which is the sign the decision needs; the reported 6.0000 against 5 was not the ground.", "It holds because 6.0000 exceeds 5, and an IRR above the hurdle is the definition of approval on any vector.", "It fails because the oracle''s root is 2.0000, below the hurdle, and the lower root governs on a terminal-negative vector since it is the first rate at which the curve is zeroed.", "It fails because the NPV of 0.027211 is within the finder''s tolerance and cannot be told from zero."]'::jsonb, 0, 'On three_roots_0_7_33 the same IRR comparison, 7.3509 against 5, approves a vector whose NPV at 5 percent is -0.028075; the engine returns null on both vectors, which removes the rate but not the question.'::text),
      ('intermediate', 'final', null::text, 34, 'Between 10 and 20 percent decline unit technical cost rises from 45.497913 to 57.021318 USD/boe and four years are trimmed. Can the table separate the decline''s effect from the trimming''s?', '["Yes: the trimming removes the capex of the trimmed years, and the difference in total capex is the trimming''s share.", "Yes: unit technical cost is an undiscounted reading and the limit only trims the discounted column, so the rise is decline alone.", "No: the cost is spread over fewer barrels for both reasons at once, and the two rows compare a ten-row field with a six-row one.", "Yes: the take, 75.6417 against 105.7792, isolates the trimming because the take is invariant to decline."]'::jsonb, 2, 'The rows column, 10 against 6, is the first thing to read; the NPV moves from 153012318.45 to -76483227.81 for the same two reasons at once.'::text, 'Between 10 and 20 percent decline unit technical cost rises from 45.497913 to 58.361925 USD/boe and three years are trimmed. Can the table separate the decline''s effect from the trimming''s?', '["Yes: the trimming removes the capex of the trimmed years, and the difference in total capex is the trimming''s share.", "Yes: unit technical cost is an undiscounted reading and the limit only trims the discounted column, so the rise it shows is decline alone.", "No: the cost is spread over fewer barrels for both reasons at once, and the two rows compare a ten-row field with a seven-row one.", "Yes: the take, 72.1778 against 93.0311, isolates the trimming because the take is invariant to decline."]'::jsonb, 2, 'The rows column, 10 against 7, is the first thing to read; the NPV moves from 182401961.12 to -30055502.32 for the same two reasons at once.'::text),
      ('intermediate', 'final', null::text, 38, 'The onward lesson says the Expert tier''s fiscal cascade is read with the conventions this tier named. What does that mean for a PIA NPV such as 203250580.21 on multiyear_pia_real?', '["It carries the same label: real basis, end-year, 10 percent nominal at 3 percent inflation, applied 6.796117; its mid-year twin reads 196677221.27 and its applied-rate profile point reads the headline, as AKATA''s does.", "It is convention-free, because the PIA cascade is charged on undiscounted bases and the NPV is a sum of after-tax rows, so the discount rate, the basis and the timing convention enter only the JV ledger, and a PIA NPV is the same number under every reading of time.", "It needs its own conventions, because five taxes on three bases each carry a timing rule that the JV ledger does not, so the royalty, the HCT, the CIT and the levy are each placed in time separately and a PIA NPV is labelled by the timing of each tax rather than by one convention.", "It is read nominal only, because the PIA''s price royalty tiers are in money of the day and cannot be deflated, so the real basis is refused on a PIA run and the profile is evaluated on the nominal flows at the nominal 10.000000 percent with no Fisher conversion and no rounding gap."]'::jsonb, 0, 'Nothing learned in the Professional tier is replaced in the Expert tier; multiyear_pia_nominal reads 203250580.21 too, because the bases agree end-year.'::text, 'The onward lesson says the Expert tier''s fiscal cascade is read with the conventions this tier named. What does that mean for a PIA NPV such as 219158380.04 on multiyear_pia_real?', '["It carries the same label: real basis, end-year, 10 percent nominal at 3 percent inflation, applied 6.796117; its mid-year twin reads 212070544.45 and its applied-rate profile point reads the headline, as AKATA''s does.", "It is convention-free, because the PIA cascade is charged on undiscounted bases and the NPV is a sum of after-tax rows, so the discount rate, the basis and the timing convention enter only the JV ledger, and a PIA NPV is the same number under every reading of time.", "It needs its own conventions, because five taxes on three bases each carry a timing rule that the JV ledger does not, so the royalty, the HCT, the CIT and the levy are each placed in time separately and a PIA NPV is labelled by the timing of each tax rather than by one convention.", "It is read nominal only, because the PIA''s price royalty tiers are in money of the day and cannot be deflated, so the real basis is refused on a PIA run and the profile is evaluated on the nominal flows at the nominal 10.000000 percent with no Fisher conversion and no rounding gap."]'::jsonb, 0, 'Nothing learned in the Professional tier is replaced in the Expert tier; multiyear_pia_nominal reads 219158380.04 too, because the bases agree end-year.'::text),
      ('intermediate', 'final', null::text, 40, 'The story so far records that at 20 percent decline the published PIA field loses four years to the economic limit and its take reads 105.7792 percent. Read with the rows column, what does that take say?', '["That the field pays more than it earns, which is an error in the cascade the engine should have reported as null.", "That the PIA royalty tiers rise with decline, since a faster decline raises the price tier the field is charged at, and a higher tier on the surviving rows lifts the government''s share of a residual that has not otherwise changed.", "That the trimmed years'' royalties are still counted while their revenue is not, which inflates the share past 100, because the limit removes revenue rows from the valued ledger while the royalty column keeps its total of 228146979.52.", "That it is a share of a residual on a six-row field, close to zero after trimming, and not comparable with the 75.6417 percent of the ten-row run at 10 percent decline."]'::jsonb, 3, 'At 40 percent decline three rows survive and the take reads 1199.4096 percent, a denominator that has almost vanished, not a rounding fault.'::text, 'The decline sweep records that at 20 percent decline the published PIA field loses three years to the economic limit and its take reads 93.0311 percent. Read with the rows column, what does that take say?', '["That the field pays almost all it earns to the government, an error in the cascade the engine should have reported as null.", "That the PIA royalty tiers rise with decline, since a faster decline raises the price tier the field is charged at, and a higher tier on the surviving rows lifts the government''s share of a residual that has not otherwise changed.", "That the trimmed years'' royalties are still counted while their revenue is not, which inflates the share, because the limit removes revenue rows from the valued ledger while the royalty column keeps its full total.", "That it is a share of a residual shrunk by trimming on a seven-row field, and not comparable with the 72.1778 percent of the ten-row run at 10 percent decline."]'::jsonb, 3, 'At 40 percent decline three rows survive and the take reads 1079.0391 percent, a denominator that has almost vanished; the figure is no rounding fault.'::text),
      ('intermediate', 'final', null::text, 41, 'The onward lesson no longer hands on the profile gap of -21759.68 as a number to distrust. Why not?', '["For the headline: the profile is the more precise figure because it is on the chart, and the headline of 72534830.66 should be corrected down by the gap to the charted 72513070.98, which is the figure the engine evaluated last and therefore the one it stands behind.", "For the basis: the gap appears on the real basis only, which shows the real basis is the less reliable of the two.", "For the IRR: a profile that misses at the applied rate misses at every rate, so the 29.2361 percent read from it is suspect, and the oracle''s habit of reporting the root nearest zero on the positive side is the correction the reader should apply to it.", "Because the applied-rate point is evaluated at the exact 6.796117 percent now and reads the headline 72534830.66, so the gap is 0.00 and there is nothing left to reconcile."]'::jsonb, 3, 'Until engines 3.10.0 the point was evaluated at its rounded label and read 72513070.98; the golden records no profile disagreement now, and the IRR disagreement on [-100, 208, -108.12] is gone the same way.'::text, 'AKATA''s applied-rate profile point is labelled 6.8 and reads the headline 72534830.66. A reader recomputes the NPV at exactly 6.8 percent and finds a slightly smaller figure. Which reading should be carried forward?', '["The recomputed one: the chart prints 6.8, so the figure evaluated at 6.8 is the one the engine stands behind, and the headline should be corrected down to it before it is reported anywhere.", "The nominal-basis one: the difference appears on the real basis only, which shows the real basis is the less reliable of the two readings.", "The recomputed one, and the IRR read from the same profile should be marked down as well, because a profile that misses at one rate misses at all of them.", "The headline: the point is evaluated at the exact 6.796117 percent, so a recomputation at the label measures the reader''s rounding."]'::jsonb, 3, 'The label is the applied rate rounded to two decimals for display, and the evaluation is at the exact rate. 6.8 percent discounts every row a little harder than 6.796117, so a recomputation at the label lands slightly below the headline, and nothing in the ledger has moved.'::text),
      ('intermediate', 'module', 'm01-why-time-matters'::text, 8, 'With inflation and every escalator set to zero, AKATA''s NPV is 65055328.97 on either basis. What does that say about the configured 72534830.66?', '["The 3 percent inflation lifts the answer by raising the revenue rows, and removing it exposes the flat prices underneath.", "The real basis adds value by deflating the capex of 255000000.00 in 2029 money, and the zero run loses that.", "The price and cost escalators lift the configured answer, not the inflation rate, which the discount rate refuses to carry on its own.", "The difference is the Fisher conversion of 10.000000 to 6.796117 percent, which the zero run no longer performs."]'::jsonb, 2, 'Set only inflation to zero and NPV stays 72534830.66; it is the escalators, not the deflator, that move the rows.'::text, 'With inflation and every escalator set to zero, AKATA''s NPV is 65055328.97 on either basis. What does that say about the configured 72534830.66?', '["The 3 percent inflation lifts the answer by raising the revenue rows, and removing it exposes the flat prices underneath.", "The real basis adds value by deflating the capex of 255000000.00 in 2029 money, and the zero run loses that.", "The price and cost escalators lift the configured answer; the inflation rate, which the discount rate refuses to carry alone, does not.", "The difference is the Fisher conversion of 10.000000 to 6.796117 percent, which the zero run no longer performs."]'::jsonb, 2, 'Set only inflation to zero and NPV stays 72534830.66; it is the escalators that move the rows, and the deflator does not.'::text),
      ('intermediate', 'module', 'm03-net-present-value'::text, 4, 'AKATA''s applied rate is 6.796117 percent and its profile point is labelled 6.8. That point reads 72534830.66, which is the headline, so the gap is 0.00. How do the label and the reading relate?', '["The point is both labelled and evaluated at 6.8 percent, and the gap is 0.00 because rounding 6.796117 up to 6.8 moves the NPV of a field this size by less than a cent, so the label and the evaluation are the same number and always were.", "The label is the exact rate truncated for display, and the reading is the 8 percent point of 65968275.69 interpolated back down to 6.8.", "The point is labelled at the applied rate rounded to two decimals and evaluated at the exact rate, so the label is a rounded name and the number behind it is not rounded.", "The point is labelled at the rounded rate and evaluated on the nominal flows, which is why it agrees with the headline."]'::jsonb, 2, 'Until engines 3.10.0 the point was evaluated at the label too, and AKATA''s read 72513070.98 against the headline, a gap of -21759.68; the golden records no profile disagreement now.'::text, 'AKATA''s applied rate is 6.796117 percent and its profile point is labelled 6.8. That point reads 72534830.66, which is the headline, so the gap is 0.00. How do the label and the reading relate?', '["The point is both labelled and evaluated at 6.8 percent, and the gap is 0.00 because rounding 6.796117 up to 6.8 moves the NPV of a field this size by less than a cent, so the label and the evaluation are the same number and always were.", "The label is the exact rate truncated for display, and the reading is the 8 percent point of 65968275.69 interpolated back down to 6.8.", "The point is labelled at the applied rate rounded to two decimals and evaluated at the exact rate, so the label is a rounded name and the number behind it is not rounded.", "The point is labelled at the rounded rate and evaluated on the nominal flows, which is why it agrees with the headline."]'::jsonb, 2, 'The engine''s own npv() at the exact rate on the same flows returns 72534830.66 as well, so the point and the headline are one computation. The label is a rounded name for display, and the point is read on the real flows like the headline.'::text),
      ('intermediate', 'module', 'm03-net-present-value'::text, 5, 'Until engines 3.10.0 the profile gap ran minus 21759.68 on AKATA, minus 40996.42 on multiyear_pia_real and minus 453.74 on allowance_cap_midyear, and was never positive. What produced that sign, and what is the gap today?', '["The point was evaluated at its rounded label, and 6.8 percent discounts every row a little harder than 6.796117; the exact rate is used now, so the gap is 0.00.", "Floating point accumulation over the discounted rows drifted downward and still does, which is why the gap scales with the size of the field and cannot be removed by changing the rate at which the point is read.", "The profile left out the valuation year row, a negative on each of these fields, and that row is included now, so the gap is 0.00.", "The profile was evaluated end-year against a mid-year headline, and a half-year shift always removes value; both are read end-year now."]'::jsonb, 0, 'The retired gap scaled with the size of the field, 40996.42 on the 203250580.21 case against 453.74 on the 2406447.46 case, and the golden records no profile disagreement on engines 3.10.0.'::text, 'A reader recomputes AKATA''s applied-rate profile point at its printed label, 6.8 percent, instead of at the applied 6.796117. Which way does the recomputed figure move against the headline 72534830.66, and why?', '["Down: 6.8 percent discounts every row a little harder than 6.796117, and the engine evaluates its point at the exact rate, so only the reader''s figure moves.", "Up or down at random: floating point accumulation over the discounted rows drifts, and the drift scales with the size of the field whatever rate the point is read at.", "Up, because 6.8 is the larger rate and a larger rate lifts the present value of a field whose flows after the first year are all positive.", "Not at all: the half-year shift of a mid-year headline absorbs the rounding, so any rate within a hundredth of the applied one gives the same figure."]'::jsonb, 0, 'AKATA''s profile falls at every step, 83023565.60 at 5 percent and 65968275.69 at 8, so a slightly higher rate gives a slightly lower NPV. The engine''s point is evaluated at 6.796117 and equals the headline; the recomputation at 6.8 lands a little below it.'::text),
      ('intermediate', 'module', 'm03-net-present-value'::text, 13, 'multiyear_pia_real has an NPV of 203250580.21 and a DPI of 0.398389; multiyear_jv_real has an NPV of 88104639.00 and a DPI of 0.598241. Which ranks first?', '["It depends on the constraint: if capital is scarce the second does more per unit of capital, and if it is not NPV ranks and the first wins.", "The first, because NPV is the only ranking and DPI is a description that cannot reverse it.", "The second, because a higher DPI means a higher return on any measure, whatever the capital available: DPI is NPV per unit of capital, and a ratio that beats another per unit beats it in total as well.", "The first, because its PV of capex of 510181818.18 is larger and larger fields carry less risk per unit, so the rate they should be read at is lower and their NPV is understated at 6.796117 percent."]'::jsonb, 0, 'NPV ranks by value; DPI ranks by value per unit of capital, and the two rankings disagree on these two fields.'::text, 'multiyear_pia_real has an NPV of 219158380.04 and a DPI of 0.429569; multiyear_jv_real has an NPV of 88104639.00 and a DPI of 0.598241. Which ranks first?', '["It depends on the constraint: if capital is scarce the second does more per unit of capital, and if it is not NPV ranks and the first wins.", "The first, because NPV is the only ranking and DPI is a description that cannot reverse it.", "The second, because a higher DPI means a higher return on any measure, whatever the capital available: DPI is NPV per unit of capital, and a ratio that beats another per unit beats it in total as well.", "The first, because its PV of capex of 510181818.18 is larger and larger fields carry less risk per unit, so the rate they should be read at is lower and their NPV is understated at 6.796117 percent."]'::jsonb, 0, 'NPV ranks by value; DPI ranks by value per unit of capital, and the two rankings disagree on these two fields.'::text),
      ('intermediate', 'module', 'm03-net-present-value'::text, 15, 'AKATA''s take reads 66.1723 percent at a working interest of 100 percent, and 66.1723 at 75, at 60, at 40 and at 25. Why does the working interest leave the share alone?', '["The royalty of 15 percent and the tax of 40 percent are the same at every interest, and take is simply those two rates restated on the pre-take value, so a run at 25 percent reports 66.1723 because the rates it is built from never moved.", "Take is read on the field-level rows before the working interest is applied, so a partner reports the whole field''s take rather than a share of it, which is why the figure is identical at 100 percent and at 60.", "The government''s part and the partners'' part both grow as the interest falls, and the two movements cancel in the ratio.", "Every monetary line and the volumes report the share, so 2029 gross revenue falls from 186032000.00 to 111619200.00 at 60 percent and both sides of the ratio are scaled by one factor."]'::jsonb, 3, 'Until engines 3.10.0 revenue, volumes, opex, capex and depreciation stayed at field level while royalty, tax and net cash flow reported the share, so take counted the partners'' portion and rose as the interest fell, 74.6292 at 75 and 91.5431 at 25.'::text, 'AKATA''s take reads 66.1723 percent at a working interest of 100 percent, and 66.1723 at 75, at 60, at 40 and at 25. Why does the working interest leave the share alone?', '["The royalty of 15 percent and the tax of 40 percent are the same at every interest, and take is simply those two rates restated on the pre-take value, so a run at 25 percent reports 66.1723 because the rates it is built from never moved.", "Take is read on the field-level rows before the working interest is applied, so a partner reports the whole field''s take rather than a share of it, which is why the figure is identical at 100 percent and at 60.", "The government''s part and the partners'' part both grow as the interest falls, and the two movements cancel in the ratio.", "Every monetary line and the volumes report the share, so 2029 gross revenue falls from 186032000.00 to 111619200.00 at 60 percent and both sides of the ratio are scaled by one factor."]'::jsonb, 3, 'A take built from a partner''s scaled net over the field''s unscaled value would count the other partners'' portion as government take and rise as the interest fell. With every line at the share, both sides of the ratio sit on one basis and the working interest drops out.'::text),
      ('intermediate', 'module', 'm04-the-internal-rate-of-return'::text, 4, 'AKATA is on the real basis, so its discounted rows are the real flows 30821366.21 and 60767504.07. Which rate is its IRR of 29.2361 percent built to be compared against?', '["The applied real rate of 6.796117 percent, because that is the rate the real flows are discounted at and the IRR is a root of the same discounted column.", "The nominal 10 percent, because the IRR zeroes the vector printed in money of the day, not the real flows.", "Either rate, since the two bases give the same NPV of 72534830.66 end-year and therefore the same root.", "The inflation rate of 3 percent, since the Fisher relation joins the two rates through it."]'::jsonb, 1, 'At the breakeven price of 64.916777 USD/bbl, where NPV is zero, the IRR reads 10.0002 percent: the nominal rate, which is the proof of which comparison it was built for.'::text, 'AKATA is on the real basis, so its discounted rows are the real flows 30821366.21 and 60767504.07. Which rate is its IRR of 29.2361 percent built to be compared against?', '["The applied real rate of 6.796117 percent, because that is the rate the real flows are discounted at and the IRR is a root of the same discounted column.", "The nominal 10 percent, because the IRR zeroes the vector printed in money of the day rather than the real flows.", "Either rate, since the two bases give the same NPV of 72534830.66 end-year and therefore the same root.", "The inflation rate of 3 percent, since the Fisher relation joins the two rates through it."]'::jsonb, 1, 'At the breakeven price of 64.916777 USD/bbl, where NPV is zero, the IRR reads 10.0002 percent: the nominal rate, which is the proof of which comparison it was built for.'::text),
      ('intermediate', 'module', 'm04-the-internal-rate-of-return'::text, 5, 'late_payout, [-1000, 0, 0, 0, 0, 2500], reports a root of 20.1124 percent and prints the NPV there as -0.000000. What does that residual say?', '["Newton overshot on the flat part of the curve and the bisection fallback ran instead, which always leaves its residual on the negative side of zero.", "The root actually sits between the sampled 4.693930 at 20 percent and -180.800000 at 25 percent, and the engine reports the midpoint of that bracket.", "The engine prints the NPV at every reported root as a negative number, because the root is approached from above by convention.", "The finder stops at a tolerance, not at an exact zero, and the rounded residual landed on the negative side."]'::jsonb, 3, 'Every reported root carries 0.000000 or -0.000000: conventional_five_year at 15.2382 percent and tiny_return at 0.1000 percent print the same kind of residual.'::text, 'late_payout, [-1000, 0, 0, 0, 0, 2500], reports a root of 20.1124 percent and prints the NPV there as -0.000000. What does that residual say?', '["Newton overshot on the flat part of the curve and the bisection fallback ran instead, which always leaves its residual on the negative side of zero.", "The root actually sits between the sampled 4.693930 at 20 percent and -180.800000 at 25 percent, and the engine reports the midpoint of that bracket.", "The engine prints the NPV at every reported root as a negative number, because the root is approached from above by convention.", "The finder stops at a tolerance short of an exact zero, and the rounded residual landed on the negative side."]'::jsonb, 3, 'Every reported root carries 0.000000 or -0.000000: conventional_five_year at 15.2382 percent and tiny_return at 0.1000 percent print the same kind of residual.'::text),
      ('intermediate', 'module', 'm04-the-internal-rate-of-return'::text, 6, 'Before engines 3.10.0 the finder''s method statement said Newton falls back to bisection when unconverged and returns null when no sign change brackets a root. What does bisection need before it can run?', '["Two rates with NPVs of opposite sign.", "Every root of the curve, so that it can halve the interval between the two nearest and confirm that Newton reached the right one.", "A vector with more than one sign change, on which it picks the root nearest zero on the positive side as the hurdle-rate answer.", "A Newton estimate to refine."]'::jsonb, 0, 'two_roots_minus73_and_173 reads -6500000.000000 at -75 percent and 26500000.000000 at -50 percent, and that pair is a bracket; a curve that never changes sign gives it nothing.'::text, 'The engine''s root finder falls back to bisection when Newton does not converge. What does bisection need before it can run?', '["Two rates with NPVs of opposite sign.", "Every root of the curve, so that it can halve the interval between the two nearest and confirm that Newton reached the right one.", "A vector with more than one sign change, on which it picks the root nearest zero on the positive side as the hurdle-rate answer.", "A Newton estimate to refine."]'::jsonb, 0, 'two_roots_minus73_and_173 reads -6500000.000000 at -75 percent and 26500000.000000 at -50 percent, and that pair is a bracket; a curve that never changes sign gives it nothing.'::text),
      ('intermediate', 'module', 'm04-the-internal-rate-of-return'::text, 7, 'no_real_root, [-1, 3, -3], changes sign twice, and its sampled curve reads -271.000000 at -90 percent, -1.000000 at 0, -0.250000 at 100 and -0.333333 at 200. Why is its IRR null?', '["Two sign changes always mean two roots, so this vector has two and the engine returns null with irrStatus multiple-roots.", "Newton stepped from 10 percent into the region below -90 percent where the last entry dominates, and an unconverged Newton returns null.", "The curve rises toward zero, touches nothing and falls back, so no sign change ever gives bisection a bracket.", "The total at 0 percent is -1.00, and the finder is not run at all on a vector whose undiscounted total never returns its outlay."]'::jsonb, 2, 'Null here means no rate zeroes the vector, not that the vector is bad or good: it says nothing more than that the search found no crossing.'::text, 'no_real_root, [-1, 3, -3], changes sign twice, and its sampled curve reads -271.000000 at -90 percent, -1.000000 at 0, -0.250000 at 100 and -0.333333 at 200. Why is its IRR null?', '["Two sign changes always mean two roots, so this vector has two and the engine returns null with irrStatus multiple-roots.", "Newton stepped from 10 percent into the region below -90 percent where the last entry dominates, and an unconverged Newton returns null.", "The curve rises toward zero, touches nothing and falls back, so no sign change ever gives bisection a bracket.", "The total at 0 percent is -1.00, and the finder is not run at all on a vector whose undiscounted total never returns its outlay."]'::jsonb, 2, 'Null here means no rate zeroes the vector and passes no judgement on it: it says nothing more than that the search found no crossing.'::text),
      ('intermediate', 'module', 'm04-the-internal-rate-of-return'::text, 8, 'AKATA at 30 USD/bbl reports IRR null beside an NPV of -169873348.04. AKATA valued from 2030 with 2029 sunk reports IRR null beside an NPV of 206819768.67. What does the engine give a reader to tell those two nulls apart, and what does it still not give?', '["Nothing at all: both return a bare null, and only the NPV beside each one has ever distinguished them.", "An irrStatus naming the branch that failed, which is not a verdict: the NPV beside each null is still the only thing saying one field is deeply uneconomic and the other worth 206819768.67.", "A signed null, positive for the sunk run and negative for the price run, carrying the verdict without the NPV.", "An irrStatus that names the branch and also grades the field, so a reader can rank the two runs from the status alone and never has to look at the NPV printed beside either one of them, whatever its sign."]'::jsonb, 1, 'Until engines 3.10.0 the null carried no status and the shapes were indistinguishable; the status names no-sign-change, no-root, multiple-roots or above-clamp, and none of the four says whether the field is worth anything.'::text, 'AKATA at 30 USD/bbl reports IRR null beside an NPV of -169873348.04. AKATA valued from 2030 with 2029 sunk reports IRR null beside an NPV of 206819768.67. What does the engine give a reader to tell those two nulls apart, and what does it still not give?', '["Nothing at all: both return a bare null, and only the NPV beside each one has ever distinguished them.", "An irrStatus naming the branch that failed, which is not a verdict: the NPV beside each null is still the only thing saying one field is deeply uneconomic and the other worth 206819768.67.", "A signed null, positive for the sunk run and negative for the price run, carrying the verdict without the NPV.", "An irrStatus that names the branch and also grades the field, so a reader can rank the two runs from the status alone and never has to look at the NPV printed beside either one of them, whatever its sign."]'::jsonb, 1, 'The status names no-sign-change, no-root, multiple-roots or above-clamp, the branch the search failed on, and none of the four says whether the field is worth anything; that is the NPV''s job.'::text),
      ('intermediate', 'module', 'm04-the-internal-rate-of-return'::text, 9, 'AKATA reports IRR null with a 200000000 abandonment in 2035, and IRR null with a 60000000 abandonment as well. The two nulls have opposite causes. What are they?', '["With 200000000 the NPV is negative at every sampled rate, -58362170.82 at 0 percent, so nothing brackets a crossing; with 60000000 it is 81637829.18 at 0 percent and -78880508.48 at 100, so the curve crosses twice and the engine will not pick one of them.", "They share one cause: a terminal negative flow always leaves the engine without a bracket, whatever the size of the abandonment.", "Newton overshoots on the steeper curve of the larger abandonment, while the 60000000 root of 23.2570 percent sits above the top of the band.", "The larger abandonment exceeds the 255000000.00 of capex it is set against, and the smaller leaves a last flow of -29598201.95 below the 2034 flow."]'::jsonb, 0, 'Until engines 3.10.0 the 60000000 run reported 23.2570 percent, one crossing of two; the engine now names a rate only where exactly one rate in the band from -99 to 1000 percent zeroes the NPV.'::text, 'AKATA reports IRR null with a 200000000 abandonment in 2035, and IRR null with a 60000000 abandonment as well. The two nulls have opposite causes. What are they?', '["With 200000000 the NPV is negative at every sampled rate, -58362170.82 at 0 percent, so nothing brackets a crossing; with 60000000 it is 81637829.18 at 0 percent and -78880508.48 at 100, so the curve crosses twice and the engine will not pick one of them.", "They share one cause: a terminal negative flow always leaves the engine without a bracket, whatever the size of the abandonment.", "Newton overshoots on the steeper curve of the larger abandonment, while the smaller abandonment''s only crossing sits above the top of the band.", "The larger abandonment exceeds the 255000000.00 of capex it is set against, and the smaller leaves a last flow of -29598201.95 below the 2034 flow."]'::jsonb, 0, 'With 200000000 nothing brackets a crossing; with 60000000 there are two crossings, and the engine names a rate only where exactly one rate in the band from -99 to 1000 percent zeroes the NPV.'::text),
      ('intermediate', 'module', 'm04-the-internal-rate-of-return'::text, 10, 'two_roots_2_and_6, [-100, 208, -108.12], has an NPV of -0.120000 at 0 percent, 0.036982 at 4 and -0.264463 at 10, and is zero at 2 percent and at 6. What does the engine return?', '["6.0000 percent, the crossing Newton reaches climbing from its start at 10 percent, with no note that a second one exists.", "2.0000 percent, the crossing nearest zero on the positive side, which is the hurdle-rate region a decision is made in.", "Both rates, reported as a range running from 2.0000 to 6.0000 percent, since either one of them zeroes the NPV.", "Null, with irrStatus multiple-roots and the crossings listed as 2.0000 and 6.0000 percent, because two rates in the band zero the NPV and it names a rate only where one does."]'::jsonb, 3, 'Until engines 3.10.0 it reported 6.0000 percent where the oracle read 2.0000 and the golden recorded a disagreement; the golden records none now.'::text, 'two_roots_2_and_6, [-100, 208, -108.12], has an NPV of -0.120000 at 0 percent, 0.036982 at 4 and -0.264463 at 10, and is zero at 2 percent and at 6. What does the engine return?', '["6.0000 percent, the crossing Newton reaches climbing from its start at 10 percent, with no note that a second one exists.", "2.0000 percent, the crossing nearest zero on the positive side, which is the hurdle-rate region a decision is made in.", "Both rates, reported as a range running from 2.0000 to 6.0000 percent, since either one of them zeroes the NPV.", "Null, with irrStatus multiple-roots and the crossings listed as 2.0000 and 6.0000 percent, because two rates in the band zero the NPV and it names a rate only where one does."]'::jsonb, 3, 'Two rates in the band zero the NPV, so the engine names neither and lists both. A finder that stopped at the crossing it reached first from 10 percent would report 6.0000 and hide 2.0000, and nothing in that rate would show it.'::text),
      ('intermediate', 'module', 'm04-the-internal-rate-of-return'::text, 11, 'A reader working from a pre-3.10.0 report takes three_roots_0_7_33''s IRR of 7.3509 percent to a hurdle of 5 percent and approves. What went wrong?', '["The reader should have used the oracle''s 0.0000 percent, which is below 5, and rejected the vector on the smaller root.", "Nothing, since 7.3509 sits above the hurdle and the curve reads 0.081930 at 30 percent.", "The NPV at 5 percent is -0.028075, negative; a hurdle comparison needs the sign of the curve at the hurdle, which is the NPV, not a root.", "The engine should have reported 33, the largest root, and the reader should compare that with the hurdle instead."]'::jsonb, 2, 'On two_roots_2_and_6 the same reasoning happens to hold because the NPV at 5 percent is 0.027211, positive; the reasoning is wrong either way, and only the sign at the hurdle is an answer.'::text, 'A reader copies from a colleague''s spreadsheet and takes three_roots_0_7_33''s IRR of 7.3509 percent to a hurdle of 5 percent and approves. What went wrong?', '["The reader should have used the oracle''s 0.0000 percent, which is below 5, and rejected the vector on the smaller root.", "Nothing, since 7.3509 sits above the hurdle and the curve reads 0.081930 at 30 percent.", "The NPV at 5 percent is -0.028075, negative; a hurdle comparison needs the sign of the curve at the hurdle, which is the NPV rather than a root.", "The engine should have reported 33, the largest root, and the reader should compare that with the hurdle instead."]'::jsonb, 2, 'On two_roots_2_and_6 the same reasoning happens to hold because the NPV at 5 percent is 0.027211, positive; the reasoning is wrong either way, and only the sign at the hurdle is an answer.'::text),
      ('intermediate', 'module', 'm04-the-internal-rate-of-return'::text, 12, 'Why must a vector whose last entry is negative cross zero an even number of times, as two_roots_2_and_6 does?', '["Because the count of roots equals the count of sign changes in the vector, and a terminal negative after a positive middle makes two.", "At very negative rates the factor on the last entry is enormous and drags the NPV down, -8832.000000 at -90 percent; at very high rates the NPV tends to the first entry, -100; negative at both ends and positive between means an even count of crossings.", "Because Newton and bisection each find one root, and the engine runs both on a terminal-negative vector.", "Because the terminal negative is discounted less than the outlay, making the curve symmetric about its peak at 4 percent."]'::jsonb, 1, 'no_real_root ends negative too and crosses zero times, which is also even: the argument fixes the parity of the count, not the count.'::text, 'Why must a vector whose last entry is negative cross zero an even number of times, as two_roots_2_and_6 does?', '["Because the count of roots equals the count of sign changes in the vector, and a terminal negative after a positive middle makes two.", "At very negative rates the factor on the last entry is enormous and drags the NPV down, -8832.000000 at -90 percent; at very high rates the NPV tends to the first entry, -100; negative at both ends and positive between means an even count of crossings.", "Because Newton and bisection each find one root, and the engine runs both on a terminal-negative vector.", "Because the terminal negative is discounted less than the outlay, making the curve symmetric about its peak at 4 percent."]'::jsonb, 1, 'no_real_root ends negative too and crosses zero times, which is also even: the argument fixes the parity of the count and leaves the count open.'::text),
      ('intermediate', 'module', 'm04-the-internal-rate-of-return'::text, 13, 'jv_analytic, [-12500000, 37500000], reports IRR 200.0000 percent and NPV 21590909.09 at 10 percent. AKATA reports 29.2361 percent and 72534830.66 at the same nominal 10 percent. A reader sorts the two by IRR. What has been measured?', '["How steeply each curve falls through zero, not how high it stands at the chosen rate; NPV ranks AKATA ahead.", "The same thing either way, because both numbers are readings of one curve and the rankings must agree whenever the discount rate is the same on both sides.", "Value per unit of capital, since 200.0000 percent reflects a 50000000.00 capex recovered in a single year against AKATA''s 255000000.00.", "The payback of each field, which is why jv_analytic at 1.333333 years ranks first."]'::jsonb, 0, 'IRR refuses to report scale: 200.0000 percent sits beside 21590909.09 and 29.2361 percent beside 72534830.66, and the steeper curve is the smaller field.'::text, 'jv_analytic, [-12500000, 37500000], reports IRR 200.0000 percent and NPV 21590909.09 at 10 percent. AKATA reports 29.2361 percent and 72534830.66 at the same nominal 10 percent. A reader sorts the two by IRR. What has been measured?', '["How steeply each curve falls through zero, whatever its height at the chosen rate; NPV ranks AKATA ahead.", "The same thing either way, because both numbers are readings of one curve and the rankings must agree whenever the discount rate is the same on both sides.", "Value per unit of capital, since 200.0000 percent reflects a 50000000.00 capex recovered in a single year against AKATA''s 255000000.00.", "The payback of each field, which is why jv_analytic at 1.333333 years ranks first."]'::jsonb, 0, 'IRR refuses to report scale: 200.0000 percent sits beside 21590909.09 and 29.2361 percent beside 72534830.66, and the steeper curve is the smaller field.'::text),
      ('intermediate', 'module', 'm04-the-internal-rate-of-return'::text, 15, 'A manager asks whether AKATA survives a discount rate of 15 percent. Which single number answers, and what does the IRR of 29.2361 percent contribute?', '["The NPV profile point at 15 percent, 33900281.71, since the profile is the sensitivity to the rate and 15 is one of its sampled points on the real flows.", "The IRR alone, because 29.2361 percent is the field''s return and any rate below it is survived by definition.", "The NPV at a nominal 15 percent, read from the discount rate sweep; the IRR only says how far the rate can rise before that NPV reaches zero.", "The discounted payback at 15 percent, since a rate the field survives is one at which it still pays back inside its life."]'::jsonb, 2, 'The profile at 15 is on the real flows, where 15 is not a nominal 15; the sweep row is the reading at the rate the manager named, and the IRR answers how wrong the rate could be, not what the value is.'::text, 'A manager asks whether AKATA survives a discount rate of 15 percent. Which single number answers, and what does the IRR of 29.2361 percent contribute?', '["The NPV profile point at 15 percent, 33900281.71, since the profile is the sensitivity to the rate and 15 is one of its sampled points on the real flows.", "The IRR alone, because 29.2361 percent is the field''s return and any rate below it is survived by definition.", "The NPV at a nominal 15 percent, read from the discount rate sweep; the IRR only says how far the rate can rise before that NPV reaches zero.", "The discounted payback at 15 percent, since a rate the field survives is one at which it still pays back inside its life."]'::jsonb, 2, 'The profile at 15 is on the real flows, where 15 differs from a nominal 15; the sweep row is the reading at the rate the manager named, and the IRR answers how wrong the rate could be and leaves the value to the NPV.'::text),
      ('intermediate', 'module', 'm05-sweeps'::text, 2, 'AKATA at 50 USD/bbl reports a take of 135.2824 percent. What does a take above 100 percent mean?', '["The royalty is charged on revenue regardless while the pre-take value is small, so the government keeps more than the whole; the contractor''s real net cash flow totals -45016230.39.", "A rounding fault in the take denominator, which the engine leaves unflagged when the pre-take value is small.", "The royalty at 15 percent and the tax at 40 percent have stacked on one base, which the cascade should have prevented since they cannot exceed 55 combined.", "The sweep reused the royalty column from the 82 USD/bbl run against the smaller revenue at 50 USD/bbl."]'::jsonb, 0, 'A take above 100 percent is a royalty on a loss, not an error; at 45 USD/bbl it reads 247.7770 percent for the same reason.'::text, 'AKATA at 50 USD/bbl reports a take of 135.2824 percent. What does a take above 100 percent mean?', '["The royalty is charged on revenue regardless while the pre-take value is small, so the government keeps more than the whole; the contractor''s real net cash flow totals -45016230.39.", "A rounding fault in the take denominator, which the engine leaves unflagged when the pre-take value is small.", "The royalty at 15 percent and the tax at 40 percent have stacked on one base, which the cascade should have prevented since they cannot exceed 55 combined.", "The sweep reused the royalty column from the 82 USD/bbl run against the smaller revenue at 50 USD/bbl."]'::jsonb, 0, 'A take above 100 percent is a royalty on a loss and no error; at 45 USD/bbl it reads 247.7770 percent for the same reason.'::text),
      ('intermediate', 'module', 'm05-sweeps'::text, 5, 'On the published oil_price_multiyear_pia_real sweep the take reads 144.0232 percent at 40 USD/bbl, 71.1024 at 80 and 71.3286 at 120, while AKATA''s JV take falls from 87.4083 at 60 to 57.9418 at 120. Why does the PIA take hold almost flat?', '["The PIA take is working-interest invariant, so it cannot move with the price either.", "The PIA field''s unit technical cost is 32.823299 USD/boe at every point, so cost and price scale together and the ratio is fixed.", "The PIA''s price royalty tiers rise with price, so the government''s share grows as the pre-take value grows.", "The PIA cascade charges its taxes on revenue rather than on income, so the take is a rate rather than a share."]'::jsonb, 2, 'Both takes are shares of a residual; the JV share falls because a fixed royalty and a fixed tax rate take a smaller fraction of a growing residual, and the PIA tiers replace that fixed royalty with one that climbs.'::text, 'On the published oil_price_multiyear_pia_real sweep the take reads 114.9262 percent at 40 USD/bbl, 69.3025 at 80 and 69.8048 at 120, while AKATA''s JV take falls from 87.4083 at 60 to 57.9418 at 120. Why does the PIA take hold almost flat?', '["The PIA take is working-interest invariant, so it cannot move with the price either.", "The PIA field''s unit technical cost is 32.823299 USD/boe at every point, so cost and price scale together and the ratio is fixed.", "The PIA''s price royalty tiers rise with price, so the government''s share grows as the pre-take value grows.", "The PIA cascade charges its taxes on revenue rather than on income, so the take is a rate rather than a share."]'::jsonb, 2, 'Both takes are shares of a residual; the JV share falls because a fixed royalty and a fixed tax rate take a smaller fraction of a growing residual, and the PIA tiers replace that fixed royalty with one that climbs.'::text),
      ('intermediate', 'module', 'm05-sweeps'::text, 6, 'An analyst averages AKATA''s nine sweep NPVs, from -169873348.04 at 30 USD/bbl to 231658748.27 at 120, and reports the mean as the expected value. What is wrong?', '["The average must be taken over the discounted flows before the ledger is summed, not over the NPVs afterwards.", "The sweep is on the flat price only, so the mean ignores the 2 percent escalator that the engine adds on top at each price.", "The sweep should have been weighted by the take at each price, since the government''s share changes from 57.9418 to null across it.", "Each NPV says what the field is worth if the price is that number for the whole life, and the sweep says nothing about how likely any price is."]'::jsonb, 3, 'Nine ledgers at nine flat prices are nine conditional answers, and averaging them is not an expected value because no probability was ever attached to a price.'::text, 'An analyst averages AKATA''s nine sweep NPVs, from -169873348.04 at 30 USD/bbl to 231658748.27 at 120, and reports the mean as the expected value. What is wrong?', '["The average must be taken over the discounted flows before the ledger is summed, and the NPVs afterwards are the wrong thing to average.", "The sweep is on the flat price only, so the mean ignores the 2 percent escalator that the engine adds on top at each price.", "The sweep should have been weighted by the take at each price, since the government''s share changes from 57.9418 to null across it.", "Each NPV says what the field is worth if the price is that number for the whole life, and the sweep says nothing about how likely any price is."]'::jsonb, 3, 'Nine ledgers at nine flat prices are nine conditional answers, and averaging them is not an expected value because no probability was ever attached to a price.'::text),
      ('intermediate', 'module', 'm05-sweeps'::text, 7, 'At a nominal discount rate of 0 percent AKATA''s rate sweep prints NPV 141637829.18, the nominal total, not the real total 117362408.71, and an applied real rate of -2.912621 percent. Why?', '["A nominal rate under the 3 percent inflation is a negative real rate, and discounting the real flows at a negative rate inflates them back to money of the day.", "At 0 percent the engine switches to the nominal basis, since a real rate cannot be derived from a nominal rate of zero.", "The sweep is run on the nominal flows because the swept rate is nominal, whatever basis the case is configured on.", "The real total is the profile''s 0 percent point, and the sweep rounds the Fisher rate differently from the profile."]'::jsonb, 0, 'The applied real rate passes through zero between 2 and 4 percent nominal, and only from there does discounting on the real basis begin to shrink the real flows.'::text, 'At a nominal discount rate of 0 percent AKATA''s rate sweep prints NPV 141637829.18, the nominal total rather than the real total 117362408.71, and an applied real rate of -2.912621 percent. Why?', '["A nominal rate under the 3 percent inflation is a negative real rate, and discounting the real flows at a negative rate inflates them back to money of the day.", "At 0 percent the engine switches to the nominal basis, since a real rate cannot be derived from a nominal rate of zero.", "The sweep is run on the nominal flows because the swept rate is nominal, whatever basis the case is configured on.", "The real total is the profile''s 0 percent point, and the sweep rounds the Fisher rate differently from the profile."]'::jsonb, 0, 'The applied real rate passes through zero between 2 and 4 percent nominal, and only from there does discounting on the real basis begin to shrink the real flows.'::text),
      ('intermediate', 'module', 'm05-sweeps'::text, 10, 'AKATA''s breakeven is 64.916777 USD/bbl. Rerun at that price, the NPV is 897.16 USD, the IRR 10.0002 percent and the take 79.0146 percent. What is the 897.16?', '["The NPV of the final row alone, which the search leaves unresolved because the 2035 revenue is priced by the escalator rather than by the flat price the search moves, so a remainder of that size is expected at any breakeven.", "Proof that the NPV curve against price never quite crosses zero, so 64.916777 is the nearest price rather than a root.", "The trace of a search that stops at a tolerance on price: nothing for a decision, something for a reader who expected zero.", "The mid-year against end-year difference at the breakeven price, which the search cannot remove."]'::jsonb, 2, 'The published cases leave the same trace, -243.53 on jv_analytic, 810.98 on pia_worked_example and 851.16 on multiyear_pia_real, and the IRR of 10.0002 percent confirms the crossing was found.'::text, 'AKATA''s breakeven is 64.916777 USD/bbl. Rerun at that price, the NPV is 897.16 USD, the IRR 10.0002 percent and the take 79.0146 percent. What is the 897.16?', '["The NPV of the final row alone, which the search leaves unresolved because the 2035 revenue is priced by the escalator rather than by the flat price the search moves, so a remainder of that size is expected at any breakeven.", "Proof that the NPV curve against price never quite crosses zero, so 64.916777 is the nearest price rather than a root.", "The trace of a search that stops at a tolerance on price: nothing for a decision, something for a reader who expected zero.", "The mid-year against end-year difference at the breakeven price, which the search cannot remove."]'::jsonb, 2, 'The published cases leave the same trace, -243.53 on jv_analytic, -1391.65 on pia_worked_example and -3574.39 on multiyear_pia_real, and the IRR of 10.0002 percent confirms the crossing was found.'::text),
      ('intermediate', 'module', 'm05-sweeps'::text, 14, 'On decline_rate_multiyear_pia at 20 percent decline the limit year is 2030, four years are trimmed and six rows are valued. What does the sweep refuse to do with the trimmed years?', '["Report them at all, so the rows column reads 10 on every point and only the KPIs reveal the trimming, because the row count is fixed by the production upload and the limit test only zeroes the values in the years it fails.", "Charge their opex, so the KPIs of the shortened field carry no cost after the limit year, while the revenue of the trimmed years is still counted inside the total of 1532137562.53.", "Discount them, so they enter the NPV at face value and pull the NPV down to -76483227.81, because a year past the limit is carried undiscounted as a liability instead of being removed from the ledger.", "Keep them: a year that fails the limit test is removed from the valued ledger, not carried at zero, and the KPIs are of the shortened field."]'::jsonb, 3, 'At 40 percent decline seven years are trimmed and three rows survive, and total revenue falls from 3485716284.18 at 5 percent decline to 794617600.00.'::text, 'On decline_rate_multiyear_pia at 20 percent decline the limit year is 2031, three years are trimmed and seven rows are valued. What does the sweep refuse to do with the trimmed years?', '["Report them at all, so the rows column reads 10 on every point and only the KPIs reveal the trimming, because the row count is fixed by the production upload and the limit test only zeroes the values in the years it fails.", "Charge their opex, so the KPIs of the shortened field carry no cost after the limit year, while the revenue of the trimmed years is still counted inside the total revenue of the run.", "Discount them, so they enter the NPV at face value and pull the NPV down to -30055502.32, because a year past the limit is carried undiscounted as a liability instead of being removed from the ledger.", "Keep them: a year that fails the limit test is removed from the valued ledger instead of carried at zero, and the KPIs are of the shortened field."]'::jsonb, 3, 'At 40 percent decline seven years are trimmed and three rows survive, and total revenue falls from 3485716284.18 at 5 percent decline to 794617600.00.'::text),
      ('intermediate', 'module', 'm05-sweeps'::text, 15, 'The decline sweep reports a take of 1199.4096 percent at 40 percent decline and a unit technical cost of 78.666122 USD/boe. What is the 1199.4096?', '["A share of a pre-take value that has almost vanished, because rows were trimmed while royalties are still charged on what remains.", "A rounding fault in the take, which the engine should have reported as null once the residual turned negative as it does on AKATA at 40 USD/bbl.", "The royalties of 118324626.82 divided by the three surviving rows of revenue, which is how the take is defined once the limit engages.", "The take on the ten-year field before trimming, carried forward unchanged because the take is an undiscounted reading."]'::jsonb, 0, 'Take is 105.7792 percent at 20 percent decline and 202.4061 at 30: the denominator shrinks toward zero as rows are cut, and a share of a value near zero is a large percentage.'::text, 'The decline sweep reports a take of 1079.0391 percent at 40 percent decline and a unit technical cost of 78.666122 USD/boe. What is the 1079.0391?', '["A share of a pre-take value that has almost vanished, because rows were trimmed while royalties are still charged on what remains.", "A rounding fault in the take, which the engine should have reported as null once the residual turned negative as it does on AKATA at 40 USD/bbl.", "The royalties of 72878470.21 divided by the three surviving rows of revenue, which is how the take is defined once the limit engages.", "The take on the ten-year field before trimming, carried forward unchanged because the take is an undiscounted reading."]'::jsonb, 0, 'Take is 93.0311 percent at 20 percent decline and 179.7616 at 30: the denominator shrinks toward zero as rows are cut, and a share of a value near zero is a large percentage.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 5, 'Step five reads the profile. AKATA''s point labelled 6.8 reads 72534830.66, the headline, so the gap is 0.00. What does the label 6.8 tell a reader about the rate the point was evaluated at?', '["That it was evaluated at 6.8 percent, and the gap of 0.00 shows 6.8 and 6.796117 give the same NPV to the cent on a field of this size.", "Nothing exact: the label is the applied rate rounded to two decimals, while the evaluation is at 6.796117 percent, which is why the point equals the headline.", "That the point sits between the 5 and 8 percent samples and was interpolated from 83023565.60 and 65968275.69.", "That the applied rate is exactly 6.8 percent, the Fisher rate rounded by the engine before any discounting is done."]'::jsonb, 1, 'Until engines 3.10.0 the point was evaluated at its label too and read 72513070.98, a gap of -21759.68; the engine''s own npv() at the exact rate returns the headline.'::text, 'Step five reads the profile. AKATA''s point labelled 6.8 reads 72534830.66, the headline, so the gap is 0.00. What does the label 6.8 tell a reader about the rate the point was evaluated at?', '["That it was evaluated at 6.8 percent, and the gap of 0.00 shows 6.8 and 6.796117 give the same NPV to the cent on a field of this size.", "Nothing exact: the label is the applied rate rounded to two decimals, while the evaluation is at 6.796117 percent, which is why the point equals the headline.", "That the point sits between the 5 and 8 percent samples and was interpolated from 83023565.60 and 65968275.69.", "That the applied rate is exactly 6.8 percent, the Fisher rate rounded by the engine before any discounting is done."]'::jsonb, 1, 'The engine''s own npv() at the exact rate returns the headline, and a recomputation at the printed 6.8 would land slightly below it, because 6.8 discounts a little harder.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 8, 'The tier ends on the sentence that IRR is a property of a curve, not of a project. What is the sentence claiming?', '["That the IRR is a zero of one vector''s NPV curve: a curve with two zeros has no single IRR, which is why the engine returns null there, and a scaled vector keeps its IRR at any size.", "That the IRR moves when the convention moves, as NPV does from 72534830.66 to 70188970.32, because the curve is redrawn under mid-year discounting.", "That the IRR is a rate on the project''s money, so a project with an IRR of 29.2361 percent earns 29.2361 percent on its 255000000.00 of capex.", "That the IRR is read from the sampled profile, so AKATA''s 29.2361 percent is where the profile crosses zero between the 15 and 20 percent points."]'::jsonb, 0, '29.2361 percent holds at every working interest and under all four conventions; [-100, 208, -108.12] is zero at 2.0000 and at 6.0000 percent, so the engine names neither and returns null with both listed.'::text, 'The tier ends on the sentence that IRR is a property of a curve rather than of a project. What is the sentence claiming?', '["That the IRR is a zero of one vector''s NPV curve: a curve with two zeros has no single IRR, which is why the engine returns null there, and a scaled vector keeps its IRR at any size.", "That the IRR moves when the convention moves, as NPV does from 72534830.66 to 70188970.32, because the curve is redrawn under mid-year discounting.", "That the IRR is a rate on the project''s money, so a project with an IRR of 29.2361 percent earns 29.2361 percent on its 255000000.00 of capex.", "That the IRR is read from the sampled profile, so AKATA''s 29.2361 percent is where the profile crosses zero between the 15 and 20 percent points."]'::jsonb, 0, '29.2361 percent holds at every working interest and under all four conventions; [-100, 208, -108.12] is zero at 2.0000 and at 6.0000 percent, so the engine names neither and returns null with both listed.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 9, 'AKATA''s flow vector is [-121123680.00, 31746007.20, 64468245.07, 53959532.44, 44874457.77, 37311468.65, 30401798.05]. An abandonment of 60000000 in 2035 is added. Which entry changes, what happens to its sign, and what does that do to the count of IRR roots?', '["The first entry grows to include the abandonment as a provision, stays negative, and the root count is unchanged because only the sign of the first flow matters.", "The last entry becomes -29598201.95, negative, and the root count goes from one to two, so the engine stops naming a rate and returns null with irrStatus multiple-roots.", "The last entry becomes -29598201.95, negative, and the root count goes from one to none, which is why the engine reports null with irrStatus no-root.", "Every entry falls by a share of the 60000000 spread as a sinking fund across the seven years, the signs are unchanged, and the single root moves down to 23.2570 percent."]'::jsonb, 1, 'The 200000000 abandonment takes the last entry to -169598201.95 and the NPV negative at every sampled rate, -58362170.82 at 0 percent, and that is the case with no root at all.'::text, 'AKATA''s flow vector is [-121123680.00, 31746007.20, 64468245.07, 53959532.44, 44874457.77, 37311468.65, 30401798.05]. An abandonment of 60000000 in 2035 is added. Which entry changes, what happens to its sign, and what does that do to the count of IRR roots?', '["The first entry grows to include the abandonment as a provision, stays negative, and the root count is unchanged because only the sign of the first flow matters.", "The last entry becomes -29598201.95, negative, and the root count goes from one to two, so the engine stops naming a rate and returns null with irrStatus multiple-roots.", "The last entry becomes -29598201.95, negative, and the root count goes from one to none, which is why the engine reports null with irrStatus no-root.", "Every entry falls by a share of the 60000000 spread as a sinking fund across the seven years, the signs are unchanged, and the single root moves a little below 29.2361 percent."]'::jsonb, 1, 'The 200000000 abandonment takes the last entry to -169598201.95 and the NPV negative at every sampled rate, -58362170.82 at 0 percent, and that is the case with no root at all.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 10, 'The onward lesson names a second source of terminal negatives beside abandonment. What is it?', '["A price deck that falls in its last entries, which turns the late revenue rows negative before the cascade is applied to them.", "Mid-year discounting, which discounts the valuation year row and so pushes a negative into the tail of the discounted column.", "A tail kept past its economic limit with the limit test off, where each late year carries a loss to the end of the vector.", "A working interest below 100 percent, which scales the late rows harder than the early ones and turns the tail negative at 25 percent."]'::jsonb, 2, 'At 20 percent decline the limit year is 2030 and four years are trimmed; with the limit off those years would stay, and each would carry a loss.'::text, 'The onward lesson names a second source of terminal negatives beside abandonment. What is it?', '["A price deck that falls in its last entries, which turns the late revenue rows negative before the cascade is applied to them.", "Mid-year discounting, which discounts the valuation year row and so pushes a negative into the tail of the discounted column.", "A tail kept past its economic limit with the limit test off, where each late year carries a loss to the end of the vector.", "A working interest below 100 percent, which scales the late rows harder than the early ones and turns the tail negative at 25 percent."]'::jsonb, 2, 'At 20 percent decline the limit year is 2031 and three years are trimmed; with the limit off those years would stay, and each would carry a loss.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 11, 'The three habits the lesson names end with reading the rows column before comparing two runs. Why that column?', '["Because the rows column carries the sunk flag, and a run with a sunk row reports 206819768.67 where the same rows kept report 77464382.26.", "Because the rows column is where the discounting convention is recorded for each run, end_year or mid_year, and two runs under different conventions cannot be ranked against each other.", "Because the number of rows sets the exponent of the last flow, so a ten-row field is discounted harder than a six-row field at the same rate.", "Because a sweep that trims years compares different fields: at 20 percent decline six rows are valued and at 40 percent three, so the KPIs are of shortened ledgers."]'::jsonb, 3, 'The 10 percent decline point keeps all 10 rows and reads 153012318.45; the 20 percent point reads -76483227.81 with four years gone, and part of that difference is the missing rows.'::text, 'The three habits the lesson names end with reading the rows column before comparing two runs. Why that column?', '["Because the rows column carries the sunk flag, and a run with a sunk row reports 206819768.67 where the same rows kept report 77464382.26.", "Because the rows column is where the discounting convention is recorded for each run, end_year or mid_year, and two runs under different conventions cannot be ranked against each other.", "Because the number of rows sets the exponent of the last flow, so a ten-row field is discounted harder than a seven-row field at the same rate.", "Because a sweep that trims years compares different fields: at 20 percent decline seven rows are valued and at 40 percent three, so the KPIs are of shortened ledgers."]'::jsonb, 3, 'The 10 percent decline point keeps all 10 rows and reads 182401961.12; the 20 percent point reads -30055502.32 with three years gone, and part of that difference is the missing rows.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 13, 'Working the method on multiyear_jv_real: 127186476.88 at 0 percent, headline 88104639.00 at 6.796117 percent, 88104639.00 at the point labelled 6.8, IRR 47.9020 percent. What is the gap, and what does the engine naming 47.9020 already tell you?', '["The gap is 0.00, and a named rate tells you only that Newton converged on something; the count of crossings still has to be checked by hand from the sign of the vector''s last flow before the rate can be relied on.", "The gap is -18628.18, because the applied rate of 6.796117 percent is rounded to 6.8 before the point is evaluated, and a named rate says nothing at all about how many crossings the curve has.", "The gap is 0.00, and a named rate already tells you it is the only rate in the band from -99 to 1000 percent that zeroes the NPV, because the engine returns null where there is more than one.", "The gap is 0.00, and a named rate tells you the last entry is positive, since the engine names a rate only on conventional vectors."]'::jsonb, 2, 'Until engines 3.10.0 the point labelled 6.8 read 88086010.81, a gap of -18628.18, and a reported rate was one crossing of however many there were.'::text, 'Working the method on multiyear_jv_real: 127186476.88 at 0 percent, headline 88104639.00 at 6.796117 percent, 88104639.00 at the point labelled 6.8, IRR 47.9020 percent. What is the gap, and what does the engine naming 47.9020 already tell you?', '["The gap is 0.00, and a named rate tells you only that Newton converged on something; the count of crossings still has to be checked by hand from the sign of the vector''s last flow before the rate can be relied on.", "The gap is a small negative amount, because the applied rate of 6.796117 percent is rounded to 6.8 before the point is evaluated, and a named rate says nothing at all about how many crossings the curve has.", "The gap is 0.00, and a named rate already tells you it is the only rate in the band from -99 to 1000 percent that zeroes the NPV, because the engine returns null where there is more than one.", "The gap is 0.00, and a named rate tells you the last entry is positive, since the engine names a rate only on conventional vectors."]'::jsonb, 2, 'The point is evaluated at the exact applied rate, so the gap is 0.00. The engine names a rate only where exactly one rate in the band zeroes the NPV, so a reported 47.9020 percent already carries the count of crossings.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 15, 'The Professional tier used to hand on two numbers to distrust. What became of them, and what is handed on in their place?', '["Both still stand, the profile gap of -21759.68 and the engine''s 6.0000 percent against the oracle''s 2.0000, reported exactly as they always were, and the third of them belongs to the Expert tier and concerns abandonment.", "The profile gap was repaired and the two-root IRR was not, so 6.0000 percent is still reported against the oracle''s 2.0000 and is the one number the tier now hands on to the Expert tier.", "Both were replaced by the breakeven residual of 897.16 and the mid-year NPV of 70188970.32, the readings the engine still reports without saying what it did.", "Both were repaired: the point labelled 6.8 now reads the headline 72534830.66, and [-100, 208, -108.12] now returns null with irrStatus multiple-roots; the habit of asking what the engine did is what travels."]'::jsonb, 3, 'The golden records no profile disagreement and no IRR disagreement on engines 3.10.0; 70188970.32 and 897.16 are correct readings under their labels and were never numbers to distrust.'::text, 'The Professional tier hands on two readings that carry their own proof: the applied-rate profile point and the IRR of a vector whose last entry is negative. What does each tell a reader?', '["The point labelled 6.8 is a rounded estimate to be corrected against the headline, and [-100, 208, -108.12] returns 6.0000 percent, the root the search reaches first from 10 percent.", "The profile point reads the headline, and [-100, 208, -108.12] returns 2.0000 percent, the lower root, which the contract keeps as the conservative rate for a hurdle.", "Both are superseded by the breakeven residual of 897.16 and the mid-year NPV of 70188970.32, the readings the engine reports without saying how.", "The point labelled 6.8 reads the headline 72534830.66 because it is evaluated at the exact rate, and [-100, 208, -108.12] is null with multiple-roots and both roots listed."]'::jsonb, 3, 'The applied-rate point is labelled at the rate rounded to two decimals and evaluated at 6.796117, so it equals the headline; a vector with two crossings in the band is null with its roots listed. 70188970.32 and 897.16 are correct readings under their labels.'::text),
      ('advanced', 'final', null::text, 2, 'deriveOilRoyaltyRate reads 0.050000 for deep offshore at 50000 bopd and 0.075000 at 50001 bopd. On a deep offshore field lifting 60000 bopd, what rate do the barrels below the 50000 bopd threshold carry?', '["0.075000, like every other barrel of the year: the daily rate picks one rate for the whole year and nothing below the step is priced separately.", "0.050000, with 0.075000 charged on the 10000 bopd above the threshold, which is the blend the marginal field table shows across its tiers.", "0.050000 for the months before the field passed 50000 bopd and 0.075000 for the months after, read row by row from the production file.", "0.062500, the average of the two tiers, because the engine blends across a step in every terrain that has one."]'::jsonb, 0, 'pia_deep_offshore_full at 60000 bopd pays 131400000.00 on 1752000000.00 of gross revenue, 0.075000 of every barrel; the blend belongs to the marginal field alone, which reads 0.062500 at 10000 bopd.'::text, 'deriveOilRoyaltyRate reads 0.050000 for deep offshore at 50000 bopd and at 50001 bopd, and 0.054167 at 60000 bopd. On a deep offshore field lifting 60000 bopd, what rate do the barrels up to 50000 bopd carry?', '["0.050000, with 0.075000 on the 10000 bopd above, so the one weighted rate the year charges on every barrel is 0.054167.", "0.075000, like every other barrel of the year: once the daily rate passes 50000 bopd the whole year''s volume steps up to the higher rate.", "0.050000 for the months before the field passed 50000 bopd and 0.075000 for the months after, read row by row from the production file.", "0.062500, the plain average of the two rates, because the engine splits a crossing year evenly between them whatever the daily rate is."]'::jsonb, 0, 'pia_deep_offshore_full at 60000 bopd pays 94900000.00 of production royalty on 1752000000.00 of gross revenue: 50000 bopd at 5 percent and the 10000 above at 7.5 percent, a weighted 0.054167 on the whole volume. Onshore and shallow water weight their tranches the same way; only frontier is flat.'::text),
      ('advanced', 'final', null::text, 3, 'AKATA under the PIA prints hcdt 0.00 in 2029, 720000.00 in 2030 and 741600.00 in 2031, while nddc reads 720000.00 in 2029 and 741600.00 in 2030. Why do the two columns carry the same numbers one year apart?', '["NDDC is charged one year in arrears and HCDT in the current year, and the 2029 HCDT of 0.00 is a rounding of the first year''s fixed sum.", "The engine charges each levy on half the opex in alternate years, so the two columns take turns carrying the full 3 percent.", "Both read the current year''s opex, and the 2029 HCDT is 0.00 because the levy is suspended in the year of first oil under the 2025 framework.", "HCDT is 3 percent of the prior year''s opex and NDDC 3 percent of the current year''s, and AKATA set pia_prior_year_opex_usd to 0, so the first year pays no HCDT."]'::jsonb, 3, 'With a prior year opex of 20000000 the 2029 HCDT is 600000.00 and NPV moves from 43223505.88 to 43002056.49; neither levy is in the tax column.'::text, 'AKATA under the PIA prints hcdt 0.00 in 2029, 720000.00 in 2030 and 741600.00 in 2031, while nddc reads 7020000.00, 2091600.00 and 763848.00. Why are the two levies far apart in the capex years and close together in 2031?', '["NDDC is charged one year in arrears and HCDT in the current year, and the 2029 HCDT of 0.00 is a rounding of the first year''s fixed sum.", "The engine charges each levy on half the opex in alternate years, so the two columns take turns carrying the full 3 percent of the budget.", "Both read the current year''s opex plus capex, and the 2029 HCDT is 0.00 because that levy is suspended in the year of first oil.", "HCDT is 3 percent of the prior year''s opex and NDDC 3 percent of the year''s opex plus capex, and AKATA set no prior-year opex, so 2029 pays no HCDT."]'::jsonb, 3, 'NDDC reads the whole annual budget, so the 210000000.00 of capex in 2029 lifts it to 7020000.00, while HCDT reads only the previous year''s opex; in 2031 there is no capex and the two differ by one year of opex escalation. With a prior-year opex of 20000000 the 2029 HCDT is 600000.00 and NPV moves from 59766796.57 to 59545347.19; neither levy is in the tax column.'::text),
      ('advanced', 'final', null::text, 4, 'Under the 2021 Act the worked example pays TET of 25999871.36 and under the 2025 framework a development levy of 41599794.17, with royalty, HCT and CIT unchanged. Why does the course call the levy 1.6 x TET?', '["The levy is charged on the HCT base, which is 15000000.00 larger because NDDC is not deducted from it.", "Same base, the CIT assessable profit of 1039994854.24; only the rates differ, 4 against 2.5.", "The levy is charged on the chargeable profit of 979994854.24 after the restriction, and then on the restricted amount again.", "The levy includes the TET it replaced plus the HCDT of 5100000.00 rolled into one line."]'::jsonb, 1, 'Total tax moves from 604809283.90 to 620409206.71 and NPV from 135185570.34 to 119585647.53; the rate is the smaller part of the difference, the base is where the money is.'::text, 'In its 2025 year under the Act the worked example pays TET of 31747249.45, and forced to the 2025 framework it pays a development levy of 42329665.93 instead, with royalty, HCT and CIT unchanged. Why is the levy four thirds of the TET?', '["The levy is charged on the HCT base, which is 15000000.00 larger because the NDDC is kept out of that base and taken off the CIT base only.", "Same base, the CIT assessable profit of 1058241648.19; only the rates differ, 4 against 3.", "Its base is the chargeable profit of 998241648.19 after the allowance, and the levy is then charged a second time on the part of the allowance that was restricted.", "It includes the TET it replaced plus the HCDT of 5100000.00 rolled into one line."]'::jsonb, 1, 'Both are charged on the CIT assessable profit of 1058241648.19, TET at 3 percent in 2025 and the levy at 4 percent, so the difference is one percent of that base, 10582416.48. Total tax moves from 617004738.36 to 627587154.84 and NPV from 141236909.83 to 130654493.35.'::text),
      ('advanced', 'final', null::text, 7, 'With the economic limit off, elt_off_tail_kept''s 2032 row sells 10000.00 bbl for 1000000.00 against 10000000.00 of opex, reports taxable income -14200000.00 and net cash flow -9200000.00. What two things does the kept row do to the ledger?', '["It banks a 14200000.00 loss with no year after it to spend it, and it hands the IRR a terminal negative, which since engines 3.10.0 comes back as null with a status.", "It relieves the 14200000.00 against the 2031 tax of 32500000.00 by carrying the loss backward into that year, and that relief is why NPV reads 13987603.31 rather than 21590909.09.", "It forfeits the 14200000.00 as a CPR deferral rather than as a tax loss, and the joint venture cascade reports it in cpr_deferred_to_next.", "It banks the loss for a year the engine appends automatically, and it raises the NPV from 13987603.31 by the relief in that year."]'::jsonb, 0, 'NPV is 13987603.31 with the row against 21590909.09 without it; the loss goes the way of jv_loss_unused_at_cessation''s 5000000.00, a memo line in no NPV.'::text, 'With the economic limit off, elt_off_tail_kept''s 2032 row sells 10000.00 bbl for 1000000.00 against 10000000.00 of opex, reports taxable income -14200000.00 and net cash flow -9200000.00. What two things does the kept row do to the ledger?', '["It banks a 14200000.00 loss with no year after it to spend it, and it hands the IRR a terminal negative, so the rate comes back as null with a status.", "It relieves the 14200000.00 against the 2031 tax of 32500000.00 by carrying the loss backward into that year, and that relief is why NPV reads 13987603.31 rather than 21590909.09.", "It forfeits the 14200000.00 as a CPR deferral rather than as a tax loss, and the joint venture cascade reports it in cpr_deferred_to_next.", "It banks the loss for a year the engine appends automatically, and it raises the NPV from 13987603.31 by the relief in that year."]'::jsonb, 0, 'NPV is 13987603.31 with the row against 21590909.09 without it; the loss goes the way of jv_loss_unused_at_cessation''s 5000000.00, a memo line in no NPV.'::text),
      ('advanced', 'final', null::text, 8, 'applyPSC on 100000000.00 of revenue with a 10 percent royalty and a 0.400000 cap recovers 36000000.00. Why not 40000000.00?', '["The cap is a share of the pool of 80000000.00 rather than of revenue, and 40 percent of the pool is what came out.", "The recovery is reduced by the contractor''s profit share of 50 percent applied to the cost oil as well as to the profit oil.", "The 4000000.00 shortfall is the tax on the cost oil, which the engine deducts before reporting the recovery.", "The cap is a share of revenue after royalty, not of the gross."]'::jsonb, 3, 'At 0.200000 the recovery is 18000000.00 and at 1.000000 it is the whole pool of 80000000.00, with profit oil moving down by the same steps as recovery moves up.'::text, 'applyPSC on 100000000.00 of revenue with a 10 percent royalty and a 0.400000 cap recovers 36000000.00. Why not 40000000.00?', '["The cap is a share of the pool of 80000000.00 rather than of revenue, and 40 percent of the pool is what came out.", "The recovery is reduced by the contractor''s profit share of 50 percent applied to the cost oil as well as to the profit oil.", "The 4000000.00 shortfall is the tax on the cost oil, which the engine deducts before reporting the recovery.", "The cap is a share of revenue after royalty, below the gross."]'::jsonb, 3, 'At 0.200000 the recovery is 18000000.00 and at 1.000000 it is the whole pool of 80000000.00, with profit oil moving down by the same steps as recovery moves up.'::text),
      ('advanced', 'final', null::text, 9, 'The marginal field royalty reads 0.062500 at 10000 bopd, exactly halfway between 0.050000 and 0.075000, but 0.106250 at 20000 bopd, which is not halfway to 0.150000. Why the difference?', '["The rate is an average across the year''s barrels: at 10000 bopd the two lower tiers split the barrels evenly, and at 20000 the first 10000 bopd are still priced at those tiers while only the rest pays 15 percent.", "The 20000 bopd row has crossed the deep offshore step at 50000 bopd, which lifts the top tier to 0.075000 for the barrels above it.", "The blend uses a geometric mean above 10000 bopd and an arithmetic one below it.", "The 15 percent tier only opens at 50000 bopd, so at 20000 bopd the rate is still a blend of the two lower tiers weighted by revenue."]'::jsonb, 0, 'The marginal rate never reaches 0.150000; it approaches from below, reading 0.132500 at 50000 bopd and 0.142708 at 120000.'::text, 'The onshore royalty reads 0.062500 at 10000 bopd, exactly halfway between 0.050000 and 0.075000, but 0.106250 at 20000 bopd, which is not halfway to 0.150000. Why the difference?', '["The rate is an average across the year''s barrels: at 10000 bopd the two lower tiers split the barrels evenly, and at 20000 the first 10000 bopd are still priced at those tiers while only the rest pays 15 percent.", "The 20000 bopd row has crossed the deep offshore step at 50000 bopd, which lifts the top tier to 0.075000 for the barrels above it, and the onshore table then borrows that tier for every barrel above 10000 bopd.", "The blend uses a geometric mean of the tier rates above 10000 bopd and an arithmetic mean below it, so the 20000 bopd reading falls short of the halfway point between the two tiers.", "The 15 percent tier only opens at 50000 bopd, so at 20000 bopd the rate is still a blend of the 5 and 7.5 percent tiers, weighted by each tier''s share of the year''s revenue."]'::jsonb, 0, 'The onshore rate never reaches 0.150000; it approaches from below, reading 0.132500 at 50000 bopd and 0.142708 at 120000. A marginal field is onshore or in shallow water and reads the same tranche table as any other field there.'::text),
      ('advanced', 'final', null::text, 10, 'cpr_forfeiture carries 40000000.00 of opex and 100000000.00 of capex over five recovery years against 80000000.00 of gross revenue, and prints cpr_cap 52000000.00. What is the 52000000.00 measured on?', '["The costs claimed: 65 percent of the opex plus the year''s fifth of the capex, so 52000000.00 is the most any year may recover and the rest becomes a tax loss.", "The gross revenue, at pia_cpr_limit_pct 65: a cap that is a share of revenue binds where costs approach revenue, and here it defers 8000000.00.", "The capex alone: the cap paces the 100000000.00 through the five recovery years, and opex is claimed outside it.", "The HCT assessable profit of 22987389.27, since the cap is a limit on deductions against profit rather than against revenue."]'::jsonb, 1, 'The worked example swept from 30 to 100 percent keeps 242500000.00 claimed at every setting because even 438000000.00 sits above the claim; the cap only exists where costs approach revenue, and the 8000000.00 deferred here is forfeited at cessation.'::text, 'cpr_forfeiture carries 40000000.00 of opex and 100000000.00 of capex over five recovery years against 80000000.00 of gross revenue, and prints cpr_cap 52000000.00. What is the 52000000.00 measured on?', '["The costs claimed: 65 percent of the opex plus the year''s fifth of the capex, so 52000000.00 is the most any year may recover and the rest becomes a tax loss.", "The crude oil and condensate revenue, at pia_cpr_limit_pct 65: the cap binds where costs approach that revenue, and here it defers 8000000.00.", "The capex alone: the cap paces the 100000000.00 through the five recovery years, and opex is claimed outside it.", "The HCT assessable profit of 13987213.60, since the cap is a limit on deductions measured against profit rather than against any revenue line."]'::jsonb, 1, 'The case sells no gas, so its crude revenue is its gross revenue of 80000000.00 and 65 percent of it is 52000000.00. The cap limits only the costs claimed against the hydrocarbon tax, and the 8000000.00 it defers here is forfeited at cessation because the ledger has no later year.'::text),
      ('advanced', 'final', null::text, 11, 'pia_loss_relief has a 2025 base year and rows in 2025 and 2026. Its 2026 row prints pia_only and pays TET 5755415.35. What does that reveal about the date trigger?', '["It reads each row''s year, and 2026 is still inside the grace year the framework allows before the levy applies.", "It is disabled whenever a loss pool is being relieved, so the row stays under the framework the loss was banked in.", "It reads the base year, not the row year, and the framework chosen once is inherited by every row.", "It switched the framework but the TET column is where the engine prints the levy on a ledger that began under the Act."]'::jsonb, 2, 'A base year of 2026 on auto selects nta_2025 by the date alone, and a ledger based in 2026 would have paid the levy; the same holds on pia_cpr_carry_two_years, 2025 to 2027 all pia_only.'::text, 'pia_loss_relief has a 2025 base year and rows in 2025 and 2026. Its 2025 row prints pia_only, and its 2026 row prints nta_2025 with TET 0.00 and a development levy of 12098579.71. What does that reveal about the date trigger?', '["It reads the base year, so a 2025 base year on auto should have kept both rows under the Act; the 2026 row is the override misfiring.", "It is disabled whenever a loss pool is being relieved, so the relief year stays under the framework in which the loss was first banked.", "It reads each row''s year of assessment, so one ledger based in 2025 carries a PIA year and then an NTA year where the levy replaces TET.", "It switched the framework only because the loss pool ran out in 2025; a ledger still relieving a loss would stay where it began."]'::jsonb, 2, 'The framework is chosen for each year of assessment: 2025 is a year under the Act and 2026 a year under the Nigeria Tax Act 2025, whatever the base year. pia_cpr_carry_two_years shows the same split, pia_only in 2025 and nta_2025 in 2026 and 2027.'::text),
      ('advanced', 'final', null::text, 12, 'AKATA with a 60000000 lump sum in 2035 reports NPV 38666394.86, total tax 148425219.46 and IRR null, and its 2035 net cash flow is -29598201.95. Why is there no rate?', '["The IRR excludes the abandonment row, and a vector of six producing years with no outflow has no sign change to bracket a root.", "The rate was computed on the pre-tax flows because the lump sum is undeductible, and a pre-tax vector never turns negative.", "The NPV of 38666394.86 is positive at every sampled rate, so no rate zeroes it.", "The final flow changed sign, and since engines 3.10.0 a rate is named only where exactly one rate in the band from -99 to 1000 percent zeroes the NPV."]'::jsonb, 3, 'Until that repair the same run printed a rate, one root of a curve that had another; at 200000000 the final flow is -169598201.95 and the IRR is null for the opposite reason, the NPV being negative at every sampled rate, -40359955.35 at the applied rate. The tax total never moves because the lump sum is post-tax.'::text, 'AKATA with a 60000000 lump sum in 2035 reports NPV 38666394.86, total tax 148425219.46 and IRR null, and its 2035 net cash flow is -29598201.95. Why is there no rate?', '["The IRR excludes the abandonment row, and a vector of six producing years with no outflow has no sign change to bracket a root.", "The rate was computed on the pre-tax flows because the lump sum is undeductible, and a pre-tax vector never turns negative.", "The NPV of 38666394.86 is positive at every sampled rate, so no rate zeroes it.", "The final flow changed sign, and a rate is named only where exactly one rate between -99 and 1000 percent zeroes the NPV."]'::jsonb, 3, 'A terminal negative gives the flows a second sign change and the NPV curve more than one root in the band, so the engine returns null with a status. At 200000000 the final flow is -169598201.95 and the IRR is null for the opposite reason, the NPV being negative at every sampled rate, -40359955.35 at the applied rate. The tax total never moves because the lump sum is post-tax.'::text),
      ('advanced', 'final', null::text, 13, 'AKATA under the PIA reports NPV 43223505.88 in shallow water, 128984232.18 at an oil price of 120, and 141623594.88 in deep offshore under the conservative reading. What does that comparison tell a negotiator?', '["That the price is the bigger lever, since a market move is worth more than any word in the fiscal terms.", "That the two moves are the same size, because deep offshore lowers only the royalty and a price rise lifts revenue by as much.", "That the terrain string is a price effect in disguise, since a lower royalty rate acts exactly like a higher realised price on every barrel.", "That a word in the document outweighs the market: the terrain string moves NPV further than the price sweep to 120."]'::jsonb, 3, 'Deep offshore under the conservative reading lowers the production royalty rate and zeroes the HCT, which lifts NPV to 141623594.88, further than the 128984232.18 an oil price of 120 buys. A cap, a lease status or a reading moves NPV further than the market, and those are words in a document.'::text, 'AKATA under the PIA reports NPV 59766796.57 in shallow water, 153901708.13 at an oil price of 120, and 136554243.51 in deep offshore under the conservative reading of the deep offshore hydrocarbon tax, a reading the texts leave open. What does the comparison tell a negotiator?', '["That the terrain string moves NPV further than the price sweep to 120, so the words in the fiscal terms outweigh the market on this field.", "That the two moves are the same size, because deep offshore lowers only the royalty and a price rise lifts the revenue by exactly as much.", "That the terrain string is a price effect in disguise, since a lower royalty rate acts like a higher realised price on every barrel.", "That a word in the document comes close to the market: the terrain string adds about 76.8 million against about 94.1 million for the price."]'::jsonb, 3, 'Deep offshore under the conservative reading lowers the liquids royalty rate to 0.050000 and sets the hydrocarbon tax to 0.00, which lifts NPV to 136554243.51; an oil price of 120 lifts it to 153901708.13. The reading itself is open, so a negotiator states it beside the number; under that reading the words of the terms move value almost as far as the market does.'::text),
      ('advanced', 'final', null::text, 14, 'On cpr_forfeiture the two-thirds CIT restriction refuses part of the allowance, cpr_deferred_to_next reads 8000000.00, and the ledger ends: CPR forfeited at cessation 8000000.00. Which of the unclaimed value on that row would a further year have rescued?', '["Both of them, since the CPR deferral would have met the next year''s cap and the refused allowance is carried too, so only a ledger that stops here loses either.", "The CPR deferral only, since this engine has never carried what the two-thirds restriction refuses and the Act carries it alone.", "The refused allowance only, which is deferred exactly one year and then claimed opex-first, while a CPR deferral is extinguished at each year end and never reaches the next cap.", "Neither, because a single-year field forfeits everything and a second year would start a fresh cascade with its own cap."]'::jsonb, 0, 'pia_cpr_carry_two_years carries 22000000.00, 44000000.00 and 66000000.00 across three binding years and forfeits the 66000000.00 at cessation; the allowance carry is priced by pia_cit_allowance_restricted_carry at NPV -113389070.73 against pia_cit_allowance_no_carry at -115209545.41.'::text, 'On cpr_forfeiture the two-thirds CIT restriction refuses part of the allowance, cpr_deferred_to_next reads 8000000.00, and the ledger ends: CPR forfeited at cessation 8000000.00. Which of the unclaimed value on that row would a further year have rescued?', '["Both of them, since the CPR deferral would have met the next year''s cap and the refused allowance is carried too, so only a ledger that stops here loses either.", "The CPR deferral only, since this engine has never carried what the two-thirds restriction refuses and the Act carries it alone.", "The refused allowance only, which is deferred exactly one year and then claimed opex-first, while a CPR deferral is extinguished at each year end and never reaches the next cap.", "Neither, because a single-year field forfeits everything and a second year would start a fresh cascade with its own cap."]'::jsonb, 0, 'pia_cpr_carry_two_years carries 22000000.00, 44000000.00 and 66000000.00 across three binding years and forfeits the 66000000.00 at cessation; the allowance carry is priced by pia_cit_allowance_restricted_carry at NPV -102455984.11 against pia_cit_allowance_no_carry at -116276490.72.'::text),
      ('advanced', 'final', null::text, 16, 'The worked example sells at 80.000000 in 2025 and pays a price royalty of 34905145.759897 on 1460000000.00 of gross revenue. A reader prices it at the 2021 rate for 80 USD. What does the reader get?', '["The same figure, because the anchors are fixed by the 2021 Act and the escalator applies only to the price, not to the schedule.", "0.023908, because the 2021 table already carries the 2025 escalation for a field whose base year is 2025.", "0.030000 rather than the 0.023908 the engine applies, an overstated royalty and both tax bases downstream understated, with the error growing every year the field runs.", "0.050000, the rate at the 100 anchor, because the engine rounds the price up to the next anchor before reading the rate."]'::jsonb, 2, 'The anchor prices escalate at 2 percent a year from 2021, so the same nominal price earns a smaller rate every year: 80 USD reads 0.030000 in 2021, 0.023908 in 2025 and 0.010630 in 2035.'::text, 'The worked example sells at 80.000000 in 2025 and pays a price royalty of 34908351.810791 on 1460000000.00 of gross revenue, on the Regulations (2021) benchmark base, the engine default. A reader prices it at the 2021 rate for 80 USD. What does the reader get?', '["The same figure, because the benchmarks are fixed by the 2021 Act and the 2 percent escalator applies only to the price and never to the schedule itself.", "0.023910, because the 2021 table already carries the 2025 escalation for any field whose base year is 2025, so the reader and the engine agree to the cent.", "0.030000 rather than the 0.023910 the engine applies, an overstated royalty and both tax bases understated, the error growing every year the field runs.", "0.050000, the rate at the 100 benchmark, because the engine rounds the price up to the next benchmark before it reads any rate off the whole schedule."]'::jsonb, 2, 'On the Regulations base the benchmarks escalate at 2 percent a year from 2021 levels, so the same nominal price earns a smaller rate every year: 80 USD reads 0.030000 in 2021, 0.023910 in 2025 and 0.010632 in 2035. The Act reads the same benchmarks as 2020 levels, an open question the course prints beside this one and never grades.'::text),
      ('advanced', 'final', null::text, 17, 'A new shallow water lease with 1000000 bbl at 30 USD per barrel and no prior production earns an allowance of 6000000.00 rather than 8000000.00, and prod_alw_cap_applied reads false. Which rule cut the allowance, and what did the flag say about it?', '["The volume cap, read on lifetime barrels, which trimmed the eligible barrels; the flag reads false because a lease with no prior production has not yet reached 100000000 bbl.", "The 20 percent of price limit, which at 30 USD sits below the 8 USD new lease rate; the flag reports the volume cap only and stayed false.", "The converted lease rate of 2.5 USD per barrel, which the engine falls back to when the price is below the 50 anchor; the flag confirms that no cap of either kind acted.", "The two thirds restriction, which limits the allowance to two thirds of the assessable profit; the flag is false because that restriction is reported on the CIT line instead."]'::jsonb, 1, 'computeProductionAllowance prints cap applied false on every price-limited row, 2000000.00 on a converted lease at 10 USD as well; the flag is only ever true for a new lease that reaches its volume cap, 500000.00 eligible bbl from a prior 99500000.'::text, 'A new shallow water lease with 1000000 bbl at 30 USD per barrel and no prior production earns an allowance of 6000000.00 rather than 8000000.00, and prod_alw_cap_applied reads false. Which rule cut the allowance, and what did the flag say about it?', '["The volume cap, read on lifetime barrels, which trimmed the eligible barrels; the flag reads false because a lease with no prior production has not yet reached 100000000 bbl.", "The 20 percent of price limit, which at 30 USD sits below the 8 USD new lease rate; the flag reports the volume cap only and stayed false.", "The converted lease rate of 2.5 USD per barrel, which the engine falls back to when the price is below the 50 anchor; the flag confirms that no cap of either kind acted.", "The two thirds restriction, which limits the allowance to two thirds of the assessable profit; the flag is false because that restriction is reported on the CIT line instead."]'::jsonb, 1, 'computeProductionAllowance prints cap applied false on every price-limited row, 2000000.00 on a converted lease at 10 USD as well; the flag is true only in a year that reaches the new-lease volume cap, where at 80 USD from a prior 99500000 the 1000000 bbl split 500000.00 below the cap and 500000.00 after it, for 6000000.00.'::text),
      ('advanced', 'final', null::text, 20, 'The worked example forced to nta_2025 at a 2025 base year pays a levy of 41599794.17, and on auto at a 2026 base year 41684425.66. A reader attributes the whole difference to the framework. What actually moved the levy?', '["The framework: the levy rate is read from the base year, and a 2026 base year carries a slightly higher levy rate than a forced 2025 one.", "The discounting: a 2026 base year discounts the levy one year less, which the KPI line reports as the higher figure.", "Not the framework, which is nta_2025 both times, but the price royalty anchors, which escalated a year further and lowered the royalty to 215289358.59, raising the assessable profit the levy follows.", "The HCDT: a second year of opex history raises the prior-year levy and the assessable profit with it."]'::jsonb, 2, 'The price royalty falls from 34905145.759897 to 32789358.588134, HCT rises to 285445692.42 and CIT to 294633192.42, and NPV moves from 119585647.53 to 120347330.91.'::text, 'The worked example forced to nta_2025 at a 2025 base year pays a levy of 42329665.93, and on auto at a 2026 base year 42414115.94, with the price royalty on the Regulations (2021) benchmark base, the engine default. A reader attributes the whole difference to the framework. What actually moved the levy?', '["The framework: the levy rate is read from the base year, and a 2026 base year carries a slightly higher levy rate than a 2025 base year forced to the same framework.", "The discounting: a 2026 base year discounts the levy one year less than a 2025 one, and the KPI line reports that smaller discount as the higher levy figure.", "The price-royalty benchmarks, which escalated a year further and lowered the royalty to 197047101.45; the framework is nta_2025 both times.", "The HCDT: a second year of opex history raises the prior-year levy, and the assessable profit and the development levy that follows it rise along with it."]'::jsonb, 2, 'The price royalty falls from 34908351.810791 to 32797101.449275, HCT rises to 286418369.57 and CIT to 300105869.57 on the larger assessable profit the levy follows, and NPV moves from 130654493.35 to 131414543.48.'::text),
      ('advanced', 'final', null::text, 22, 'AKATA''s 2029 row sells oil and gas for 186032000.00 of gross revenue at an oil price of 82.000000 and prints a price royalty of 3605512.362941. A reader who applies the year''s rate to the whole 186032000.00 lands above it. Which revenue does the price royalty charge?', '["The gross revenue less the production royalty of 22944240.00, which is the revenue after the first royalty and therefore the base of the second one.", "The oil and gas together, with the gas converted at 6 Mscf per barrel of oil equivalent and priced at the year''s oil price of 82.000000.", "The oil revenue alone: the price royalty reads the oil price and charges the oil, and the gas inside the gross revenue carries none of it.", "The revenue after HCDT and NDDC, since the levies come off before any royalty and the smaller base explains the smaller figure."]'::jsonb, 2, 'pia_gas_only_hct_zero has no oil and prints price_royalty 0.000000 beside a production royalty of 6300000.00 on 90000000.00 of gas revenue; on AKATA at 92.345318 in 2035 the price royalty is 1421137.383868 on 73325786.51, falling with the barrels because the anchors escalate at the same 2 percent as the price.'::text, 'AKATA''s 2029 row sells oil and gas for 186032000.00 of gross revenue at an oil price of 82.000000 and prints a price royalty of 3606152.270399 on the Regulations (2021) benchmark base, the engine default. A reader who applies the year''s rate to the whole 186032000.00 lands above it. Which revenue does the price royalty charge?', '["The gross revenue less the production royalty of 10070350.00, which is the revenue left after the first royalty and therefore the base of the second one.", "The oil and gas together, with the gas converted at 6 Mscf per barrel of oil equivalent and priced at the year''s oil price of 82.000000.", "The oil revenue alone: the price royalty reads the oil price and charges the oil, and the gas inside the gross revenue carries none of it.", "The revenue after HCDT and NDDC, since the levies come off before any royalty and the smaller base explains the smaller figure."]'::jsonb, 2, 'pia_gas_only_hct_zero has no oil and prints price_royalty 0.000000 beside a production royalty of 4500000.00 on 90000000.00 of gas revenue; on AKATA at 92.345318 in 2035 the price royalty is 1421219.023426 on a smaller oil revenue, falling with the barrels because the benchmarks escalate at the same 2 percent as the price.'::text),
      ('advanced', 'final', null::text, 23, 'pia_gas_only_hct_zero reports hct_assessable_profit 0.00 and NPV 17380000.00; with pia_hct_include_gas_revenue true the base becomes 68600000.00, HCT 19380000.00 and NPV -2000000.00. Which run reads the Act as the engine understands it?', '["The second: gas is a hydrocarbon and the default of excluding it is an omission the hatch corrects.", "The first: the hydrocarbon tax base is liquids, oil and condensate, with gas left out, and the hatch is a legacy escape that rebuilds the base on the whole revenue.", "Neither: gas carries its own HCT rate in the table, and both runs apply the liquids rate to it by mistake.", "Both, because the engine charges HCT on gas at 0.000000 in the first and at 0.300000 in the second, and the terrain decides which."]'::jsonb, 1, 'CIT is still 14880000.00 on a cit_chargeable_profit of 49600000.00 in both runs; on AKATA the gas revenue and its royalty are out of the HCT base of 130971072.31 and in the CIT base of 134762247.64.'::text, 'pia_gas_only_hct_zero, a gas-only field, reports hct_assessable_profit 0.00, HCT 0.00 and NPV 18318000.00. pia_gas_only_legacy_hct, the same field with pia_hct_include_gas_revenue true, reports the same three figures. What does the pair show about the hydrocarbon tax?', '["That the flag failed to load from the case, since gas is a hydrocarbon and a working flag would have put the gas revenue into the base.", "That its base is crude oil and condensate, so a field selling only gas has no base, and the flag leaves the default path as it is.", "That gas carries its own hydrocarbon tax rate of 0.000000 in the rate table, which is why moving the gas into the base changes nothing.", "That both runs tax the gas at the terrain''s rate and report it inside the CIT line, which is why CIT reads 15420000.00 in both of them."]'::jsonb, 1, 'The hydrocarbon tax is charged on crude oil and condensate, so the gas-only field''s HCT base is 0.00 in both runs, while CIT is 15420000.00 on a cit_chargeable_profit of 51400000.00 in both. On AKATA in 2029 the gas revenue and its royalty are out of the HCT assessable profit of 136924208.42 and in the CIT assessable profit of 141335497.73.'::text),
      ('advanced', 'final', null::text, 25, 'jv_abandonment_wi_60 charges the entered 10000000.00 in full against 60 percent flows, and pia_sinking_fund_wi_50 collects 30000000.00 against a total_abandonment_cost of 30000000.00. What is abandonment_cost_usd under each funding mode?', '["A share-level number under a lump sum and a field-level one under a fund, so the fund at a 50 percent interest collects only half of what was entered.", "The share under both, since engines 3.10.0 grossed the fund by one over the working interest so that it collects exactly what was entered.", "A field-level number under both, scaled by the working interest on the way into the ledger.", "A field-level number under a lump sum and a share-level one under a fund, so a partner must halve the entry before switching modes."]'::jsonb, 2, 'Until that repair the fund collected half and pia_sinking_fund_wi_50 read a higher NPV than the 55592785.17 it reports now; the unit technical cost of jv_abandonment_wi_60 is 43.333333 against 40.000000 at a full interest.'::text, 'jv_abandonment_wi_60 charges the entered 10000000.00 in full against 60 percent flows, and pia_sinking_fund_wi_50 collects 30000000.00 against a total_abandonment_cost of 30000000.00. What is abandonment_cost_usd under each funding mode?', '["A share-level number under a lump sum and a field-level one under a fund, so the fund at a 50 percent interest collects only half of what was entered.", "Field-level under both, scaled by the working interest on the way into the ledger, so a 50 percent partner''s fund collects half the entry.", "The share under both: the engine charges the amount as entered, so a partner enters its own share of the cost whichever mode it picks.", "Under a lump sum a field-level number and under a fund a share-level one, so a partner must halve the entry before switching modes."]'::jsonb, 2, 'Both published cases carry the entered figure unscaled: jv_abandonment_wi_60 charges 10000000.00 against 60 percent flows, which is why its unit technical cost reads 43.333333, and pia_sinking_fund_wi_50 collects 30000000.00 and reports NPV 59518454.92. A partner enters its own share under either mode.'::text),
      ('advanced', 'final', null::text, 26, 'AKATA under the PIA is NPV 43223505.88. Write the sentence that names it.', '["43223505.88 at 10 percent nominal, mid-year, base year 2029, framework pia_only, shallow water, new lease.", "43223505.88 on the real basis, end-year, base year 2029, framework nta_2025, shallow water, converted PML, conservative reading.", "43223505.88 on the real basis, end-year, base year 2029, framework nta_2025, deep offshore, converted PML, aggressive reading.", "43223505.88 on the real basis, end-year, base year 2025, framework pia_only, shallow water, converted PML."]'::jsonb, 1, 'Every one of those words is a lever the ledger has shown moving: forced to pia_only the same rows report 49802016.74, and deep offshore conservative 141623594.88.'::text, 'AKATA under the PIA, with the price royalty on the Regulations (2021) base, the engine default, is NPV 59766796.57. Write the rest of the sentence that names it.', '["59766796.57 at 10 percent nominal, mid-year, base year 2029, framework pia_only, shallow water, new lease.", "59766796.57 on the real basis, end-year, base year 2029, framework nta_2025, shallow water, converted PML.", "59766796.57 on the real basis, end-year, base year 2029, framework nta_2025, deep offshore, converted PML, aggressive reading.", "59766796.57 on the real basis, end-year, base year 2025, framework pia_only, shallow water, converted PML, no escalation."]'::jsonb, 1, 'Every one of those words is a lever the ledger has shown moving: forced to pia_only the same rows report 63590226.39, and deep offshore under the conservative reading 136554243.51.'::text),
      ('advanced', 'final', null::text, 27, 'pia_sinking_fund''s 30000000.00 contribution lowers HCT from 284810956.27 to 275810956.27 and CIT from 293998456.27 to 284998456.27 while TET stays 25999871.36. Which bases received the contribution?', '["The HCT chargeable profit and the CIT chargeable profit, each at its own rate; the levy base, the assessable profit, is untouched.", "The HCT base only, with the CIT change following because CIT is charged on the profit after HCT.", "All three bases, with the TET unchanged only because it is rounded to the nearest cent.", "The HCDT and NDDC lines, which are opex-based and so absorb an opex-lane contribution first."]'::jsonb, 0, 'The contribution rides the opex lane and relieves the two profit taxes at their rates and nothing else; NPV falls from 135185570.34 to 123185570.34.'::text, 'pia_sinking_fund''s 30000000.00 contribution lowers HCT from 285784994.46 to 276784994.46, CIT from 299472494.46 to 290472494.46 and TET from 31747249.45 to 30847249.45. Which bases received the contribution?', '["The HCT and CIT assessable profits, each 30000000.00 lower, so HCT, CIT and TET all fall at their own rates.", "The HCT base only, with the CIT change following because CIT is charged on the profit left after the hydrocarbon tax.", "The cash flow alone, as a post-tax transfer into the fund, with the tax lines moving because the fund''s own earnings are taxed in the year.", "The HCDT and NDDC lines, which are opex-based and so absorb an opex-lane contribution before either profit tax sees any of it."]'::jsonb, 0, 'The contribution rides the opex lane: both assessable profits fall from 1058241648.19 to 1028241648.19, so HCT and CIT each fall by 9000000.00 at 30 percent and TET by 900000.00 at 3 percent. NPV falls from 141236909.83 to 130136909.83.'::text),
      ('advanced', 'final', null::text, 29, 'pia_deep_offshore_wi_50 halves every monetary line and reports NPV 445282165.97, exactly half of 890564331.93, while pia_deep_offshore_naive_30k halves the upload instead and reports 372530915.97. Where does the naive run lose the difference?', '["It loses the production allowance, which the engine grants only above the 50000 bopd threshold.", "It is discounted for one more year because the smaller field is assumed to start later.", "It pays HCT at 0.300000, since the conservative reading only applies above the deep offshore threshold.", "At half the daily rate it falls into the 0.050000 tier, so its royalty is 43800000.00 rather than half of 131400000.00, and it still bears the full 100000000.00 of capex and opex and the full levies."]'::jsonb, 3, 'Two errors in opposite directions, and neither cancels the other: the royalty is understated and the costs overstated, and take reads 44.8919 percent against 42.6183.'::text, 'pia_deep_offshore_wi_50 halves every monetary line and reports NPV 453861842.57, exactly half of 907723685.14, while pia_deep_offshore_naive_30k halves the upload instead and reports 369073842.57. Where does the naive run lose the difference?', '["It loses the production allowance, which the engine grants to a deep offshore lease only in a year whose daily rate stays above the 50000 bopd threshold.", "One more year of discounting, because the engine assumes a field half the size starts a year later and pushes every row back by one.", "Through HCT charged at 0.300000, since the conservative reading of the deep offshore tax only applies to a field producing above the 50000 bopd threshold.", "At half the daily rate every barrel carries 0.050000, so its royalty is 43800000.00 against 47450000.00, and it still bears the full capex, opex and levies."]'::jsonb, 3, 'Two errors in opposite directions, and neither cancels the other: the royalty is understated because 30000 bopd never reaches the 7.5 percent share, and the costs are overstated because 100000000.00 of capex and of opex are borne in full; take reads 45.4033 percent against 41.5126.'::text),
      ('advanced', 'final', null::text, 30, 'cpr_forfeiture has cit_assessable_profit 7987389.27, cit_chargeable_profit 2662463.09 and cit_tax 798738.93, and its ledger is one year long. Where does the allowance the two-thirds restriction refused reappear?', '["In cpr_deferred_to_next, which reads 8000000.00 and is the restricted allowance waiting for the next year.", "In hct_loss_carryforward, since the HCT on the same row is charged on 8487389.27 without the restriction and the difference is banked there.", "Nowhere on this ledger: the engine carries it since 3.10.0, but a single year has no later year for the carryforward to be claimed in.", "Nowhere on any ledger, because this engine has never carried what the restriction refuses."]'::jsonb, 2, 'The 8000000.00 in cpr_deferred_to_next is the CPR cap''s deferral, a different mechanism; pia_cit_allowance_restricted_carry claims its carried allowance the following year and reports NPV -113389070.73 against -115209545.41 with the carry switched off.'::text, 'cpr_forfeiture has cit_assessable_profit 13987213.60, cit_chargeable_profit 4662404.53 and cit_tax 1398721.36, and its ledger is one year long. Where does the allowance the two-thirds restriction refused reappear?', '["In cpr_deferred_to_next, which reads 8000000.00 and is the restricted allowance waiting for the next year.", "In hct_loss_carryforward, since the HCT on the same row is charged without the restriction and the difference between the two bases is banked there.", "In cit_allowance_carryforward, 10675190.93, which a one-year ledger never claims because it has no later year to claim it in.", "Nowhere on any ledger, because this engine has never carried what the restriction refuses."]'::jsonb, 2, 'The 8000000.00 in cpr_deferred_to_next is the CPR cap''s deferral, a different mechanism. The restriction limits the allowance to two thirds of the assessable profit before 2026 and carries the excess forward; pia_cit_allowance_restricted_carry claims its carried allowance the following year and reports NPV -102455984.11 against -116276490.72 with the carry switched off.'::text),
      ('advanced', 'final', null::text, 31, 'With pia_apply_minimum_etr true at 85 percent the worked example''s total tax becomes 883995626.10, which is 85 percent of 1039994854.24, through a top-up of 279186342.20. Which taxes did the floor treat as already paid?', '["Only HCT and CIT, 284810956.27 plus 293998456.27, which is why the top-up is so large.", "HCT, CIT and TET, because royalty is charged on revenue and cannot count toward an effective rate on profit.", "All 604809283.90 of them, royalty and the levies included.", "Only the taxes on the chargeable profit of 979994854.24, the profit that the floor is measured against."]'::jsonb, 1, 'The 604809283.90 in the tax column is HCT 284810956.27 plus CIT 293998456.27 plus TET 25999871.36, with royalty 217405145.76, HCDT and NDDC outside it; test the floor against HCT plus CIT alone and the shortfall comes out larger than 279186342.20, and the top-up is charged on a profit measured before capex, so net cash flow becomes -144000771.86 and take 114.7315 percent.'::text, 'With pia_apply_minimum_etr true at 85 percent, min_etr_85 still reports total tax 617004738.36, NPV 141236909.83 and take 85.5512 percent, the worked example''s own figures. Why did an 85 percent floor add nothing?', '["Because 85 percent sits below the effective rate the year already pays, the HCT, CIT and TET together clearing 85 percent of the profit.", "Because the engine applies the floor only to years under the NTA, and 2025 is a year under the Act, which charges TET and has no floor.", "Because the floor counts the royalty as tax, and with the royalty of 199158351.81 added the year''s taxes clear the 85 percent on their own.", "Because the top-up is computed but written only into the engine statements, and the tax column is never allowed to carry it."]'::jsonb, 1, 'The engine states that its top-up is a project-level approximation of NTA s.57 applied only to years under the NTA and reported on its own line. min_etr_85 and min_etr_not_binding both read framework pia_only with TET 31747249.45 and no top-up, and their totals match the worked example to the cent.'::text),
      ('advanced', 'final', null::text, 32, 'AKATA at a three-year shift has no 2031 row. NPV falls from 40880824.32 to 17894126.42 and IRR falls from 14.6753 to 11.6363 percent, both as they should, yet payback shortens from 4.96 to 4.90 years. What does the shortening payback tell a reader?', '["That the delay improved the field, because the later rows sell at escalated prices of 87.019056 and beyond and the capex was shifted with them, so the 255000000.00 is a year cheaper on present value and the crossing arrives sooner.", "That the engine emitted an empty 2031 row with zero flow and the extra row diluted the cumulative sum, so the crossing was interpolated over ten rows instead of nine and moved in the field''s favour.", "That the loss pool of 21000000.00 was spent in the delayed first year and brought the crossing forward.", "That payback is counted on rows rather than on calendar years, so the missing row made the delay look shorter to it; the NPV is discounted on calendar years and can be trusted."]'::jsonb, 3, 'A longer wait for the same money cannot shorten a payback; capex is not shifted, the engine refuses to emit a row for an empty year, and until engines 3.10.0 the IRR of this run read 15.1070 percent and rose with the delay for the same reason.'::text, 'AKATA at a three-year shift has no 2031 row. NPV falls from 40880824.32 to 17894126.42 and IRR falls from 14.6753 to 11.6363 percent, both as they should, yet payback shortens from 4.96 to 4.90 years. What does the shortening payback tell a reader?', '["That the delay improved the field, because the later rows sell at escalated prices of 87.019056 and beyond and the capex was shifted with them, so the 255000000.00 is a year cheaper on present value and the crossing arrives sooner.", "That the engine emitted an empty 2031 row with zero flow and the extra row diluted the cumulative sum, so the crossing was interpolated over ten rows instead of nine and moved in the field''s favour.", "That the loss pool of 21000000.00 was spent in the delayed first year and brought the crossing forward.", "That payback is counted on rows rather than on calendar years, so the missing row made the delay look shorter to it; the NPV is discounted on calendar years and can be trusted."]'::jsonb, 3, 'A longer wait for the same money cannot shorten a payback; capex is not shifted, the engine refuses to emit a row for an empty year, and a payback counted on rows reads the missing year as no time at all.'::text),
      ('advanced', 'final', null::text, 34, 'AKATA in deep offshore reports 61725382.46 under the aggressive reading and 141623594.88 under the conservative one, with royalties of 59501441.00 in both, against 43223505.88 in shallow water. How much of the conservative gain is royalty and how much is the hydrocarbon tax?', '["The royalty alone takes 43223505.88 to 61725382.46, since the aggressive reading keeps the HCT rate at 0.300000; the reading of the HCT rule takes it the rest of the way to 141623594.88.", "It is all royalty: the HCT rate is 0.000000 in deep offshore under either reading, and the two figures differ by the CIT the readings charge, since the aggressive reading moves the CIT rate rather than the HCT rate.", "It is all hydrocarbon tax: the production royalty is 0.125000 in every offshore terrain and only the price royalty moved, so the 59501441.00 of royalties in deep offshore is the shallow water figure less the price component alone.", "The two cannot be separated, because the terrain string sets one blended fiscal rate that the engine does not decompose."]'::jsonb, 0, 'The 2029 production royalty is 9301600.00 in deep offshore against 22944240.00 in shallow water, and HCT is 29481778.65 aggressive against 0.00 conservative; the terrain string moves NPV further than the price sweep from 82 to 120.'::text, 'AKATA in deep offshore reports 60060654.75 under the aggressive reading and 136554243.51 under the conservative one, two readings the texts leave open, with royalties of 59503845.87 in both, against 59766796.57 in shallow water. How much of the conservative gain is royalty and how much is the hydrocarbon tax?', '["The royalty alone takes 59766796.57 to 60060654.75, since the aggressive reading keeps HCT at 0.300000; the HCT reading takes it the rest of the way.", "It is all royalty: the HCT rate is 0.000000 in deep offshore under either reading, and the two figures differ by the CIT the readings charge, since the aggressive reading moves the CIT rate rather than the HCT rate.", "It is all hydrocarbon tax: the production royalty is 0.125000 in every offshore terrain and only the price royalty moved, so the royalties differ by the price component alone.", "The two cannot be separated, because the terrain string sets one blended fiscal rate that the engine does not decompose."]'::jsonb, 0, 'The 2029 production royalty is 9301600.00 in deep offshore against 10070350.00 in shallow water, and HCT is 27439344.48 under the aggressive reading against 0.00 under the conservative one. Which reading applies to a deep offshore year under the NTA is left open by the texts, so the course prints both and grades neither.'::text),
      ('advanced', 'final', null::text, 35, 'AKATA under production sharing reports a take of 82.1085 percent at a 60 percent cost oil cap, at 80 and at 100, but 99.0577 at 45 and 120.4874 at 30. Why does the take stop moving above 60?', '["Above 60 percent the cap no longer binds in any year, so cost oil equals the year''s costs and the take is the royalty plus tax on a fixed profit oil.", "The engine caps the take at 82.1085 percent for production sharing, which is the royalty rate plus the tax rate blended at the contractor share.", "Once the pool clears inside the field''s life the cap only moves timing, and timing is what NPV and IRR price, not take.", "Above 60 percent the contractor share of profit oil steps down to hold the take constant, as the tranche mode requires once the pool has cleared."]'::jsonb, 2, 'At 60 percent the pool clears in 2034, at 80 in 2031 and at 100 in 2030; NPV still rises from 29960298.75 to 48148675.31 across the three because the money arrives sooner.'::text, 'AKATA under production sharing reports a take of 82.1085 percent at a 60 percent cost oil cap, at 80 and at 100, but 99.0577 at 45 and 120.4874 at 30. Why does the take stop moving above 60?', '["Above 60 percent the cap no longer binds in any year, so cost oil equals the year''s costs and the take is the royalty plus tax on a fixed profit oil.", "The engine caps the take at 82.1085 percent for production sharing, which is the royalty rate plus the tax rate blended at the contractor share.", "Once the pool clears inside the field''s life the cap only moves timing, and timing is what NPV and IRR price and take ignores.", "Above 60 percent the contractor share of profit oil steps down to hold the take constant, as the tranche mode requires once the pool has cleared."]'::jsonb, 2, 'At 60 percent the pool clears in 2034, at 80 in 2031 and at 100 in 2030; NPV still rises from 29960298.75 to 48148675.31 across the three because the money arrives sooner.'::text),
      ('advanced', 'final', null::text, 36, 'AKATA run as a marginal field cuts the 2029 production royalty from 22944240.00 to 10182990.00 but reports HCT of 29251153.65 against 25422778.65, and NPV 61154067.34 rather than a larger gain. Why did the tax take most of the royalty back?', '["The marginal blend charges the shortfall in royalty as HCT, since the two are reconciled at the end of the cascade.", "The marginal field pays the price royalty at the top tier, and the price royalty is charged inside the HCT column.", "The marginal terrain carries the highest gas royalty, and AKATA''s associated gas makes up the difference.", "The pre-2021 flag was not set, so the field pays HCT at 30 percent on a base the smaller royalty has left larger."]'::jsonb, 3, 'pia_marginal_field_blend sets the flag and pays 0.150000, 26361776.50 on 175745176.68; the blend does not switch the tax rate, the flag does.'::text, 'AKATA in shallow water with pia_marginal_field_pre_2021 true keeps its 2029 production royalty at 10070350.00 and pays HCT at 0.150000, 13604359.74 in 2029, for NPV 97891150.04 against 59766796.57 as a converted PML. What did the marginal field status change?', '["The royalty tranches, which fall to a marginal blend of 5 and 7.5 percent, and the lower HCT is the tax following the smaller royalty through the base.", "Both royalty and HCT, since marginal_field is a terrain of its own with its own royalty table and its own hydrocarbon tax rate.", "The production allowance, which a marginal field claims at the new-lease 8 USD/bbl, and the lower HCT is that larger allowance.", "The hydrocarbon tax rate alone: a marginal field converted under s.94(1) pays 15 percent, and the engine keeps its royalty on the shallow-water tranches."]'::jsonb, 3, 'A marginal field is onshore or in shallow water, and the engine refuses marginal_field as a terrain; the pre-2021 flag moves the HCT rate and nothing else. pia_marginal_field_blend, run onshore with the flag, pays HCT 24111699.56 at 0.150000, and the same case in shallow water returns the same totals.'::text),
      ('advanced', 'final', null::text, 37, 'AKATA under the PIA claims 66000000.00 against a cpr_cap of 120920800.00 in 2029, its 24000000.00 of opex plus a fifth of the 210000000.00 capex, and 75720000.00 against 103717068.00 in 2030 beside opex of 24720000.00. Why did the claim grow by more than the opex did?', '["The 45000000.00 of capex spent in 2030 started its own five-year recovery, so 2030 claims a fifth of both tranches beside its opex.", "The 2029 allowance was restricted to two thirds of the assessable profit and the disallowed third was carried into the 2030 claim, as the Act requires it to be.", "The cap fell from 120920800.00 to 103717068.00, and the engine claims the whole gap between cap and opex in any year the cap falls, so a lower cap raises the claim.", "The production allowance of 4625000.00 is claimed inside the CPR claim from the second year onward, and its arrival is the extra in 2030."]'::jsonb, 0, 'On the worked example the recovery years are the whole answer, 482500000.00 claimed at 1 and 212500000.00 at 10 against 242500000.00 at 5; on AKATA each tranche runs its own clock, and a field that stops before the years run out never claims the rest.'::text, 'AKATA under the PIA claims 64001892.15 against a cpr_cap of 117260000.00 in 2029 and 73427625.35 against 100577100.00 in 2030, while its opex rose only from 24000000.00 to 24720000.00. Why did the claim grow by more than the opex did?', '["The 45000000.00 of capex spent in 2030 started its own five-year allowance, so 2030 claims a fifth of both tranches beside its opex, at the crude share.", "The 2029 allowance was restricted to two thirds of the assessable profit and the disallowed third was carried into the 2030 claim, as the Act requires it to be.", "The cap fell from 117260000.00 to 100577100.00, and the engine claims the whole gap between cap and opex in any year the cap falls, so a lower cap raises the claim.", "The production allowance of 4625000.00 is claimed inside the CPR claim from the second year onward, and its arrival is the extra in 2030."]'::jsonb, 0, 'The capital allowance runs five years from each year''s spend, a fifth a year in NTA years, and the texts fix five years, so the engine refuses any other recovery life. On AKATA each tranche runs its own clock, costs shared with gas enter at the crude-plus-condensate share of revenue, and a field that stops before the years run out never claims the rest.'::text),
      ('advanced', 'final', null::text, 38, 'On the real basis AKATA''s applied rate is 6.796117 percent and the profile point that carries it is labelled 6.8. What does that point read?', '["The NPV at exactly 6.8 percent, which sits a little way under the headline, because the label is past the applied rate and NPV always falls as the rate rises.", "72534830.66, the headline itself: since engines 3.10.0 the point is labelled at the rounded rate and evaluated at the exact one, so the gap is 0.00.", "Whichever of the two the reader asks for, since the profile carries the labelled point and the exact one as a pair.", "A value interpolated between the 5 percent point of 83023565.60 and the 8 percent point of 65968275.69 rather than computed."]'::jsonb, 1, 'Until the repair of 2026-09-15 the point was evaluated at its label too, and eight published cases carried a gap, -40996.42 on multiyear_pia_real and -18628.18 on multiyear_jv_real among them; the golden now records 0 profile disagreements.'::text, 'On the real basis AKATA''s applied rate is 6.796117 percent and the profile point that carries it is labelled 6.8. What does that point read?', '["The NPV at exactly 6.8 percent, which sits a little way under the headline, because the label is past the applied rate and NPV always falls as the rate rises.", "72534830.66, the headline itself: the point is labelled at the rounded rate and evaluated at the exact one, so the gap between them is 0.00.", "Whichever of the two the reader asks for, since the profile carries the labelled point and the exact one as a pair.", "A value interpolated between the 5 percent point of 83023565.60 and the 8 percent point of 65968275.69 rather than computed."]'::jsonb, 1, 'The profile point that carries the applied rate is evaluated at the exact 6.796117 percent and only labelled 6.8, so it reads the headline NPV; the published golden records no profile disagreements.'::text),
      ('advanced', 'final', null::text, 39, 'AKATA on auto reports 43223505.88 with a levy of 5390489.91 in 2029; forced to pia_only it reports 49802016.74 with TET of 3369056.19. A reader writes 43223505.88 beside the word pia_only. What does the checklist say?', '["The headline passes, because the framework only changes the last line of the cascade and the NPV is reported before the levy is charged.", "The headline passes if the override was left on auto, since auto is neither framework and the label is a matter of convention.", "The headline fails: basis, convention and framework are written beside it, and 43223505.88 belongs to nta_2025.", "The headline fails only by the levy: subtract 21007007.79 and add 3369056.19 to move it to the pia_only figure, since the two frameworks share every other line."]'::jsonb, 2, 'Get the framework wrong and every row''s last line is wrong; one of tet_tax and dev_levy_tax is 0.00 on every row and the fiscal_framework column says which.'::text, 'AKATA on auto reports 59766796.57 with a levy of 5653419.91 in 2029; forced to pia_only it reports 63590226.39 with TET of 4240064.93. A reader writes 59766796.57 beside the word pia_only. What does the checklist say?', '["The headline passes, because the framework only changes the last line of the cascade and the NPV is reported before the levy is charged.", "The headline passes if the override was left on auto, since auto is neither framework and the label is a matter of convention.", "The headline fails: basis, convention and framework are written beside it, and 59766796.57 belongs to nta_2025.", "The headline fails only by the levy: take off the 2029 levy of 5653419.91 and add the TET of 4240064.93 to reach the pia_only figure, the two frameworks sharing every other line."]'::jsonb, 2, 'Get the framework wrong and every row''s last line is wrong; one of tet_tax and dev_levy_tax is 0.00 on every row, the fiscal_framework column says which, and the hydrocarbon tax moves with the framework as well.'::text),
      ('advanced', 'final', null::text, 41, 'The 2029 row of AKATA as a new lease is identical whether the prior cumulative is 0 or 96000000: allowance 17600000.00, cap applied false, HCT 21792778.65. Which reading in the working order catches the difference before the headline does?', '["The lease and reading step, followed by the totals: allowance 77440000.00 against 32000000.00 over the life, since the cap bites in later years.", "The framework step, since a lease with prior production is read under pia_only and one without under nta_2025.", "The 2029 row alone, whose cap applied flag reads true once the prior barrels are entered.", "The royalty step, because prior production lifts the field into the 0.075000 tier and the royalty totals differ, so the difference is in the royalty line rather than in the allowance."]'::jsonb, 0, 'NPV is 56241834.89 against 46513356.33 and HCT 61048493.72 against 74680493.72; the strings must be read from the case, not guessed from a rule of thumb.'::text, 'Run at a stated new-PML hydrocarbon tax rate of 30 percent, a reading the texts leave open, the 2029 row of AKATA as a new lease prints the same allowance, cap flag and hydrocarbon tax whether the prior cumulative is 0 or 96000000: allowance 17600000.00, cap applied false, HCT 23578719.48. Which reading in the working order catches the difference before the headline does?', '["The lease and reading step, followed by the totals: allowance 77440000.00 against 54720000.00 over the life, since the cap bites in later years.", "The framework step, since a lease with prior production is read under pia_only and one without under nta_2025.", "The 2029 row alone, whose cap applied flag reads true once the prior barrels are entered.", "The royalty step, because prior production lifts the field into the 0.075000 tier and the royalty totals differ, so the difference is in the royalty line rather than in the allowance."]'::jsonb, 0, 'At the stated rate NPV is 72785125.58 against 67920886.30 and HCT 75682840.32 against 82498840.32. The allowance totals are the same at a stated 15 percent, so they catch the cap whatever reading is stated; the strings must be read from the case.'::text),
      ('advanced', 'final', null::text, 42, 'psc_wi_50 halves oil_bbl to 500000.00 a year and reports total oil 1000000.00 bbl, while pia_deep_offshore_wi_50 halves oil_bbl to 10950000.00 but keeps cumulative_oil_bbl_lifetime at 21900000.00. Which ledger still remembers the field?', '["The PSC one: entitlement volumes are the field''s volumes scaled, and the tranche table is read on the field''s cumulative rather than the entitlement, so a 50 percent share still opens each year at the field''s tranche boundary.", "The PIA one: the working interest is applied to the money afterward, and cumulative_oil_bbl_lifetime and prod_alw_eligible_bbl keep the field''s barrels so the tier is read at 60000 bopd.", "Both, since each reports working_interest_pct and the engine can recover the field from a share when that column is set.", "Neither, because a scaled run has no field-level readout in either regime and the naive upload cannot be told from a small field."]'::jsonb, 1, 'Under a PSC the working interest is applied at the door and the rows are the share; under the PIA the royalty is still 0.075000 and half of 131400000.00 is 65700000.00, with take invariant at 42.6183 percent.'::text, 'psc_wi_50 halves oil_bbl to 500000.00 a year and reports total oil 1000000.00 bbl, while pia_deep_offshore_wi_50 halves oil_bbl to 10950000.00 but keeps cumulative_oil_bbl_lifetime at 21900000.00. Which ledger still remembers the field?', '["The PSC one: entitlement volumes are the field''s volumes scaled, and the tranche table is read on the field''s cumulative rather than the entitlement, so a 50 percent share still opens each year at the field''s tranche boundary.", "The PIA one: the working interest is applied to the money afterward, and cumulative_oil_bbl_lifetime and prod_alw_eligible_bbl keep the field''s barrels so the tier is read at 60000 bopd.", "Both, since each reports working_interest_pct and the engine can recover the field from a share when that column is set.", "Neither, because a scaled run has no field-level readout in either regime and the naive upload cannot be told from a small field."]'::jsonb, 1, 'Under a PSC the working interest is applied at the door and the rows are the share; under the PIA the liquids rate is still 0.054167 at 60000 bopd, half of 94900000.00 is 47450000.00, and take is invariant at 41.5126 percent.'::text),
      ('advanced', 'module', 'm01-cost-recovery'::text, 4, 'The one-year applyPSC case at the 0.4 cap is rerun with 30000000 brought forward from an earlier year. Cost recovered is still 36000000.00, profit oil still 27000000.00 and net still minus 30500000.00. What did the extra pool change?', '["The recovery rises to 66000000.00, because the cap is a share of the pool and a larger pool lets more cost oil out in the same year.", "Only the carried amount, from 44000000.00 to 74000000.00; a bigger pool does not recover faster, it waits.", "The profit oil, which is reduced by the brought-forward amount before the split so that the contractor''s tax falls while the cash is unchanged.", "The tax, because the brought-forward cost is deductible against the contractor''s profit oil in the year it arrives even though the cap refuses to recover it."]'::jsonb, 1, 'The cap is a ceiling on recovery per year, not on the pool, so 30000000 of extra cost changes nothing in the year except how much is carried out of it.'::text, 'The one-year applyPSC case at the 0.4 cap is rerun with 30000000 brought forward from an earlier year. Cost recovered is still 36000000.00, profit oil still 27000000.00 and net still minus 30500000.00. What did the extra pool change?', '["The recovery rises to 66000000.00, because the cap is a share of the pool and a larger pool lets more cost oil out in the same year.", "Only the carried amount, from 44000000.00 to 74000000.00; a bigger pool does not recover faster, it waits.", "The profit oil, which is reduced by the brought-forward amount before the split so that the contractor''s tax falls while the cash is unchanged.", "The tax, because the brought-forward cost is deductible against the contractor''s profit oil in the year it arrives even though the cap refuses to recover it."]'::jsonb, 1, 'The cap is a ceiling on recovery per year and leaves the pool unbounded, so 30000000 of extra cost changes nothing in the year except how much is carried out of it.'::text),
      ('advanced', 'module', 'm01-cost-recovery'::text, 12, 'psc_wi_50 reports total oil 1000000.00 bbl for a field that lifted 1000000 bbl in each of 2030 and 2031, and the rows carry oil_bbl 500000.00. Why has the volume halved with the money?', '["The engine halves the volumes because the cap binds in both years, and a binding cap converts half of the barrels into cost oil that is not counted as production.", "The production file was pre-scaled to 50 percent before upload, and the engine reads the halved barrels as the field''s production.", "Under a PSC the working interest is applied at the door, so the rows are the contractor''s share and the volumes are entitlement volumes, not field volumes.", "The oil_bbl column reports the barrels behind the contractor''s profit oil, and at a 50 percent profit share that is half the field''s production."]'::jsonb, 2, 'The joint venture ledger keeps field revenue and field volumes and applies the share later; the PSC ledger scales everything first, which is why NPV halves to minus 2295454.55 and take stays 101.0000.'::text, 'psc_wi_50 reports total oil 1000000.00 bbl for a field that lifted 1000000 bbl in each of 2030 and 2031, and the rows carry oil_bbl 500000.00. Why has the volume halved with the money?', '["The engine halves the volumes because the cap binds in both years, and a binding cap converts half of the barrels into cost oil that is not counted as production.", "The production file was pre-scaled to 50 percent before upload, and the engine reads the halved barrels as the field''s production.", "Under a PSC the working interest is applied at the door, so the rows are the contractor''s share and the volumes are entitlement volumes rather than field volumes.", "The oil_bbl column reports the barrels behind the contractor''s profit oil, and at a 50 percent profit share that is half the field''s production."]'::jsonb, 2, 'The joint venture ledger keeps field revenue and field volumes and applies the share later; the PSC ledger scales everything first, which is why NPV halves to minus 2295454.55 and take stays 101.0000.'::text),
      ('advanced', 'module', 'm01-cost-recovery'::text, 13, 'psc_sinking_fund adds abandonment_cost_usd 10000000 funded from 2031. The 2031 row shows decom_fund_contribution 10000000.00, net cash flow 29500000.00 against 39500000.00, and tax still 13500000.00. Where did the contribution go?', '["Into the recoverable cost lane, so it rides the pool as a cost to be recovered rather than being paid outside the contract.", "It was deducted from the contractor''s profit oil before tax, which is why the net fell by the full 10000000.00 while the taxable income stayed at 27000000.00.", "It was paid from the contractor''s profit oil after tax and shared with the state at the 50 percent profit split, leaving the contractor''s cash lower by the whole sum.", "It was charged as a lump sum in the last year of the field, and the sinking fund label only records that the money was set aside in 2031 rather than spent."]'::jsonb, 0, 'The tax is unchanged at 13500000.00 because the base is unchanged; the contribution is a cost, and costs under a PSC go into the pool, not into the tax base.'::text, 'psc_sinking_fund adds abandonment_cost_usd 10000000 funded from 2031. The 2031 row shows decom_fund_contribution 10000000.00, net cash flow 29500000.00 against 39500000.00, and tax still 13500000.00. Where did the contribution go?', '["Into the recoverable cost lane, so it rides the pool as a cost to be recovered rather than being paid outside the contract.", "It was deducted from the contractor''s profit oil before tax, which is why the net fell by the full 10000000.00 while the taxable income stayed at 27000000.00.", "It was paid from the contractor''s profit oil after tax and shared with the state at the 50 percent profit split, leaving the contractor''s cash lower by the whole sum.", "A lump sum charged in the last year of the field, the sinking fund label only recording that the money was set aside in 2031 rather than spent."]'::jsonb, 0, 'The tax is unchanged at 13500000.00 because the base is unchanged; the contribution is a cost, and costs under a PSC go into the pool and stay out of the tax base.'::text),
      ('advanced', 'module', 'm01-cost-recovery'::text, 15, 'AKATA under production sharing at a 30 percent cap leaves 207346412.26 in the pool at the end of 2035. Which output column of the engine reports that figure?', '["The depreciation column, which under a PSC reports the unrecovered capex in the pool rather than a write-off, because cost oil replaces depreciation.", "None. The rows carry no cost recovered and no carried forward column, the KPI block prints unrecovered cost at cessation not reported, and the pool is read only by marching applyPSC over the engine''s own rows.", "The cumulative_cash_flow column, which on a PSC row is the contractor''s cumulative position after cost oil and therefore mirrors the pool with its sign reversed.", "The tax column, because tax is the only line that moves with the pool, 10393930.24 in 2035 at 30 percent against 8400589.37 at 60, and the pool is recoverable from it."]'::jsonb, 1, 'Tax does move with the pool, but a reader who has not marched the pool cannot tell a low tax from a low profit, and the NPV of minus 104151944.05 does not say why either.'::text, 'AKATA under production sharing at a 30 percent cap leaves 207346412.26 in the pool at the end of 2035. Which output column of the engine reports that figure?', '["The depreciation column, which under a PSC reports the unrecovered capex in the pool rather than a write-off, because cost oil replaces depreciation.", "psc_cost_pool_after on the 2035 row, and kpis.psc_unrecovered_cost_at_cessation repeats it as the cost the end of the field leaves unrecovered.", "The cumulative_cash_flow column, which on a PSC row is the contractor''s cumulative position after cost oil and therefore mirrors the pool with its sign reversed.", "The tax column, because tax moves with the pool, 10393930.24 in 2035 at 30 percent against 8400589.37 at 60, and the pool can be read back from it."]'::jsonb, 1, 'Every production sharing row carries psc_cost_pool_after, the cost still carried at the year end, and the KPI block reports the pool cessation leaves; no column prints the cost recovered in a year, so the recovery itself is read by marching applyPSC. Tax moves with the pool, but tax alone cannot tell a low tax from a low profit.'::text),
      ('advanced', 'module', 'm02-the-pia-royalties'::text, 1, 'AKATA under the PIA is shallow water and its 2029 production royalty is 22944240.00 on 186032000.00 of gross revenue. A reader applying 0.125000 to the gross does not land on that figure. What did the reader miss?', '["The price royalty of 3605512.362941, which the engine folds into the production royalty column before reporting the row.", "The gas. The 0.125000 is charged on the oil and a separate gas royalty of 0.070000 on the gas, and the row is the sum of the two.", "The HCDT, which is deducted from gross revenue before the royalty rate is applied so that the royalty base is smaller than the gross.", "The water depth of 60 m, which places AKATA in a reduced shallow water band below the 0.125000 that a 100 m field pays."]'::jsonb, 1, 'Onshore the same row reads 27454240.00 with the oil at 0.150000 and the gas still at 0.070000; the gas rate has its own table and its own terrain reading.'::text, 'AKATA under the PIA is shallow water, lifting 2200000 bbl in 2029, and its 2029 production royalty is 10070350.00 on 186032000.00 of gross revenue. A reader applying 0.125000 to the gross lands far above that figure. What did the reader miss?', '["The price royalty of 3606152.270399, which the engine deducts from the production royalty column before it reports the row, lowering the charge.", "The tranches. At 6027.40 bopd the liquids pay the weighted 0.054261, the first 5000 bopd at 5 percent and the rest at 7.5 percent, plus gas at 0.050000.", "The HCDT, which is deducted from gross revenue before the royalty rate is applied, so that the royalty base is smaller than the gross revenue of the year.", "The water depth of 60 m, which places AKATA in a reduced shallow water band well below the 0.125000 that a field at 100 m of water would pay on every barrel."]'::jsonb, 1, 'Onshore and shallow water charge 5 percent on the first 5000 bopd, 7.5 percent on the next 5000 and their own terrain rate only above 10000 bopd, as one weighted rate; AKATA never reaches the 12.5 percent tranche. The gas pays 281600.00 at 0.050000. Onshore the same row also reads 10070350.00. The price royalty is a separate line, the HCDT is not a royalty deduction, and the rate never reads the depth.'::text),
      ('advanced', 'module', 'm02-the-pia-royalties'::text, 2, 'pia_deep_offshore_full lifts 21900000 bbl in 2025, 60000 bopd, and pays 131400000.00 of production royalty on 1752000000.00 of gross revenue. A reader prices the first 50000 bopd at 0.050000 and only the barrels above at 0.075000 and gets a smaller figure. What is wrong with the reader''s method?', '["The reader has the threshold wrong: deep offshore steps at 50001 bopd, and at 60000 bopd the whole of the first 50001 bopd is charged at 0.050000 and only the rest at 0.075000.", "The reader has the tiers reversed: the first 50000 bopd of a deep offshore field pay 0.075000 and the barrels above the threshold pay the lower 0.050000 tier.", "The reader should have blended the two rates across the twelve months of 2025 and then applied the average to the year, since the engine prices the year on its monthly rates.", "Deep offshore steps once at 50000 bopd and the rate that applies to the year applies to the whole year; the blend exists in the marginal field terrain alone."]'::jsonb, 3, 'pia_deep_offshore_naive_30k halves the volume to 10950000 bbl, under the threshold, and pays 43800000.00 on 876000000.00, 0.050000 of every barrel; there is no barrel priced at the other rate in either case.'::text, 'pia_deep_offshore_full lifts 21900000 bbl in 2025, 60000 bopd, and pays 94900000.00 of production royalty on 1752000000.00 of gross revenue. A second reader charges 0.075000 on every barrel and gets a larger figure. What is wrong with that reader''s method?', '["The threshold is wrong: deep offshore switches at 60000 bopd, and a field sitting exactly on 60000 bopd is charged the lower 0.050000 on every barrel of the year it produces.", "The tiers are reversed: the first 50000 bopd of a deep offshore field pay the 0.075000 rate and only the barrels above the threshold pay the lower 0.050000 tranche.", "The reader should have blended the two rates month by month through 2025 and applied the average, since the engine prices each year on its twelve monthly readings.", "The 7.5 percent applies only to the share above 50000 bopd: the first 50000 pay 5 percent, and the year pays one weighted rate, 0.054167."]'::jsonb, 3, 'Deep offshore pays 5 percent up to and including 50000 bopd and 7.5 percent on the share above, as one weighted average on the whole volume: (50000 x 0.05 + 10000 x 0.075) / 60000 = 0.054167, 94900000.00. pia_deep_offshore_naive_30k, at 30000 bopd, pays 0.050000 on every barrel, 43800000.00. The engine reads the year''s barrels over its calendar days, and the tranches are not reversed.'::text),
      ('advanced', 'module', 'm02-the-pia-royalties'::text, 3, 'The worked example and pia_deep_offshore_full both carry pia_water_depth_m 100, and one pays a production royalty rate of 0.125000 while the other pays 0.075000. What does deriveOilRoyaltyRate read?', '["The terrain string and the daily rate. It does not read the water depth, the licence type, the lease status or the price.", "The water depth, and 100 m sits on the boundary between the shallow water and deep offshore bands so the engine falls back to the terrain string to break the tie.", "The licence type, since a PML pays the shallow water rate and the deep offshore case is on a different licence.", "The oil price, which moves the field between the 0.125000 and 0.075000 tiers because the price royalty and the production royalty share one curve."]'::jsonb, 0, 'The rate is chosen by a string somebody typed; the depth is carried in the config and never consulted, and the licence type moves the hydrocarbon tax rate, not this one.'::text, 'The worked example and pia_deep_offshore_full both carry pia_water_depth_m 100, and one pays a production royalty rate of 0.112500 while the other pays 0.054167. What does deriveOilRoyaltyRate read?', '["The terrain string and the daily rate. It does not read the water depth, the licence type, the lease status or the price.", "The water depth, and 100 m sits on the boundary between the shallow water and deep offshore bands, so the engine falls back on the terrain string to break the tie.", "The licence type, since a PML pays the shallow water tranches and the deep offshore case is held on a different licence with its own royalty schedule.", "The oil price, which moves the field between the 0.112500 and 0.054167 rates because the price royalty and the production royalty share one curve."]'::jsonb, 0, 'The rate is chosen by a string somebody typed; the depth is carried in the config and never consulted, and the licence type moves the hydrocarbon tax rate only. The worked example is shallow water at 50000 bopd, weighted 5, 7.5 and 12.5 percent; the deep offshore case is 60000 bopd, weighted 5 and 7.5 percent.'::text),
      ('advanced', 'module', 'm02-the-pia-royalties'::text, 4, 'AKATA''s total royalties read 143184623.40 onshore, 122393644.64 as shallow water and 59501441.00 as deep offshore, with NPV 37060198.23, 43223505.88 and 141623594.88. Which of the NPV moves is due to the royalty alone?', '["Both moves. The terrain string changes only the royalty table, and every other line in the cascade follows from the royalty through the tax bases.", "Shallow water to deep offshore. The onshore move also raises the NDDC levy to the onshore rate, so it is not a pure royalty change.", "Onshore to shallow water. The deep offshore move under the conservative reading also zeroes the hydrocarbon tax; the aggressive reading keeps the same 59501441.00 of royalties and gives NPV 61725382.46.", "Neither. Each terrain also changes the gas royalty, 0.070000 onshore and shallow water against 0.050000 deep offshore, so no move is oil royalty alone."]'::jsonb, 2, 'The same 59501441.00 of royalties gives NPV 141623594.88 or 61725382.46 depending on a reading of the hydrocarbon tax; the royalty explains the first move and only part of the second.'::text, 'AKATA''s total royalties read 60324870.87 onshore and in shallow water alike and 59503845.87 in deep offshore. NPV is 59766796.57 onshore and in shallow water; in deep offshore it is 136554243.51 read conservative_zero and 60060654.75 read aggressive_pml_30. Which NPV move is due to the royalty alone?', '["Onshore to shallow water, since the terrain string changes only the royalty table there and every other line in the ledger follows from the royalty.", "Shallow water to deep offshore under conservative_zero, since that reading keeps the tax rate of shallow water and changes nothing but the royalty tranches.", "Shallow water to deep offshore under aggressive_pml_30: the tax rate stays at 30 percent and only the royalty moves, by 821025.00.", "None of them, because each terrain also changes the gas royalty, 0.070000 onshore and in shallow water against 0.050000 offshore, so no move is oil alone."]'::jsonb, 2, 'Onshore and shallow water only differ above 10000 bopd, so at AKATA''s rate there is no move at all. Under aggressive_pml_30 the deep offshore year pays the same 30 percent hydrocarbon tax as shallow water, so the move from 59766796.57 to 60060654.75 is the royalty saved. conservative_zero also removes the tax, a reading the texts leave open, and gas pays 0.050000 in every terrain.'::text),
      ('advanced', 'module', 'm02-the-pia-royalties'::text, 5, 'deriveOilRoyaltyRate for a marginal field reads 0.050000 at 5000 bopd, 0.062500 at 10000 and 0.106250 at 20000. Why is the 10000 bopd rate exactly halfway between the first two tiers while the 20000 bopd rate is not halfway to 0.150000?', '["The 10000 bopd row is an interpolation between two table entries and the 20000 row is a table entry, so only the first is an average.", "At 10000 bopd the year''s barrels split evenly between the 5 percent and 7.5 percent tiers; at 20000 bopd half the barrels sit in the 15 percent tier and the other half are still priced at the two lower tiers.", "The blend is arithmetic below 10000 bopd and geometric above it, which is why the upper rows rise more slowly than a straight average would.", "The 20000 bopd rate is capped by the deep offshore step at 50000 bopd, so the marginal curve is bent toward 0.132500 rather than toward 0.150000."]'::jsonb, 1, 'The rate is the average across the year''s barrels, so the first 10000 bopd are always priced at the two lower tiers and the rate approaches 0.150000 from below, 0.142708 at 120000 bopd.'::text, 'deriveOilRoyaltyRate onshore reads 0.050000 at 5000 bopd, 0.062500 at 10000 and 0.106250 at 20000, the tranches a producing marginal field onshore also pays. Why is the 10000 bopd rate exactly halfway between the first two tranches while the 20000 bopd rate is not halfway to 0.150000?', '["The 10000 bopd row is an interpolation between two table entries and the 20000 row is a table entry, so only the first is an average.", "At 10000 bopd the year''s barrels split evenly between the 5 percent and 7.5 percent tiers; at 20000 bopd half the barrels sit in the 15 percent tier and the other half are still priced at the two lower tiers.", "The blend is arithmetic below 10000 bopd and geometric above it, which is why the upper rows rise more slowly than a straight average of the tranche rates would, and why the curve bends away from 0.150000 as the daily rate grows.", "The 20000 bopd rate is capped by the deep offshore tranche boundary at 50000 bopd, so the onshore curve is bent toward 0.132500 and away from 0.150000."]'::jsonb, 1, 'The rate is the average across the year''s barrels, so the first 10000 bopd are always priced at the two lower tranches and the rate approaches 0.150000 from below, 0.142708 at 120000 bopd. A marginal field is onshore or in shallow water; the terrain string marginal_field is refused.'::text),
      ('advanced', 'module', 'm02-the-pia-royalties'::text, 6, 'AKATA as a marginal field pays a 2029 production royalty of 10182990.00 against 22944240.00 as shallow water, yet its 2029 HCT is 29251153.65 against 25422778.65 and total tax rises to 223261390.90. Why did the tax rise when the royalty fell?', '["The marginal field terrain carries a hydrocarbon tax rate of its own, higher than shallow water, which the engine applies whenever the blended royalty is used, so the blend and the rate move together.", "The price royalty is charged at a higher rate on a marginal field and is added into the HCT base rather than deducted from it, which lifts the tax.", "The marginal terrain forfeits the production allowance, and the 5500000.00 that shallow water deducts from the base is charged in full on a marginal field.", "pia_marginal_field_pre_2021 was not set, so the field pays 30 percent on a base that the smaller royalty has left larger; the blend does not switch the tax rate."]'::jsonb, 3, 'pia_marginal_field_blend has the flag true and pays 0.150000, 26361776.50 on 175745176.68; AKATA marginal pays 0.300000 and NPV is 61154067.34, with the tax taking back most of the royalty saved.'::text, 'AKATA in shallow water, run as a producing marginal field converted under s.94(1) (pia_marginal_field_pre_2021 true), keeps its 2029 production royalty of 10070350.00, yet its 2029 HCT falls from 27208719.48 to 13604359.74 and NPV rises from 59766796.57 to 97891150.04. What did the flag change?', '["The royalty tranches, since the flag moves the field onto the lower marginal schedule and the smaller royalty leaves a larger base that is then taxed less.", "The price royalty, which the flag waives on a marginal field, so the hydrocarbon tax base loses 3606152.27 of deduction and the tax falls with it.", "The production allowance, which the flag doubles for a converted marginal field, so the chargeable profit is halved before the rate applies.", "The hydrocarbon tax rate, 15 percent for a marginal field converted under s.94(1) against 30 percent; the royalty is the terrain''s either way."]'::jsonb, 3, 'The flag sets the hydrocarbon tax rate to 0.150000 and leaves the royalty to the terrain: total royalties stay 60324870.87 and total tax falls to 171815891.58. pia_marginal_field_blend, run onshore with the flag, pays HCT 24111699.56 on a chargeable profit of 160744663.71. The price royalty and the allowance do not move with the flag.'::text),
      ('advanced', 'module', 'm02-the-pia-royalties'::text, 7, 'The PIA worked example sells at 80.000000 in 2025 and pays a price royalty of 34905145.759897 on 1460000000.00 of gross revenue, the 0.023908 in the table, where the 2021 curve reads 0.030000 at 80. What lowered the rate?', '["The anchor prices escalate at 2 percent a year from 2021, so the same nominal price sits lower on the curve every year.", "The rate is applied to revenue after the production royalty of 182500000.00 rather than to the gross, and the smaller base shows up as a smaller apparent rate.", "The price is deflated by the 3 percent inflation before the curve is read, so the real price of 2025 is below 80 and earns the lower rate.", "The twelve monthly rows of 2025 are each read on the curve and averaged, and the monthly reads fall below the annual read because the curve is convex."]'::jsonb, 0, 'At 60 USD/bbl the rate is 0.010000 in 2021, 0.005431 in 2025 and 0.000205 in 2030; a flat price is a falling royalty because the anchors move under it.'::text, 'The PIA worked example sells at 80.000000 in 2025 and pays a price royalty of 34908351.810791 on 1460000000.00 of gross revenue, the 0.023910 in the table on the Regulations (2021) base, the engine default, where the 2021 curve reads 0.030000 at 80. What lowered the rate?', '["The benchmarks rise every 1 January by 2 percent from 2021, so the same nominal price sits lower on the curve every year.", "The rate is applied to revenue after the production royalty of 164250000.00 rather than to the gross, and the smaller base shows up as a smaller apparent rate.", "The price is deflated by the 3 percent inflation before the curve is read, so the real price of 2025 is below 80 and earns the lower rate on every barrel.", "The twelve monthly rows of 2025 are each read on the curve and averaged, and the monthly reads fall below the annual read because the curve is convex."]'::jsonb, 0, 'At 60 USD/bbl the rate is 0.010000 in 2021, 0.005432 in 2025 and 0.000209 in 2030; a flat price is a falling royalty because the benchmarks move under it. On the Act''s reading the benchmarks start a year earlier, a question the texts leave open.'::text),
      ('advanced', 'module', 'm02-the-pia-royalties'::text, 8, 'In 2035 a price of 60 USD/bbl reads a price royalty rate of 0.000000, and in 2026 a price of 55 already does. What has happened to the curve?', '["The engine floors the rate at 0.000000 whenever the price is below the year''s applied oil price, and 60 is below every escalated price in the deck.", "The lower tier has been switched off by the 2025 framework change, which removed the price royalty below the 100 anchor for every terrain.", "The 50 anchor, escalating at 2 percent a year from 2021, has moved past those prices, and below the first anchor the rate is nothing.", "The rate is rounded to six decimals, and by 2035 the true rate at 60 is a small positive number that rounds to zero."]'::jsonb, 2, 'At 60 the rate is 0.010000 in 2021, 0.005431 in 2025, 0.000205 in 2030 and 0.000000 in 2035, a royalty in name only long before it vanishes.'::text, 'In 2035 a price of 60 USD/bbl reads a price royalty rate of 0.000000, and in 2026 a price of 55 already does. What has happened to the curve?', '["The engine floors the rate at 0.000000 whenever the price is below the year''s applied oil price, and 60 is below every escalated price in the deck.", "The lower tier has been switched off by the 2025 framework change, which removed the price royalty below the 100 anchor for every terrain.", "The 50 benchmark, rising 2 percent a year from 2021, has moved past those prices, and below the low benchmark the rate is nothing.", "The rate is rounded to six decimals, and by 2035 the true rate at 60 is a small positive number that rounds to zero."]'::jsonb, 2, 'At 60 the rate is 0.010000 in 2021, 0.005432 in 2025, 0.000209 in 2030 and 0.000000 in 2035, a royalty in name only long before it vanishes. These are the Regulations (2021) base figures, the engine default.'::text),
      ('advanced', 'module', 'm02-the-pia-royalties'::text, 9, 'pia_price_royalty_ceiling at 200.000000 pays 365000000.000000 on 3650000000.00 of gross revenue, exactly 10 percent, and the table reads 0.100000 at 200 in 2021, 2025, 2030 and 2035. What does a price above the 150 anchor earn?', '["A rate that keeps climbing at the upper tier''s slope, twice as steep as the lower tier, so that 200 earns more than 150 and 250 more than 200.", "The upper tier rate read at the escalated 150 anchor, which drifts upward with the years so that 200 earns a little more each year.", "A rate of 0.100000 plus the lower tier rate at 100, because the tiers stack and a price that has passed both anchors pays both.", "The ceiling of 0.100000 and no more, which is the only part of the curve that the years do not erode."]'::jsonb, 3, 'pia_high_price_royalty_tiers at 140.000000 pays 202709508.889684 on 2555000000.00, still between the escalated 100 and 150 anchors; 160 and 200 both read 0.100000 in 2021.'::text, 'pia_price_royalty_ceiling at 200.000000 pays 365000000.000000 on 3650000000.00 of gross revenue, exactly 10 percent, and the table reads 0.100000 at 200 in 2021, 2025, 2030 and 2035. What does a price at or above the year''s high benchmark earn?', '["A rate that keeps climbing at the upper tier''s slope, twice as steep as the lower tier, so that 200 earns more than 150 and 250 more than 200.", "The upper tier rate read at the escalated 150 anchor, which drifts upward with the years so that 200 earns a little more each year.", "A rate of 0.100000 plus the lower tier rate at 100, because the tiers stack and a price that has passed both anchors pays both.", "The ceiling of 0.100000 and no more, which is the only part of the curve that the years do not erode."]'::jsonb, 3, 'pia_high_price_royalty_tiers at 140.000000 pays 202719327.420547 on 2555000000.00, a rate of 0.079342, still between the escalated middle and high benchmarks; 160 and 200 both read 0.100000 in 2021. A price of 160 in 2025 still sits below that year''s 162.36 benchmark and reads 0.097820.'::text),
      ('advanced', 'module', 'm02-the-pia-royalties'::text, 10, 'pia_gas_only_hct_zero sells 20000000.00 Mscf and no oil for 90000000.00 of gross revenue at an oil price of 80.000000, and its price_royalty column reads 0.000000 beside a production royalty of 6300000.00. Why no price royalty?', '["The price royalty reads the oil price and charges the oil; there is no oil, and gas does not carry it.", "The gas price of 4.5 USD per Mscf is far below the 50 anchor, and the engine reads the price royalty curve at the gas price for a gas field.", "The oil price of 80.000000 in 2025 reads 0.000000 on the curve because the 50 anchor has escalated past it by 2025.", "The field is treated as frontier when it has no oil, and frontier is exempt from the price royalty outright."]'::jsonb, 0, 'The 6300000.00 is 0.070000 on the gas; the price royalty on a field with gas is charged on the oil revenue alone, not on the gross, which is the second common mistake.'::text, 'pia_gas_only_hct_zero sells 20000000.00 Mscf and no oil for 90000000.00 of gross revenue at an oil price of 80.000000, and its price_royalty column reads 0.000000 beside a production royalty of 4500000.00. Why no price royalty?', '["The price royalty reads the oil price and charges the oil; there is no oil, and gas does not carry it.", "The gas price of 4.5 USD per Mscf is far below the 50 anchor, and the engine reads the price royalty curve at the gas price for a gas field.", "The oil price of 80.000000 in 2025 reads 0.000000 on the curve because the 50 anchor has escalated past it by 2025.", "The field is treated as frontier when it has no oil, and frontier is exempt from the price royalty outright."]'::jsonb, 0, 'The 4500000.00 is 0.050000 on the gas, the gas rate in every terrain. The price royalty is charged on crude and condensate, each at its own price, and never on the gas revenue; there is no frontier switch, and 80.000000 in 2025 still reads 0.023910.'::text),
      ('advanced', 'module', 'm02-the-pia-royalties'::text, 11, 'pia_frontier_exempt prints a production royalty of 21900000.00 on 292000000.00 of gross revenue and a price royalty of 0.000000, at a price of 80.000000 in 2025. What two things does the frontier terrain do to the royalties?', '["It steps the production royalty from 0.050000 to 0.075000 at 50000 bopd like deep offshore and defers the price royalty until the field reaches that threshold.", "It fixes the production royalty at 0.075000 at every daily rate, and it exempts the field from the price royalty outright, 0.000000 even at 200 USD/bbl.", "It blends the production royalty across three tiers like a marginal field and reads the price royalty at the 2021 anchors without escalation.", "It fixes the production royalty at 0.075000 and caps the price royalty at the 0.100000 ceiling, which at 80.000000 in 2025 happens to round to 0.000000."]'::jsonb, 1, 'pia_onshore_new_lease on the same 292000000.00 of revenue pays 43800000.00 of production royalty and 6981029.151979 of price royalty; the frontier string removes half of one and all of the other.'::text, 'pia_frontier_exempt prints a production royalty of 21900000.00 on 292000000.00 of gross revenue and a price royalty of 0.000000, at a price of 80.000000 in 2025. What two things does the frontier terrain do to the royalties?', '["It weights the production royalty at 0.050000 up to 50000 bopd and 0.075000 above like deep offshore, and defers the price royalty until that threshold is reached.", "It fixes the production royalty at 0.075000 at every daily rate, and it exempts the field from the price royalty outright, 0.000000 even at 200 USD/bbl.", "It blends the production royalty across three tranches like an onshore field and reads the price royalty on the 2021 benchmarks without any escalation.", "It fixes the production royalty at 0.075000 and caps the price royalty at the 0.100000 ceiling, which at 80.000000 in 2025 happens to round to 0.000000."]'::jsonb, 1, 'pia_onshore_new_lease on the same 292000000.00 of revenue, at 10000 bopd, pays 18250000.00 of production royalty at the weighted 0.062500 and 6981670.362158 of price royalty; frontier pays more production royalty, 7.5 percent flat, and no price royalty at all.'::text),
      ('advanced', 'module', 'm02-the-pia-royalties'::text, 12, 'pia_deep_offshore_wi_50 and pia_deep_offshore_naive_30k both carry oil_bbl 10950000.00 on the 2025 row, yet the first pays 65700000.00 of production royalty and the second 43800000.00. Why do two rows with the same barrels pay different royalties?', '["The WI 50 row adds its price royalty of 20943087.455938 into the production royalty column, and the naive row reports the same price royalty separately.", "The naive row is read at 2025 anchors and the WI 50 row at 2021 anchors, because a working interest below 100 percent fixes the curve at the year the licence was granted.", "The tier is read on the field''s barrels and the working interest is applied to the money afterward; the WI 50 row is still a 60000 bopd field at 0.075000, while the naive upload made a 30000 bopd field at 0.050000.", "The WI 50 row applies 0.075000 to the field''s 21900000.00 bbl and then halves, while the naive row applies 0.050000 to the full 21900000.00 and does not halve, and the two scalings happen to land on those figures."]'::jsonb, 2, 'cumulative_oil_bbl_lifetime reads 21900000.00 on the WI 50 row and 10950000.00 on the naive row; only that column and prod_alw_eligible_bbl remember the field.'::text, 'pia_deep_offshore_wi_50 and pia_deep_offshore_naive_30k both carry oil_bbl 10950000.00 on the 2025 row, yet the first pays 47450000.00 of production royalty and the second 43800000.00. Why do two rows with the same barrels pay different royalties?', '["The WI 50 row adds its price royalty of 20945011.086475 into the production royalty column, and the naive row reports that same price royalty separately.", "The naive row is read at 2025 benchmarks and the WI 50 row at 2021 benchmarks, because a working interest below 100 percent fixes the price curve at the licence year.", "The tranche is read on the field''s barrels and the share applied to the money after: WI 50 is still a 60000 bopd field at 0.054167, the naive upload a 30000 bopd one at 0.050000.", "The WI 50 row applies 0.075000 to the field''s 21900000.00 bbl and then halves, while the naive row applies 0.050000 and does not halve, and the scalings land on those figures."]'::jsonb, 2, 'royalty_liquids_bopd reads 60000 on the WI 50 row and 30000 on the naive row, and cumulative_oil_bbl_lifetime reads 21900000.00 and 10950000.00; the lifetime column, prod_alw_eligible_bbl and royalty_liquids_bopd remember the field, and oil_bbl does not. Half of 94900000.00 is 47450000.00.'::text),
      ('advanced', 'module', 'm02-the-pia-royalties'::text, 13, 'pia_deep_offshore_naive_30k lands in the cheaper 0.050000 tier yet reports NPV 372530915.97, below the correct half share of 445282165.97. What pulls it down?', '["It still bears the full 100000000.00 of capex, 100000000.00 of opex, 5100000.00 of HCDT and 15000000.00 of NDDC against half the revenue; two errors in opposite directions, and neither cancels the other.", "The lower tier lowers the royalty but the hydrocarbon tax rises to take back the difference, since deep offshore under the conservative reading charges HCT on the royalty saved.", "The engine detects the pre-scaled upload and charges a penalty royalty at the 0.075000 rate on the barrels it infers were left out of the file.", "The naive row is discounted one extra year because the halved production is read as starting in 2026, and the extra division by 1.1 costs the difference."]'::jsonb, 0, 'The take reads 44.8919 percent against 42.6183 for both honest runs; the naive row is a different field with the wrong costs, not a share of the real one.'::text, 'pia_deep_offshore_naive_30k lands in the cheaper 0.050000 rate yet reports NPV 369073842.57, below the correct half share of 453861842.57. What pulls it down?', '["It still bears the full 100000000.00 of capex, 100000000.00 of opex, 5100000.00 of HCDT and 15000000.00 of NDDC against half the revenue; two errors in opposite directions, and neither cancels the other.", "The lower rate lowers the royalty but the hydrocarbon tax rises to take back the difference, since deep offshore under the conservative reading charges its tax on whatever royalty the smaller field has saved in the year.", "The engine detects the pre-scaled upload and charges a penalty royalty at the 0.075000 rate on the barrels it infers were left out of the file.", "The naive row is discounted one extra year because the halved production is read as starting in 2026, and the extra division by 1.1 costs the difference."]'::jsonb, 0, 'The take reads 45.4033 percent against 41.5126 for both honest runs; the naive row is a different field with the wrong costs and cannot stand in for a share of the real one.'::text),
      ('advanced', 'module', 'm02-the-pia-royalties'::text, 14, 'AKATA under the PIA at pia_working_interest_pct 50 reports NPV 21611752.94, exactly half of 43223505.88, and a take of 75.5752 percent that has not moved. Under joint venture terms the same field reads take 66.1723 percent at a working interest of 100, 60 and 25 alike. Why is take invariant under both regimes?', '["The PIA scales the whole ledger, while the JV take is invariant for a different reason, the partners'' royalty and tax being charged at the operator''s rates.", "Take is computed before the working interest is applied in either regime, so the ratio never sees a share at all and reports the field''s number.", "The royalties are field-level tiers in both regimes and do not scale with the working interest, so the state''s share stays the same fraction of a smaller revenue.", "Both ledgers scale every monetary line and the volumes together, so each line the ratio reads is cut with the rest and the ratio is the number it was."]'::jsonb, 3, 'Until engines 3.10.0 the JV rows kept field-level revenue and counted the partners'' share as take, so the same field read 79.7034 percent at a 60 percent interest; PIA royalties halve to 61196822.32 while the eligible barrels stay 2200000.00.'::text, 'AKATA under the PIA at pia_working_interest_pct 50 reports NPV 29883398.29, exactly half of 59766796.57, and a take of 70.6449 percent that has not moved. Under joint venture terms the same field reads take 66.1723 percent at a working interest of 100, 60 and 25 alike. Why is take invariant under both regimes?', '["The PIA scales the whole ledger, while the JV take is invariant for a different reason, the partners'' royalty and tax being charged at the operator''s rates.", "Take is computed before the working interest is applied in either regime, so the ratio never sees a share at all and reports the field''s number.", "The royalties are field-level tiers in both regimes and do not scale with the working interest, so the state''s share stays the same fraction of a smaller revenue.", "Both ledgers scale every monetary line and the volumes together, so each line the ratio reads is cut with the rest and the ratio is the number it was."]'::jsonb, 3, 'Both regimes put every monetary line and the volumes at the share, so the ratio is unchanged. Under the PIA the royalties halve to 30162435.44 while the tranches and the allowance cap stay field-level, and the 2200000.00 barrels the allowance reads are the field''s.'::text),
      ('advanced', 'module', 'm02-the-pia-royalties'::text, 15, 'A production file has been pre-scaled to the operator''s share before upload. What can the engine report to warn the reader?', '["A working_interest_pct of 50 inferred from the ratio of the uploaded barrels to the lifetime cumulative, which it prints in the KPI block as a warning.", "Nothing. It cannot tell a pre-scaled upload from a small field: the naive run reports working_interest_pct not reported exactly as the full run does.", "A prod_alw_cap_applied flag of true on the first row, because a halved field reaches the wrong tier and the engine marks any tier it cannot reconcile.", "An ingestion refusal, since the volume columns of a pre-scaled file fail the per-well naming check that the production loader applies."]'::jsonb, 1, 'The row''s oil_bbl is the entitlement either way; the only honest scaling is pia_working_interest_pct on the full field, which keeps cumulative_oil_bbl_lifetime at 21900000.00.'::text, 'A production file has been pre-scaled to the operator''s share before upload. What can the engine report to warn the reader?', '["A working_interest_pct of 50 inferred from the ratio of uploaded barrels to the lifetime cumulative, which it prints in the KPI block as a warning.", "Nothing. It cannot tell a pre-scaled upload from a small field: the naive run reports working_interest_pct not reported exactly as the full run does.", "A prod_alw_cap_applied flag of true on the first row, because a halved field reaches the wrong tier and the engine marks a tier it cannot reconcile.", "An ingestion refusal, since the volume columns of a pre-scaled file fail the per-well naming check that the production loader applies."]'::jsonb, 1, 'The row''s oil_bbl is the entitlement either way; the only honest scaling is pia_working_interest_pct on the full field, which keeps cumulative_oil_bbl_lifetime at 21900000.00.'::text),
      ('advanced', 'module', 'm03-hydrocarbon-tax'::text, 2, 'The worked example prints nddc 15000000.00 on opex of 182500000.00 while pia_onshore_new_lease prints 900000.00 on opex of 30000000.00. Both carry pia_nddc_levy_pct_of_opex 3. What makes the first one so large?', '["pia_nddc_levy_fixed_usd 15000000 is set on the worked example, and a fixed sum replaces the percentage whatever the opex is.", "The worked example reads the levy on the prior year''s opex of 170000000, and 3 percent of that is 5100000.00, which the engine then grosses up for the deductible NDDC.", "The worked example is shallow water and the NDDC is charged on shallow water opex at a higher rate than the 3 percent that applies onshore.", "The worked example''s opex is uploaded as twelve monthly rows and the levy is charged on each row at 3 percent and then summed twelve times over."]'::jsonb, 0, 'A 3 percent field with no opex pays none, but the fixed sum is a flat 15000000.00 in every year regardless of opex; on AKATA, with no fixed sum, hcdt and nddc read the same 720000.00 and 741600.00 one year apart.'::text, 'The worked example prints nddc 15000000.00 on opex of 182500000.00 while pia_onshore_new_lease prints 2400000.00 on opex of 30000000.00 and capex of 50000000.00. Both carry the 3 percent rate. What makes the first one so large?', '["pia_nddc_levy_fixed_usd 15000000 is set on the worked example, and a fixed sum replaces the percentage whatever the opex is.", "The worked example reads the levy on the prior year''s opex of 170000000, and 3 percent of that is 5100000.00, which the engine then grosses up for the deductible NDDC.", "Shallow water opex, since the worked example is shallow water and the NDDC is charged there at a higher rate than the 3 percent onshore.", "Monthly rows: the worked example''s opex is uploaded as twelve monthly rows and the levy is charged on each at 3 percent and summed twelve times."]'::jsonb, 0, 'Without a fixed sum the levy is 3 percent of the year''s total annual budget, opex plus capex: 3 percent of 80000000.00 is 2400000.00. The fixed sum is a flat 15000000.00 in every year regardless of spend. On AKATA, with no fixed sum, the NDDC reads 7020000.00, 2091600.00 and 763848.00 in 2029 to 2031 beside HCDT of 0.00, 720000.00 and 741600.00. The prior-year opex feeds HCDT only, the terrain sets no NDDC rate, and monthly rows are summed to a year before any levy.'::text),
      ('advanced', 'module', 'm03-hydrocarbon-tax'::text, 3, 'pia_prior_year_opex_zero removes the 5100000.00 HCDT from the worked example. Both tax bases rise by exactly 5100000.00, HCT rises from 284810956.27 to 286340956.27, and NPV rises from 135185570.34 to 137098070.34, less than the levy saved. Why less?', '["The NPV is on the real basis, and the 5100000.00 saved in 2025 money is deflated by the 3 percent inflation before it reaches the NPV.", "The levy is deductible from both bases, so removing it raises HCT, CIT and TET, and the extra taxes take back part of the 5100000.00.", "The levy is only partly removed: the engine keeps a minimum HCDT on the current year''s opex when the prior year is zero, and that minimum still costs cash.", "The 5100000.00 comes back as a deferred CPR cost, which the cap defers to a later year that the one-year field does not have."]'::jsonb, 1, 'Removing the levy raised both bases by the levy, and the CIT base sits 15000000.00 below the HCT base in both rows because NDDC is deducted for CIT and not for HCT.'::text, 'pia_prior_year_opex_zero removes the 5100000.00 HCDT from the worked example. Both tax bases rise by exactly 5100000.00, HCT rises from 285784994.46 to 287314994.46, and NPV rises from 141236909.83 to 143123909.83, less than the levy saved. Why less?', '["The NPV is on the real basis, and the 5100000.00 saved in 2025 money is deflated by the 3 percent inflation before it reaches the NPV.", "The levy is deductible from both bases, so removing it raises HCT, CIT and TET, and the extra taxes take back part of the 5100000.00.", "The levy is only partly removed: the engine keeps a minimum HCDT on the current year''s opex when the prior year is zero, and that minimum still costs cash.", "The 5100000.00 comes back as a deferred CPR cost, which the cap defers to a later year that the one-year field does not have."]'::jsonb, 1, 'Removing the levy raised both bases by the levy, so HCT, CIT and TET all rose and took back part of the saving. The two assessable profits stay equal to each other, 1058241648.19 with the levy and 1063341648.19 without it, because this oil-only field deducts HCDT and NDDC in both. The one-year field has no deflation to apply in its base year, HCDT has no minimum on the current year''s opex, and the cost price ratio cap does not reach the levies.'::text),
      ('advanced', 'module', 'm03-hydrocarbon-tax'::text, 4, 'On the worked example cit_assessable_profit is 1039994854.24 and hct_assessable_profit is 1054994854.24, a gap of exactly 15000000.00. What sits in that gap?', '["The production allowance, which is deducted from the HCT base and not from the CIT base, and on this case the allowance is 45625000.00 before the price cap.", "The HCDT of 5100000.00 together with the TET of 25999871.36, which are deducted for CIT because they are levies and not for HCT because they are taxes.", "One year of the capital allowance on the 300000000.00 of capex, which CIT deducts at the assessable stage and HCT deducts one stage later.", "The NDDC, which is deducted for CIT and not for HCT, and 15000000.00 is the fixed NDDC."]'::jsonb, 3, 'The allowance comes off later: hct_assessable_profit less 60000000.00 of capital allowance less 45625000.00 of production allowance is hct_chargeable_profit 949369854.24.'::text, 'On the worked example cit_assessable_profit and hct_assessable_profit both read 1058241648.19, and the NDDC is a fixed 15000000.00. Where does that NDDC sit?', '["Only in the HCT base; CIT takes the production allowance of 45625000.00 at the assessable stage in its place, and the two figures agree by coincidence of the round inputs.", "In neither base: the HCDT of 5100000.00 and the TET of 31747249.45 are deducted there, and the NDDC comes off the cash alone, beside the taxes.", "Only in the CIT base, with HCT deducting one year of capital allowance on the 300000000.00 of capex at the assessable stage to make up the difference.", "In both bases: the hydrocarbon tax deducts it (PIA s.263(1)(f), (h)) as CIT does, so the two assessable profits agree."]'::jsonb, 3, 'Both profit taxes deduct HCDT and NDDC, and on an oil-only field the shared costs enter the hydrocarbon tax whole, so the two assessable profits are equal. The allowances come off later: 1058241648.19 less 60000000.00 of capital allowance less 45625000.00 of production allowance is hct_chargeable_profit 952616648.19, while CIT takes the capital allowance only, for cit_chargeable_profit 998241648.19. The production allowance never reaches CIT, TET is a tax and is deducted from neither base, and no capital allowance enters either assessable profit.'::text),
      ('advanced', 'module', 'm03-hydrocarbon-tax'::text, 5, 'The worked example''s CPR cap is swept from 30 to 100 percent and cpr_costs_claimed stays 242500000.00 and NPV stays 135185570.34 at every setting. What does the sweep show about the cap?', '["The cap is a share of revenue, 438000000.00 even at 30 percent, and it does nothing while the claim of 242500000.00 sits below it.", "The cap is a share of the costs, and a cap that ranges from 30 to 100 percent of 242500000.00 is always satisfied by claiming the whole 242500000.00.", "The cap only acts on new leases, and the worked example is a converted lease so the CPR limit is read but never applied.", "The cap acts on the deferred pool from earlier years and the worked example, having one year, has no pool for the cap to bind on."]'::jsonb, 0, 'The cap only exists where costs approach revenue: on AKATA in 2032 the cap is 75826707.47 against opex 26225448.00 plus 51000000.00 of allowance, and 1398740.53 defers.'::text, 'The worked example''s CPR limit is swept from 30 to 100 percent and cpr_costs_claimed stays 242500000.00 and NPV stays 141236909.83 at every setting. What does the sweep show about the cap?', '["The cap is a share of revenue, 438000000.00 even at 30 percent, and it does nothing while the claim of 242500000.00 sits below it.", "The cap is a share of the costs, and a cap that ranges from 30 to 100 percent of 242500000.00 is always satisfied by claiming the whole 242500000.00.", "The cap only acts on new leases, and the worked example is a converted lease so the CPR limit is read but never applied.", "The cap acts on the deferred pool from earlier years and the worked example, having one year, has no pool for the cap to bind on."]'::jsonb, 0, 'The cap only acts where costs approach the liquids revenue: on AKATA in 2032 the cap, 65 percent of the oil revenue, is 73531102.32, and 1356394.56 defers. The cap is a share of revenue and never of the costs, it acts on converted and new leases alike, and on the worked example there is no pool and no binding cap in the only year.'::text),
      ('advanced', 'module', 'm03-hydrocarbon-tax'::text, 6, 'cpr_forfeiture has a cpr_cap of 52000000.00, claims 52000000.00, defers 8000000.00 and prints hct_loss_carryforward 0.00. The field has no later year. What is the 8000000.00?', '["A tax loss carried forward at the HCT rate, which the engine reports in cpr_deferred_to_next rather than in the loss column because it arose from the cap.", "A capital allowance the engine will claim in the next recovery year of the five, since the cap defers the allowance and not the opex.", "A deferred cost that is not a tax loss and does not survive cessation; the KPI block reports CPR forfeited at cessation 8000000.00.", "A cost that earns interest at the discount rate while it waits, so that the 8000000.00 grows to a larger claim in whichever year the cap next allows it."]'::jsonb, 2, 'pia_cpr_carry_two_years adds 22000000.00 to the deferred pool in every year and forfeits 66000000.00 at cessation while hct_loss_carryforward reads 0.00 on every row; a deferral is not a loss.'::text, 'cpr_forfeiture has a cpr_cap of 52000000.00, claims 52000000.00 and defers 8000000.00; the same row also carries a separate HCT loss of 512786.40 in hct_loss_carryforward. The field has no later year. What is the 8000000.00?', '["A tax loss carried forward at the HCT rate, which the engine reports in cpr_deferred_to_next rather than in the loss column because it arose from the cap.", "A capital allowance the engine will claim in the next recovery year of the five, since the cap defers the allowance and not the opex.", "A deferred cost that is not a tax loss and does not survive cessation; the KPI block reports CPR forfeited at cessation 8000000.00.", "A cost that earns interest at the discount rate while it waits, so that the 8000000.00 grows to a larger claim in whichever year the cap next allows it."]'::jsonb, 2, 'pia_cpr_carry_two_years, at its stated 30 percent limit, adds 22000000.00 to the deferred pool in every year and forfeits 66000000.00 at cessation while hct_loss_carryforward reads 0.00 on every row; a deferral is not a loss. The 512786.40 on cpr_forfeiture is a real HCT loss: the production allowance takes the chargeable profit below zero after the capped claim. The deferral earns no interest and does not wait for the next allowance year.'::text),
      ('advanced', 'module', 'm03-hydrocarbon-tax'::text, 7, 'AKATA at a CPR limit of 65 percent defers 1398740.53 in 2032 and 14561618.62 in 2033, then clears in 2034. At a limit of 40 percent HCT rises from 77020493.72 to 107354738.83 and NPV falls from 43223505.88 to minus 1723561.25. Why does a tighter cap hurt a declining field so much?', '["A tighter cap lengthens the capex recovery from five years to more, and the allowance that is pushed past 2035 is never claimed.", "The cap is a share of a shrinking revenue while the costs are not shrinking, so more is deferred each year and what is still deferred when the field stops is lost.", "The cap at 40 percent is read on the costs rather than on the revenue, and 40 percent of the costs is far less than 65 percent of them.", "The deferred costs become tax losses, and losses under the PIA are relieved at a lower rate than the 30 percent HCT that the costs would have offset."]'::jsonb, 1, 'In 2032 the cap is 75826707.47 against opex 26225448.00 and 51000000.00 of allowance; in 2034 the cap is 55829921.49 and the claim 51384196.40. The cap on a declining field is a tax on the decline.'::text, 'AKATA at a CPR limit of 65 percent defers 1356394.56 in 2032 and 14120774.92 in 2033, then clears in 2034. At a limit of 40 percent HCT rises from 91654840.32 to 121989085.43 and NPV falls from 59766796.57 to 37056190.44. Why does a tighter cap hurt a declining field so much?', '["A tighter cap lengthens the capex recovery from five years to more, and the allowance that is pushed past 2035 is never claimed.", "The cap is a share of a shrinking revenue while the costs are not shrinking, so deferrals pile up and what is still deferred when the field stops is lost.", "The cap at 40 percent is read on the costs rather than on the revenue, and 40 percent of the costs is far less than 65 percent of them.", "The deferred costs become tax losses, and losses under the PIA are relieved at a lower rate than the 30 percent HCT that the costs would have offset in the year they arose."]'::jsonb, 1, 'At 40 percent the deferral starts in 2030 and grows every year to 2034, and more than 101 million is still deferred when the field stops, so it is never claimed. At 65 percent in 2032 the cap is 73531102.32; in 2034 it is 54139706.27 against a claim of 49828572.67. CIT stays 102166298.31 at either limit because the cap limits the hydrocarbon tax only. The cap does not lengthen the five-year allowance, is read on revenue, and never turns a deferral into a loss.'::text),
      ('advanced', 'module', 'm03-hydrocarbon-tax'::text, 9, 'A new shallow water lease with 1000000 bbl in the year earns 8000000.00 from a prior cumulative of 99000000, 4000000.00 on 500000.00 eligible bbl from 99500000, and 0.00 from 100000000. How is the cap read?', '["On lifetime barrels against pia_new_lease_prod_alw_cap_shallow_bbl 100000000, and the year that crosses the cap is split at the barrel that crosses it.", "On the year''s own barrels, so any year that lifts more than the remaining headroom loses the whole allowance for that year.", "On the prior cumulative alone, so a field that starts the year under 100000000 keeps the full 8000000.00 whatever it lifts in the year.", "On the price, since 8 USD/bbl is 10 percent of 80 and the 20 percent of price limit leaves headroom that shrinks as the cumulative rises."]'::jsonb, 0, 'allowance_cap_midyear lifts 2000000.00 bbl from a prior 99000000 and reports prod_alw_eligible_bbl 1000000.00, allowance 8000000.00, cap applied true and cumulative_oil_bbl_lifetime 101000000.00; the 2026 row earns 0.00.'::text, 'A new shallow water lease with 1000000 bbl in the year earns 8000000.00 from a prior cumulative of 99000000, 6000000.00 from 99500000, and 4000000.00 from 100000000. How is the cap read?', '["On lifetime barrels against the 100000000 cap: barrels below it earn 8 USD/bbl, later barrels 4 USD/bbl, and a crossing year is split.", "On the year''s own barrels, so any year that lifts more than the remaining headroom loses the whole allowance for that year.", "By the prior cumulative alone, so a field that starts the year under 100000000 keeps the full 8000000.00 whatever it lifts.", "Against the price, since 8 USD/bbl is 10 percent of 80 and the 20 percent limit leaves headroom that shrinks as the cumulative rises."]'::jsonb, 0, 'allowance_cap_midyear lifts 2000000.00 bbl from a prior 99000000: 1000000.00 below the cap and 1000000.00 after it, allowance 12000000.00, cap applied true, cumulative_oil_bbl_lifetime 101000000.00; its 2026 row earns 4000000.00 on 1000000.00 barrels, all after the cap. The year''s own barrels, the prior cumulative alone and the price do not decide the split.'::text),
      ('advanced', 'module', 'm03-hydrocarbon-tax'::text, 10, 'AKATA as a new lease from a prior cumulative of 0 and from a prior cumulative of 96000000 print identical 2029 rows, allowance 17600000.00 on 2200000.00 eligible bbl with the flag false, yet the life totals are 77440000.00 and 32000000.00 and NPV 56241834.89 against 46513356.33. Why is the first row identical?', '["The engine reads the prior cumulative only from the second year onward, so the first row of every new lease is priced as if the field were fresh.", "The 2029 row earns the allowance on the price cap alone, 20 percent of 82.000000, and the volume cap is only tested once the price cap stops binding.", "The cap has not yet been reached in 2029; it is read on lifetime barrels, and it is the later years that lose the allowance, so only the totals show the difference.", "The flag false on both rows means the volume cap was disabled for the run, and the difference in totals comes from the shorter recovery period of the second case."]'::jsonb, 2, 'At 96000000 prior the field passes 100000000 inside the life, and from that barrel on the eligible count is 0.00; HCT reads 74680493.72 against 61048493.72 with no cap.'::text, 'AKATA as a new lease, with the new-acreage hydrocarbon tax rate stated at 30 (a reading the texts leave open), prints the same 2029 allowance line from a prior cumulative of 0 and of 96000000: allowance 17600000.00 on 2200000.00 eligible bbl with the flag false. Yet the life allowances are 77440000.00 and 54720000.00. Why is the 2029 allowance the same?', '["The engine reads the prior cumulative only from the second year onward, so the first row of every new lease is priced as if the field were fresh.", "The 2029 row earns the allowance on the price cap alone, 20 percent of 82.000000, and the volume cap is only tested once the price cap stops binding.", "The cap has not yet been reached in 2029; it is read on lifetime barrels, and the later years earn the after-cap rate.", "The flag false on both rows means the volume cap was disabled for the run, and the difference in totals comes from the shorter recovery period of the second case."]'::jsonb, 2, 'From a prior of 96000000 the field passes 100000000 in 2030, and every barrel after that earns 4.00 USD/bbl where the fresh field earns 8.00, so the allowances part from 2030 on, though the 2029 cumulative_oil_bbl_lifetime already reads 2200000.00 against 98200000.00. The allowances do not depend on the stated hydrocarbon tax rate; the HCT does, 75682840.32 against 82498840.32 at the stated 30. The prior cumulative is read from the first year, the price limit does not bind at 82, and the recovery period is five years in both runs.'::text),
      ('advanced', 'module', 'm03-hydrocarbon-tax'::text, 11, 'pia_gas_only_hct_zero sells 20000000.00 Mscf and no liquids for 90000000.00. hct_assessable_profit is 0.00 and hct_tax 0.00, while CIT is 14880000.00 on cit_chargeable_profit 49600000.00. Why is one profit tax charged and not the other?', '["The HCT rate is 0.000000 for a gas field under the conservative deep offshore reading, and the engine applies that reading to any field without oil.", "The production allowance on a gas field takes the HCT base to zero, while CIT, which has no allowance, is still charged.", "The HCT is charged only above the minimum effective tax rate of 15 percent, and CIT at 30 percent already satisfies it on a gas field.", "The HCT base is oil and condensate; gas is left out unless pia_hct_include_gas_revenue is opened, while the CIT base includes gas."]'::jsonb, 3, 'With the hatch open the base is rebuilt on the whole revenue, hct_assessable_profit 68600000.00, hct_tax 19380000.00, and NPV falls from 17380000.00 to minus 2000000.00.'::text, 'pia_gas_only_hct_zero sells 20000000.00 Mscf and no liquids for 90000000.00. hct_assessable_profit is 0.00 and hct_tax 0.00, while CIT is 15420000.00 on cit_chargeable_profit 51400000.00. Why is one profit tax charged and not the other?', '["The HCT rate is 0.000000 for a gas field under the conservative deep offshore reading, and the engine applies that reading to any field without oil.", "The production allowance on a gas field takes the HCT base to zero, while CIT, which has no allowance, is still charged.", "The HCT is charged only above the minimum effective tax rate of 15 percent, and CIT at 30 percent already satisfies it on a gas field.", "The HCT base is crude oil and condensate only (PIA s.260(1)), while the CIT base includes the gas revenue."]'::jsonb, 3, 'The hydrocarbon tax is charged on crude oil and condensate, so a gas-only field has no base for it. pia_gas_only_legacy_hct, the same field with pia_hct_include_gas_revenue true, prints the same HCT 0.00 and NPV 18318000.00. No deep offshore reading applies to a shallow water field, the production allowance is 0.00 with no liquids, and no minimum tax test runs in a 2025 year.'::text),
      ('advanced', 'module', 'm03-hydrocarbon-tax'::text, 12, 'On the worked example''s chargeable profit of 949369854.24 the HCT is 284810956.27 on a PML and 142405478.14 on a PPL, and the NPV moves from 135185570.34 to 277591048.48. What moved the tax?', '["The PPL halves the production allowance and the capital allowance together, which halves the chargeable profit and therefore the tax charged on it.", "The licence type alone: deriveHctRate reads 0.300000 for a shallow water PML converted lease and 0.150000 for a PPL, on the same base.", "The PPL moves the field from the 2021 Act to the 2025 framework, and the framework switch halves the hydrocarbon tax rate.", "The PPL is read as a new lease, and the 8 USD/bbl allowance takes the base down to half of the converted lease figure."]'::jsonb, 1, 'The framework does not move HCT: AKATA under force_pia reports the same 77020493.72 as under nta_2025. The licence moves take from 86.1703 percent to 71.6019 with nothing else changed.'::text, 'On the worked example''s chargeable profit of 952616648.19 the HCT is 285784994.46 on a PML and 142892497.23 on a PPL, and the NPV moves from 141236909.83 to 284129407.06. What moved the tax?', '["The PPL halves the production allowance and the capital allowance together, which halves the chargeable profit and therefore the tax charged on it.", "The licence type alone: deriveHctRate reads 0.300000 for a shallow water PML converted lease and 0.150000 for a PPL, on the same base.", "A framework switch: the PPL moves the field from the 2021 Act to the 2025 framework, and the switch halves the hydrocarbon tax rate.", "The PPL is read as a new lease, and the 8 USD/bbl allowance takes the base down to half of the converted lease figure."]'::jsonb, 1, 'The licence moves take from 85.5512 percent to 70.9331 with nothing else changed. The framework sets no different rate for a converted shallow water PML: AKATA reads 0.300000 in every year under force_pia and on auto. The PPL changes neither allowance, stays in the same 2025 year, and is not a new lease.'::text),
      ('advanced', 'module', 'm03-hydrocarbon-tax'::text, 13, 'pia_deep_offshore_full pays HCT 0.00 and reports NPV 890564331.93; the same field reads HCT 419659147.53 under pia_deep_offshore_nta_aggressive with NPV 449025977.03, and 174857978.14 under the custom 12.5 with NPV 693827146.42. What decides which one is right?', '["Nothing in the engine. pia_deep_offshore_hct_interpretation is a string somebody chose, and conservative_zero is a default, not a finding.", "The water depth: pia_water_depth_m 100 is the boundary at which the engine switches from the conservative reading to the aggressive one.", "The framework date trigger: a base year of 2025 selects the 2021 Act and the conservative reading, and a later base year selects the aggressive one automatically.", "The licence: a PML pays the aggressive 0.300000 and a PPL the custom rate, so the string is only a label for what the licence already decided."]'::jsonb, 0, 'On AKATA the same choice is NPV 141623594.88 against 61725382.46, a larger move than the oil price sweep from 82 to 120, which reaches 128984232.18.'::text, 'pia_deep_offshore_full, a 2025 year, pays HCT 0.00 and reports NPV 907723685.14. The same field under force_nta reads HCT 426107993.35 with the stated reading aggressive_pml_30 (NPV 466664592.02) and 177544997.23 with custom 12.5 (NPV 715227588.14). What decides the HCT?', '["In a PIA year the Act, which charges deep offshore nothing; in an NTA year no text does, and the engine refuses the year until a reading is stated.", "Water depth: pia_water_depth_m 100 is the boundary at which the engine switches from the conservative reading to the aggressive one by itself.", "The date trigger alone: every NTA year takes aggressive_pml_30 by default, as the NTA extends the shallow water PML rate to each terrain.", "A PML pays the aggressive 0.300000 and a PPL the custom rate, so the reading string is only a label for what the licence has already decided."]'::jsonb, 0, 'NTA s.65(1) brings deep offshore into the hydrocarbon tax and s.72 prints rates only for onshore and shallow water, so conservative_zero, aggressive_pml_30 and custom are readings somebody states, and the choice stays open. On AKATA the choice is NPV 136554243.51 against 60060654.75, less than the move an oil price sweep from 82 to 120 makes, to 153901708.13. Water depth and licence do not set the NTA reading, and no reading is applied by default.'::text),
      ('advanced', 'module', 'm03-hydrocarbon-tax'::text, 14, 'cpr_forfeiture has cit_assessable_profit 7987389.27 and its recoverable costs would take the base below zero. The engine reports cit_chargeable_profit 2662463.09 and cit_tax 798738.93. What became of the allowance the restriction refused?', '["It became the 8000000.00 in cpr_deferred_to_next, which is the same refused allowance reported under the CPR label rather than the CIT one.", "It was carried to the HCT computation on the same row, which is why the HCT base of 8487389.27 is higher than the CIT base.", "It went into the allowance carryforward that engines 3.10.0 added, and then died with the field, because one year has no later year to claim it in.", "It was written off in the year it arose, since this engine has never carried what the two-thirds restriction refuses."]'::jsonb, 2, 'The chargeable profit is exactly one third of 7987389.27 because two thirds is the most the allowance may take; the published pair prices the carry, pia_cit_allowance_restricted_carry at NPV -113389070.73 against pia_cit_allowance_no_carry at -115209545.41.'::text, 'cpr_forfeiture has cit_assessable_profit 13987213.60 and a first-year allowance that would take the base below zero. The engine reports cit_chargeable_profit 4662404.53 and cit_tax 1398721.36. What became of the allowance the restriction refused?', '["It became the 8000000.00 in cpr_deferred_to_next, which is the same refused allowance reported under the CPR label rather than the CIT one.", "It was carried into the HCT computation on the same row, where it lowers the hydrocarbon tax base below the CIT base by the refused amount.", "It sits in cit_allowance_carryforward, 10675190.93, the excess the two-thirds limit carries forward, and dies with the one-year field.", "It was written off in the year it arose; this engine never carries what the two-thirds restriction refuses."]'::jsonb, 2, 'The chargeable profit is exactly one third of 13987213.60 because two thirds is the most the allowance may take in a pre-2026 year (CITA Second Schedule para 24(7), as substituted by Finance Act 2023 s.9(b)). The published pair prices the carry: pia_cit_allowance_restricted_carry at NPV -102455984.11 against pia_cit_allowance_no_carry at -116276490.72. The 8000000.00 in cpr_deferred_to_next is the cost price ratio deferral, a different amount, and the two assessable profits are equal.'::text),
      ('advanced', 'module', 'm03-hydrocarbon-tax'::text, 15, 'On the one-year worked example, pia_capex_recovery_years 1 claims 482500000.00 and gives NPV 279185570.34, while 10 claims 212500000.00 and gives NPV 117185570.34. What does the setting decide on a field that stops before its recovery years run out?', '["The timing only, because the unclaimed allowance is carried to the cessation year and claimed there in a single final deduction.", "How much of the 300000000.00 is ever claimed: one year claims all of it, ten years claim a tenth, and the rest is never claimed at all.", "The rate at which the deferred CPR pool is released, since the recovery years set the cap on cost claims and not the capital allowance.", "Whether the two thirds restriction binds, since a faster recovery lifts the allowance above two thirds of a thin profit in the first year."]'::jsonb, 1, 'At 5 years the claim is 242500000.00 and NPV 135185570.34; on AKATA the second year''s 45000000.00 of capex starts its own five-year recovery, and a field that stops early leaves its allowance unclaimed.'::text, 'On the one-year worked example, pia_capex_recovery_years 5 runs to NPV 141236909.83, while 1 and 10 are both refused. Why does the engine refuse them?', '["A one-year field cannot carry any allowance past its only year, so the engine refuses every recovery life longer than the ledger it is given.", "The texts fix the capital allowance at five years (PIA Fifth Schedule para 17(1); NTA First Schedule Part II para 14(1)).", "The recovery years set the CPR limit too, and a limit outside 30 to 100 percent is refused by the cap itself.", "Because the two-thirds restriction would bind at one year and at ten, and the engine refuses any run in which that restriction binds."]'::jsonb, 1, 'The PIA sets the allowance at 20, 20, 20, 20 and 19 percent and the NTA at 20 percent a year, so any other recovery life is refused with both texts named. At five years the worked example claims 242500000.00 against the cap. The CPR limit is a separate input, the ledger length does not decide the recovery life, and the restriction never causes a refusal.'::text),
      ('advanced', 'module', 'm04-levies-and-losses'::text, 1, 'On the published PIA worked example the tertiary education tax is 25999871.36 under pia_only and the development levy is 41599794.17 under nta_2025, and the course calls the levy 1.6 x TET. What makes the ratio exactly the ratio of the rates?', '["The levy is charged on the HCT assessable profit of 1054994854.24, which is larger than the CIT base by the fixed NDDC, and the extra base happens to match the rate change.", "Both are charged on the same line, the CIT assessable profit of 1039994854.24, so only the rates differ, 4 against 2.5.", "The levy is charged on the chargeable profit of 979994854.24 after the two-thirds restriction and then grossed up by the restriction, which returns the ratio of the rates.", "The levy includes the TET it replaces, so the 4 percent is the old TET with a surcharge stacked on the same base."]'::jsonb, 1, 'Royalty 217405145.76, HCT 284810956.27 and CIT 293998456.27 are identical in both runs; only the last line changes, and total tax moves from 604809283.90 to 620409206.71.'::text, 'On the published PIA worked example the tertiary education tax is 31747249.45 in its 2025 PIA year, and the development levy is 42329665.93 when the same year is forced to nta_2025, four thirds of the TET. What makes the ratio exactly the ratio of the rates?', '["The levy is charged on revenue less royalty, a larger base than the TET''s, and the extra base matches the rate step.", "Both are charged on the same line, the CIT assessable profit of 1058241648.19, so only the rates differ, 4 against 3.", "The levy is charged on the chargeable profit of 998241648.19 after the capital allowance and then grossed up by the allowance, which returns the ratio of the rates.", "Each levy includes the one it replaces, so the 4 percent is the 3 percent TET plus a one point surcharge."]'::jsonb, 1, 'Royalty 199158351.81, HCT 285784994.46 and CIT 299472494.46 are identical in both runs; only the last line changes, and total tax moves from 617004738.36 to 627587154.84. The TET rate is 3 percent from 2023 under the Finance Act 2023, so on one base the two levies stand as 4 to 3.'::text),
      ('advanced', 'module', 'm04-levies-and-losses'::text, 2, 'A reader who knows the 2021 Act and has heard of the 2025 framework adds TET and the development levy to the same year of AKATA. What does the ledger say about that total?', '["No run of the engine produces it: one of tet_tax and dev_levy_tax is 0.00 on every row, and the fiscal_framework column says which one was charged.", "It is right for AKATA, whose 2029 base year sits on the trigger, so the engine charges TET of 3369056.19 under the Act and a levy of 5390489.91 under the framework in the same year.", "It is right whenever the override is set to auto, because auto blends the two frameworks in proportion to the years each one covers.", "It overstates by the TET only in the years after 2026, since the levy replaces TET from the switch date and the earlier rows keep both."]'::jsonb, 0, 'AKATA on auto pays a levy of 5390489.91 in 2029 and 21007007.79 over the life with TET at 0.00; forced to pia_only it pays TET of 3369056.19 and no levy.'::text, 'A reader who knows the 2021 Act and has heard of the 2025 framework adds TET and the development levy to the same year of AKATA. What does the ledger say about that total?', '["No run of the engine produces it: one of tet_tax and dev_levy_tax is 0.00 on every row, and the fiscal_framework column says which one was charged.", "It is right for AKATA, whose 2029 base year sits on the trigger, so the engine charges TET of 4240064.93 under the Act and a levy of 5653419.91 under the framework in the same year.", "It is right whenever the override is set to auto, because auto blends the two frameworks in proportion to the years each one covers.", "It overstates by the TET only in the years after 2026, since the levy replaces TET from the switch date and the earlier rows keep both."]'::jsonb, 0, 'AKATA on auto is an NTA ledger in every year from 2029: it pays a levy of 5653419.91 in 2029 and 23822173.11 over the life with TET at 0.00; forced to pia_only it pays TET of 4240064.93 in 2029 and no levy.'::text),
      ('advanced', 'module', 'm04-levies-and-losses'::text, 3, 'On pia_loss_relief the 2026 TET is 5755415.35 whether the 2025 CIT loss of 12056305.36 is relieved or clamped. Why does the pool never reach the levy?', '["The pool was already spent against the 2025 HCT of 508108.39, so nothing was left for 2026 to relieve against any base at all.", "The TET is charged on the HCT base, which never went into loss, so a CIT pool has no base to meet on the levy line.", "The clamp only deletes losses on the JV cascade; under the PIA the pool is relieved against every tax on the row including the levy.", "Relief acts on the chargeable profit and the levy sits on the assessable profit, a line the pool is never subtracted from."]'::jsonb, 3, 'The 2026 CIT is 59448092.62 relieved against 63064984.23 clamped, while HCT 63814984.23 and TET 5755415.35 are the same in both runs.'::text, 'On pia_loss_relief the 2026 development levy is 12098579.71 whether the 2025 CIT loss of 43056393.20 is relieved or clamped. Why does the pool never reach the levy?', '["The pool was spent against the 2025 hydrocarbon tax before the year closed, so nothing was left over for 2026 to relieve against any base at all.", "The levy is charged on the HCT base, which never went into loss, so a CIT pool has no base to meet on the levy line of the 2026 row.", "The clamp only deletes losses on the JV cascade; under the PIA the pool is relieved against every tax on the row including the levy.", "Relief acts on the chargeable profit and the levy sits on the assessable profit, a line the pool is never subtracted from."]'::jsonb, 3, 'The 2026 row is an NTA year, so the levy stands where TET would. The 2026 CIT is 65822429.87 relieved against 78739347.83 clamped, and the HCT 61697429.87 against 64789347.83, while the levy of 12098579.71 is the same in both runs: 4 percent of an assessable profit neither pool is subtracted from.'::text),
      ('advanced', 'module', 'm04-levies-and-losses'::text, 4, 'A PIA ledger has a base year of 2027 and no value for pia_under_nta_2025_override at all. Which framework do its rows print?', '["pia_only, because with no override the engine has no instruction to leave the 2021 Act and keeps the framework it was written for.", "The engine refuses the run, since the framework is a required string and the decision table has no row for an unset override.", "nta_2025, because an unset override behaves as auto and the date trigger selects the 2025 framework from 2026 onward.", "nta_2025 for the rows from 2027 and pia_only for any earlier rows the upload carries, because the trigger is read on each row''s year."]'::jsonb, 2, 'The decision table reads base 2027 with the override unset as nta_2025, beside base 2025 auto as pia_only and base 2030 force_pia as pia_only.'::text, 'A PIA ledger runs from 2027 to 2030 and carries no value for pia_under_nta_2025_override at all. Which framework do its rows print?', '["pia_only, because with no override the engine has no instruction to leave the 2021 Act and keeps the framework it was written for.", "The engine refuses the run, since the framework is a required string and the decision table has no row for an unset override.", "nta_2025 on every row, because an unset override behaves as auto and auto makes each year of assessment from 2026 an NTA year.", "nta_2025 on the 2027 row alone and pia_only from 2028, because an unset override applies the 2025 framework to the first year of the ledger only."]'::jsonb, 2, 'The framework is read for each year of assessment. On auto, or with the override unset, 2024 and 2025 are pia_only and 2026 onward nta_2025, so a ledger that starts in 2027 is nta_2025 throughout; force_pia and force_nta apply one framework to every year.'::text),
      ('advanced', 'module', 'm04-levies-and-losses'::text, 5, 'pia_loss_relief has a 2025 base year with rows in 2025 and 2026, and its 2026 row prints pia_only with TET 5755415.35 and a development levy of 0.00. Why did the 2026 row not switch?', '["The framework is chosen once from the base year and every row inherits it; the row year is never read.", "The 2026 row is still inside the transition year, and the engine only switches a row that falls after the base year plus one.", "The loss pool of 12056305.36 carried into 2026 pins the row to the framework the loss was banked under, so relief and framework travel together.", "The engine switched the rate but kept the column name, so the 5755415.35 is a levy at 4 percent printed under the TET heading."]'::jsonb, 0, 'The same holds on pia_cpr_carry_two_years, whose 2025 to 2027 rows all print pia_only, and on elt_pia_multiyear from 2025 to 2030.'::text, 'pia_loss_relief runs on auto with rows in 2025 and 2026. Its 2025 row prints pia_only with no development levy, and its 2026 row prints nta_2025 with a development levy of 12098579.71 and no TET. Why do the two rows differ?', '["The framework is chosen for each year of assessment: on auto a year before 2026 is a PIA year and a year from 2026 an NTA year.", "The loss banked in 2025 moves the ledger onto the 2025 framework in the year it is spent, so any year that uses relief prints nta_2025 whatever its date.", "The engine chose one framework from the base year, and a 2025 base year selects nta_2025 for every row after the first one by design of the switch.", "The engine renamed the column and kept the rate, so the 12098579.71 is TET at 3 percent under the levy heading."]'::jsonb, 0, 'The same holds on pia_cpr_carry_two_years, pia_only in 2025 and nta_2025 in 2026 and 2027, and on elt_pia_multiyear, nta_2025 from 2026 to 2030. A ledger that crosses 2026 is named pia_only_then_nta_2025 in the KPI line.'::text),
      ('advanced', 'module', 'm04-levies-and-losses'::text, 6, 'The worked example at a 2025 base year forced to nta_2025 pays a levy of 41599794.17 with NPV 119585647.53; the same volumes at a 2026 base year on auto pay 41684425.66 with NPV 120347330.91. The framework is nta_2025 both times. What moved the levy?', '["The 3 percent inflation rate deflated the 2026 base year once more, lifting the real profit on which the levy is charged.", "The price royalty anchors escalated a year further, so the price royalty fell from 34905145.759897 to 32789358.588134 and the assessable profit the levy follows rose to 1042110641.41.", "The levy rate steps up in its second year under the framework, which is why the later ledger pays a little more at the same base.", "The 2026 run discounts one year less, and the levy is reported on the discounted profit rather than the row''s nominal one."]'::jsonb, 1, 'Total royalty fell from 217405145.76 to 215289358.59, and HCT rose from 284810956.27 to 285445692.42 and CIT from 293998456.27 to 294633192.42 on the same movement.'::text, 'The worked example in 2025 forced to nta_2025 pays a levy of 42329665.93 with NPV 130654493.35; the same volumes in 2026 on auto pay 42414115.94 with NPV 131414543.48. The framework is nta_2025 both times. What moved the levy?', '["The 3 percent inflation rate deflated the 2026 year once more, lifting the real profit on which the development levy is computed, so the later year pays more.", "The royalty-by-price benchmarks escalated a year further, so the price royalty fell from 34908351.810791 to 32797101.449275 and the assessable profit the levy follows rose to 1060352898.55.", "The levy rate steps up in its second year under the framework, above 4 percent, which is why the later ledger pays a little more on the same assessable base.", "The 2026 run discounts one year less than the 2025 run, and the development levy is reported on the discounted profit of the year rather than the nominal profit printed on the row."]'::jsonb, 1, 'Total royalty fell from 199158351.81 to 197047101.45, and HCT rose from 285784994.46 to 286418369.57 and CIT from 299472494.46 to 300105869.57 on the same movement. The price royalty here is on the Petroleum Royalty Regulations (2021) base, the engine default.'::text),
      ('advanced', 'module', 'm04-levies-and-losses'::text, 10, 'On pia_loss_relief the 2026 HCT of 63814984.23 is the same with relief on and off while the CIT is 59448092.62 relieved against 63064984.23 clamped. Why does relief touch one tax and not the other?', '["The pools are kept per base: 2025''s HCT chargeable profit stayed positive at 1693694.64, so no HCT pool existed, while the CIT base was -12056305.36 and banked a pool.", "HCT is charged on liquids and the loss arose on gas, so the pool is a gas pool that only the CIT base, which includes gas, can absorb.", "The HCT pool was used first against the 2025 HCT of 508108.39 and exhausted, leaving only the CIT pool to reach 2026.", "The engine relieves the larger tax last, and the CIT pool of 12056305.36 was exhausted before the HCT line was reached."]'::jsonb, 0, 'An HCT profit cannot absorb a CIT loss; the two are reported apart as hct_loss_carryforward and cit_loss_carryforward, and NPV moves from -8763295.32 clamped to -5475212.04 relieved.'::text, 'On pia_loss_relief the 2026 HCT is 61697429.87 relieved against 64789347.83 clamped, and the CIT 65822429.87 against 78739347.83. Why does relief move both taxes?', '["The pools are kept per base and 2025 put both into loss: the HCT base banked 10306393.20 and the CIT base 43056393.20, each spent in 2026 against its own tax.", "HCT is charged on liquids and the loss arose on gas, so the pool is one gas pool that both bases share in proportion to revenue.", "One pool of 43056393.20 is banked on the CIT base, and the engine lends part of it to the HCT base whenever the HCT base turns positive in a following year of the ledger.", "The engine relieves the larger tax first and passes whatever is left of a single pool to the smaller one, which is why both taxes fall by exactly the same amount in 2026."]'::jsonb, 0, 'An HCT profit cannot absorb a CIT loss; the two pools are reported apart as hct_loss_carryforward and cit_loss_carryforward, and NPV moves from -9568013.75 clamped to 4985473.45 relieved.'::text),
      ('advanced', 'module', 'm04-levies-and-losses'::text, 12, 'Each regime names the value the horizon left behind differently. Which regime prints no cessation memo at all?', '["Joint venture, which banks the loss in the row''s loss_carryforward column and therefore has no separate memo to print.", "Production sharing: unrecovered cost at cessation is not reported, and the pool can only be read by marching the cost recovery function over the rows.", "The PIA, whose deferred CPR balance is relieved against the final year''s CIT and so never reaches cessation.", "None of them: the JV prints tax losses unused, the PIA prints CPR forfeited and the PSC prints the unrecovered pool at cessation."]'::jsonb, 1, 'cpr_forfeiture ends with CPR forfeited at cessation 8000000.00 and jv_loss_unused_at_cessation with tax losses unused 5000000.00; the PSC pool of 207346412.26 on AKATA at a 30 percent cap appears in no output.'::text, 'Each regime names the value the horizon left behind differently. Which pairing of regime and cessation line is right?', '["Joint venture, which banks the loss in the row''s loss_carryforward column and so prints no line at cessation.", "Production sharing, with kpis.psc_unrecovered_cost_at_cessation: the cost the cost oil cap never let the contractor recover.", "The PIA, whose deferred CPR balance is relieved against the final year''s CIT and so never reaches cessation or any line of its own.", "Joint venture, with CPR forfeited at cessation: the carried royalty the final year could not claim."]'::jsonb, 1, 'cpr_forfeiture ends with CPR forfeited at cessation 8000000.00 and jv_loss_unused_at_cessation with tax losses unused 5000000.00; production sharing reports its unrecovered pool at cessation, 207346412.26 on AKATA at a 30 percent cost oil cap.'::text),
      ('advanced', 'module', 'm04-levies-and-losses'::text, 13, 'With pia_apply_minimum_etr true at 85 percent the worked example grows a min_etr_topup column reading 279186342.20 and total tax becomes 883995626.10. Which taxes count as already paid when the floor is measured?', '["HCT and CIT alone, 284810956.27 and 293998456.27, since the floor is a floor on the profit taxes and royalty is not a tax on profit.", "All of them: the 604809283.90 the floor is measured against includes royalty and the levies.", "Only the taxes charged on the chargeable profit of 979994854.24, which is the profit the 85 percent is applied to and the only line a rate can be measured on.", "HCT, CIT and TET, but not royalty, since royalty is charged on revenue rather than on profit."]'::jsonb, 3, 'The top-up is 85 percent of the CIT assessable profit of 1039994854.24 less the 604809283.90 in the tax column, and that column is HCT 284810956.27 plus CIT 293998456.27 plus TET 25999871.36; royalty 217405145.76, HCDT and NDDC sit outside it, and against HCT plus CIT alone the shortfall would come out larger than 279186342.20.'::text, 'With pia_apply_minimum_etr true at 85 percent and the worked example forced to nta_2025, the row grows a min_etr_topup column and total tax becomes 85 percent of the CIT assessable profit of 1058241648.19. Which taxes count as already paid when the floor is measured?', '["HCT and CIT alone, 285784994.46 and 299472494.46, since the floor is a floor on the profit taxes and a levy on profit is a separate charge outside it.", "All of them: the amount the floor is measured against includes the royalty of 199158351.81, the HCDT, the NDDC and the development levy.", "HCT, CIT and the tertiary education tax at 3 percent, since the floor is tested in exactly the years in which the tertiary education tax is charged.", "HCT, CIT and the development levy, the three taxes in the tax column of an NTA year, with the royalty left outside."]'::jsonb, 3, 'The floor is tested only in NTA years, where the development levy stands in place of TET. Forced to nta_2025 the year pays 627587154.84 before the floor, HCT 285784994.46 plus CIT 299472494.46 plus levy 42329665.93, and the top-up lifts the total to 85 percent of 1058241648.19; the royalty, HCDT and NDDC sit outside it. On the published 2025 year the floor is never tested.'::text),
      ('advanced', 'module', 'm04-levies-and-losses'::text, 14, 'At 15 percent the floor does not bind on the worked example. What does the row show for min_etr_topup?', '["Nothing: the column exists only where the floor was charged, and the KPI line reads min ETR top-up not reported.", "A value of 0.00, printed so that a reader can confirm the floor was tested and found already satisfied.", "The shortfall as a negative number, the amount by which 604809283.90 exceeds 15 percent of 1039994854.24.", "The 15 percent of the assessable profit of 1039994854.24, printed as the floor tested, with a flag beside it reading false because it did not bind."]'::jsonb, 0, 'The default for pia_apply_minimum_etr is false and every other published PIA case runs with it off; when it binds at 85 percent the column appears with 279186342.20.'::text, 'With pia_apply_minimum_etr true at 15 percent, the worked example forced to nta_2025 already pays taxes well above the floor. What does the row show for min_etr_topup?', '["Nothing: the column exists only where the floor was charged, and the KPI line reads min ETR top-up not reported.", "A value of 0.00, printed so that a reader can confirm the floor was tested and found already satisfied.", "The shortfall as a negative number, the amount by which the 627587154.84 of tax exceeds 15 percent of 1058241648.19.", "The 15 percent of the assessable profit of 1058241648.19, printed as the floor tested, with a flag beside it reading false because it did not bind."]'::jsonb, 0, 'The default for pia_apply_minimum_etr is false. The floor is tested only in NTA years: on the published 2025 year it is never tested at any percentage, and forced to nta_2025 at 15 percent the year''s taxes already exceed it, so no column appears.'::text),
      ('advanced', 'module', 'm04-levies-and-losses'::text, 15, 'The 85 percent run turns the worked example''s net cash flow of 135185570.34 into -144000771.86 and its take of 86.1703 percent into 114.7315. How can a take exceed 100 percent?', '["It cannot; a take above 100 percent is a display fault in the KPI line, and the 114.7315 should be read as 100 with the excess carried to the next year.", "The take ratio counts the 300000000.00 of capex as government revenue once the floor binds, since capex recovery is suspended under a minimum rate.", "The top-up is charged on a profit measured before capex, so it can exceed the cash the year generates, and the engine refuses to cap it at the year''s cash.", "The floor is measured on the chargeable profit of 979994854.24 while take is measured on the assessable one, and the two denominators differ by enough to push the ratio past 100."]'::jsonb, 2, 'Payback moves from Year 0 to beyond project life and DPI from 0.450619 to -0.480003; the government collected more than the year''s pre-take value.'::text, 'Forced to nta_2025 with the floor at 85 percent, the worked example''s net cash flow turns from positive to negative and its take rises from 86.6338 percent to past 100 percent. How can a take exceed 100 percent?', '["It cannot; a take above 100 percent is a display fault in the KPI line, and the figure should be read as 100 with the excess carried into the next year of the ledger.", "The take ratio counts the 300000000.00 of capex as government revenue once the floor binds, since capex recovery is suspended under a minimum rate.", "The top-up is charged on a profit measured before capex, so it can exceed the cash the year generates, and the engine refuses to cap it at the year''s cash.", "The floor is measured on the chargeable profit of 998241648.19 while take is measured on the assessable one, and the two denominators differ by enough to push the ratio past 100."]'::jsonb, 2, 'Payback moves from Year 0 to beyond project life and DPI from 0.435515 to -0.470879; the government collected more than the year''s pre-take value. The floor applies only to NTA years, so the published 2025 run at 85 percent pays no top-up and changes nothing.'::text),
      ('advanced', 'module', 'm05-end-of-life'::text, 8, 'pia_sinking_fund contributes 30000000.00 in its single year: HCT falls from 284810956.27 to 275810956.27 and CIT from 293998456.27 to 284998456.27. What happens to the TET of 25999871.36?', '["It falls by 2.5 percent of 30000000.00, since the levy sits on the assessable profit that the contribution reduces.", "Nothing: the contribution relieves the two profit taxes at their rates and the engine refuses to relieve the levies.", "It falls in proportion to CIT, because the levy is a fixed fraction of the CIT paid and moves with it.", "It rises, because a lower HCT leaves more assessable profit for the levy to be charged on."]'::jsonb, 1, 'NPV falls from 135185570.34 to 123185570.34 and the unit technical cost rises from 26.438356 to 28.082192 USD per boe; the levy line is unchanged.'::text, 'pia_sinking_fund contributes 30000000.00 in 2025, a year under the PIA: HCT falls from 285784994.46 to 276784994.46 and CIT from 299472494.46 to 290472494.46. What happens to the TET of 31747249.45?', '["It falls by 2.5 percent of 30000000.00, since the tax sits on the assessable profit that the contribution reduces and 2.5 percent is its rate in 2025.", "It falls by 3 percent of the 30000000.00, to 30847249.45, because TET is charged on the CIT assessable profit the contribution reduces.", "It falls in proportion to CIT, because the tax is a fixed fraction of the CIT paid in the year and so moves exactly as the CIT line moves.", "It rises, because a lower HCT leaves more assessable profit behind in the year for the tertiary education tax to be charged on."]'::jsonb, 1, 'TET at 3 percent from 2023 is charged on the CIT assessable profit, which the contribution takes from 1058241648.19 to 1028241648.19, so TET falls to 30847249.45. NPV falls from 141236909.83 to 130136909.83 and the unit technical cost rises from 26.438356 to 28.082192 USD per boe. The 2.5 percent rate belongs to years before 2023.'::text),
      ('advanced', 'module', 'm05-end-of-life'::text, 10, 'pia_sinking_fund_wi_50 runs at a 50 percent working interest and reports total fund contributions of 30000000.00 beside a total_abandonment_cost and an abandonment_cost_funded of 30000000.00, with NPV 55592785.17. What does the agreement between those three figures say?', '["That the working interest is not applied to the decommissioning lane at all, so a fund at any interest collects the field-level cost and the partner overpays.", "That abandonment_cost_usd is the share under both funding modes since engines 3.10.0, so a fund collects exactly the amount that was entered.", "That the engine grossed the entered 15000000.00 up to a field figure and printed both, which is why the contributions and the cost now agree.", "That the fund was overfunded, and the surplus is released to the contractor in the final row, which is why the contributions exceed what the partner owes."]'::jsonb, 1, 'Until engines 3.10.0 the same row collected 15000000.00 against a reported 30000000.00 and read NPV 61592785.17; on AKATA at 50 percent the fund now collects the whole 60000000.00 and reports NPV 7713047.81 with IRR 14.1861 percent.'::text, 'pia_sinking_fund_wi_50 runs at a 50 percent working interest and reports total fund contributions of 30000000.00 beside a total_abandonment_cost and an abandonment_cost_funded of 30000000.00, with NPV 59518454.92. What does the agreement between those three figures say?', '["That the working interest is not applied to the decommissioning lane at all, so a fund at any interest collects the field-level cost and the partner overpays.", "That abandonment_cost_usd is the share under both funding modes, so a fund collects exactly the amount that was entered.", "It shows the engine grossed an entered 15000000.00 up to a field figure and printed both, which is why the contributions and the cost agree.", "An overfunded fund, the surplus released to the contractor in the final row, which is why the contributions exceed what the partner owes."]'::jsonb, 1, 'The engine grosses the fund by one over the working interest before the monetary lines are scaled, so the contribution lands at the 30000000.00 entered. On AKATA at 50 percent the fund collects the whole 60000000.00 and reports NPV 7713047.81 with IRR 14.1861 percent.'::text),
      ('advanced', 'module', 'm05-end-of-life'::text, 13, 'AKATA at a three-year shift lists rows for 2029, 2030 and 2032 onward with no 2031 row. NPV fell from 40880824.32 at two years to 17894126.42 and IRR fell from 14.6753 to 11.6363 percent, both as they should, yet payback shortened from 4.96 to 4.90 years. Which reading cannot be trusted?', '["The IRR, which fell too far: a longer delay on the same flows cannot move a rate by three percentage points, and the missing row took the rest.", "The NPV, which double-discounted the empty year and fell further than the delay alone can explain.", "None of them, because a ledger with a missing calendar year is refused by the engine and the KPIs printed are those of the two-year run carried forward unchanged.", "The payback, which is counted on rows rather than on calendar years, so the missing row made the delay look a year shorter to it."]'::jsonb, 3, 'A longer wait for the same money cannot shorten a payback; until engines 3.10.0 the IRR of that run read 15.1070 percent and rose with the delay, which was the same row counting reaching the rate.'::text, 'AKATA at a three-year shift lists rows for 2029, 2030 and 2032 onward with no 2031 row. NPV fell from 40880824.32 at two years to 17894126.42 and IRR fell from 14.6753 to 11.6363 percent, both as they should, yet payback shortened from 4.96 to 4.90 years. Which reading cannot be trusted?', '["The IRR, which fell too far: a longer delay on the same flows cannot move a rate by three percentage points, and the missing row took the rest.", "The NPV, which double-discounted the empty year and fell further than the delay alone can explain.", "None of them, because a ledger with a missing calendar year is refused by the engine and the KPIs printed are those of the two-year run carried forward unchanged.", "The payback, which is counted on rows rather than on calendar years, so the missing row made the delay look a year shorter to it."]'::jsonb, 3, 'A longer wait for the same money cannot shorten a payback. The IRR and the NPV both fell with the delay, so only the payback, counted on rows, misreads the missing year.'::text),
      ('advanced', 'module', 'm05-end-of-life'::text, 15, 'The sampled NPV curve of the vector [-100, 208, -108.12] reads zero at 2 percent and again at 6 percent. What does irr() return for it?', '["6.0000 percent, the root Newton reaches from a start of 10 percent, reported on its own with nothing beside it in the result to say that a second root exists inside the band.", "2.0000 percent, the root nearest zero on the positive side, which the engine prefers as the hurdle-rate reading.", "null, with irrStatus multiple-roots and both roots listed, because a rate is named only where exactly one rate in the band from -99 to 1000 percent zeroes the NPV.", "The larger root by rule, since an IRR is read as the highest rate at which the project is still worth doing."]'::jsonb, 2, 'Until engines 3.10.0 it returned 6.0000 percent unflagged; terminal negatives are where the shape comes from, and AKATA with a 60000000 lump sum ends on -29598201.95 and now returns null too.'::text, 'The sampled NPV curve of the vector [-100, 208, -108.12] reads zero at 2 percent and again at 6 percent. What does irr() return for it?', '["6.0000 percent, the root Newton reaches from a start of 10 percent, reported on its own with nothing beside it in the result to say that a second root exists inside the band.", "2.0000 percent, the root nearest zero on the positive side, which the engine prefers as the hurdle-rate reading.", "null, with irrStatus multiple-roots and both roots listed, because a rate is named only where exactly one rate in the band from -99 to 1000 percent zeroes the NPV.", "The larger root by rule, since an IRR is read as the highest rate at which the project is still worth doing."]'::jsonb, 2, 'Terminal negatives are where the shape comes from: AKATA with a 60000000 lump sum ends on -29598201.95 and returns null as well, with its status beside it.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 1, 'AKATA under the PIA pays a development levy of 5390489.91 in 2029. Which line of the row is it charged on?', '["The CIT assessable profit of 134762247.64, before the two-thirds restriction.", "The CIT chargeable profit of 92762247.64, after the capital allowance has been taken off, since a levy follows the tax it accompanies.", "The HCT chargeable profit of 84742595.49, because the levy replaced the TET that the 2021 Act charged on the hydrocarbon tax base.", "The gross revenue of 186032000.00, at a rate blended with the royalty, which is why it moves with the terrain string."]'::jsonb, 0, 'Five taxes on three bases: the levy at 4 percent of 134762247.64 is 5390489.91, and the row''s TET is 0.00 because the base year 2029 selects nta_2025.'::text, 'AKATA under the PIA pays a development levy of 5653419.91 in 2029. Which line of the row is it charged on?', '["The CIT assessable profit of 141335497.73, the base as it stands before the capital allowance comes off.", "The CIT chargeable profit of 99335497.73, after the capital allowance has been taken off, since a levy follows the tax it accompanies.", "The HCT chargeable profit of 90695731.60, because the levy replaced the TET that the 2021 Act charged on the hydrocarbon tax base.", "The gross revenue of 186032000.00, at a rate blended with the royalty, which is why it moves with the terrain string."]'::jsonb, 0, 'The levy at 4 percent of 141335497.73 is 5653419.91. TET is 0.00 because 2029 is itself a year from 2026, so the framework the engine reads for that year of assessment is nta_2025.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 2, 'AKATA under production sharing at a 60 percent cost oil cap reports NPV 29960298.75, and its pool reads 133542720.00 at the end of 2029 and 0.00 by 2034. Where does a reader get those pool figures?', '["From the taxable_income column, which under a PSC is the unrecovered cost carried into the year.", "From the KPI block, which reports the cost recovered in each year whenever the cap binds.", "Only by marching the cost recovery function over the rows the engine produced, because the cost recovered in a year is printed in no column.", "From the difference between gross revenue and net cash flow on each row, which is the cost oil taken that year."]'::jsonb, 2, 'At a 30 percent cap the pool ends at 207346412.26; the rows report royalty, profit oil as taxable income, tax and net cash flow, and since engines 3.10.0 a run can also carry psc_cost_pool_after, the balance rather than the recovery.'::text, 'AKATA under production sharing at a 60 percent cost oil cap reports NPV 29960298.75, and its pool reads 133542720.00 at the end of 2029 and 0.00 by 2034. Where does a reader get those pool figures, and what is still missing?', '["The taxable_income column, which under a production sharing contract is the unrecovered cost carried into each year of the ledger.", "From the KPI block, which reports the cost recovered each year whenever the cost oil cap binds, beside the pool it leaves behind.", "From psc_cost_pool_after on each row; the cost recovered in a year is printed in no column and needs the recovery function marched.", "By subtracting net cash flow from gross revenue on each row, which gives the cost oil the contractor took in that year."]'::jsonb, 2, 'Each PSC row reports royalty, profit oil as taxable income, tax, net cash flow and psc_cost_pool_after, the balance carried. At a 30 percent cap the pool ends at 207346412.26, which the KPI reports as unrecovered at cessation; the recovery itself is in no column.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 3, 'Which terrain''s oil royalty rate changes with the daily rate as a single step rather than a blend?', '["The marginal field, whose rate is 0.050000 to 5000 bopd and then steps once to 0.150000 for every barrel above it.", "Shallow water, which charges 0.125000 up to 50000 bopd and steps to a higher tier past the threshold like deep offshore does.", "Frontier, which starts at 0.050000 and steps to 0.075000 once the field is producing at scale.", "Deep offshore, 0.050000 to 50000 bopd and 0.075000 past it."]'::jsonb, 3, 'Shallow water charges 0.125000 at every rate; the marginal field blends by rate and reads 0.062500 at 10000 bopd; frontier is 0.075000 throughout.'::text, 'Which terrain''s oil royalty rate holds at 0.050000 all the way to 50000 bopd before any barrel pays more?', '["The marginal field, a terrain of its own that charges 0.050000 to 5000 bopd and then 0.150000 on every barrel above that rate.", "Shallow water, which charges 0.050000 up to 50000 bopd and then weights 12.5 percent only on the share of the volume above that rate.", "Frontier, which starts at 0.050000 and weights 7.5 percent on the share above 50000 bopd once the field is producing at scale.", "Deep offshore: 5 percent up to 50000 bopd and 7.5 percent on the share above, weighted, so 0.054167 at 60000 bopd."]'::jsonb, 3, 'Onshore and shallow water weight 5 and 7.5 percent tranches from 5000 bopd, so shallow water already reads 0.062500 at 10000 bopd and 0.112500 at 50000. Frontier is 0.075000 at every rate. A marginal field is onshore or shallow water with its conversion flag set; marginal_field is refused as a terrain.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 4, 'A field sells at a flat 80 USD per barrel for a decade. What does the PIA price royalty do over that decade?', '["It stays fixed at the 2021 rate of 0.030000, because a flat price meets the same anchor every year.", "It falls every year, because the anchors escalate at 2 percent a year from 2021: 80 USD pays 0.023908 in 2025 and 0.010630 in 2035.", "It rises with the field''s cumulative production, since the anchors are read on lifetime barrels rather than on the calendar.", "It falls only after 2030, when the 50 anchor escalates past 80 and the royalty switches off."]'::jsonb, 1, 'A flat price is a falling royalty; at 60 USD the royalty is gone by 2035 because the 50 anchor has escalated past it, and only the 0.100000 ceiling at 200 holds in every year.'::text, 'A field sells at a flat 80 USD per barrel for a decade. What does the PIA price royalty do over that decade?', '["It stays fixed at the 2021 rate of 0.030000, because a flat price meets the same benchmark every year and the benchmarks never move.", "It falls every year as the benchmarks escalate: on the Regulations (2021) base, the default, 80 USD pays 0.023910 in 2025 and 0.010632 in 2035.", "It rises with the field''s cumulative production, since the benchmarks are read on lifetime barrels rather than the calendar year of the sale.", "It falls only after 2030, when the 50 anchor escalates past 80 and the royalty switches off."]'::jsonb, 1, 'A flat price is a falling royalty on either base; the Act reads the same benchmarks one year earlier, a reading the course leaves open. At 60 USD the royalty is gone by 2031 on the Regulations base, and at 200 USD the rate still sits at its 0.100000 ceiling in 2035.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 5, 'AKATA''s NPV moves from 43223505.88 in shallow water to 141623594.88 in deep offshore under the conservative reading. Which two rates did the terrain string change?', '["The production royalty rate and the CIT rate, since CIT under the PIA is set by terrain and falls offshore.", "The production royalty rate and the development levy rate, which the 2025 framework sets lower for deep water.", "The production royalty rate, 0.125000 to 0.050000 on oil, and the HCT rate, 0.300000 to zero under the conservative reading.", "The price royalty rate and the HCT rate, because the price royalty anchors are set per terrain and deep offshore has the highest."]'::jsonb, 2, 'The aggressive reading keeps the HCT rate at 0.300000 and reports 61725382.46 with the same 59501441.00 of royalties; CIT stays 30 in every published case.'::text, 'AKATA''s NPV moves from 59766796.57 in shallow water to 136554243.51 in deep offshore under the stated conservative_zero reading. Which two rates did the terrain string change?', '["The production royalty rate and the CIT rate, since CIT under the PIA is set by terrain and falls offshore.", "The production royalty rate and the development levy rate, which the 2025 framework sets lower for deep water.", "The liquids production royalty rate, the weighted 0.054261 to 0.050000, and the HCT rate, 0.300000 to zero under that reading.", "The price royalty rate and the HCT rate, because the price royalty anchors are set per terrain and deep offshore has the highest."]'::jsonb, 2, 'The aggressive_pml_30 reading keeps the HCT rate at 0.300000 and reports 60060654.75 with the same 59503845.87 of royalties; CIT stays 30 percent in every case, and neither reading is graded.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 6, 'A reader checks every rate on AKATA under the PIA against the published tables, finds each one right, and reports 61725382.46 where 141623594.88 is the right answer. What went wrong?', '["One string, the deep offshore HCT reading, was read the other way; the strings are where the marks are lost, and no rate the reader typed was wrong.", "The reader used the 2021 price royalty anchors, which overstate the royalty and pull the NPV down by the difference.", "The reader ran the ledger on the nominal basis rather than the real one, and the 3 percent inflation accounts for the gap.", "The reader forgot the production allowance of 5500000.00 a year, which over the life is the difference between the two figures."]'::jsonb, 0, 'A fiscal ledger is worked from the outside in: regime, framework, terrain, then the bases; every rate can be right and the headline still wrong.'::text, 'Two readers run AKATA in deep offshore, check every rate against the published tables and find each one right, yet one reports 60060654.75 and the other 136554243.51. What separates them?', '["One string, the stated reading of the deep offshore HCT in an NTA year; neither figure is usable without that reading written beside it.", "The Regulations price royalty benchmarks, used by one reader only, which overstate the royalty and pull the NPV down by the difference between the two.", "A nominal basis for one reader and a real one for the other, with the 3 percent inflation accounting for the gap.", "One reader forgot the production allowance of 5500000.00 in 2029, which over the life of the field is the difference between the two figures."]'::jsonb, 0, 'aggressive_pml_30 charges the hydrocarbon tax at 0.300000 and conservative_zero at nothing. The engine refuses a deep offshore NTA year until one is stated, and the course grades neither: the texts leave the rate open.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 7, 'AKATA as a new lease with prior cumulative 0 and as a new lease with prior cumulative 96000000 print identical 2029 rows, allowance 17600000.00 on 2200000.00 eligible bbl with the cap flag false. How does a reader tell the two runs apart?', '["From the 2029 cap flag, which reads true on the prior-production run because the cap is tested on the prior barrels before the year begins.", "Only from the totals: the allowance is 77440000.00 over the life in one and 32000000.00 in the other, because the cap bites in later years.", "From the 2029 HCT, which is lower on the prior-production run because the allowance is prorated by the barrels left under the cap.", "They cannot be told apart at all, because the engine reports the allowance only for the first year and the totals are both 77440000.00."]'::jsonb, 1, 'HCT is 61048493.72 against 74680493.72 and NPV 56241834.89 against 46513356.33; a converted lease earns 5500000.00 in 2029 and 24200000.00 over the life.'::text, 'AKATA as a new lease with prior cumulative 0 and as a new lease with prior cumulative 96000000, both run at a stated new-PML hydrocarbon tax rate, print the same 2029 allowance line: allowance 17600000.00 on 2200000.00 eligible bbl with the cap flag false. How does a reader tell the two runs apart?', '["From the 2029 cap flag, which reads true on the prior-production run because the cap is tested on the prior barrels before the year begins.", "From cumulative_oil_bbl_lifetime, 2200000.00 against 98200000.00 in 2029; the allowances part from 2030, 77440000.00 against 54720000.00 over the life.", "From the 2029 HCT, which is lower on the prior-production run because the allowance is prorated by the barrels left under the cap.", "They cannot be told apart at all, because the engine reports the allowance only for the first year and the totals are both 77440000.00."]'::jsonb, 1, 'In 2030 the second run crosses 100000000 and earns 14600000.00 against 14800000.00; the 2029 HCT is 23578719.48 in both. After the cap every later barrel still earns the lower after-cap allowance, which is why the second total is lower yet well above zero. The allowance does not depend on the stated rate; a converted lease earns 5500000.00 in 2029 and 24200000.00 over the life.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 8, 'On AKATA''s 2029 row under the PIA the CIT assessable profit is 134762247.64 and the chargeable profit 92762247.64. What is the 42000000.00 between them?', '["The production allowance of 5500000.00 plus the CPR deferral, which together reduce the CIT base before the rate is applied.", "The two-thirds restriction, which caps the chargeable profit at two thirds of the assessable one in every year.", "The HCT of 25422778.65 and the levy of 5390489.91, deducted from the CIT base together with the NDDC of 720000.00 because CIT is charged after them.", "The capital allowance, a fifth of the 210000000.00 capex over pia_capex_recovery_years 5."]'::jsonb, 3, 'CIT at 30 percent of 92762247.64 is 27828674.29; the production allowance never reaches CIT, and the restriction only acts where the allowance is large against a thin profit.'::text, 'On AKATA''s 2029 row under the PIA the CIT assessable profit is 141335497.73 and the chargeable profit 99335497.73. What is the 42000000.00 between them?', '["The production allowance of 5500000.00 plus the CPR deferral, which together reduce the CIT base before the rate is applied.", "The two-thirds restriction, which caps the chargeable profit at two thirds of the assessable one in every year.", "The HCT of 27208719.48 and the levy of 5653419.91, deducted from the CIT base together with the NDDC of 7020000.00 because CIT is charged after them.", "The capital allowance: a fifth of the 210000000.00 capex, the 20 percent a year the texts fix in NTA years."]'::jsonb, 3, 'CIT at 30 percent of 99335497.73 is 29800649.32. The production allowance never reaches CIT, and the two-thirds restriction on capital allowances is a rule for PIA years, so an NTA year like 2029 has none.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 9, 'AKATA''s CPR cap binds in 2033, deferring 14561618.62, and the deferral clears in 2034. What would the same deferral have been if the ledger had ended in 2033?', '["A forfeiture: a deferred cost does not become a loss and does not survive cessation, so it would be reported as CPR forfeited and never claimed.", "A tax loss of 14561618.62 banked in hct_loss_carryforward and reported as tax losses unused at cessation.", "A refund, because a cap that binds in the final year is settled against the taxes already paid in earlier years.", "A claim in the final year, since the engine lifts the cap in the last row so that nothing is left on the table."]'::jsonb, 0, 'cpr_forfeiture defers 8000000.00 with no later year and ends with CPR forfeited at cessation 8000000.00; pia_cpr_carry_two_years forfeits 66000000.00 after three binding years.'::text, 'AKATA''s CPR cap binds in 2033, deferring 14120774.92, and the deferral clears in 2034. What would the same deferral have been if the ledger had ended in 2033?', '["A forfeiture: a deferred cost does not become a loss and does not survive cessation, so it would be reported as CPR forfeited and never claimed.", "A tax loss of 14120774.92 banked in hct_loss_carryforward and reported beside the other tax losses left unused at cessation.", "A refund, because a cap that binds in the final year is settled against the hydrocarbon tax already paid in the earlier years of the field.", "A claim in the final year, since the engine lifts the cap in the last row so that no deferred cost is left on the table at cessation."]'::jsonb, 0, 'cpr_forfeiture defers 8000000.00 with no later year and ends with CPR forfeited at cessation 8000000.00; pia_cpr_carry_two_years forfeits 66000000.00 after three binding years.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 11, 'The engine holds both readings of deep offshore HCT, 141623594.88 and 61725382.46 on AKATA. Which does it choose?', '["The conservative one, which the course records as conservative_zero and which is a finding of the extraction rather than a default.", "Neither: the choice belongs to counsel, and a ledger that reports one without the other has taken a legal position without saying so.", "The aggressive one, because the engine prefers the reading that collects more tax when the law is unsettled.", "The one that agrees with the terrain string, since deep offshore under the 2025 framework carries a fixed rate of 0.300000 in the table."]'::jsonb, 1, 'The engine models one reading of the law at a time; conservative_zero is a default somebody chose, not a finding.'::text, 'The engine holds both readings of deep offshore HCT in an NTA year, 136554243.51 and 60060654.75 on AKATA. Which does it choose?', '["The conservative one, which the course records as conservative_zero and which is a finding of the extraction rather than a default.", "Neither: it refuses the run until a reading is stated, and the choice belongs to counsel, never to a default.", "The aggressive one, because the engine prefers the reading that collects more tax when the law is unsettled.", "The one that agrees with the terrain string, since deep offshore under the 2025 framework carries a fixed rate of 0.300000 in the table."]'::jsonb, 1, 'NTA s.65(1) brings deep offshore into the hydrocarbon tax and s.72 prints rates only for onshore and shallow water, so without pia_deep_offshore_hct_interpretation the engine refuses a deep offshore NTA year. Neither reading is a finding.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 12, 'A reader builds a distribution of AKATA''s NPV by rerunning the ledger across many price paths. What does the distribution inherit?', '["Every convention the ledger carries: basis, discounting convention, framework, terrain and reading, since the engine models one price path, one schedule and one working interest at a time.", "Nothing but the price range, because a probabilistic layer strips the fiscal conventions out of the runs it aggregates and reports a distribution that is free of convention, which is the whole point of building one.", "The IRR''s choice of root, which becomes a distribution of its own once Newton starts from 10 percent on every path, and which then replaces the NPV as the ranking measure because a rate needs no discount rate.", "A breakeven price, which the engine reports for each path and averages into the headline."]'::jsonb, 0, 'Ranges belong to the sweeps and to a probabilistic layer this course does not own; the price sweep from 82 to 120 moves NPV less than the terrain string does.'::text, 'A reader builds a distribution of AKATA''s NPV by rerunning the ledger across many price paths. What does the distribution inherit?', '["Every convention the ledger carries: basis, discounting convention, framework, terrain and reading, since the engine models one price path, one schedule and one working interest at a time.", "Nothing but the price range, because a probabilistic layer strips the fiscal conventions out of the runs it aggregates and reports a distribution that is free of convention, which is the whole point of building one.", "The IRR''s choice of root, which becomes a distribution of its own once Newton starts from 10 percent on every path, and which then replaces the NPV as the ranking measure because a rate needs no discount rate.", "A breakeven price, which the engine reports for each path and averages into the headline."]'::jsonb, 0, 'Ranges belong to the sweeps and to a probabilistic layer this course does not own; the price sweep from 82 to 120 alone takes AKATA from 59766796.57 to 153901708.13.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 14, 'The same AKATA rows produced 72534830.66, 43223505.88, 141623594.88 and 61725382.46 without a barrel or a price changing. What changed between the four?', '["The discount rate, swept across the profile from 0 to 20 percent, with the four figures read at four of its points.", "The regime, the terrain string and the reading of the deep offshore HCT rule, and each figure is right for its question.", "The basis and the convention, since nominal against real and end-year against mid-year give four combinations.", "The working interest, stepped from 100 percent down through the published shares, with the PIA take invariant at 75.5752 percent across them."]'::jsonb, 1, '72534830.66 is JV terms, 43223505.88 the PIA in shallow water, 141623594.88 deep offshore conservative and 61725382.46 deep offshore aggressive; a number without its convention is not a number.'::text, 'The same AKATA rows produced 72534830.66, 59766796.57, 136554243.51 and 60060654.75 without a barrel or a price changing. What changed between the four?', '["The discount rate, swept across the profile from 0 to 20 percent, with the four figures read at four of its points.", "The regime, the terrain string and the stated reading of the deep offshore HCT rule, which the last two figures answer two ways.", "The basis and the convention, since nominal against real and end-year against mid-year give four combinations.", "The working interest, stepped from 100 percent down through the published shares, with the PIA take invariant at 70.6449 percent across them."]'::jsonb, 1, '72534830.66 is JV terms, 59766796.57 the PIA in shallow water, and 136554243.51 and 60060654.75 deep offshore under the stated conservative_zero and aggressive_pml_30 readings; a number without its convention is not a number.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 15, 'The ledger prices its levers in one currency. On AKATA under the PIA, what is a CPR cap of 40 percent worth?', '["The distance from 43223505.88 to 21611752.94, the same halving that a 50 percent working interest produces, since a cap on costs and a share of the field scale the ledger alike.", "Nothing on AKATA, because a cap of 40 percent of costs is above the costs claimed in every year, just as the worked example swept from 30 to 100 percent keeps 242500000.00 claimed at every setting.", "The distance from 43223505.88 to -1723561.25: the cap is a word in a document and it moves NPV further than the oil price sweep from 82 to 120 does.", "The distance from 43223505.88 to 37060198.23, the same move as taking the field onshore."]'::jsonb, 2, 'At 40 percent HCT rises from 77020493.72 to 107354738.83 and CIT from 85840666.18 to 117121931.63; the cap is a tax on the decline.'::text, 'The ledger prices its levers in one currency. On AKATA under the PIA, what is a CPR limit of 40 percent worth?', '["The distance from 59766796.57 to 29883398.29, the same halving that a 50 percent working interest produces, since a cap on costs and a share scale the ledger alike.", "Nothing on AKATA, because a limit of 40 percent is above the costs claimed in every year, just as the worked example swept from 30 to 100 percent keeps 242500000.00 claimed.", "The distance from 59766796.57 to 37056190.44, all of it through the HCT line; the price sweep from 82 to 120 moves NPV further.", "The distance from 59766796.57 to 97891150.04, the same move as converting the field as a marginal field under s.94(1)."]'::jsonb, 2, 'At 40 percent HCT rises from 91654840.32 to 121989085.43 while CIT stays 102166298.31, because the cap limits only the costs claimed against the hydrocarbon tax; the price sweep to 120 takes NPV to 153901708.13.'::text)
    ) as t(tier, scope, module_key, ord, old_prompt, old_options, old_answer, old_expl, new_prompt, new_options, new_answer, new_expl)
  loop
    select case
             when q.prompt = r.old_prompt and q.options = r.old_options and q.answer_index = r.old_answer and q.explanation is not distinct from r.old_expl then 'old'
             when q.prompt = r.new_prompt and q.options = r.new_options and q.answer_index = r.new_answer and q.explanation is not distinct from r.new_expl then 'new'
             else 'other' end
      into v_state
      from public.academy_quiz_questions q
     where q.app_slug = 'cashflow' and q.active and q.tier = r.tier and q.scope = r.scope
       and q.module_key is not distinct from r.module_key and q.ord = r.ord;
    get diagnostics v_count = row_count;
    if v_count <> 1 then
      raise exception 'ec7 pia recut refused: cashflow/%/%/%/ord % matched % active rows, expected 1', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord, v_count;
    end if;
    if v_state = 'other' then
      raise exception 'ec7 pia recut refused: cashflow/%/%/%/ord % carries neither its published text nor the recut text', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord;
    end if;
    if v_state = 'old' then
      update public.academy_quiz_questions q
         set prompt = r.new_prompt, options = r.new_options, answer_index = r.new_answer, explanation = r.new_expl
       where q.app_slug = 'cashflow' and q.active and q.tier = r.tier and q.scope = r.scope
         and q.module_key is not distinct from r.module_key and q.ord = r.ord;
      get diagnostics v_count = row_count;
      if v_count <> 1 then
        raise exception 'ec7 pia recut refused: cashflow/%/%/%/ord % update touched % rows', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord, v_count;
      end if;
      v_updated := v_updated + 1;
    else
      v_done := v_done + 1;
    end if;
  end loop;

  for r in select t as tier from unnest(array['beginner', 'intermediate', 'advanced']) t loop
    select count(*) into v_count from public.academy_quiz_questions where app_slug = 'cashflow' and active and tier = r.tier;
    if v_count <> 132 then
      raise exception 'ec7 pia recut refused: cashflow/% holds % active questions, expected 132', r.tier, v_count;
    end if;
  end loop;
  select count(*) into v_count from public.academy_quiz_questions where app_slug = 'cashflow' and active;
  if v_count <> 396 then
    raise exception 'ec7 pia recut refused: cashflow holds % active questions, expected 396', v_count;
  end if;
  raise notice 'ec7 pia recut: cashflow questions, % updated, % already recut, of 154', v_updated, v_done;
end $$;

-- ----------------------------------------------------------------------------
-- 1. fiscal: 110 question rows.
-- ----------------------------------------------------------------------------
do $$
declare
  r         record;
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_done    integer := 0;
begin
  for r in
    select * from (values
      ('beginner', 'final', null::text, 2, 'PIA and Generic both carry corporate income tax at 30 percent, resource rent tax at 0 and a minimum tax of 0, yet the default project returns 406.2057 to the contractor under PIA and 986.7327 under Generic. What opened the gap?', '["The PIA sliding royalty, which reaches 10 percent on this deck against the Generic flat rate of 12.5 percent.", "The tax base, which is gross revenue under PIA and the contractor''s profit share under Generic.", "A cost recovery limit of 80 percent instead of 100, and an R factor split handing over 60, then 40, then 30 percent of profit oil instead of all of it.", "The production profile, which the PIA template shortens to the years in which its tranches apply."]'::jsonb, 2, 'PIA pays the smaller tax bill of the two, 174.0882 against 422.8854, and still leaves the contractor less than half the cash. A tax rate quoted alone predicts nothing.'::text, 'On the default project the contractor keeps 1058.0159 under the PIA template and 986.7327 under Generic, though both tax profit at 30 percent with no resource rent tax and no minimum tax. What opened the gap?', '["The PIA cost recovery limit of 70 percent of the gross value of crude oil and NGL, which hands cost back to the contractor faster than Generic''s full limit does.", "A tax base that is gross revenue under PIA and the contractor''s profit share under Generic.", "A much smaller royalty, 154.4828 against 335.8660, which the government''s 5 percent of profit oil and the larger PIA tax win back only in part.", "The production profile, which the PIA template shortens to the years in which its tranches apply."]'::jsonb, 2, 'Totals do not care when cost comes back: both templates recover 941.4436 over the life. The PIA line pays the larger tax, 453.4354 against 422.8854, and still keeps more cash. A tax rate quoted alone predicts nothing.'::text),
      ('beginner', 'final', null::text, 6, 'The engine returns a total government cash flow of 1339.2784 under the PIA template on the default project. What is that number?', '["A shape, useful for asking which instrument moved which result, and unfit for filing anything.", "An assessment of the Nigerian take on a deepwater project, computed under the Petroleum Industry Act.", "A screening estimate that the Petroleum Economics Studio engine would reproduce to within a rounding.", "A statutory minimum, since the templates are calibrated to the floor each jurisdiction would accept."]'::jsonb, 0, 'The engine''s own header says the single source of truth for Nigerian fiscal math is the Petroleum Economics Studio engine, and that this model compares the shape of regimes.'::text, 'The engine returns a total government cash flow of 687.4682 under the PIA template on the default project. What is that number?', '["A shape, useful for asking which instrument moved which result, and unfit for filing anything.", "A filed assessment of the Nigerian take on this project, ready to lodge because the template carries the terms of the Act.", "A screening estimate that the Petroleum Economics Studio engine would reproduce to within a rounding.", "A statutory ceiling on what the state may collect, since each template is calibrated to the most its jurisdiction allows."]'::jsonb, 0, 'The engine''s own header says the single source of truth for Nigerian fiscal math is the Petroleum Economics Studio engine, and that this model compares the shape of regimes.'::text),
      ('beginner', 'final', null::text, 16, 'Nigeria PIA and Brazil collect exactly the same total royalty on both published projects, 268.6928 and 700.1194. One is a slider and one is flat 10 percent. How?', '["The slider averages its two tiers of 7.5 and 10 percent across the life, which lands on the flat rate.", "A sliding royalty defaults to the flat rate of the template it is compared against when no tier is crossed.", "The two templates share a cost recovery limit, and royalty is charged after the limit has been applied.", "Every applied price in both fields is above the slider''s 50 USD per bbl threshold, so it sits in its 10 percent tier throughout."]'::jsonb, 3, 'The default project prices oil at 70, 75 and 80 and the test project at 80, so a sliding instrument that never slides is a flat one.'::text, 'Brazil - Concession charges a flat 10 percent and collects 268.6928 of royalty on the default project, where Nigeria - PIA (2021) collects 154.4828. What does the PIA template''s royalty charge in each year?', '["Two price tiers, 7.5 percent from 0 and 10 percent from 50 USD per bbl, which on this deck sit in the 10 percent tier in every one of the 25 years of the life of the field.", "A flat 5 percent on the whole of gross revenue in every year, oil, gas and NGL alike, which is why its total comes to about half of Brazil''s flat 10 percent.", "A rate keyed on the R factor, stepping up each time cumulative revenue overtakes another multiple of cumulative cost on the field, whatever the oil price does in the year.", "A production royalty at the deep offshore rate for the year''s daily oil rate, a royalty by price once oil passes that year''s low benchmark, and 5 percent on gas and NGL."]'::jsonb, 3, 'Over the life that comes to 154.4828 on revenue of 2686.9277, and on the test project 443.2226 against Brazil''s 700.1194. On neither project do the two collect the same total.'::text),
      ('beginner', 'final', null::text, 18, 'The six templates fall into two families. What defines the family that Brazil, the Gulf of Mexico and Generic belong to?', '["A flat royalty rate, which the other three replace with a slider keyed on the oil price.", "A flat split handing the contractor 100 percent of profit oil, with cost recovery at a 100 percent limit.", "A tax stack with no resource rent tax, which is what leaves the contractor the whole of the residual.", "A cost recovery limit above 80 percent, which stops the pool from ever carrying a balance forward."]'::jsonb, 1, 'That is what a concession looks like inside a model built around a production sharing ledger, and the other three cap recovery at 80, 90 and 50 percent.'::text, 'The six templates fall into two families. What defines the family that Brazil, the Gulf of Mexico and Generic belong to?', '["A flat royalty rate, which none of the other three templates carries in any form at all.", "A flat split handing the contractor 100 percent of profit oil, with cost recovery at a 100 percent limit.", "A tax stack with no resource rent tax, which is what leaves the contractor the whole of the residual.", "A cost recovery limit above 80 percent, which stops the pool from ever carrying a balance forward."]'::jsonb, 1, 'That is what a concession looks like inside a model built around a production sharing ledger. Ghana and Angola cap recovery at 90 and 50 percent of revenue after royalty, and Nigeria - PIA (2021) at 70 percent of the gross value of crude oil and NGL.'::text),
      ('beginner', 'final', null::text, 29, 'Payback and payout are two clocks on one ledger. What does each one measure?', '["Payback is the first year the unrecovered pool closes at 0.0000, and payout the first year profit oil is positive.", "Payback is the first year cumulative contractor net cash flow is above zero, and payout the first year the R factor is above 1.0.", "Payback is measured on the contractor''s cash and payout on the state''s, so the two together bracket the project.", "Payback is the undiscounted crossing and payout the same crossing taken at the project''s discount rate."]'::jsonb, 1, 'Both are null when the event never happens, and on the default project PIA and Angola report payback 4 against payout 3.'::text, 'Payback and payout are two clocks on one ledger. What does each one measure?', '["Payback is the first year the unrecovered pool closes at 0.0000, and payout the first year profit oil is positive.", "Payback is the first year cumulative contractor net cash flow is above zero, and payout the first year the R factor is above 1.0.", "Payback is measured on the contractor''s cash and payout on the state''s, so the two together bracket the project.", "Payback is the undiscounted crossing and payout the same crossing taken at the project''s discount rate."]'::jsonb, 1, 'Both are null when the event never happens, and on the default project Angola - Deepwater PSC reports payback 4 against payout 3.'::text),
      ('beginner', 'final', null::text, 30, 'Run six templates on the default project and total revenue reads 2686.9277 on every line. What does that constant make possible?', '["It makes the whole of the spread in the answer attributable to the regime and to nothing else.", "It makes the six ledgers comparable with the test project''s 7001.1938.", "It makes the cost recovery totals comparable, since a constant revenue means a constant recoverable pool.", "It makes the government cash flow rankable by royalty rate, since the base of the royalty is the same in each."]'::jsonb, 0, 'A fiscal regime prices barrels, it does not produce them. Contractor cash ranges from 406.2057 to 986.7327 against that identical sales figure.'::text, 'Run six templates on the default project and total revenue reads 2686.9277 on every line. What does that constant make possible?', '["It makes the whole of the spread in the answer attributable to the regime and to nothing else.", "It makes the six ledgers comparable with the test project''s 7001.1938.", "It makes the cost recovery totals comparable, since a constant revenue means a constant recoverable pool.", "It makes the government cash flow rankable by royalty rate, since the base of the royalty is the same in each."]'::jsonb, 0, 'A fiscal regime prices barrels, it does not produce them. Contractor cash ranges from 428.8774 to 1058.0159 against that identical sales figure.'::text),
      ('beginner', 'final', null::text, 32, 'ODIDI closes its cumulative in the black under all six templates and returns a negative value under all six at the project''s 12 percent. What is the reading?', '["The value and the cumulative disagree because the value excludes the year 1 capex of 420.0000.", "The field returns its nominal money and is still not worth building at the rate it is discounted at.", "The field is worth building under the templates whose cumulative is largest, which the value fails to rank.", "The negative values are an artefact of the fixed 25 year horizon cutting the life short."]'::jsonb, 1, 'Brazil ends with 192.9896 of cash and a value of -5.8662, and Angola with 109.1947 and -58.1813.'::text, 'Five of the six templates leave ODIDI with a negative value at 12 percent even though every cumulative closes positive. How should those five be read?', '["The value and the cumulative disagree because the value excludes the year 1 capex of 420.0000.", "The money comes back in nominal terms under those five, and the field still fails the discount rate it is judged at.", "The five are worth building after all, because a cumulative in the black outranks a value taken at any discount rate.", "The negative values are an artefact of the fixed 25 year horizon cutting the life short."]'::jsonb, 1, 'Brazil ends with 192.9896 of cash and a value of -5.8662, and Angola with 109.1947 and -58.1813. Under Nigeria - PIA (2021) the same field clears 12 percent, with a value of 1.7389.'::text),
      ('beginner', 'final', null::text, 33, 'Under PIA the government take on ODIDI stays inside a band from 75.1077 to 79.4678 across nine price points, where another template gives up tens of percentage points across the same range. What does one run at one deck tell you about that difference?', '["The ranking at the base price, which the sweep then preserves at every other price it visits.", "The direction of the movement, since a regime with the higher take at one price gives up more of it as prices climb.", "The size of the movement, which is proportional to the royalty rate the template carries.", "Nothing, because one run is one deck and the shape of a regime across prices is not in a single ledger."]'::jsonb, 3, 'Two regimes that look similar on one run behave nothing alike on the next, and the same holds for a cost overrun.'::text, 'On ODIDI the PIA template''s government take moves only between 42.2597 and 50.4050 over nine swept prices, while another template loses tens of percentage points over the same range. What does a single run at a single deck tell you about that contrast?', '["The ranking at the base price, which the sweep then preserves at every other price it visits.", "The direction of the movement, since a regime with the higher take at one price gives up more of it as prices climb.", "The size of the movement, which is proportional to the royalty rate the template carries.", "Nothing, because one run is one deck and the shape of a regime across prices is not in a single ledger."]'::jsonb, 3, 'Two regimes that look similar on one run behave nothing alike on the next, and the same holds for a cost overrun.'::text),
      ('beginner', 'final', null::text, 34, 'ODIDI''s year 1 under the Gulf of Mexico terms sells 139.6563 and spends 420.0000 of capex and 25.0037 of opex. What does the state collect that year?', '["26.1856, all of it royalty, charged on gross revenue in the year the whole of the capital was spent.", "0.0000, because the year''s residual is nothing and there is no profit oil for the state to share.", "26.1856 of royalty less the state''s share of the year''s opex, which the recovery machinery credits back.", "10.4742, which is the 7.5 percent the PIA slider charges at a deck price of 45 USD per bbl."]'::jsonb, 0, 'Royalty comes off gross revenue before any cost is considered, and revenue after royalty for the year is 113.4707.'::text, 'ODIDI''s year 1 under the Gulf of Mexico terms sells 139.6563 and spends 420.0000 of capex and 25.0037 of opex. What does the state collect that year?', '["26.1856, all of it royalty, charged on gross revenue in the year the whole of the capital was spent.", "0.0000, because the year''s residual is nothing and there is no profit oil for the state to share.", "26.1856 of royalty less the state''s share of the year''s opex, which the recovery machinery credits back.", "10.4742, which is a flat 7.5 percent royalty charged on the year''s gross revenue at a deck price of 45 USD per bbl."]'::jsonb, 0, 'Royalty comes off gross revenue before any cost is considered, and revenue after royalty for the year is 113.4707.'::text),
      ('beginner', 'final', null::text, 36, 'The Designer''s own field empties its cost pool in year 3 under the Gulf of Mexico terms and closes the life at 0.0000, while the teaching field empties its own and then closes the life with 24.2824 unrecovered, at the same 100 percent limit. What differs?', '["Its cost recovery limit of 100 percent is reached in every one of its 25 years, where the other field''s stops binding altogether once the standing pool has cleared in year 3.", "The teaching field declines 14 percent a year, so late revenue after royalty of 5.6128 no longer covers opex of 12.3405 and the pool refills.", "Its capex of 420.0000 is smaller than the 500.0000 of the other field, and a smaller pool takes longer to clear.", "Its cash flows are discounted at 12 percent rather than 10, and the pool is carried forward at the project rate."]'::jsonb, 1, 'A full limit is a ceiling on revenue after royalty, not a promise to return the spend, and this field closes with 24.2824 unrecovered.'::text, 'The Designer''s own field empties its cost pool in year 3 under the Gulf of Mexico terms and closes the life at 0.0000, while the teaching field empties its own and then closes the life with 24.2824 unrecovered, at the same 100 percent limit. What differs?', '["Its cost recovery limit of 100 percent is reached in every one of its 25 years, where the other field''s stops binding altogether once the standing pool has cleared in year 3.", "The teaching field declines 14 percent a year, so late revenue after royalty of 5.6128 no longer covers opex of 12.3405 and the pool refills.", "Its capex of 420.0000 is smaller than the 500.0000 of the other field, and a smaller pool takes longer to clear.", "Its cash flows are discounted at 12 percent rather than 10, and the pool is carried forward at the project rate."]'::jsonb, 1, 'Late in its life this field''s revenue after royalty no longer covers opex, so the pool refills and closes at 24.2824 even under a full limit.'::text),
      ('beginner', 'final', null::text, 40, 'ODIDI under Brazil returns 192.9896 of contractor cash over 25 years and a value of -5.8662 at 12 percent. Which reading is wrong?', '["The value, because a life that returns positive cash cannot be worth less than nothing.", "Neither. Both are readings of the same 25 rows, and the Associate answer quotes each with its basis.", "The total, because it adds year 25 money to year 1 money and so overstates what came back.", "The pair, because a total and a value that disagree in sign cannot both be readings of one ledger."]'::jsonb, 1, 'Which of the two a decision rests on takes a discount convention, and every one of the six templates on ODIDI shows the same pair of signs.'::text, 'ODIDI under Brazil returns 192.9896 of contractor cash over 25 years and a value of -5.8662 at 12 percent. Which reading is wrong?', '["The value, because a life that returns positive cash cannot be worth less than nothing.", "Neither. Both are readings of the same 25 rows, and the Associate answer quotes each with its basis.", "The total, because it adds year 25 money to year 1 money and so overstates what came back.", "The pair, because a total and a value that disagree in sign cannot both be readings of one ledger."]'::jsonb, 1, 'Which of the two a decision rests on takes a discount convention. Five of the six templates on ODIDI show this pair of signs; under Nigeria - PIA (2021) both are positive, 229.9586 and 1.7389.'::text),
      ('beginner', 'final', null::text, 41, 'What can the Associate reading of ODIDI, which puts the state''s collection between 232.9950 and 316.7898, not say?', '["Which template collects the most, since two collections are only comparable when the closing unrecovered pools of the two ledgers are equal.", "Which template leaves the contractor the most cash over the life of the field, which is a ranking that needs a discount convention this tier does not carry.", "How much of each collection came from royalty rather than from tax.", "Which of those splits is fair, which survives a price collapse, and which numbers on a comparison screen are measurements at all."]'::jsonb, 3, 'The contractor keeps between 109.1947 and 192.9896 across the same six templates, and stating the range is not judging it.'::text, 'The Associate reading of ODIDI puts the state''s collection between 196.0260 and 316.7898. What can that reading not say?', '["Which template collects the most, since two collections are only comparable when the closing unrecovered pools of the two ledgers are equal.", "Which template leaves the contractor the most cash over the life of the field, which is a ranking that needs a discount convention this tier does not carry.", "How much of each collection came from royalty rather than from tax.", "Which of those splits is fair, which survives a price collapse, and which numbers on a comparison screen are measurements at all."]'::jsonb, 3, 'Stating a range is one reading and judging it is another. On the contractor''s side, the same six runs span 109.1947 to 229.9586.'::text),
      ('beginner', 'final', null::text, 42, 'Every template in the Associate tier was read at one setting, yet three of the six carry an instrument that moves on its own. Which are they?', '["A cost recovery limit that tightens automatically as the standing pool grows, and a minimum tax that arms itself once the residual has fallen far enough.", "A corporate rate that steps with the R factor, and a royalty that steps with cumulative production.", "A royalty keyed on the oil price and a profit split keyed on the R factor, which under PIA steps the share from 60 to 40 to 30 percent.", "A discount rate that follows the price deck from one year to the next, and a profit split that follows the closing unrecovered pool of the year before it."]'::jsonb, 2, 'The R factor is a ratio of cumulatives, so it can fall back below a threshold it passed and step the contractor''s share up again.'::text, 'Every template in the Associate tier was read at one setting, yet three of the six carry an instrument that moves on its own. Which are they?', '["A cost recovery limit that tightens automatically as the standing pool grows, and a minimum tax that arms itself once the residual has fallen far enough to trigger it.", "A corporate rate that steps with the R factor, and a royalty that steps with cumulative production, so that both of them tighten together as the field matures.", "A profit split keyed on the R factor under Ghana and Angola, and under the PIA template a royalty that follows price and daily rate and a split that follows cumulative production.", "A discount rate that follows the price deck from one year to the next, and a profit split that follows the closing unrecovered pool of the year before it, whatever the price may be."]'::jsonb, 2, 'Under Ghana and Angola the R factor is a ratio of cumulatives, so it can fall back below a threshold it passed and step the contractor''s share back up. Cumulative production only grows, so the PIA split can only move one way.'::text),
      ('beginner', 'module', 'm01-what-a-fiscal-regime-is'::text, 3, 'Nigeria - PIA (2021) and Generic Royalty/Tax both carry CIT 30 percent, RRT 0 percent and minimum tax 0 percent, yet on the Designer''s default project the contractor keeps 406.2057 million USD under one and 986.7327 million USD under the other. What opened that gap?', '["A heavier tax bill under the PIA terms, which totals 422.8854 million USD over the life against 174.0882 million USD for the Generic terms.", "The other three fields, a cost recovery limit of 80 percent instead of 100 and an R factor split of 60, then 40, then 30 percent instead of a flat 100 percent to the contractor.", "A larger royalty under the PIA slider, which collects 335.8660 million USD against the 268.6928 million USD the Generic rate collects.", "Different sales, since the PIA line is run against a lower price deck than the Generic line is."]'::jsonb, 1, 'The PIA line pays the smaller tax of the two, 174.0882 million USD against 422.8854, and the smaller royalty, 268.6928 against 335.8660. A tax rate quoted on its own predicts nothing.'::text, 'Nigeria - PIA (2021) and Generic Royalty/Tax both carry CIT 30 percent, RRT 0 percent and minimum tax 0 percent, yet on the Designer''s default project the contractor keeps 1058.0159 million USD under one and 986.7327 million USD under the other. What opened that gap?', '["A lighter tax bill under the PIA terms, which totals 422.8854 million USD over the life against 453.4354 million USD for the Generic terms.", "The royalty field: the PIA royalty collects 154.4828 million USD against Generic''s 335.8660, more than its heavier tax wins back.", "A larger cost recovery under the PIA limit, which returns 1591.0013 million USD of cost against the 941.4436 million USD the Generic limit returns.", "Different sales, since the PIA line is run against a lower price deck than the Generic line is, year after year across the life."]'::jsonb, 1, 'Both lines sell the same 2686.9277 million USD and recover the same 941.4436. The PIA line pays the larger tax, 453.4354 million USD against 422.8854, and the smaller royalty, 154.4828 against 335.8660. A tax rate quoted on its own predicts nothing.'::text),
      ('beginner', 'module', 'm01-what-a-fiscal-regime-is'::text, 12, 'Why is subtracting the two printed endpoints of a derived column and matching the printed difference a bad check?', '["The printed endpoints belong to different rows of the ledger, while a derived difference is only ever computed within one row.", "A derived column is computed at full precision and then rounded, and its endpoints are rounded too, so a printed pair of 79.2711 and 79.4678 carries a printed climb of 0.1968.", "A derived column is an estimate the engine never returns, so it carries no defined precision to check anything against.", "Derived columns print to six decimals and returned columns to four, so the two can never be put in the same subtraction."]'::jsonb, 1, 'Both figures are correct and the hand subtraction is off by one in the last place. The default project''s Generic Royalty/Tax pair does the same thing, printing 51.2558 and 41.0660 against a climb of -10.1897.'::text, 'Why is subtracting the two printed endpoints of a derived column and matching the printed difference a bad check?', '["The printed endpoints belong to different rows of the ledger, while a derived difference is only ever computed within one row, so no pair of printed endpoints can ever reproduce it.", "A derived column is computed at full precision and then rounded, and its endpoints are rounded too, so a printed pair of 41.6869 and 41.6802 carries a printed climb of -0.0068.", "A derived column is an estimate the engine never returns, so it carries no defined precision to check anything against.", "Derived columns print to six decimals and returned columns to four, so the two can never be put in the same subtraction, whichever two rows the printed endpoints come from."]'::jsonb, 1, 'Both figures are correct and the hand subtraction is off by one in the last place. The default project''s Generic Royalty/Tax pair does the same thing, printing 51.2558 and 41.0660 against a climb of -10.1897.'::text),
      ('beginner', 'module', 'm01-what-a-fiscal-regime-is'::text, 14, 'The engine header names a single source of truth for Nigerian fiscal math. What is this model for?', '["Comparing the shape of regimes against each other, with the Petroleum Economics Studio engine holding the fiscal truth.", "Assessing a Nigerian liability under the Petroleum Industry Act, which is why the template set carries a PIA entry at all.", "Producing a filing figure, once a template has been reconciled against the Petroleum Economics Studio engine on the same project.", "Replacing that engine for screening work, since the two agree on a total government cash flow of 1339.2784 million USD."]'::jsonb, 0, 'A template named for a jurisdiction is a caricature in six numbers, useful for asking which instrument moved which result and unfit for filing anything.'::text, 'The engine header names a single source of truth for Nigerian fiscal math. What is this model for?', '["Comparing the shape of regimes against each other, with the Petroleum Economics Studio engine holding the fiscal truth.", "Assessing a Nigerian liability under the Petroleum Industry Act, which is why the template set carries a PIA entry at all.", "Producing a filing figure, once a template has been reconciled against the Petroleum Economics Studio engine on the same project.", "Replacing that engine for screening work, since the two agree on a total government cash flow of 687.4682 million USD on the Designer''s default project."]'::jsonb, 0, 'Even the template carrying the Act''s base terms is a model of them. It answers which instrument moved which result, and no filing can rest on it.'::text),
      ('beginner', 'module', 'm03-revenue-and-royalty'::text, 7, 'A reader takes the cost recovery ceiling as a percent of gross revenue instead. How large is the error in year 1 of the default project?', '["Exactly the royalty, 50.9979 million USD of extra recovery, which then flows into the pool, into the R factor and into every split keyed on it.", "It is immaterial at a 100 percent limit, since the ceiling binds either way in the year the capex lands.", "It is the spread between the two limits the template set uses, 80 percent against 100, applied to the year''s revenue.", "It cancels in the totals, a larger recovery in year 1 leaving a smaller pool for the years that follow it."]'::jsonb, 0, 'The tell is worth memorising: if a cost recovery ceiling ever equals gross revenue, the wrong base has been used, because royalty is always taken first.'::text, 'Under the Gulf of Mexico terms a reader takes the cost recovery ceiling as a percent of gross revenue instead. How large is the error in year 1 of the default project?', '["Exactly the royalty: 50.9979 million USD of extra recovery, and a pool that much smaller going into year 2.", "It is immaterial at a 100 percent limit, since the ceiling binds either way in the year the capex lands.", "The spread between two limits the template set uses, 50 percent against 100, applied to the year''s revenue.", "It cancels in the totals, a larger recovery in year 1 leaving a smaller pool for the years that follow it."]'::jsonb, 0, 'The tell is worth memorising: if an after-royalty ceiling ever equals gross revenue, the wrong base has been used. Only Nigeria - PIA (2021) takes its limit on a gross base, 70 percent of the value of crude oil and NGL.'::text),
      ('beginner', 'module', 'm03-revenue-and-royalty'::text, 9, 'Nigeria - PIA (2021) collects total royalty of 268.6928 million USD on the default project and 700.1194 on the test project, and Brazil - Concession collects exactly the same on both. How does a slider match a flat 10 percent?', '["The engine averages a sliding scale over the life of the field and charges one mean rate, which for tiers of 7.5 and 10 percent works out at 10 percent on both decks.", "The slider keys on the first dated point of the deck, which is above 50 USD per bbl on both projects, and that point then fixes the rate for the whole of the 25 year run.", "Every applied price on both decks is above the 50 USD per bbl threshold, so the slider sits in its 10 percent tier in every year and never slides.", "A sliding royalty falls back to the flat rate of the nearest template whenever its two tiers straddle the deck."]'::jsonb, 2, 'The default deck prices oil at 70, 75 and 80 USD per bbl and the test deck at 80. A sliding instrument that never slides is a flat one, and whether it slides is a property of the deck.'::text, 'Nigeria - PIA (2021) collects total royalty of 154.4828 million USD on the default project and 443.2226 on the test project, against Brazil''s flat 10 percent at 268.6928 and 700.1194. Why is the PIA total the smaller on both?', '["The engine averages the template''s two price tiers of 7.5 and 10 percent over the life and charges one mean rate, which falls below Brazil''s flat 10 percent.", "The PIA royalty keys on the first dated point of the deck, which fixes a single 5 percent rate for the whole of the 25 year run on both of the projects.", "Its oil pays 5 percent below 50,000 bopd plus a royalty by price only while the price clears the year''s low benchmark, and gas and NGL pay 5 percent.", "A PIA royalty falls back to half the flat rate of the nearest template whenever the deck sits above its price benchmark for the year in question."]'::jsonb, 2, 'On the default project that is 154.4828 on revenue of 2686.9277. On neither published project do the two collect the same total.'::text),
      ('beginner', 'module', 'm03-revenue-and-royalty'::text, 10, 'What can move the tier a sliding royalty selects?', '["The applied oil price for the year, and nothing else.", "The oil price or the gas price, whichever of the two streams contributed more revenue in the year being priced.", "Cumulative production, which is the variable a progressive royalty is normally keyed on in a real contract.", "The R factor, the ratio this sandbox uses to key the royalty tiers and the profit split tiers alike."]'::jsonb, 0, 'It reads the applied oil price, so anything that changes that price changes the tier as well as the revenue. Not gas, not NGL, not rate, not cumulative volume, not the R factor.'::text, 'What can move the tier a sliding royalty selects?', '["The applied oil price for the year, and nothing else.", "The oil price or the gas price, whichever of the two streams contributed more revenue in the year being priced.", "Cumulative production, which is the variable a progressive royalty is normally keyed on in a real contract.", "The R factor, the ratio this sandbox uses to key the royalty tiers and the profit split tiers alike."]'::jsonb, 0, 'It reads the applied oil price, so anything that changes that price changes the tier as well as the revenue. Gas, NGL, rate, cumulative volume and the R factor play no part.'::text),
      ('beginner', 'module', 'm03-revenue-and-royalty'::text, 12, 'Three of the six templates take a flat 100 percent of profit oil to the contractor and recover cost at 100 percent. What are the other three?', '["Tiered on the oil price, at those same three limits, a sharing regime keying its split on the price it sells at.", "Flat splits below 100 percent, the difference between the split and 100 being the government''s share of profit oil.", "Concessions as well, differing only in the royalty rates of 7.5, 5 and 0 percent that the three of them carry.", "Tiered on the R factor, with cost recovery capped at 80, 90 and 50 percent."]'::jsonb, 3, 'Those are the templates where the middle columns do real work, because an unrecovered balance has somewhere to accumulate and the contractor''s share changes as the field matures.'::text, 'Three of the six templates take a flat 100 percent of profit oil to the contractor and recover cost at 100 percent. What are the other three?', '["Tiered on the oil price, at those same three limits of 100 percent, a sharing regime keying its split on the price it sells at in the year.", "Flat splits below 100 percent, the difference between the split and 100 being the government''s share of profit oil in every year of the life of the field, whatever the field produces.", "Concessions as well, differing only in the royalty rates of 12.5, 5 and 0 percent that the three of them carry.", "Two tiered on the R factor, capped at 90 and 50 percent, and Nigeria - PIA (2021), capped at 70 percent of gross crude and NGL value with a split by cumulative production."]'::jsonb, 3, 'Those are the templates where the middle columns do real work, because an unrecovered balance has somewhere to accumulate and the contractor''s share can change as the field matures.'::text),
      ('beginner', 'module', 'm03-revenue-and-royalty'::text, 13, 'Which template collects the most royalty on the default project, and what does that predict about its contractor?', '["USA - Gulf of Mexico at 503.7989 million USD, which leaves that contractor the least cash of the six at 406.2057 million USD.", "Generic Royalty/Tax at 335.8660 million USD, since 12.5 percent is the highest flat rate anywhere in the list.", "USA - Gulf of Mexico at 503.7989 million USD, and it predicts nothing: that contractor keeps 980.9313 million USD, more than four of the other five.", "Nigeria - PIA (2021) at 268.6928 million USD, a slider in its top tier outcollecting every flat rate in the set."]'::jsonb, 2, '406.2057 million USD is the PIA contractor, under a royalty of 268.6928 million USD. The royalty ranking and the contractor ranking are not the same ranking.'::text, 'Which template collects the most royalty on the default project, and what does that predict about its contractor?', '["USA - Gulf of Mexico at 503.7989 million USD, which leaves that contractor the least cash of all six templates on the default project, 428.8774 million USD.", "Generic Royalty/Tax at 335.8660 million USD, since 12.5 percent is the highest flat rate anywhere in the list.", "USA - Gulf of Mexico at 503.7989 million USD, and it predicts nothing: that contractor keeps 980.9313 million USD, more than three of the other five.", "Nigeria - PIA (2021) at 154.4828 million USD, its royalty by price outcollecting every flat rate in the set of six templates."]'::jsonb, 2, 'The most contractor cash, 1058.0159 million USD, sits under the PIA template''s royalty of 154.4828 million USD. The royalty ranking and the contractor ranking are not the same ranking.'::text),
      ('beginner', 'module', 'm04-the-concession-ledger'::text, 4, 'The Gulf of Mexico terms set the cost recovery limit at 100 percent, and year 1 of the Designer''s default project still closes with a pool of 310.0117. What did that limit actually allow?', '["Recovery of 271.9889, the whole of gross revenue, which still falls short of the year''s spending and leaves the remainder to be carried forward.", "Recovery of the year''s opex of 31.0027 and capex of 500.0000 in full, with the pool holding only what the revenue could not fund.", "Recovery of nothing at all in year 1, because the pool is seeded with the capex before any allowance against revenue is computed for the year.", "Recovery of 220.9910, the whole of revenue after royalty, against opex of 31.0027 and capex of 500.0000."]'::jsonb, 3, 'A 100 percent limit is a ceiling on revenue after royalty, not a promise to return the spend, so 310.0117 is carried into year 2.'::text, 'The Gulf of Mexico terms set the cost recovery limit at 100 percent, and year 1 of the Designer''s default project still closes with a pool of 310.0117. What did that limit actually allow?', '["Recovery of 271.9889, the whole of gross revenue, which still falls short of the year''s spending and leaves the remainder to be carried forward.", "Recovery of the year''s opex of 31.0027 and capex of 500.0000 in full, with the pool holding only what the revenue could not fund.", "Recovery of nothing at all in year 1, because the pool is seeded with the capex before any allowance against revenue is computed for the year.", "Recovery of 220.9910, the whole of revenue after royalty, against opex of 31.0027 and capex of 500.0000."]'::jsonb, 3, 'A 100 percent limit is a ceiling on revenue after royalty and makes no promise to return the spend, so 310.0117 is carried into year 2.'::text),
      ('beginner', 'module', 'm05-reading-the-ledger'::text, 4, 'On the default project the PIA and Angola templates report payback in year 4 while payout is year 3, and the other four report 3 for both. What does the one year gap say?', '["The R factor and the cumulative are computed on different production profiles, so the two clocks are never strictly comparable.", "The pool cleared a year later under those two templates, and payback cannot be reported before the pool closes.", "Payout is discounted at the project''s 10 percent and payback is not, so payout always arrives in an earlier year.", "The project earned its cost back before the contractor got its cash back, because the state takes its share in between."]'::jsonb, 3, 'Payout is the first year the R factor is above 1.0, cumulative revenue over cumulative cost, and it knows nothing about who kept the money.'::text, 'On the default project the Angola template reports payback in year 4 while payout is year 3, and the other five report 3 for both. What does the one year gap say?', '["The R factor and the cumulative are computed on different production profiles, so the two clocks are never strictly comparable.", "The pool cleared a year later under that template, and payback cannot be reported before the pool closes.", "Payout is discounted at the project''s 10 percent and payback is not, so payout always arrives in an earlier year.", "The project earned its cost back before the contractor got its cash back, because the state takes its share in between."]'::jsonb, 3, 'Payout is the first year the R factor is above 1.0, cumulative revenue over cumulative cost, and it knows nothing about who kept the money.'::text),
      ('beginner', 'module', 'm05-reading-the-ledger'::text, 6, 'Four of the six templates report payback in year 3 on the default project. Why is that a poor place to rank them?', '["Payback is measured on the discounted cumulative, and the discounting compresses the differences between the templates into one year.", "Payback is measured from the R factor, which is a ratio of cumulatives and moves too little between templates to separate them.", "Payback is a whole year, so a tie in the column is not a tie in the money: the same year 3 covers 986.7327 under Generic and 623.9658 under Brazil.", "Payback is reported to the nearest year and the engine rounds up, so four templates that really differ are printed as the same year."]'::jsonb, 2, 'It is an integer clock on an undiscounted running sum, and it has no view of anything that happens after the crossing.'::text, 'Five of the six templates report payback in year 3 on the default project. Why is that a poor place to rank them?', '["Payback is measured on the discounted cumulative, and the discounting compresses the differences between the templates into one year.", "Payback is measured from the R factor, which is a ratio of cumulatives and moves too little between templates to separate them.", "Payback is a whole year, so a tie in the column is not a tie in the money: the same year 3 covers 986.7327 under Generic and 623.9658 under Brazil.", "Payback is reported to the nearest year and the engine rounds up, so five templates that really differ are printed as the same year."]'::jsonb, 2, 'It is an integer clock on an undiscounted running sum, and it has no view of anything that happens after the crossing.'::text),
      ('beginner', 'module', 'm05-reading-the-ledger'::text, 9, 'Brazil pays the most tax of the six templates on the default project at 852.8256 and leaves the contractor 623.9658, the third highest figure in the table. What does that show?', '["That the tax column is charged on gross revenue under Brazil and on the profit share under the other five, so the two are not comparable.", "Tax and take rank differently, because the state also collects through royalty and through its share of profit oil.", "That the resource rent tax of 40 percent is refunded to the contractor through the cost pool, which is why the cash survives the tax.", "That a high tax bill signals a high residual, so the contractor''s cash and the tax column will normally move together across templates."]'::jsonb, 1, 'PIA pays the least tax of the six, 174.0882, and leaves the contractor the least cash, 406.2057.'::text, 'Brazil pays the most tax of the six templates on the default project at 852.8256 and leaves the contractor 623.9658, the fourth highest figure in the table. What does that show?', '["That the tax column is charged on gross revenue under Brazil and on the profit share under the other five, so the two are not comparable.", "Tax and take rank differently, because the state also collects through royalty and through its share of profit oil.", "That the resource rent tax of 40 percent is refunded to the contractor through the cost pool, which is why the cash survives the tax.", "That a high tax bill signals a high residual, so the contractor''s cash and the tax column will normally move together across templates."]'::jsonb, 1, 'Nigeria - PIA (2021) pays the second most tax, 453.4354, and leaves the contractor the most cash, 1058.0159, while Ghana pays the least tax, 230.9340, and leaves the least cash, 428.8774.'::text),
      ('beginner', 'module', 'm05-reading-the-ledger'::text, 11, 'On the teaching field ODIDI every template closes its cumulative in the black and every template returns a negative value at the project''s 12 percent. What does that pair of readings mean?', '["The field returns the contractor''s nominal money and still is not worth building at the rate the project is discounted at.", "The cumulative was computed on a different set of rows from the value, so one of the two readings has to be discarded.", "The field pays back inside the horizon but the closing unrecovered pool is larger than the cash returned in every case.", "The value is negative because the horizon of 25 years ends before the cumulative has finished climbing."]'::jsonb, 0, 'Brazil ends the life with 192.9896 of contractor cash and a value of -5.8662, and Angola with 109.1947 and -58.1813.'::text, 'On the teaching field ODIDI every template closes its cumulative in the black, and five of the six return a negative value at the project''s 12 percent. What does that pair of readings mean for those five?', '["Under those five the field returns the contractor''s nominal money and still is not worth building at the rate the project is discounted at.", "The cumulative was computed on a different set of rows from the value, so one of the two readings has to be discarded.", "Under those five the field pays back inside the horizon, but the closing unrecovered pool is larger than the cash returned in every one of their cases.", "The value is negative because the horizon of 25 years ends before the cumulative has finished climbing."]'::jsonb, 0, 'Brazil ends the life with 192.9896 of contractor cash and a value of -5.8662, and Angola with 109.1947 and -58.1813. The sixth, Nigeria - PIA (2021), clears 12 percent with a value of 1.7389.'::text),
      ('beginner', 'module', 'm05-reading-the-ledger'::text, 13, 'Swept from 40 to 120 USD per bbl on ODIDI, government take under the Gulf of Mexico terms falls from 78.5512 percent to 40.8517 while under PIA it stays within 75.1077 to 79.4678. What does a single ledger tell you about that?', '["It tells you the ranking at the run''s own price, and that ranking holds across the sweep.", "Nothing at all, because one run is one price deck and the shape of a regime across prices is not in it.", "It tells you the direction of the movement, since a regime with a higher take at the base price always gives up more of it as prices rise.", "It tells you which template is progressive, from government take at the base price."]'::jsonb, 1, 'Two regimes that look similar on one run behave nothing alike on the next, and the single ledger shows neither shape.'::text, 'Swept from 40 to 120 USD per bbl on ODIDI, government take under the Gulf of Mexico terms falls from 78.5512 percent to 40.8517 while under Nigeria - PIA (2021) it stays within 42.2597 to 50.4050. What does a single ledger tell you about that?', '["It tells you the ranking at the run''s own price, and that ranking holds across the sweep.", "Nothing at all, because one run is one price deck and the shape of a regime across prices is not in it.", "It tells you the direction of the movement, since a regime with a higher take at the base price always gives up more of it as prices rise.", "It tells you which template is progressive, from government take at the base price."]'::jsonb, 1, 'Two regimes that look similar on one run behave nothing alike on the next, and the single ledger shows neither shape.'::text),
      ('beginner', 'module', 'm06-the-associate-reading'::text, 5, 'ODIDI under Brazil returns the contractor 192.9896 over 25 years, the most of the six templates, and a value of -5.8662 at the project''s 12 percent. How can both be true?', '["The value is computed on the government''s cash flows rather than the contractor''s, which is why it carries the opposite sign.", "The total adds 25 undiscounted rows and the value discounts each of them, and at 12 percent the year 1 capex outweighs cash that arrives late, so positive nominal cash is still worth less than nothing today.", "The 192.9896 is a total of undiscounted rows and the value excludes the capex, so the two are not readings of the same ledger.", "The closing unrecovered pool of 19.3270 is subtracted in the value and not in the total, and that is the whole of the difference."]'::jsonb, 1, 'Same rows, two verdicts. Every one of the six templates closes ODIDI''s cumulative in the black and returns a negative value at 12 percent.'::text, 'ODIDI under Brazil returns the contractor 192.9896 over 25 years, the second most of the six templates, and a value of -5.8662 at the project''s 12 percent. How can both be true?', '["The value is computed on the government''s cash flows rather than the contractor''s, which is why it carries the opposite sign to the contractor''s own total over the same 25 years of the field.", "The total adds 25 undiscounted rows and the value discounts each of them, and at 12 percent the year 1 capex outweighs cash that arrives late, so positive nominal cash is still worth less than nothing today.", "The 192.9896 is a total of undiscounted rows and the value excludes the capex, so the two are not readings of the same ledger.", "The closing unrecovered pool of 19.3270 is subtracted in the value and not in the total, and that deduction, charged against the final year of the 25 year life, is the whole of the difference between the two readings."]'::jsonb, 1, 'Same rows, two verdicts. Five of the six templates close ODIDI''s cumulative in the black and return a negative value at 12 percent; the PIA template''s value is 1.7389.'::text),
      ('beginner', 'module', 'm06-the-associate-reading'::text, 13, 'ODIDI hands the state between 232.9950 and 316.7898 depending on which of the six templates prices it. What can the Associate reading not say about that range?', '["Which template collects the most, since the six collections are only comparable when the closing pools are equal.", "Which template leaves the contractor the least cash, which needs a discount convention the tier does not carry.", "Which of the splits is fair, which survives a price collapse, and which numbers on a comparison screen are measurements at all.", "How much of each collection is royalty, since the ledger prints government cash flow as a single undivided column."]'::jsonb, 2, 'The contractor keeps between 109.1947 and 192.9896 across the same six templates, and the tier can state the range without judging it.'::text, 'ODIDI hands the state between 196.0260 and 316.7898 depending on which of the six templates prices it. What can the Associate reading not say about that range?', '["Which template collects the most, since the six collections are only comparable when the closing pools are equal.", "Which template leaves the contractor the least cash, which needs a discount convention the tier does not carry.", "Which of the splits is fair, which survives a price collapse, and which numbers on a comparison screen are measurements at all.", "How much of each collection is royalty, since the ledger prints government cash flow as a single undivided column."]'::jsonb, 2, 'The contractor keeps between 109.1947 and 229.9586 across the same six templates, and the tier can state the range without judging it.'::text),
      ('beginner', 'module', 'm06-the-associate-reading'::text, 14, 'Every regime in the Associate tier was read at one setting. Which instruments actually move on their own in the templates this tier held still?', '["The cost recovery limit, which tightens as the standing pool grows, and the minimum tax, which arms itself once the residual falls.", "A royalty keyed on price and a profit split keyed on the R factor, which under PIA steps the contractor''s share from 60 to 40 to 30 percent.", "The corporate rate, which steps with the R factor tier, and the royalty, which steps with cumulative production.", "The discount rate, which follows the price deck, and the profit split, which follows the closing unrecovered pool."]'::jsonb, 1, 'The R factor is a ratio of cumulatives, so it can fall back below a threshold it passed and step the contractor''s share up again.'::text, 'Every regime in the Associate tier was read at one setting. Which instruments actually move on their own in the templates this tier held still?', '["The cost recovery limit, which tightens as the standing pool grows, and the minimum tax, which arms itself once the residual falls away.", "The R factor split Ghana and Angola carry, and the PIA template''s royalty on price and daily rate with its split on cumulative production.", "The corporate rate, which steps with the R factor tier, and the royalty, which steps with cumulative production.", "The discount rate, which follows the price deck, and the profit split, which follows the closing unrecovered pool of the year before it, whatever the price."]'::jsonb, 1, 'A split on cumulative production can only move one way, since production only accumulates. Ghana''s and Angola''s R factor, a ratio of cumulatives, can fall back and hand the contractor a larger share again.'::text),
      ('intermediate', 'final', null::text, 3, 'The selection that picks a royalty tier keeps no memory of the tier it chose the year before. What follows on a deck whose price falls back?', '["The rate holds at the highest tier the price has ever reached, in the way a real sliding scale ratchets once a threshold has been passed.", "The rate is averaged across the tiers the deck has visited, which is what keeps a royalty line smooth across a step in the price deck.", "The rate cannot fall, because the selection starts each year from the rate it finished the year before and only tests the tiers above it.", "The rate can move up one year and down the next, since the tier is chosen fresh from that year''s own price."]'::jsonb, 3, 'The teaching field pays an implied 0.075000 through year 5 and 0.100000 from year 6 under the PIA tiers, and a deck falling back below 50 USD per bbl would return it to 0.075000 with nothing in the instrument to prevent it.'::text, 'The selection that picks a royalty tier keeps no memory of the tier it chose the year before. What follows on a deck whose price falls back?', '["The rate holds at the highest tier the price has ever reached, in the way a real sliding scale ratchets once a threshold has been passed.", "The rate is averaged across the tiers the deck has visited, which is what keeps a royalty line smooth across a step in the price deck.", "The rate cannot fall, because the selection starts each year from the rate it finished the year before and only tests the tiers above it.", "The rate can move up one year and down the next, since the tier is chosen fresh from that year''s own price."]'::jsonb, 3, 'Under the tiered teaching regime the teaching field pays an implied 0.075000 through year 5 and 0.100000 from year 6, and a deck falling back below 50 USD per bbl would return it to 0.075000 with nothing in the instrument to prevent it.'::text),
      ('intermediate', 'final', null::text, 6, 'A sliding royalty selects its tier from the oil price. What happens to the gas and NGL revenue in that year?', '["It is charged at the first tier''s rate, because no gas price reaches a threshold keyed in USD per bbl.", "It is left out of the royalty base, which is why the implied rate on gross revenue reads below the tier''s own rate.", "It is charged at whatever rate the oil price chose, since the rate applies to the whole of gross revenue.", "It is charged at a rate selected from the gas price against the same tier list, so a field can carry two royalty rates in one year."]'::jsonb, 2, 'Only the oil price selects the tier, and the instrument can see nothing else: not cost, not cumulative revenue, not production rate.'::text, 'A sliding royalty selects its tier from the oil price. What happens to the gas and NGL revenue in that year?', '["It is charged at the first tier''s rate, because no gas price reaches a threshold keyed in USD per bbl.", "It is left out of the royalty base, which is why the implied rate on gross revenue reads below the tier''s own rate.", "It is charged at whatever rate the oil price chose, since the rate applies to the whole of gross revenue.", "It is charged at a rate selected from the gas price against the same tier list, so a field can carry two royalty rates in one year."]'::jsonb, 2, 'Only the oil price selects the tier. Cost, cumulative revenue and production rate are all invisible to the instrument.'::text),
      ('intermediate', 'final', null::text, 7, 'The teaching field under the PIA template sells 139.6563 million USD in year 1, pays a royalty of 10.4742 and recovers 103.3457 against an 80 percent limit. What was the limit taken as a percent of?', '["Revenue after royalty, because 103.3457 million USD is 80 percent of what is left once the royalty has been taken off the top.", "Gross revenue, so the allowance for the year was 80 percent of 139.6563 million USD and the pool released as much of it as it held.", "The recoverable pool, which is the balance brought forward plus the year''s capex and opex, drawn down at 80 percent of itself.", "Profit oil, since the allowance and the profit share are the two halves of what is left after royalty."]'::jsonb, 0, 'Royalty is taken first and never becomes recoverable cost. The pool closes that year at 341.6581 million USD with the capex of 420.0000 inside it.'::text, 'The teaching field under the PIA template sells 139.6563 million USD in year 1, pays a royalty of 6.9828 and recovers 97.7288 against a 70 percent limit. What was the limit taken as a percent of?', '["The gross value of crude oil and NGL before royalty, so 97.7288 million USD is 70 percent of the oil and NGL sales alone.", "Gross revenue as a whole, gas included, so the allowance for the year was 70 percent of 139.6563 million USD and the pool released that much.", "The recoverable pool, which is the balance brought forward plus the year''s capex and opex, drawn down at 70 percent of itself every year.", "Revenue after royalty, because the royalty of 6.9828 million USD is taken off the top before any cost can be recovered against the limit."]'::jsonb, 0, 'This template takes its cost limit on the gross value of crude oil and NGL, before royalty, where every other regime in the course takes a percent of revenue after royalty. The pool closes that year at 347.2750 million USD with the capex of 420.0000 inside it.'::text),
      ('intermediate', 'final', null::text, 9, 'On the teaching field under the PIA template the pool closes year 8 at 14.5837 million USD and year 9 at 0.0000, and cost recovered falls from 49.9934 in year 8 to 30.4412 in year 9 and 15.3141 in year 10. What is that last figure?', '["The remainder of the year 1 capex of 420.0000 million USD, released on the schedule the engine follows once the early years are settled.", "The 80 percent allowance on that year''s revenue after royalty, which is the binding number in every year of the run.", "A partial draw, since year 10 is the year the pool empties and only part of the allowance can be taken in it.", "That year''s own opex, because the pool is empty and nothing else is left to recover."]'::jsonb, 3, 'Year 9 is the partial draw at 30.4412 million USD. From year 10 the instrument hands back each year''s opex and passes the rest through as profit oil.'::text, 'On the teaching field under the PIA template the pool closes year 9 at 14.8678 million USD and year 10 at 0.0000, and cost recovered falls from 41.7592 in year 9 to 30.1819 in year 10 and 14.8473 in year 11. What is that last figure?', '["The remainder of the year 1 capex of 420.0000 million USD, released on the schedule the engine follows once the early years are settled.", "The 70 percent allowance on that year''s gross value of crude oil and NGL, which is the binding number in every year of the run.", "A partial draw, since year 11 is the year the pool empties and only part of the allowance can be taken in it.", "That year''s own opex, because the pool is empty and nothing else is left to recover."]'::jsonb, 3, 'Year 10 is the partial draw at 30.1819 million USD, the 14.8678 carried out of year 9 plus that year''s opex of 15.3141. From year 11, until the pool reopens late in the life, the instrument hands back each year''s opex and passes the rest through as profit oil.'::text),
      ('intermediate', 'final', null::text, 18, 'A tranche list is read to choose one split for the year. Which tranche''s split survives?', '["The one carrying the highest threshold the ratio has reached, because a copy of the list is sorted by threshold before it is read.", "The one that came last in the list as typed among those whose threshold was reached, since the list is read in the order it was written.", "The one carrying the lowest split among those whose threshold was reached, because the engine resolves a choice in the government''s favour.", "The one the previous year selected, unless a new threshold has been reached since."]'::jsonb, 0, 'Every shipped template is written sorted, so no template ledger moved. A list with two tranches at one threshold is the case the engine refuses, and it refuses it by naming the repeated threshold.'::text, 'A tranche list is read to choose one split for the year. Which tranche''s split survives?', '["The one carrying the highest threshold the ratio has reached, because a copy of the list is sorted by threshold before it is read.", "The one that came last in the list as typed among those whose threshold was reached, since the list is read in the order it was written.", "The one carrying the lowest split among those whose threshold was reached, because the engine resolves a choice in the government''s favour.", "The one the previous year selected, unless a new threshold has been reached since."]'::jsonb, 0, 'Every shipped template is written sorted, so its ledger reads the same either way. A list with two tranches at one threshold is the case the engine refuses, and it refuses it by naming the repeated threshold.'::text),
      ('intermediate', 'final', null::text, 24, 'On the test project USA - Gulf of Mexico collects 616.4851 million USD of tax inside a government cash flow of 1929.2089, and Nigeria - PIA (2021) collects 389.4896 inside 3372.6496. Which regime is the heavier?', '["USA, on the tax, since tax is the only column in which a government''s claim on a contractor is actually collected.", "Neither, because the two columns disagree and a comparison can only be made on regimes whose orders agree.", "Nigeria, on the take. The tax column measures one instrument and the take measures the regime.", "USA, because a higher tax against a lower take means more of its claim is being taken through instruments the take does not include."]'::jsonb, 2, 'The two columns point in opposite directions on the same ledger, because the government''s share of profit oil never passes through the tax line.'::text, 'On the test project USA - Gulf of Mexico collects 616.4851 million USD of tax inside a government cash flow of 1929.2089, and Nigeria - PIA (2021) collects 1074.4895 inside 1782.9635. Which regime is the heavier?', '["Nigeria, on the tax, since tax is the only column in which a government''s claim on a contractor is actually collected.", "Neither, because the two columns disagree and a comparison can only be made on regimes whose orders agree.", "USA, on the take. The tax column measures one instrument and the take measures the regime.", "Nigeria, because a higher tax against a lower take means more of its claim is being taken through instruments the take does not include."]'::jsonb, 2, 'The two columns point in opposite directions across two ledgers. USA - Gulf of Mexico''s heavier take is its 18.75 percent royalty, 1312.7238 million USD that never passes through the tax line, while the PIA template collects 443.2226 of royalty and takes 5 and later 10 percent of profit oil beside the larger tax.'::text),
      ('intermediate', 'final', null::text, 27, 'Two published cases have their only root ABOVE the band: -1 then 2000, whose root is 199900 percent, and -100 then 1500, whose root is 1400 percent. What does the engine report for each, and which one would the retired rule have printed a rate for?', '["A rate for both, 199900 and 1400 percent, because a root that exists is reported wherever it lies and only a missing root gives null.", "Null with the status above-clamp for both, and the retired bisection would have printed 1400 percent for the second, because that root sat inside the doubling bracket it searched.", "Null with the status no-root for both, because a rate above the band is treated exactly as a rate that does not exist at all anywhere.", "Null for the first and 1400 percent for the second, because the band is applied to the search range rather than to the answer the search returns."]'::jsonb, 1, 'The band runs from -99 to 1000 percent and a root outside it is not a rate the engine will name, so both are null with the status above-clamp and irrRootAboveBand set. The distinction worth carrying is what the retired rule did: it doubled from 100 percent to 102400, so it reported 102400 for the first, whose root is past even that, and it reported the real 1400 percent for the second, whose root sat inside the bracket.'::text, 'Two published cases have their only root ABOVE the band: -1 then 2000, whose root is 199900 percent, and -100 then 1500, whose root is 1400 percent. What does the engine report for each, and what does the second one show?', '["A rate for both, 199900 and 1400 percent, because a root that exists is reported wherever it lies and only a missing root gives null.", "Null with the status above-clamp for both, and the second shows the band limits what is reported: 1400 percent is a finite, real root and it is still not named.", "Null with the status no-root for both, because a rate above the band is treated exactly as a rate that does not exist at all anywhere, whatever the size of the root.", "Null for the first and 1400 percent for the second, because only a root lying beyond ten times the band''s upper edge is withheld, and 1400 percent falls well short of that limit."]'::jsonb, 1, 'The band runs from -99 to 1000 percent and a root outside it is not a rate the engine will name, so both are null with the status above-clamp and irrRootAboveBand set. The first root is far beyond any search; the second is a plain finite number, and the band still keeps it out of the rate column.'::text),
      ('intermediate', 'final', null::text, 34, 'The teaching field summary is sorted by contractor net present value descending and Brazil - Concession is first at negative 5.8662 million USD. Government cash flow runs the other way, 316.7898 for Angola against 232.9950 for Brazil. Which order is right?', '["The take order, since a present value that is negative for every regime cannot rank anything and should not be sorted on at all.", "The present value order, because the summary''s own sort is the engine''s verdict and the take column is a derived quantity beside it.", "Neither, because the two disagree, and a ranking that reverses under a second column is evidence that the comparison was mis-specified.", "Both, and they are orders of different things."]'::jsonb, 3, 'The best regime for the contractor on that field has a present value of negative 5.8662 million USD. Being least bad is a real answer, and it needs its label saying so.'::text, 'The teaching field summary is sorted by contractor net present value descending and Nigeria - PIA (2021) is first at 1.7389 million USD. Government cash flow runs the other way, 316.7898 for Angola against 196.0260 for the PIA template. Which order is right?', '["The take order, since a present value this close to zero cannot rank anything and should not be sorted on at all.", "The present value order, because the summary''s own sort is the engine''s verdict and the take column is a derived quantity beside it.", "Neither, because the two disagree, and a ranking that reverses under a second column is evidence that the comparison was mis-specified.", "Both, and they are orders of different things."]'::jsonb, 3, 'The best regime for the contractor on that field is worth 1.7389 million USD at 12 percent, and the most government cash flow belongs to Angola, in the last row. Each order answers its own question, and each needs its label.'::text),
      ('intermediate', 'final', null::text, 35, 'Three of the six templates split profit oil on the R factor. What does a year in which the contractor''s tranche is 0.300000 do to the tax base?', '["It leaves the whole of profit oil taxable, since the tax is charged before the split and the split then divides what is left of it.", "It leaves 0.300000 of profit oil taxable and charges the government''s share at the same rate, which the take column reports on its own.", "It leaves only the contractor''s 0.300000 of profit oil taxable, because the government''s share of profit oil never passes through the tax line.", "It leaves the whole of profit oil taxable but at 0.300000 of the rate, which is how a split is expressed inside the stack."]'::jsonb, 2, 'In year 11 of the default project a tranche of 0.300000 on 80.0217 million USD of profit oil leaves a base of 24.0065, which is how Ghana - Deepwater collects 230.9340 over the life at 35 percent while Generic Royalty/Tax collects 422.8854 at 30.'::text, 'Two of the six templates split profit oil on the R factor, and so does the tiered teaching regime. What does a year in which the contractor''s tranche is 0.300000 do to the tax base?', '["It leaves the whole of profit oil taxable, since the tax is charged before the split and the split then divides what is left of it.", "It leaves 0.300000 of profit oil taxable and charges the government''s share at the same rate, which the take column reports on its own.", "It leaves only the contractor''s 0.300000 of profit oil taxable, because the government''s share of profit oil never passes through the tax line.", "It leaves the whole of profit oil taxable but at 0.300000 of the rate, which is how a split is expressed inside the stack."]'::jsonb, 2, 'In year 11 of the default project the tiered teaching regime''s tranche of 0.300000 on 80.0217 million USD of profit oil leaves a base of 24.0065, which is how Ghana - Deepwater collects 230.9340 over the life at 35 percent while Generic Royalty/Tax collects 422.8854 at 30.'::text),
      ('intermediate', 'final', null::text, 40, 'On the teaching field under the PIA template the implied royalty rate steps from 0.075000 to 0.100000 in year 6, and the R factor crosses 1.0 in the same year, from 0.997329 to 1.136133. Are those the same event?', '["Yes. Reaching payout is what moves a field into the upper royalty tier, which is why both columns change in the same row.", "No. The royalty moved because the deck steps to 65 USD per bbl in year 6, and the ratio crossed because cumulative revenue overtook cumulative cost.", "Yes, because both instruments read the applied oil price, and a deck step therefore moves the royalty tier and the ratio together.", "No, and the royalty step is the earlier of the two, since a price event reaches the ledger a year before a cumulative one can."]'::jsonb, 1, 'One is a price event and the other is a cumulative one, and this field is the only teaching case where a royalty tier changes inside the life.'::text, 'On the teaching field under the tiered teaching regime the implied royalty rate steps from 0.075000 to 0.100000 in year 6, and the R factor crosses 1.0 in the same year, from 0.997329 to 1.136133. Are those the same event?', '["Yes. Reaching payout is what moves a field into the upper royalty tier, which is why both columns change in the same row.", "No. The royalty moved because the deck steps to 65 USD per bbl in year 6, and the ratio crossed because cumulative revenue overtook cumulative cost.", "Yes, because both instruments read the applied oil price, and a deck step therefore moves the royalty tier and the ratio together.", "No, and the royalty step is the earlier of the two, since a price event reaches the ledger a year before a cumulative one can."]'::jsonb, 1, 'One is a price event and the other is a cumulative one. The same deck step also starts the PIA template''s royalty by price in year 6, because 65 USD passes that year''s low benchmark.'::text),
      ('intermediate', 'module', 'm01-the-sliding-scale'::text, 1, 'Three probe decks on the Designer''s default project, priced at 49.990000, 50.000000 and 50.010000 USD per bbl, are run against the PIA royalty tiers of 0 USD/bbl at 7.5 percent and 50 USD/bbl at 10 percent. What rate does the deck priced exactly at the threshold pay?', '["0.075000, the lower tier, because a threshold is the price at which the next tier BEGINS and a price merely equal to it has not yet passed into the band above.", "The mean of the two tiers, because the engine interpolates the rate over the last cent of approach to a threshold rather than jumping.", "0.100000, the upper tier, on gross revenue of 198.9889 giving a royalty of 19.8989.", "0.075000, because the walk stops at the first tier whose threshold is not yet strictly exceeded and keeps the rate it was holding."]'::jsonb, 2, 'The comparison in the engine is `oilPrice >= tier.threshold`, so the threshold belongs to the tier above it: 49.990000 pays 14.9214 at 0.075000 while 50.000000 pays 19.8989 at 0.100000.'::text, 'Three probe decks on the Designer''s default project, priced at 49.990000, 50.000000 and 50.010000 USD per bbl, are run against the tiered teaching regime''s royalty tiers of 0 USD/bbl at 7.5 percent and 50 USD/bbl at 10 percent. What rate does the deck priced exactly at the threshold pay?', '["0.075000, the lower tier, because a threshold is the price at which the next tier BEGINS and a price merely equal to it has not yet passed into the band above.", "The mean of the two tiers, because the engine interpolates the rate over the last cent of approach to a threshold rather than jumping.", "0.100000, the upper tier, on gross revenue of 198.9889 giving a royalty of 19.8989.", "0.075000, because the walk stops at the first tier whose threshold is not yet strictly exceeded and keeps the rate it was holding."]'::jsonb, 2, 'The comparison in the engine is `oilPrice >= tier.threshold`, so the threshold belongs to the tier above it: 49.990000 pays 14.9214 at 0.075000 while 50.000000 pays 19.8989 at 0.100000.'::text),
      ('intermediate', 'module', 'm01-the-sliding-scale'::text, 2, 'Why can a price multiplier sweep of the default project, run at 0.700000, 0.710000, 0.720000 and 0.800000, not settle which tier owns a threshold?', '["A sweep brackets a threshold and never lands on one: 0.710000 puts the price at 49.700000 and 0.720000 puts it at 50.400000, so no swept point is ever the threshold itself.", "The sweep changes gross revenue at the same time as the rate, so the implied rate of royalty over gross revenue is contaminated and cannot be read.", "The sweep reports the royalty only as a lifetime total, so no single year''s rate can be recovered from it.", "The multiplier is applied after the royalty is charged, so the tier a swept point selects belongs to the unswept deck price and not to the price printed."]'::jsonb, 0, 'The implied rate steps from 0.075000 to 0.100000 somewhere between the multipliers 0.710000 and 0.720000, and a bracket names an interval rather than a side.'::text, 'Why is a price multiplier sweep of the default project, run at 0.700000, 0.710000, 0.720000 and 0.800000, unable to settle which tier owns a threshold?', '["A sweep brackets a threshold and never lands on one: 0.710000 puts the price at 49.700000 and 0.720000 puts it at 50.400000, so no swept point is ever the threshold itself.", "The sweep changes gross revenue at the same time as the rate, so the implied rate of royalty over gross revenue is contaminated and cannot be read.", "The sweep reports the royalty only as a lifetime total, so no single year''s rate can be recovered from it.", "The multiplier is applied after the royalty is charged, so the tier a swept point selects belongs to the unswept deck price and not to the price printed."]'::jsonb, 0, 'The year 1 implied rate steps from 0.075000 to 0.100000 somewhere between the multipliers 0.710000 and 0.720000, and a bracket names an interval rather than a side.'::text),
      ('intermediate', 'module', 'm01-the-sliding-scale'::text, 5, 'At a price multiplier of 1.200000 on the default project the PIA royalty charges 32.3089 on gross revenue of 323.0889. How much of that revenue was charged at 7.5 percent?', '["None of it. One tier is selected for the year and its rate is charged on the whole of gross revenue, with nothing left in the lower band.", "The share of revenue attributable to the first 50 USD per bbl of price, with the remainder taken at 10 percent in the manner of an income tax bracket.", "The gas and NGL portion of revenue, which stays in the first tier because only the oil price is allowed to select a tier above it.", "The portion earned before the applied price crossed the threshold, which on a rising deck is the earlier years of the same run."]'::jsonb, 0, 'The implied rate at 1.200000 is 0.100000 on every dollar. A blended answer lands between the two printed royalties and looks reasonable, which is what makes it dangerous.'::text, 'At a price multiplier of 1.200000 on the default project the tiered teaching regime''s royalty charges 32.3089 in year 1 on gross revenue of 323.0889. How much of that revenue was charged at 7.5 percent?', '["None of it. One tier is selected for the year and its rate is charged on the whole of gross revenue, with nothing left in the lower band.", "The share of revenue attributable to the first 50 USD per bbl of price, with the remainder taken at 10 percent in the manner of an income tax bracket.", "The gas and NGL portion of revenue, which stays in the first tier because only the oil price is allowed to select a tier above it.", "The portion earned before the applied price crossed the threshold, which on a rising deck is the earlier years of the same run."]'::jsonb, 0, 'The implied rate at 1.200000 is 0.100000 on every dollar. A blended answer lands between the two printed royalties and looks reasonable, which is what makes it dangerous.'::text),
      ('intermediate', 'module', 'm01-the-sliding-scale'::text, 6, 'The teaching field ODIDI holds 45 USD per bbl through year 5 and steps to 65 at year 6. Under the PIA royalty its year 5 royalty is 5.7145 on gross revenue of 76.1939 and its year 6 royalty is 9.3986 on 93.9859. What moved?', '["Only the rate, since the oil volume is declining and the deck step merely holds gross revenue flat while the tier above takes over.", "Only the revenue, because a deck that steps inside the life of a field cannot move a tier that was fixed when the regime was loaded.", "Both the revenue and the rate: the deck lifted the price so revenue rose, and the same step carried the price past 50 so the implied rate went from 0.075000 to 0.100000.", "The cost recovery limit released profit oil in that year, and the royalty follows the profit oil upward while the rate itself holds at 0.075000."]'::jsonb, 2, 'Two effects compound in one row. Revenue rises from 76.1939 to 93.9859 and the implied rate rises from 0.075000 to 0.100000, so the royalty rises by more than the price move alone.'::text, 'The teaching field ODIDI holds 45 USD per bbl through year 5 and steps to 65 at year 6. Under the tiered teaching regime''s royalty its year 5 royalty is 5.7145 on gross revenue of 76.1939 and its year 6 royalty is 9.3986 on 93.9859. What moved?', '["Only the rate, since the oil volume is declining and the deck step merely holds gross revenue flat while the tier above takes over.", "Only the revenue, because a deck that steps inside the life of a field cannot move a tier that was fixed when the regime was loaded.", "Both the revenue and the rate: the deck lifted the price so revenue rose, and the same step carried the price past 50 so the implied rate went from 0.075000 to 0.100000.", "The cost recovery limit released profit oil in that year, and the royalty follows the profit oil upward while the rate itself holds at 0.075000."]'::jsonb, 2, 'Two effects compound in one row. Revenue rises from 76.1939 to 93.9859 and the implied rate rises from 0.075000 to 0.100000, so the royalty rises by more than the price move alone.'::text),
      ('intermediate', 'module', 'm01-the-sliding-scale'::text, 11, 'Across the default project sweep the PIA implied rate is 0.075000 at multipliers 0.500000, 0.600000, 0.700000 and 0.710000, and 0.100000 at 0.720000, 0.800000, 1.000000 and 1.200000. What is that pattern?', '["A step function with one break, flat inside each tier and discontinuous where the applied price crosses 50 USD per bbl.", "A ramp that rises with price throughout, sampled coarsely enough at these eight multipliers that its slope looks flat inside each band.", "A step that repeats at every multiple of the threshold, with a further break at 100 USD per bbl.", "A progressive schedule whose average rate rises with price while the marginal rate holds."]'::jsonb, 0, 'Nothing between two thresholds is interpolated. The rate is 0.100000 at an applied price of 50.400000 and still 0.100000 at 84.000000.'::text, 'Across the default project sweep the tiered teaching regime''s year 1 implied rate is 0.075000 at multipliers 0.500000, 0.600000, 0.700000 and 0.710000, and 0.100000 at 0.720000, 0.800000, 1.000000 and 1.200000. What is that pattern?', '["A step function with one break, flat inside each tier and discontinuous where the applied price crosses 50 USD per bbl.", "A ramp that rises with price throughout, sampled coarsely enough at these eight multipliers that its slope looks flat inside each band.", "A step that repeats at every multiple of the threshold, with a further break at 100 USD per bbl.", "A progressive schedule whose average rate rises with price while the marginal rate holds."]'::jsonb, 0, 'Nothing between two thresholds is interpolated. The rate is 0.100000 at an applied price of 50.400000 and still 0.100000 at 84.000000.'::text),
      ('intermediate', 'module', 'm01-the-sliding-scale'::text, 12, 'The PIA template''s lowest royalty tier is keyed at 0 USD/bbl. Why does that hide something a reader needs to check?', '["Because a threshold of 0 USD/bbl is skipped by the walk, leaving the 50 USD/bbl tier as the only rate the template can charge.", "Because a zero threshold makes the implied rate undefined in any year the applied oil price is itself below one dollar.", "Because the engine treats a 0 USD/bbl key as an instruction to charge no royalty until the next threshold in the list is reached.", "Because at any positive price that tier is genuinely reached, so the fallback to the lowest tier''s rate never shows itself and the selection looks like an ordinary threshold rule."]'::jsonb, 3, 'On tiers keyed at 60 and 80 USD/bbl the fallback is visible as 0.125000 charged below every threshold, and that is the entry every tier list has to be checked for.'::text, 'The tiered teaching regime''s lowest royalty tier is keyed at 0 USD/bbl. Why does that hide something a reader needs to check?', '["Because a threshold of 0 USD/bbl is skipped by the walk, leaving the 50 USD/bbl tier as the only rate the regime can charge.", "Because a zero threshold makes the implied rate undefined in any year the applied oil price is itself below one dollar.", "Because the engine treats a 0 USD/bbl key as an instruction to charge no royalty at all until the next threshold in the list is reached, so the lowest tier''s rate is never actually charged.", "Because at any positive price that tier is genuinely reached, so the fallback to the lowest tier''s rate never shows itself and the selection looks like an ordinary threshold rule."]'::jsonb, 3, 'On tiers keyed at 60 and 80 USD/bbl the fallback is visible as 0.125000 charged below every threshold, and that is the entry every tier list has to be checked for.'::text),
      ('intermediate', 'module', 'm03-the-r-factor'::text, 7, '`rfactor_tranche_crossing` and `rfactor_falls_back` run the same tranches of 60 percent at R 1, 40 percent at R 1.6 and 30 percent at R 2.5 on the same project. Why does only one of them fall back?', '["The crossing case ratchets its tranche once reached, and the falling back case has that behaviour switched off by its higher opex figure.", "The crossing case reaches the third tranche a year later, and a tranche entered later in the life has fewer years left in which to be lost again.", "The crossing case has no cost recovery limit binding on it, so its cumulative cost stops growing once the pool clears and the ratio cannot fall.", "The crossing case peaks at 3.109087 in year 12 and has only declined to 2.654466 by year 25, which is still above 2.5, so its split never leaves the 30 percent tranche."]'::jsonb, 3, 'The only differences are capex 350 against 320 and opex 20 against 25. A reversal is an accident of where the ratio settles, not a property one case has and the other lacks.'::text, '`rfactor_tranche_crossing` and `rfactor_falls_back` run the same tranches of 60 percent at R 1, 40 percent at R 1.6 and 30 percent at R 2.5 on the same project. Why does only one of them fall back?', '["The crossing case ratchets its tranche once reached, and the falling back case has that behaviour switched off by its higher opex figure.", "The crossing case reaches the third tranche a year later, and a tranche entered later in the life has fewer years left in which to be lost again.", "The crossing case has no cost recovery limit binding on it, so its cumulative cost stops growing once the pool clears and the ratio cannot fall.", "The crossing case peaks at 3.109087 in year 12 and has only declined to 2.654466 by year 25, which is still above 2.5, so its split never leaves the 30 percent tranche."]'::jsonb, 3, 'The only differences are capex 350 against 320 and opex 20 against 25. A reversal is an accident of where the ratio settles. Neither case carries a property the other lacks.'::text),
      ('intermediate', 'module', 'm03-the-r-factor'::text, 8, 'On the default project year 1 the R factor is 0.512217, below every threshold in the PIA tranche list. What contractor split is applied?', '["0.600000, the lowest tranche''s split, used as the fallback before any threshold has been reached.", "No split at all, since a tranche list cannot select a rate until its lowest threshold has actually been reached by the ratio.", "0.300000, because the walk falls through a list none of whose thresholds are met and keeps the split carried by the last entry.", "A split interpolated between zero and the first tier''s 60 percent in proportion to how far the ratio has climbed toward 1."]'::jsonb, 0, '`getTieredSplit` keeps the lowest tranche''s split until a threshold is reached, exactly as the sliding royalty falls back to its lowest tier''s rate.'::text, 'On the default project year 1 the R factor is 0.512217, below every threshold in the tiered teaching regime''s tranche list. What contractor split is applied?', '["0.600000, the lowest tranche''s split, used as the fallback before any threshold has been reached.", "No split at all, since a tranche list cannot select a rate until its lowest threshold has actually been reached by the ratio.", "0.300000, because the walk falls through a list none of whose thresholds are met and keeps the split carried by the last entry.", "A split interpolated between zero and the first tier''s 60 percent in proportion to how far the ratio has climbed toward 1."]'::jsonb, 0, '`getTieredSplit` keeps the lowest tranche''s split until a threshold is reached, exactly as the sliding royalty falls back to its lowest tier''s rate.'::text),
      ('intermediate', 'module', 'm03-the-r-factor'::text, 9, 'In year 5 on the default project the PIA tranches give the contractor 59.3639 out of profit oil of 148.4098, at an R factor of 1.769792. How was that computed?', '["The first 1.6 of the ratio was priced at the 60 percent rate and the balance of it at 40 percent, in the manner of a marginal income tax band.", "The profit oil was apportioned between the tranches in proportion to the years spent in each, then split at the two rates.", "The whole of the 148.4098 was split at 0.400000, the rate the 1.6 tranche carries, with no part of it left at the rate below.", "The 40 percent rate was applied to profit oil after the year''s cost recovery draw had been taken out of it a second time."]'::jsonb, 2, 'The tranches are not marginal bands. A blended answer lands above 59.3639 and below what a 60 percent rate would give, which is the most plausible-looking wrong answer available.'::text, 'In year 5 on the default project the tiered teaching regime''s tranches give the contractor 59.3639 out of profit oil of 148.4098, at an R factor of 1.769792. How was that computed?', '["The first 1.6 of the ratio was priced at the 60 percent rate and the balance of it at 40 percent, in the manner of a marginal income tax band.", "The profit oil was apportioned between the tranches in proportion to the years spent in each, then split at the two rates.", "The whole of the 148.4098 was split at 0.400000, the rate the 1.6 tranche carries, with no part of it left at the rate below.", "The 40 percent rate was applied to profit oil after the year''s cost recovery draw had been taken out of it a second time."]'::jsonb, 2, 'The tranches are not marginal bands. A blended answer lands above 59.3639 and below what a 60 percent rate would give, which is the most plausible-looking wrong answer available.'::text),
      ('intermediate', 'module', 'm03-the-r-factor'::text, 11, 'In year 11 on the default project the R factor is 2.581420, which has reached all three PIA thresholds, and the implied split reads 0.300000 on profit oil of 80.0217. What would happen if the 2.5 tranche were typed first?', '["The split would be whichever qualifying tranche came last in the reordered list, so 0.600000 would be charged on that year''s profit oil and no error would be raised.", "The engine would refuse the regime, since a tranche list whose thresholds do not ascend fails validation before any year is computed.", "The split would be interpolated between the tranches the reordering brackets, which is how the engine resolves a list it cannot read in order.", "Nothing at all. A sorted copy of the list is read, so the highest threshold reached is still 2.5 and the split in that row is still 0.300000."]'::jsonb, 3, '`tiers_unsorted_selected_by_threshold` types these tranches out of order and returns every row of the sorted case, closing at 279.5803 million USD of contractor net cash flow. Only a repeated threshold is refused, and it is refused by name.'::text, 'In year 11 on the default project the R factor is 2.581420, which has reached all three of the tiered teaching regime''s thresholds, and the implied split reads 0.300000 on profit oil of 80.0217. What would happen if the 2.5 tranche were typed first?', '["The split would be whichever qualifying tranche came last in the reordered list, so 0.600000 would be charged on that year''s profit oil and no error would be raised.", "The engine would refuse the regime, since a tranche list whose thresholds do not ascend fails validation before any year is computed.", "The split would be interpolated between the tranches the reordering brackets, which is how the engine resolves a list it cannot read in order.", "Nothing at all. A sorted copy of the list is read, so the highest threshold reached is still 2.5 and the split in that row is still 0.300000."]'::jsonb, 3, '`tiers_unsorted_selected_by_threshold` types these tranches out of order and returns every row of the sorted case, closing at 279.5803 million USD of contractor net cash flow. Only a repeated threshold is refused, and it is refused by name.'::text),
      ('intermediate', 'module', 'm03-the-r-factor'::text, 14, 'The R factor column on the default project is identical under the USA Gulf of Mexico template and under Nigeria PIA. What does that say about it?', '["It is cached from the first template loaded in a comparison run, which is why the six templates report the same column.", "It responds only to production, price and cost, so no royalty, cost recovery limit, split or tax setting can move it.", "It is computed from the contractor''s own position, and the two templates happen to leave the contractor in the same place on this project.", "It is fixed by the Designer''s default project rather than by the regime, and a different project would make the two columns diverge."]'::jsonb, 1, 'Neither cumulative depends on the regime. Royalty is not subtracted from the revenue side and tax is not added to the cost side.'::text, 'The R factor column on the default project is identical under the "USA - Gulf of Mexico" template and under "Nigeria - PIA (2021)". What does that say about it?', '["It is cached from the first template loaded in a comparison run, which is why the six templates report the same column.", "It responds only to production, price and cost, so no royalty, cost recovery limit, split or tax setting can move it.", "It is computed from the contractor''s own position, and the two templates happen to leave the contractor in the same place on this project.", "It is fixed by the Designer''s default project rather than by the regime, and a different project would make the two columns diverge."]'::jsonb, 1, 'Neither cumulative depends on the regime. Royalty is not subtracted from the revenue side and tax is not added to the cost side.'::text),
      ('intermediate', 'module', 'm04-the-tax-stack'::text, 8, 'The resource rent tax uplift is a percent of total capex. What does the engine do with it?', '["It takes the capex times the uplift off the base in every one of the 25 years, so the relief over the life runs to several times the capex.", "It takes the capex times the uplift off the base once, in the year the capex is spent, so no charge can arise in year 1 on a project that spends its capital there.", "It takes the capex times the uplift off the base in every year the cost recovery pool still carries a balance, since the uplift is the tax side of the same unrecovered capital.", "It opens a relief pool once, at the capex times one plus the uplift, and draws that pool down against the profit share until it is exhausted."]'::jsonb, 3, 'At the default 20 percent on 500.0000 million USD of capex the pool is 1.2 times the capital cost and the first positive charge falls in year 7. Until the 2026-09-15 repair the subtraction was made in every one of the 25 years.'::text, 'The resource rent tax uplift is a percent of total capex. What does the engine do with it?', '["It takes the capex times the uplift off the base in every one of the 25 years, so the relief over the life runs to several times the capex.", "It takes the capex times the uplift off the base once, in the year the capex is spent, so no charge can arise in year 1 on a project that spends its capital there.", "It takes the capex times the uplift off the base in every year the cost recovery pool still carries a balance, since the uplift is the tax side of the same unrecovered capital.", "It opens a relief pool once, at the capex times one plus the uplift, and draws that pool down against the profit share until it is exhausted."]'::jsonb, 3, 'At the default 20 percent on 500.0000 million USD of capex the pool is 1.2 times the capital cost. On the Designer''s default project Brazil - Concession''s first positive resource rent tax charge falls in year 7, and Angola - Deepwater PSC''s in year 13.'::text),
      ('intermediate', 'module', 'm04-the-tax-stack'::text, 13, 'Nigeria - PIA (2021) collects the smallest total tax of the four templates carrying a corporate income tax alone, 174.0882 million USD, inside the largest government cash flow of the four, 1339.2784. What does that pair say?', '["The template''s royalty must be the largest of the four, because a small tax inside a large take can only be made up by a charge on gross revenue.", "The tax line measures one instrument and the take measures the regime, and on one ledger the two can point in opposite directions.", "The take is the wrong column to read, since it includes the contractor''s own profit share.", "The tax total is understated, because the government''s share of profit oil is a tax collected in kind and belongs in that column."]'::jsonb, 1, 'USA - Gulf of Mexico collects 260.7539 million USD of tax inside a take of 764.5528, so ranking these regimes by the tax column reverses the ranking by take.'::text, 'Nigeria - PIA (2021) collects the largest total tax of the four templates carrying a corporate income tax alone, 453.4354 million USD, inside the smallest government cash flow of the four, 687.4682. What does that pair say?', '["The template''s royalty must be the smallest of the four, because a large tax inside a small take can only come from a royalty that collects almost nothing.", "The tax line measures one instrument and the take measures the regime, and on one ledger the two can point in opposite directions.", "The take is the wrong column to read, since it includes the contractor''s own profit share.", "The tax total is overstated, because the government''s share of profit oil is a tax collected in kind and has been counted in that column a second time."]'::jsonb, 1, 'Ghana - Deepwater collects 230.9340 million USD of tax inside a take of 1316.6067, so ranking these four regimes by the tax column reverses the ranking by take.'::text),
      ('intermediate', 'module', 'm05-rate-and-return'::text, 7, 'All six templates return a negative present value on the teaching field at 12 percent, Brazil - Concession the least negative at negative 5.8662 million USD. What does the engine report in its rate of return column for Brazil there?', '["The field loses money under that regime, as a negative present value reports, so the column carries a negative rate.", "A rate just under 12 percent, which is the crossing that matters and the one the summary reports.", "Nothing. Its present value crosses zero twice, once at a negative rate and once below 12 percent, so no single rate can be named.", "A rate of 0.0000 percent, since its undiscounted contractor net cash flow of 192.9896 million USD never covers the capital."]'::jsonb, 2, 'Brazil returns 192.9896 million USD of undiscounted contractor net cash flow and pays back in year 6. A negative present value on a field whose rate column is empty is not a loss.'::text, 'On the teaching field at 12 percent, Brazil - Concession returns negative 5.8662 million USD, the least negative of the five templates below zero. What sits in the engine''s rate of return column for Brazil?', '["The field loses money under that regime, as a negative present value reports, so the column carries a negative rate.", "A rate just under 12 percent, which is the crossing that matters and the one the summary reports.", "Nothing. Its present value crosses zero twice, once at a negative rate and once below 12 percent, so no single rate can be named.", "A rate of 0.0000 percent, since its undiscounted contractor net cash flow of 192.9896 million USD never covers the capital."]'::jsonb, 2, 'Brazil returns 192.9896 million USD of undiscounted contractor net cash flow and pays back in year 6. A negative present value on a field whose rate column is empty is not a loss.'::text),
      ('intermediate', 'module', 'm05-rate-and-return'::text, 9, 'The published case with flows of negative 1 then 2000 has a root at 199900.0000 percent. What does the engine report for it?', '["199900.0000 percent, since the root is exact and the band is a search hint rather than a limit on what may be reported.", "Null, with the status above-clamp, because the only root sits beyond the top of the band the engine searches.", "1000.0000 percent, the top of the band, which is the nearest rate the engine is prepared to defend.", "The top of a doubling search that started at 100 percent, since a bracket that stopped short is still the engine''s fallback."]'::jsonb, 1, '`irr_above_clamp_inside_old_bracket`, with flows of negative 100 then 1500, has a root of 1400.0000 percent and the same status, so a root the retired bisection would have printed is refused as well.'::text, 'The published case with flows of negative 100 then 1500 has its only root at 1400.0000 percent. What does the engine put in the rate column?', '["1400.0000 percent, since a root the solver can verify exactly is reported wherever it lies on the rate axis.", "Null, with the status above-clamp, because the only root sits beyond the top of the band the engine searches.", "1000.0000 percent, the upper edge of the searched band, which is the closest defensible rate the engine can print.", "Null with the status no-root, since a single root is treated as a failed search whenever it falls outside the band."]'::jsonb, 1, 'The band runs from -99 to 1000 percent and neither edge is ever returned as a rate. A root above it, however exact, leaves the column null with the status above-clamp.'::text),
      ('intermediate', 'module', 'm05-rate-and-return'::text, 11, 'Two published cases used to report 0.0000 percent, one worth 25.6198 million USD at 10 percent and one worth negative 16.5289. What do they report now?', '["0.0000 percent for both, since the repair changed the statuses the engine records and not the rates it prints.", "Null with the status no-sign-change for the first, and the negative root itself, negative 10.0000 percent, for the second.", "Null with the status no-root for both, since neither of them has a rate the engine is willing to name.", "Null with the status above-clamp for the first and null with the status multiple-roots for the second."]'::jsonb, 1, 'One project never loses and the other never wins, and the retired rule printed the same four characters for both.'::text, 'Two published cases are worth 25.6198 million USD and negative 16.5289 at 10 percent: flows of 10 then 20, and flows of negative 100 then 90. What does the engine report for their rates?', '["0.0000 percent for both, since neither project has a rate that changes sign and zero is the floor the rate column carries.", "Null with the status no-sign-change for the first, and the negative root itself, negative 10.0000 percent, for the second.", "Null with the status no-root for both, since neither of them has a rate the engine is willing to name.", "Null with the status above-clamp for the first and null with the status multiple-roots for the second."]'::jsonb, 1, 'One project never loses and the other never wins, and the engine keeps them apart: a null with its status for the first, a reported negative rate for the second.'::text),
      ('intermediate', 'module', 'm05-rate-and-return'::text, 12, 'A reader sees an empty rate column on several regimes of one comparison and reads it as a set of projects that broke even. What is wrong with that reading?', '["Nothing, provided the present value at a rate of zero is checked as well, because the same statuses fire on a project sitting at break even.", "Only the precision, since the column would print four decimals on a rate the engine had actually found.", "A null is the engine declining to name a rate, and none of its reasons for declining has anything to do with breaking even.", "It confuses the rate with the payout year, which is the first year the R factor rises above 1.0."]'::jsonb, 2, 'All six templates on the teaching field come back null, and their present values at 12 percent run from negative 5.8662 to negative 58.1813 million USD.'::text, 'A reader sees an empty rate column on several regimes of one comparison and reads it as a set of projects that broke even. What is wrong with that reading?', '["Nothing, provided the present value at a rate of zero is checked as well, because the same statuses fire on a project sitting at break even.", "Only the precision, since the column would print four decimals on a rate the engine had actually found.", "A null is the engine declining to name a rate, and none of its reasons for declining has anything to do with breaking even.", "It confuses the rate with the payout year, which is the first year the R factor rises above 1.0."]'::jsonb, 2, 'All six templates on the teaching field come back null, and their present values at 12 percent run from 1.7389 down to negative 58.1813 million USD, so a null sits beside a small gain and a heavy loss alike.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 3, 'Under one template the implied royalty rate on the teaching field reads 0.187500 in year 1 and 0.187500 in year 25. Under another it reads 0.075000 in years 1 to 5 and 0.100000 from year 6. Which reading identifies the instrument?', '["The one that changes inside the life, because a rate that moves mid field is a sliding scale and the year it moves is a price event.", "The one that holds, because only a flat royalty can charge the same rate in year 1 and in year 25 of a declining field.", "Neither, because an implied rate is royalty over gross revenue and that ratio is fixed by the price deck rather than by the tier list.", "The one that changes, because a royalty rate that moves inside a life is following the production decline through the variable opex."]'::jsonb, 0, 'A sliding royalty sitting below every threshold reads as constant as a flat one, so a rate that holds proves nothing. Year 1 pays 26.1856 million USD on 139.6563 and year 25 pays 1.2953 on 6.9081 under the flat 18.75 percent.'::text, 'Under one template the implied royalty rate on the teaching field reads 0.187500 in year 1 and 0.187500 in year 25. Under the tiered teaching regime it reads 0.075000 in years 1 to 5 and 0.100000 from year 6. Which reading identifies the instrument?', '["The one that changes inside the life, because a rate that moves mid field is a sliding scale and the year it moves is a price event.", "The one that holds, because only a flat royalty can charge the same rate in year 1 and in year 25 of a declining field.", "Neither, because an implied rate is royalty over gross revenue and that ratio is fixed by the price deck rather than by the tier list.", "The one that changes, because a royalty rate that moves inside a life is following the production decline through the variable opex."]'::jsonb, 0, 'A sliding royalty sitting below every threshold reads as constant as a flat one, so a rate that holds proves nothing. Year 1 pays 26.1856 million USD on 139.6563 and year 25 pays 1.2953 on 6.9081 under the flat 18.75 percent.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 6, 'Every one of the six templates returns a negative present value on the teaching field at 12 percent. How is that reported?', '["As one fact about the field, that its cash flows carry no 12 percent return under any of the six regimes, rather than as six separate failures.", "As six loss making regimes, since a negative present value on a 25 year ledger is the model''s report of a loss.", "As evidence that the field''s own discount rate has been set too high, because a rate that no regime in the comparison can beat is not a screening rate at all.", "As an artefact of year end discounting, which is the more conservative of the two conventions in the package."]'::jsonb, 0, 'Brazil - Concession is the least negative at negative 5.8662 million USD, and it returns 192.9896 undiscounted with payback in year 6. No regime on that field carries a single rate of return at all.'::text, 'Five of the six templates return a negative present value on the teaching field at 12 percent, and Nigeria - PIA (2021) returns 1.7389 million USD. What does that spread say?', '["That the field sits close to its 12 percent hurdle, so the regime decides which side of zero it lands on.", "That five of the regimes are loss making, since a negative present value on a 25 year ledger is the model''s report of a loss.", "That the PIA template earns a single rate of return above 12 percent, which is what a positive present value at 12 percent proves.", "That it is an artefact of year end discounting, and the mid year convention would turn all six of the present values negative."]'::jsonb, 0, 'The PIA template''s present value is zero at -19.2469 and at 12.1606 percent, just above the rate the field is discounted at, and Brazil - Concession, the least negative of the other five, sits at negative 5.8662. No regime on that field carries a single rate of return.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 7, 'The summary of a comparison is sorted by contractor net present value descending. What can be read off a regime''s position in it?', '["That the last row is the heaviest regime for the contractor, since government cash flow runs in the reverse order of contractor present value.", "That the rows are in order of rate of return as well, because the two measures rank the same cash flows on the same ledger.", "That the rows are in order of payback, since a regime that returns capital faster carries more of its cash in the early discounted years.", "That the first row is the best regime for the contractor, and nothing else."]'::jsonb, 3, 'On the teaching field the sort puts Brazil - Concession first and Angola - Deepwater PSC last, while government cash flow runs the other way at 316.7898 million USD for Angola against 232.9950 for Brazil.'::text, 'The summary of a comparison is sorted by contractor net present value descending. What can be read off a regime''s position in it?', '["That the last row is the heaviest regime for the contractor, since government cash flow runs in the reverse order of contractor present value.", "That the rows are in order of rate of return as well, because the two measures rank the same cash flows on the same ledger.", "That the rows are in order of payback, since a regime that returns capital faster carries more of its cash in the early discounted years.", "That the first row is the best regime for the contractor, and nothing else."]'::jsonb, 3, 'On the teaching field the sort puts Nigeria - PIA (2021) first and Angola - Deepwater PSC last, and neither position says anything about payback, rate of return or the government''s share.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 10, 'The comparison summary carries government share of net revenue, and Brazil - Concession reads 27.5413 percent on the teaching field. What should a reader know about that column before quoting it?', '["It is government cash flow divided by gross revenue, so it is not comparable with a headline tax rate at all.", "Government take, the same government cash flow divided without the capex added back, sits in the same result object and appears on the screen too.", "It is the rate the tax column implies, so it can be checked by dividing total tax by total profit oil on the same ledger.", "It is reported only for regimes whose profit oil is positive in every year, so a comparison of six can carry fewer than six values."]'::jsonb, 1, 'Two ratios of one government cash flow live in one result and both are on the screen. Working out which is which is where the next tier starts, and the six on that field run from 27.5413 to 37.4463 percent.'::text, 'The comparison summary carries government share of net revenue, and Brazil - Concession reads 27.5413 percent on the teaching field. What should a reader know about that column before quoting it?', '["It is government cash flow divided by gross revenue, so it is not comparable with a headline tax rate at all.", "Government take, the same government cash flow divided without the capex added back, sits in the same result object and appears on the screen too.", "It is the rate the tax column implies, so it can be checked by dividing total tax by total profit oil on the same ledger.", "It is reported only for regimes whose profit oil is positive in every year, so a comparison of six can carry fewer than six values."]'::jsonb, 1, 'Two ratios of one government cash flow live in one result and both are on the screen. Working out which is which is where the next tier starts, and the six on that field run from 23.1713 to 37.4463 percent.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 11, 'The capex sweep on the teaching field runs eight multipliers from 0.8 to 1.5, the last of them exactly 1.5. What does the resilience verdict built on it price?', '["Every overrun the project could suffer, since the sweep is run to the point where the least resilient regime stops paying back.", "The overrun at which the best regime for the contractor changes.", "The contractor present value given up between a 20 percent underspend and a 50 percent overrun, which is the range the axis claims.", "A cost overrun measured against the closing pool, because an overrun that cannot be recovered is the only kind that reaches the contractor."]'::jsonb, 2, 'Over those eight points Ghana - Deepwater gives up 181.1922 million USD of contractor present value and Angola - Deepwater PSC 252.6075. Until the 2026-09-15 repair the loop stopped at 1.4 and every resilience figure was understated.'::text, 'The capex sweep on the teaching field runs eight multipliers from 0.8 to 1.5, the last of them exactly 1.5. What does the resilience verdict built on it price?', '["Every overrun the project could suffer, since the sweep is run to the point where the least resilient regime stops paying back.", "The overrun at which the best regime for the contractor changes.", "The contractor present value given up between a 20 percent underspend and a 50 percent overrun, which is the range the axis claims.", "A cost overrun measured against the closing pool, because an overrun that cannot be recovered is the only kind that reaches the contractor."]'::jsonb, 2, 'Over those eight points Ghana - Deepwater gives up 181.1922 million USD of contractor present value and Angola - Deepwater PSC 252.6075, and the last point is the engine called at 1.5.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 13, 'The verdict named best for the contractor on the teaching field is Brazil - Concession, whose present value there is negative 5.8662 million USD. What is that verdict saying?', '["That Brazil is the least bad of the six, which is a real answer to a real question and not the question most readers think they asked.", "That Brazil returns a positive present value once the negative sign is read as a convention of the summary column.", "That the verdict is unusable, since a ranking of six negative numbers cannot name a best regime at all.", "That the field is uneconomic under every regime, so the verdict is about the field rather than about Brazil."]'::jsonb, 0, 'Every rate of return on that field is below the 12 percent it is discounted at. Being least bad is worth saying out loud, with its label attached.'::text, 'The verdict named best for the contractor on the teaching field is Nigeria - PIA (2021), whose present value there is 1.7389 million USD and which carries no single rate of return. What is that verdict saying?', '["That the PIA template is the only one of the six to clear the field''s 12 percent, by a margin a modest overrun erases.", "That the PIA template earns a single rate of return above 12 percent, which the summary leaves out only because of rounding.", "That the verdict is unusable, since a comparison in which five of the six values are negative cannot name a best regime at all.", "That the field is uneconomic under every regime alike, so the verdict describes the field rather than the template it names."]'::jsonb, 0, 'Its present value is zero at -19.2469 and at 12.1606 percent, so the verdict names no rate. On the capex sweep a 10 percent overrun already turns it to negative 31.8615 million USD.'::text),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 15, 'On the teaching field under the PIA template the pool clears in year 9 and stands at 0.0000 through year 18, then reads 0.5221 million USD in year 19 and 30.5883 at the close of year 25. What reopened it?', '["A second round of capex late in the life, which enters the pool whole in the year it is spent as the first round did.", "The royalty rate stepping up in year 19, which reduced revenue after royalty below the level the limit needs to clear a year''s cost.", "Revenue fell far enough that the allowance no longer covered the year''s own cost, so the shortfall began accruing again.", "The uplift on the resource rent tax, which adds whatever relief it has not used to the cost pool in the years the tax is zero."]'::jsonb, 2, 'In year 19 the allowance releases 12.3236 million USD against a cost of 12.8457, and the difference of that year and every year after it is what carries the pool to 30.5883.'::text, 'On the teaching field under the PIA template the pool clears in year 10 and stands at 0.0000 through year 18, then reads 0.8723 million USD in year 19 and 32.2234 at the close of year 25. What reopened it?', '["A second round of capex late in the life, which enters the pool whole in the year it is spent as the first round did.", "The royalty rate stepping up in year 19, which reduced revenue after royalty below the level the limit needs to clear a year''s cost.", "Revenue fell far enough that the allowance no longer covered the year''s own cost, so the shortfall began accruing again.", "The uplift on the resource rent tax, which adds whatever relief it has not used to the cost pool in the years the tax is zero."]'::jsonb, 2, 'In year 19 the allowance releases 11.9734 million USD against a cost of 12.8457, and the shortfall of that year and every year after it is what carries the pool to 32.2234.'::text),
      ('advanced', 'final', null::text, 6, 'What does `summary[0]` guarantee on any comparison?', '["The highest contractor NPV and the fastest payback, since the two move together on every published comparison in the course.", "The best result for the contractor on NPV, IRR and payback, which is what makes it the row a recommendation is written from.", "The highest contractor NPV at the comparison''s discount rate, and nothing else.", "The lowest government cash flow, because take and contractor NPV are the two sides of one revenue total and must run opposite each other."]'::jsonb, 2, 'On the default project rank 2 returns an IRR of 40.2125 percent and rank 3 returns 44.0823, so even the IRR column is already out of order.'::text, 'What does `summary[0]` guarantee on any comparison?', '["The highest contractor NPV and the fastest payback, since the two move together on every published comparison in the course.", "The best result for the contractor on NPV, IRR and payback, which is what makes it the row a recommendation is written from.", "The highest contractor NPV at the comparison''s discount rate, and nothing else.", "The lowest government cash flow, because take and contractor NPV are the two sides of one revenue total and must run opposite each other."]'::jsonb, 2, 'On the default project rank 3 returns an IRR of 40.2125 percent and rank 4 returns 44.0823, so even the IRR column is already out of order.'::text),
      ('advanced', 'final', null::text, 9, 'USA - Gulf of Mexico shows a price climb of -17.2498 percentage points and Generic Royalty/Tax -10.1897 on the default project. What makes those two regressive?', '["A fixed royalty rate and a fixed tax rate on a growing profit hand the government a shrinking fraction once cost recovery has been paid off.", "A cost recovery limit that rises with price, which returns more of the contractor''s cost before any split is taken.", "A profit split tiered on the R factor, which walks the contractor into a more generous tranche as revenue grows.", "A minimum tax that binds at low prices and stops binding once the computed charge exceeds it."]'::jsonb, 0, 'Brazil - Concession climbs the most at 20.5076 percentage points, and the three templates whose split is tiered on the R factor climb by 19.6873, 10.1420 and 7.8960.'::text, 'USA - Gulf of Mexico shows a price climb of -17.2498 percentage points and Generic Royalty/Tax -10.1897 on the default project. What makes those two regressive?', '["A fixed royalty rate and a fixed tax rate on a growing profit hand the government a shrinking fraction once cost recovery has been paid off.", "A cost recovery limit that rises with price, which returns more of the contractor''s cost before any split is taken and so shrinks the state''s share of each barrel.", "A profit split tiered on the R factor, which walks the contractor into a more generous tranche as revenue grows.", "A minimum tax that binds at low prices and stops binding once the computed charge exceeds it, which flattens the government''s share as price rises."]'::jsonb, 0, 'Brazil - Concession climbs the most at 20.5076 percentage points, the two templates whose split is tiered on the R factor climb by 19.6873 and 7.8960, and Nigeria - PIA (2021) is almost flat at -0.0068.'::text),
      ('advanced', 'final', null::text, 24, 'The contractor verdict on ODIDI prints -5.9 million USD and says there is no single IRR, because the NPV is zero at -18.8% and 11.4%. What did it rank?', '["The first row of the summary at full precision, -5.8662 million USD, because the sort has already put the highest contractor NPV there.", "The largest contractor NPV it could find across the six ledgers, recomputed at the comparison''s discount rate before the sentence was built.", "The rounded figures themselves, which is why two regimes printing the same value are reported as a tie by this verdict.", "The undiscounted lifetime contractor net cash flow, which on ODIDI is 192.9896 million USD for that regime."]'::jsonb, 0, 'Every insight sentence rounds money and rates to one decimal place while the ranking underneath runs at full precision.'::text, 'The contractor verdict on ODIDI prints 1.7 million USD and says there is no single IRR, because the NPV is zero at -19.2% and 12.2%. What did it rank?', '["The first row of the summary at full precision, 1.7389 million USD, because the sort has already put the highest contractor NPV there.", "The largest contractor NPV it could find across the six ledgers, recomputed at the comparison''s discount rate before the sentence was built.", "The rounded figures themselves, which is why two regimes printing the same value are reported as a tie by this verdict.", "The undiscounted lifetime contractor net cash flow, which on ODIDI is 229.9586 million USD for that regime."]'::jsonb, 0, 'Every insight sentence rounds money and rates to one decimal place while the ranking underneath runs at full precision.'::text),
      ('advanced', 'final', null::text, 25, 'On flows of -1 then 2000 the retired bisection returned 102400 percent where the true rate is 199900 percent. What does the engine do with those flows now?', '["It returns 199900.0000 percent, the band having been widened until the search reached the root.", "It returns 1000.0000 percent, the top of the band, as the screening engine returns its own clamp.", "It returns null with the status no-root, since a root outside the band is a root the engine did not find.", "It returns null with the status above-clamp, because the only root lies beyond the band from -99 to 1000 percent."]'::jsonb, 3, 'The NPV at 102400 percent is 0.0009 and at 199900 percent is 0.0000, so the retired value was the edge of a search and never a root.'::text, 'A two-year project spends 1 million USD and then earns 2000, so its one real root sits at 199900 percent. Which answer does `calculateIRR` give for it, and on what grounds?', '["It returns 199900.0000 percent, the band having been widened until the search reached the root.", "It returns 1000.0000 percent, the top of the band, as the screening engine returns its own clamp.", "It returns null with the status no-root, since a root outside the band is a root the engine did not find.", "It returns null with the status above-clamp, because the only root lies beyond the band from -99 to 1000 percent."]'::jsonb, 3, 'The NPV at 102400 percent is 0.0009 and at 199900 percent is 0.0000, so 102400 is no root; the only root lies above the band, and the engine says so with a status instead of a rate.'::text),
      ('advanced', 'final', null::text, 26, 'Two published cases once returned an IRR of 0.0000 percent, one with an NPV at 10 percent of 25.6198 million USD and one of -16.5289. What does each return today?', '["Null with the status no-root on both, neither having a rate inside the band from -99 to 1000 percent.", "Null with the status no-sign-change on the profitable one, and the negative root itself, -10.0000 percent, on the one that loses money at every rate.", "0.0000 percent on the profitable one and null on the other, the engine still declining to print a negative rate.", "-10.0000 percent on both, the shared contract reporting the nearest root inside the band whatever the flows do."]'::jsonb, 1, 'A reader who rejected 102400 percent as absurd and accepted 0.0000 percent as break even had caught the harmless case and swallowed the dangerous one.'::text, 'Two published cases have an NPV at 10 percent of 25.6198 and of -16.5289 million USD: one never changes sign, the other is -100 then 90. What does `calculateIRR` return for each?', '["Null with the status no-root on both, neither having a rate inside the band from -99 to 1000 percent that brings its NPV to zero at year-end discounting.", "Null with the status no-sign-change on the profitable one, and the negative root itself, -10.0000 percent, on the one that loses money at every positive rate.", "0.0000 percent on the profitable one and null on the other, the engine still declining to print a negative rate even where the only root lies well inside its band.", "-10.0000 percent on both, the shared contract reporting the nearest root inside the band whatever the flows do, including flows that never change sign."]'::jsonb, 1, 'A profitable flow with no sign change has no rate to report, and a loss at every positive rate has a real negative root; a reader who would accept 0.0000 percent for either has read neither status.'::text),
      ('advanced', 'final', null::text, 29, 'Why did the capex sweep once return seven points rather than eight?', '["The engine dropped the last point to keep the axis readable.", "The loop counted steps from 0.8 in tenths, and seven steps is what the 0.7 range of the published cases allows.", "The last multiplier was reserved for the direct call the golden publishes beside the sweep, so it was computed but not returned.", "The accumulating multiplier reached 1.5000000000000004 and failed its own test."]'::jsonb, 3, 'The engine returns the labels 0.8, 0.9, 1.0, 1.1, 1.2, 1.3, 1.4 and 1.5, written from a step count, and the last of them equals the engine called directly at 1.5.'::text, 'On the default project Nigeria - PIA (2021) keeps 291.8238 million USD of contractor NPV at a capex multiplier of 1.4 and 255.8175 at 1.5. What does that single last step cost, set against the 243.6525 the regime gives up over the whole sweep?', '["243.6525 million USD, since the last step of a sweep carries its whole loss once the grid reaches the overrun on the label.", "255.8175 million USD, the NPV at 1.5, because a loss is read from the endpoint of the axis and never from a difference.", "34.81 million USD, the range loss of 243.6525 spread evenly over the seven steps, since a sweep loses the same amount at every step.", "About 36.01 million USD, the swept point at 1.4 minus the swept point at 1.5."]'::jsonb, 3, 'The last step is the 1.4 point minus the 1.5 point; the range loss runs from the first swept point at 0.8 to the eighth at 1.5, and the two are different spans of one sweep.'::text),
      ('advanced', 'final', null::text, 31, 'Every rate in a written answer on ODIDI is correct and the resilience answer is still wrong. What was skipped?', '["The ranges, since the capex sweep stops at a multiplier of 1.4 while the chart promises 1.5.", "The sort, since a resilience verdict is read off the summary''s first row.", "The field: a capex loss belongs to one project, and ODIDI orders the six templates differently from the default project.", "The discount rate, since ODIDI is discounted at 12 percent and the swept losses are reported at the comparison''s own 10."]'::jsonb, 2, 'Ranges and definitions are where the marks are lost, not rates, and ODIDI''s losses of 181.1922 and 252.6075 million USD belong to that field alone.'::text, 'Every rate in a written answer on ODIDI is correct and the resilience answer is still wrong. What was skipped?', '["The ranges, since the capex sweep stops at a multiplier of 1.4 while the chart promises 1.5.", "The sort, since a resilience verdict is read off the summary''s first row.", "The field: a capex loss belongs to one project, and ODIDI orders the six templates differently from the default project.", "The discount rate, since ODIDI is discounted at 12 percent and the swept losses are reported at the comparison''s own 10."]'::jsonb, 2, 'Ranges and definitions are where the marks are lost, and ODIDI''s losses of 181.1922 and 252.6075 million USD belong to that field alone.'::text),
      ('advanced', 'final', null::text, 33, 'On ODIDI the highest contractor NPV and the largest government cash flow sit in different rows. Which rows, and why is that not a contradiction?', '["Brazil - Concession heads both, and the appearance of a split comes from the government share of net revenue column, which is a ratio rather than a total.", "Brazil - Concession at -5.8662 million USD heads the sort while Angola - Deepwater PSC collects 316.7898 at rank 6, because the sort key is discounted and government cash flow is an undiscounted lifetime total.", "Generic Royalty/Tax heads the sort at -13.3840 million USD while Nigeria - PIA (2021) collects 312.9610 million USD, and the two differ because one of those columns is a percent of revenue and the other is money over the whole life.", "Angola - Deepwater PSC heads both on ODIDI, which is what makes the field a poor one to rehearse a comparison on."]'::jsonb, 1, 'All six ODIDI NPVs at 12 percent are negative, so the head of the sort is the least bad rather than the good one.'::text, 'On ODIDI the highest contractor NPV and the largest government cash flow sit in different rows. Which rows, and why is that not a contradiction?', '["Brazil - Concession heads both, and the appearance of a split comes from the government share of net revenue column, which is a ratio rather than a total.", "Nigeria - PIA (2021) at 1.7389 million USD heads the sort while Angola - Deepwater PSC collects 316.7898 at rank 6, because the sort ranks the contractor''s discounted cash and take is the state''s undiscounted share.", "Generic Royalty/Tax heads the sort at -13.3840 million USD while Nigeria - PIA (2021) collects 196.0260 million USD, and the two differ because one of those columns is a percent of revenue and the other is money over the whole life.", "Angola - Deepwater PSC heads both on ODIDI, which is what makes the field a poor one to rehearse a comparison on."]'::jsonb, 1, 'Only the head of the ODIDI sort returns a positive NPV at 12 percent, 1.7389 million USD, and the same regime collects the least for the government, 196.0260.'::text),
      ('advanced', 'final', null::text, 34, 'Under the PIA template on ODIDI the contractor net cash flow reads -1.0205 million USD in year 20 and stays negative to year 25, while the cumulative ends at 113.0236. What does that mean for the payback year?', '["Payback is recomputed at the end and reported as the last year the cumulative was above zero, which on this ledger is year 25.", "Payback is null on this ledger, because a cumulative that turns down inside the horizon has not recovered the capital.", "Payback is unaffected because the engine reads only the years before the R factor passes 1.0, which on ODIDI is year 6.", "Payback is a first crossing and not a high water mark, and the cumulative peaks at 138.3627 million USD before falling back."]'::jsonb, 3, 'The cumulative first turns positive in year 7 at 6.1264 million USD, and late year opex against a declining revenue is what pulls it back.'::text, 'Under the PIA template on ODIDI the contractor net cash flow reads -0.0003 million USD in year 20 and stays negative to year 25, while the cumulative ends at 229.9586. What does that mean for the payback year?', '["Payback is recomputed at the end and reported as the last year the cumulative was above zero, which on this ledger is year 25.", "Payback is null on this ledger, because a cumulative that turns down inside the horizon has not recovered the capital.", "Payback is unaffected because the engine reads only the years before the R factor passes 1.0, which on ODIDI is year 6.", "Payback is a first crossing and not a high water mark, and the cumulative peaks at 250.9149 million USD before falling back."]'::jsonb, 3, 'The cumulative first turns positive in year 7 at 43.8352 million USD, and late year opex against a declining revenue is what pulls it back.'::text),
      ('advanced', 'final', null::text, 35, 'On the Designer''s defaults the Concessionary regime reads 46.3452 percent in the summary and 59.6210 percent on the price chart at the base price. Which one is the rate on profit, and why do they differ?', '["The summary''s 46.3452, because it adds total capex back to the contractor side, while the chart''s 59.6210 divides the same two totals with nothing added back.", "The chart''s 59.6210, because the sweep re-runs the whole ledger at each of its nine prices and therefore works on profit, while the summary reports a single ratio taken on cash.", "The summary''s 46.3452, because it is discounted at 10 percent while the chart''s number is an undiscounted lifetime ratio.", "Neither, since both divide take by take plus contractor cash and the difference between them is the swept price."]'::jsonb, 0, 'The Nigerian PIA (PSC) regime shows the same pair, 56.5354 against 72.7302, a gap of 16.1948 percentage points on one screen.'::text, 'On the Designer''s defaults the Concessionary regime reads 46.3452 percent in the summary and 59.6210 percent on the price chart at the base price. Which one is government share of net revenue, and why do they differ?', '["The summary''s 46.3452, because it adds total capex back to the contractor side, while the chart''s 59.6210 divides the same two totals with nothing added back.", "The chart''s 59.6210, because the sweep re-runs the whole ledger at each of its nine prices and therefore works on profit, while the summary reports a single ratio taken on cash.", "The summary''s 46.3452, because it is discounted at 10 percent while the chart''s number is an undiscounted lifetime ratio.", "Neither, since both divide take by take plus contractor cash and the difference between them is the swept price."]'::jsonb, 0, 'The Designer''s sample PSC regime, whose values are illustrative samples, shows the same pair, 56.5354 against 72.7302, a gap of 16.1948 percentage points on one screen.'::text),
      ('advanced', 'final', null::text, 36, 'The payback column of `cmp_all_templates_default_project` reads 3, 3, 3, 4, 3 and 4 down the summary. What does the payback verdict then report?', '["The regime with the highest NPV, because the tie is broken by summary order and the summary is sorted on contractor NPV.", "No verdict at all, because a four way tie at the top cannot be ranked and an unsupportable claim is omitted.", "All four regimes at year 3, in summary order, against year 4 for one of the two at the slowest year.", "The regime whose R factor payout year is earliest, which is the tie break the engine applies whenever an integer column ties in the summary."]'::jsonb, 2, 'Naming every regime tied at the fastest year is the 2026-09-15 repair. Until then the sentence named Generic Royalty/Tax alone, which leads the sort at 397.0445 million USD, so a tied payback verdict was the NPV ranking under another label.'::text, 'The payback verdict on `cmp_all_templates_default_project` closes with "against year 4 for Angola - Deepwater PSC". What is Angola in that sentence?', '["The runner-up, the regime that recovers its capital second fastest of the six templates.", "The regime with the lowest contractor NPV, which the sentence quotes as the comparison''s floor.", "The slowest regime left once the tied fastest ones are named, here the only one paying back in year 4.", "The one regime whose R factor payout comes later than its cash payback, which the sentence flags as a warning."]'::jsonb, 2, 'The verdict names every regime tied at the fastest year, sets them aside and takes the maximum of what is left, so the second name is the slowest of the rest. The payback column reads 3, 3, 3, 3, 4 and 3 down the summary, and Angola pays out in year 3, before its payback.'::text),
      ('advanced', 'final', null::text, 39, 'On the default project the price climb and the capex loss rank the six templates in nearly the same order. What connects the two sweeps?', '["A regime that takes a rising share of the upside absorbs a share of the downside, so the contractor''s NPV under it moves less when capital cost rises.", "Both sweeps are computed from the same series, since the capex sweep is the price sweep re-expressed in money rather than in percentage points of government take.", "Both sweeps hold the other variable at the base case, so the two rankings are the same ranking measured twice.", "Both are endpoint differences over seven points, so a regime that leads one must lead the other by construction."]'::jsonb, 0, 'The two steepest climbers give up the least at 100.7185 and 88.6123 million USD and the two regressive ones give up 244.0782 and 267.7301, and the orders still differ row for row.'::text, 'On the default project the price climb and the capex loss rank the six templates in nearly the same order. What connects the two sweeps?', '["A regime that takes a rising share of the upside absorbs a share of the downside, so the contractor''s NPV under it moves less when capital cost rises.", "They are computed from the same series, since the capex sweep is the price sweep re-expressed in money rather than in percentage points of government take.", "Both sweeps hold the other variable at the base case, so the two rankings are the same ranking measured twice.", "Each is an endpoint difference over eight points, so a regime that leads one must lead the other by construction."]'::jsonb, 0, 'The two steepest climbers give up the least at 100.7185 and 88.6123 million USD and the two most regressive give up 244.0782 and 267.7301, while Nigeria - PIA (2021), almost flat at -0.0068, gives up 243.6525, so the orders still differ row for row.'::text),
      ('advanced', 'final', null::text, 41, 'ODIDI carries oil, gas and NGL while the Suite test project produces 30000 bbl/d of oil with no gas and no NGL. What does that change about a price sweep on each?', '["On the test project the sweep is meaningless because a single stream cannot show progressivity at all, and on ODIDI it is the only one of the two readings a fiscal analyst should quote.", "On the test project the multiplier is the whole revenue multiplier, and on ODIDI it moves oil only while gas at 40 Mscf/d and NGL at 900 bbl/d stay where the deck left them.", "On both the multiplier scales all three stream prices, and the difference is only that two of ODIDI''s streams are small.", "On the test project the sweep must re-run the decline as well, since an oil only field has no gas revenue to hold the ledger up at a low price."]'::jsonb, 1, 'A flat curve on a gas weighted field means the sweep did not move most of the revenue, not that the terms are neutral to price.'::text, 'ODIDI carries oil, gas and NGL while the Suite test project produces 30000 bbl/d of oil with no gas and no NGL. What does that change about a price sweep on each?', '["On the test project the sweep is meaningless because a single stream cannot show progressivity at all, and on ODIDI it is the only one of the two readings a fiscal analyst should quote.", "On the test project the multiplier is the whole revenue multiplier, and on ODIDI it moves oil only while gas at 40 Mscf/d and NGL at 900 bbl/d stay where the deck left them.", "On both the multiplier scales all three stream prices, and the difference is only that two of ODIDI''s streams are small.", "On the test project the sweep must re-run the decline as well, since an oil only field has no gas revenue to hold the ledger up at a low price."]'::jsonb, 1, 'A flat curve on a gas weighted field means the sweep did not move most of the revenue, and it says little about whether the terms respond to price.'::text),
      ('advanced', 'final', null::text, 42, 'The engine returns 58.5739 million USD for Nigeria - PIA (2021) at a capex multiplier of 1.5 both as a swept point and when called directly. What does that agreement pin?', '["That the golden publishes the oracle''s eighth point in place of the engine''s, the two being equal at that multiplier.", "That the chart may drop a point whose contractor NPV falls below the base case by more than half, as 58.5739 does against 154.8286.", "That a direct call and a swept point use different discount conventions which happen to meet at a multiplier of 1.5.", "That the sweep reaches its endpoint rather than approaching it, which is the check a step count buys over an accumulating sum."]'::jsonb, 3, 'The golden also pins the grid itself as `capexGrid`, eight multipliers from 0.8 to 1.5, so neither the count nor the labels can drift back.'::text, 'The engine returns 255.8175 million USD for Nigeria - PIA (2021) at a capex multiplier of 1.5 both as a swept point and when called directly. What does that agreement pin?', '["That the golden publishes the oracle''s eighth point in place of the engine''s, the two being equal at that multiplier.", "That the chart may drop a point whose contractor NPV falls below the base case by more than a third, as 255.8175 does against 432.0925.", "That a direct call and a swept point use different discount conventions which happen to meet at a multiplier of 1.5.", "That the sweep reaches its endpoint rather than approaching it, which is the check a step count buys over an accumulating sum."]'::jsonb, 3, 'The golden also pins the grid itself as `capexGrid`, eight multipliers from 0.8 to 1.5, so the count and the labels are pinned as well as the values.'::text),
      ('advanced', 'module', 'm01-six-regimes-at-once'::text, 2, 'All six templates on the default project return gross revenue of 2686.9277 million USD. What does that identical figure say about a fiscal regime?', '["The six templates happen to share a royalty base, and a template built on a different base would return a different revenue.", "Cost recovery is struck before revenue is reported, so the revenue line is already net of the recoverable pool and equal by construction.", "It touches neither production nor price, so revenue belongs to the field and only the division of it moves.", "Revenue is the figure discounted at 10 percent, which removes the regime''s effect on timing."]'::jsonb, 2, 'On that same 2686.9277 million USD, lifetime contractor net cash flow is 406.2057 million USD under Nigeria - PIA (2021) and 986.7327 under Generic Royalty/Tax.'::text, 'All six templates on the default project return gross revenue of 2686.9277 million USD. What does that identical figure say about a fiscal regime?', '["The six templates happen to share a royalty base, and a template built on a different base would return a different revenue.", "Cost recovery is struck before revenue is reported, so the revenue line is already net of the recoverable pool and equal by construction.", "It touches neither production nor price, so revenue belongs to the field and only the division of it moves.", "Revenue is the figure discounted at 10 percent, which removes the regime''s effect on timing."]'::jsonb, 2, 'On that same 2686.9277 million USD, lifetime contractor net cash flow is 1058.0159 million USD under Nigeria - PIA (2021) and 986.7327 under Generic Royalty/Tax.'::text),
      ('advanced', 'module', 'm01-six-regimes-at-once'::text, 3, 'The summary comes back sorted. What can be read off a row''s position, and what tie break applies when two regimes match?', '["Contractor NPV descending, with the payback year as the secondary key wherever two NPVs are equal.", "Contractor NPV descending and nothing else, and there is no secondary key at all, so equal NPVs keep the order they were passed in.", "Contractor NPV descending and government cash flow ascending together, since the two mirror each other.", "The internal rate of return descending, so rank 2 at 40.2125 percent above rank 3 at 44.0823 is an error."]'::jsonb, 1, 'summary[0] is the best regime for the contractor and nothing else can be read off a position, and the comparison exposes no option to sort on another column.'::text, 'The summary comes back sorted. What can be read off a row''s position, and what tie break applies when two regimes match?', '["Contractor NPV descending, with the payback year as the secondary key wherever two NPVs are equal, so the faster regime is listed first on a tie.", "Contractor NPV descending and nothing else, and there is no secondary key at all, so equal NPVs keep the order they were passed in.", "Contractor NPV descending and government cash flow ascending together, since the two mirror each other on every comparison the engine runs.", "The internal rate of return descending, so rank 3 at 40.2125 percent sitting above rank 4 at 44.0823 percent is an error in the sort."]'::jsonb, 1, 'summary[0] is the best regime for the contractor and nothing else can be read off a position, and the comparison exposes no option to sort on another column.'::text),
      ('advanced', 'module', 'm01-six-regimes-at-once'::text, 4, 'On the default project rank 2 returns an internal rate of return of 40.2125 percent and rank 3 returns 44.0823 percent. What has gone wrong?', '["The two rates were solved at different discount rates, because the bisection reruns each regime against its own hurdle.", "The rank 2 regime failed to converge, so the solver reported the edge of its own bracket in that row instead of a root.", "The rows were ordered on the payback year, which puts a regime with a later payout above one with a higher rate.", "Nothing at all."]'::jsonb, 3, 'Generic Royalty/Tax leads on NPV at 397.0445 million USD with a rate of 44.6574 percent, and Brazil - Concession sits at rank 3 with 287.2804 and 44.0823, so the higher rate and the higher NPV belong to different regimes.'::text, 'On the default project rank 3 returns an internal rate of return of 40.2125 percent and rank 4 returns 44.0823 percent. What has gone wrong?', '["Each rate was solved at a different discount rate, since the solver reruns each regime against its own hurdle.", "The rank 3 regime failed to converge, so the solver reported the edge of its own bracket in that row instead of a root.", "A payback sort ordered the rows, which puts a regime with a later payout above one with a higher rate.", "Nothing at all."]'::jsonb, 3, 'Nigeria - PIA (2021) leads on NPV at 432.0925 million USD with a rate of 46.7732 percent, USA - Gulf of Mexico sits at rank 3 with 382.0660 and 40.2125, and Brazil - Concession at rank 4 with 287.2804 and 44.0823, so the higher rate and the higher NPV belong to different regimes.'::text),
      ('advanced', 'module', 'm01-six-regimes-at-once'::text, 5, 'On ODIDI, Ghana - Deepwater sits at rank 3 collecting 308.8447 million USD for the government and USA - Gulf of Mexico at rank 4 collecting 277.6679. Why does the lower ranked regime collect less?', '["The take column is reported after royalty on that field, and USA - Gulf of Mexico charges the higher flat royalty of the two.", "The sort key is NPV discounted at 12 percent while take is an undiscounted lifetime total, and the larger contractor sum arrives later.", "The ranking was set by the government share of net revenue column, where 32.8219 percent sits below 36.5071 percent.", "USA - Gulf of Mexico never pays back on ODIDI, so its take was truncated at the fixed 25 year horizon."]'::jsonb, 1, 'USA - Gulf of Mexico keeps 148.3166 million USD of lifetime contractor net cash flow against 117.1399 for Ghana - Deepwater and ranks lower anyway, paying back in year 7 against year 6.'::text, 'On ODIDI, Ghana - Deepwater sits at rank 4 collecting 308.8447 million USD for the government and USA - Gulf of Mexico at rank 5 collecting 277.6679. Why does the lower ranked regime collect less?', '["The take column is reported after royalty on that field, and USA - Gulf of Mexico charges the higher flat royalty of the two.", "The sort key is NPV discounted at 12 percent while take is an undiscounted lifetime total, and the larger contractor sum arrives later.", "The ranking was set by the government share of net revenue column, where 32.8219 percent sits below 36.5071 percent.", "USA - Gulf of Mexico never pays back on ODIDI, so its take was truncated at the fixed 25 year horizon."]'::jsonb, 1, 'USA - Gulf of Mexico keeps 148.3166 million USD of lifetime contractor net cash flow against 117.1399 for Ghana - Deepwater and ranks lower anyway, paying back in year 7 against year 6.'::text),
      ('advanced', 'module', 'm01-six-regimes-at-once'::text, 6, 'Which regime is best for the government on ODIDI, and where is that read from?', '["The regime at rank 2, Generic Royalty/Tax, since the second row is the state''s preference once the contractor''s own pick is set aside.", "Brazil - Concession at rank 1, because on a field where every NPV is negative the leading row is the one the state has squeezed hardest.", "Angola - Deepwater PSC, read out of the take column at 316.7898 million USD, from rank 6.", "Nigeria - PIA (2021), whose 36.9937 percent is the harshest rate of the six."]'::jsonb, 2, 'Nothing in the summary sorts by take, and quoting the second row as the government''s preference is the exact claim the Insights tab used to make.'::text, 'Which regime is best for the government on ODIDI, and where is that read from?', '["The regime at rank 2, Brazil - Concession, since the second row is the state''s preference once the contractor''s own pick is set aside.", "Nigeria - PIA (2021) at rank 1, because on a field this marginal the leading row is the one the state has squeezed hardest.", "Angola - Deepwater PSC, read out of the take column at 316.7898 million USD, from rank 6.", "Ghana - Deepwater, whose 36.5071 percent is the harshest government share of net revenue the summary shows."]'::jsonb, 2, 'Nothing in the summary sorts by take, and quoting the second row as the government''s preference is a claim no column supports.'::text),
      ('advanced', 'module', 'm02-the-price-sweep'::text, 3, 'At 40 USD per bbl the Designer''s default production sharing regime leaves 5.9578 million USD of cost unrecovered at the end of the life. What does that say?', '["The cost recovery limit binds hard at the bottom of the sweep, and the pool closes to 0.7642 at 50 and to 0.0000 from 60 upward.", "The pool carries forward past the horizon, so the contractor recovers the remainder in the following licence period.", "The engine wrote the remainder off as an abandonment provision, which is what makes the NPV smaller than the loss.", "Cost recovery was capped by the profit oil split rather than by the limit, since a low price walks the R factor into a generous tranche."]'::jsonb, 0, 'A limit that never binds at the deck price binds at 40 USD per bbl, where NPV is -51.1673 million USD and the engine names no internal rate of return at all.'::text, 'At 40 USD per bbl the Designer''s sample PSC regime leaves 5.9578 million USD of cost unrecovered at the end of the life. What does that say?', '["The cost recovery limit binds hard at the bottom of the sweep, and the pool closes to 0.7642 at 50 and to 0.0000 from 60 upward.", "The pool carries forward past the horizon, so the contractor recovers the remainder in the following licence period.", "The engine wrote the remainder off as an abandonment provision, which is what makes the NPV smaller than the loss.", "Cost recovery was capped by the profit oil split rather than by the limit, since a low price walks the R factor into a generous tranche."]'::jsonb, 0, 'At the deck price the limit binds only in the first four years and the pool clears; at 40 USD per bbl the pool is still open after year 25, NPV is -51.1673 million USD, and the engine reports no single IRR, the NPV being zero at -40.1442 and 6.6994 percent.'::text),
      ('advanced', 'module', 'm02-the-price-sweep'::text, 4, 'The nine published price runs are named price_40_pia_default through price_120_pia_default. Which regime do they actually run?', '["The Nigeria - PIA (2021) template, which is why the 70 point returns that template''s NPV of 154.8286 million USD on the default project.", "All six templates at once, with the PIA row published at each price and the other five rows computed and then discarded.", "The Nigeria - PIA (2021) template on the test project, the one project whose first deck point is not 70 USD per bbl.", "The Designer''s own default regime, id 1, Nigerian PIA (PSC)."]'::jsonb, 3, 'The template and the Designer regime share a country and nothing else: cost recovery at 70 percent against 80, and royalty from 12.5 percent against 7.5 percent. The template returns 154.8286 million USD on that project and the Designer regime 169.7176.'::text, 'The nine published price runs are named price_40_pia_default through price_120_pia_default. Which regime do they actually run?', '["The Nigeria - PIA (2021) template, which is why the 70 point returns that template''s NPV of 432.0925 million USD on the default project.", "All six templates at once, with the PIA row published at each price and the other five rows computed and then discarded.", "The Nigeria - PIA (2021) template on the test project, the one project whose first deck point is not 70 USD per bbl.", "The Designer''s sample PSC regime, id 1, which the engine names Nigerian PIA (PSC)."]'::jsonb, 3, 'The template and the Designer''s sample PSC regime, whose values are illustrative samples, share little: the sample regime recovers cost to 70 percent of revenue after royalty and charges a royalty of 12.5 percent below 80 USD/bbl and 15 percent from 80, while the template recovers to 70 percent of the gross value of crude oil and NGL and charges the PIA 2021 royalty. The template returns 432.0925 million USD on that project and the sample regime 169.7176.'::text),
      ('advanced', 'module', 'm02-the-price-sweep'::text, 13, 'A gas weighted project shows a government take that barely moves across the nine points. What is the correct conclusion?', '["The terms are flat rated, so the regime is neither progressive nor regressive.", "The project sits at its cost recovery limit at every price, which pins the share until the recoverable pool clears.", "The sweep did not move most of that project''s revenue, not that its terms are neutral to price.", "The engine flagged every point undefined and returned a constant, as it does whenever contractor net cash flow is negative."]'::jsonb, 2, 'The multiplier scales oil only, so comparing the steepness of two projects'' curves compares their stream mix as much as their terms. The test project is 30000 bbl/d of oil with no gas and no NGL, so there the multiplier is the whole revenue multiplier.'::text, 'A gas weighted project shows a government take that barely moves across the nine points. What is the correct conclusion?', '["The terms are flat rated, so the regime is neither progressive nor regressive.", "The project sits at its cost recovery limit at every price, which pins the share until the recoverable pool clears.", "The sweep did not move most of that project''s revenue, so the flat curve says little about its terms.", "The engine flagged every point undefined and returned a constant, as it does whenever contractor net cash flow is negative."]'::jsonb, 2, 'The multiplier scales oil only, so comparing the steepness of two projects'' curves compares their stream mix as much as their terms. The test project is 30000 bbl/d of oil with no gas and no NGL, so there the multiplier is the whole revenue multiplier.'::text),
      ('advanced', 'module', 'm02-the-price-sweep'::text, 14, 'On the Designer''s two default regimes at the deck''s own first year price, Concessionary (Royalty/Tax) reads 46.3452 in one place and 59.6210 in another. What separates those two figures?', '["The table adds total capex back into the contractor''s side of the denominator and the chart does not.", "The chart is computed at the swept price and the table at the deck price, which are not the same price.", "The chart counts the government''s profit oil share as well as tax and the table counts tax alone.", "The chart is undiscounted while the table is discounted at 10 percent."]'::jsonb, 0, 'Both are the same ratio on the same cash flows and only the add-back differs. The gap on that row is 13.2758 percentage points, and on Nigerian PIA (PSC) it is 16.1948.'::text, 'On the Designer''s two default regimes at the deck''s own first year price, Concessionary (Royalty/Tax) reads 46.3452 in one place and 59.6210 in another. What separates those two figures?', '["The table adds total capex back into the contractor''s side of the denominator and the chart does not.", "The chart is computed at the swept price and the table at the deck price, which are not the same price.", "The chart counts the government''s profit oil share as well as tax and the table counts tax alone.", "The chart is undiscounted while the table is discounted at 10 percent."]'::jsonb, 0, 'Both are the same ratio on the same cash flows and only the add-back differs. The gap on that row is 13.2758 percentage points, and on the Designer''s sample PSC regime it is 16.1948.'::text),
      ('advanced', 'module', 'm02-the-price-sweep'::text, 15, 'Why can a reader not carry one fixed offset between government share of net revenue in the summary and government take on the chart?', '["The two are computed on different projects, so a gap measured on one field cannot be carried to another.", "The gap runs from 9.6793 to 17.0850 percentage points across six templates on one project at one price.", "The chart prints four decimal places and the table one, so the offset changes with the rounding.", "The gap changes sign between a regime that adds capex back and one that does not."]'::jsonb, 1, 'The gap grows with government share of net revenue itself, so Ghana - Deepwater''s 16.7958 carried across to Generic Royalty/Tax, where it is 9.6793, overstates the chart badly.'::text, 'Why can a reader not carry one fixed offset between government share of net revenue in the summary and government take on the chart?', '["The two are computed on different projects, so a gap measured on one field cannot be carried to another.", "The gap runs from 8.7699 to 16.7958 percentage points across six templates on one project at one price.", "The chart prints four decimal places and the table one, so the offset changes with the rounding.", "The gap changes sign between a regime that adds capex back and one that does not."]'::jsonb, 1, 'The gap grows with government share of net revenue itself, so Ghana - Deepwater''s 16.7958 carried across to Nigeria - PIA (2021), where it is 8.7699, overstates the chart badly.'::text),
      ('advanced', 'module', 'm03-the-capex-sweep'::text, 1, 'What multipliers does the capex sweep hand back with its points?', '["Seven labels, 0.8 through 1.4, the eighth being unreachable in floating point.", "Nine labels from 0.7 to 1.5, the multipliers the published capex cases are run at.", "Eight labels: 0.8, 0.9, 1.0, 1.1, 1.2, 1.3, 1.4 and 1.5.", "Six labels, one per template."]'::jsonb, 2, 'The multipliers are written from a step count, as 8 plus the step number over 10, so the last is exactly 1.5. The loop they replaced accumulated 0.1, arrived at 1.5000000000000004 and stopped at 1.4.'::text, 'What multipliers does the capex sweep hand back with its points?', '["Seven labels, 0.8 through 1.4, the eighth being unreachable in floating point.", "Nine labels from 0.7 to 1.5, the multipliers the published capex cases are run at.", "Eight labels: 0.8, 0.9, 1.0, 1.1, 1.2, 1.3, 1.4 and 1.5.", "Six labels, one per template."]'::jsonb, 2, 'The multipliers are written from a step count, as 8 plus the step number over 10, so the last is exactly 1.5 and the last swept point equals a direct call at 1.5.'::text),
      ('advanced', 'module', 'm03-the-capex-sweep'::text, 2, 'Until the 2026-09-15 repair the capex axis was labelled to a multiplier of 1.5 and its last tick read 1.4. What had ended the loop early?', '["Accumulating 0.1 in binary floating point arrives at 1.5000000000000004, which is greater than 1.5.", "The engine refused a multiplier above 1.4 because no cost recovery limit can absorb a larger overrun.", "The eighth point returned a negative NPV for one regime, so the sweep dropped it.", "The label came from the loop bound and the points from a step count."]'::jsonb, 0, 'The point was never unreachable. Nigeria - PIA (2021) holds 58.5739 million USD of contractor NPV at a multiplier of 1.5 against 79.1811 at 1.4, and that value now arrives as a swept point rather than a direct call.'::text, 'A capex sweep written as a loop that adds 0.1 to a multiplier starting at 0.8, while it stays at or below 1.5, returns seven points and its last reads 1.4. What ends that loop early?', '["Accumulating 0.1 in binary floating point arrives at 1.5000000000000004, which is greater than 1.5.", "A refusal by the engine of any multiplier above 1.4, because no cost recovery limit can absorb a larger overrun.", "Its eighth point returned a negative NPV for one regime, so the sweep dropped it.", "The label came from the loop bound and the points from a step count."]'::jsonb, 0, 'The engine sweeps a fixed grid of eight multipliers, so Nigeria - PIA (2021) returns 255.8175 million USD of contractor NPV at 1.5 as a swept point, against 291.8238 at 1.4.'::text),
      ('advanced', 'module', 'm03-the-capex-sweep'::text, 8, 'The nine published capex cases are named capex_0.7_pia_default to capex_1.5_pia_default. How do they relate to the sweep the chart draws?', '["They are the swept points themselves, published one case per label on the chart''s axis.", "They are the same regime as the chart over a shifted range, the Nigeria - PIA (2021) template under the name the Designer gives it.", "They are the oracle''s own sweep rather than the engine''s, published so that the two can be compared point by point.", "A different range on a different regime."]'::jsonb, 3, 'The published set runs the Designer''s default regime, id 1, at multipliers of 0.7 to 1.5, returning 169.7176 million USD of NPV at 1.0 where the template returns 154.8286, and the chart sweeps 0.8 to 1.5 on the six templates.'::text, 'The nine published capex cases are named capex_0.7_pia_default to capex_1.5_pia_default. How do they relate to the sweep the chart draws?', '["Identical to the swept points, published one case per label on the chart''s axis.", "They are the same regime as the chart over a shifted range, the Nigeria - PIA (2021) template under the name the Designer gives it.", "The oracle''s own sweep rather than the engine''s, published so that the two can be compared point by point.", "A different range on a different regime."]'::jsonb, 3, 'The published set runs the Designer''s sample PSC regime, id 1, at multipliers of 0.7 to 1.5, returning 169.7176 million USD of NPV at 1.0 where the template returns 432.0925, and the chart sweeps 0.8 to 1.5 on the six templates.'::text),
      ('advanced', 'module', 'm03-the-capex-sweep'::text, 11, 'On the default project the two steepest climbers give up the least contractor NPV and the two regressive templates give up the most. Why is that agreement not a coincidence?', '["The two verdicts are computed by the same reduce over the same array, so they cannot disagree.", "A regime taking a rising share of the upside absorbs a share of the downside too, so the contractor''s NPV moves less when capital cost rises.", "Both sweeps hold the other variable at its base case, which forces the two rankings to match row for row, so a regime placed third by climb is placed third by loss as well.", "The price climb is an input to the capex loss, which is why the two orderings track one another so closely."]'::jsonb, 1, 'Angola - Deepwater PSC climbs 19.6873 percentage points and gives up 88.6123 million USD while USA - Gulf of Mexico climbs -17.2498 and gives up 267.7301, and the orders agree in tendency and not row for row.'::text, 'On the default project the two steepest climbers give up the least contractor NPV and the two most regressive templates give up the most. Why is that agreement not a coincidence?', '["The two verdicts are computed by the same reduce over the same array, so they cannot disagree.", "A regime taking a rising share of the upside absorbs a share of the downside too, so the contractor''s NPV moves less when capital cost rises.", "Both sweeps hold the other variable at its base case, which forces the two rankings to match row for row, so a regime placed third by climb is placed third by loss as well.", "The price climb is an input to the capex loss, which is why the two orderings track one another so closely."]'::jsonb, 1, 'Angola - Deepwater PSC climbs 19.6873 percentage points and gives up 88.6123 million USD while USA - Gulf of Mexico climbs -17.2498 and gives up 267.7301, and the orders agree in tendency and not row for row.'::text),
      ('advanced', 'module', 'm04-the-insights'::text, 1, 'On `cmp_all_templates_default_project` four of the six templates pay back in year 3. How does the payback verdict report that?', '["It names the first of them in summary order, which is the highest NPV regime, and says nothing of the other three.", "It names all four of them, in summary order, against year 4 for Angola - Deepwater PSC.", "It is omitted, because a four way tie at the top cannot be ranked and an unsupportable claim is dropped.", "It names whichever of them crosses zero cumulative contractor net cash flow earliest inside year 3, the engine interpolating within the year to separate a tie."]'::jsonb, 1, 'Nigeria - PIA (2021) also pays back in year 4 and is not named, because the closing clause reports one regime at the slowest year. Naming every regime tied at the fastest year is the 2026-09-15 repair; the retired rule named the first of them, which was the NPV winner at 397.0445 million USD.'::text, 'On `cmp_all_templates_default_project` five of the six templates pay back in year 3. How does the payback verdict report that?', '["It names the first of them in summary order, which is the highest NPV regime, and says nothing of the other four.", "It names all five of them, in summary order, against year 4 for Angola - Deepwater PSC.", "It is omitted, because a five way tie at the top cannot be ranked and an unsupportable claim is dropped.", "It names whichever of them crosses zero cumulative contractor net cash flow earliest inside year 3, the engine interpolating within the year to separate a tie."]'::jsonb, 1, 'Nigeria - PIA (2021) leads the sort at 432.0925 million USD and is named first, and Angola - Deepwater PSC is the one regime at the slowest year. A verdict naming only the first tied regime would repeat the NPV ranking under another label.'::text),
      ('advanced', 'module', 'm04-the-insights'::text, 5, 'An earlier build called Nigeria - PIA (2021) the most progressive on `cmp_never_recovers`, rising 0.0 percentage points. What does the price verdict return there now, and why?', '["It declines to rank, because every point is undefined and so no swept price gives every regime a government take within 0 to 100 percent.", "It still names Nigeria - PIA (2021), since two null endpoints subtract to a climb of zero that ranks like any other.", "It names Angola - Deepwater PSC, the regime that collected the most, because the take column breaks a tie in the climbs.", "It is omitted entirely, as it is for a single regime, because the verdict needs at least two regimes whose series carry usable points before it will rank anything."]'::jsonb, 0, 'Lifetime contractor net cash flow of -16279.9099 million USD outweighs a government cash flow of 1431.0440, profit is not positive at any swept price, and the sentence says no regime is economic at any swept price from 40 to 120 USD per bbl.'::text, 'Every price series on `cmp_never_recovers` comes back null, flagged undefined, at each of the nine prices. How does the price verdict read there, and on what grounds?', '["It declines to rank, because every point is undefined and so no swept price gives every regime a government take within 0 to 100 percent.", "It names Nigeria - PIA (2021), since two null endpoints subtract to a climb of zero that ranks like any other.", "It names Angola - Deepwater PSC, the regime that collected the most, because the take column breaks a tie in the climbs.", "It is omitted entirely, as it is for a single regime, because the verdict needs at least two regimes whose series carry usable points before it will rank anything."]'::jsonb, 0, 'Under Nigeria - PIA (2021) lifetime contractor net cash flow of -15870.1271 million USD outweighs a government cash flow of 1021.2611, profit is not positive at any swept price, and the sentence says no regime is economic at any swept price from 40 to 120 USD per bbl.'::text),
      ('advanced', 'module', 'm04-the-insights'::text, 6, 'The Insights tab once called the second ranked regime the one that maximises government revenue. What does the second row of `cmp_all_templates_default_project` actually collect?', '["1339.2784 million USD, because government cash flow descending is the summary''s secondary sort once contractor NPV has ordered the rows.", "758.7514 million USD, the largest of the six, which is why the old sentence looked right on this project.", "764.5528 million USD, while the largest take on that comparison is 1339.2784 million USD and belongs to the regime in sixth place.", "1263.7523 million USD, for Angola - Deepwater PSC, the regime the take column puts second."]'::jsonb, 2, 'The sort carries no information about take, and on this project the take column runs the other way, from 758.7514 at rank 1 to 1339.2784 at rank 6.'::text, 'A reader takes the second ranked regime to be the one that maximises government revenue. What does the second row of `cmp_all_templates_default_project` actually collect?', '["1316.6067 million USD, because government cash flow descending is the summary''s secondary sort once contractor NPV has ordered the rows.", "764.5528 million USD, the largest of the six, which is why the reading looks right on this project.", "758.7514 million USD, while the largest take on that comparison is 1316.6067 million USD and belongs to the regime in sixth place.", "1263.7523 million USD, for Angola - Deepwater PSC, the regime the take column puts second."]'::jsonb, 2, 'The sort carries no information about take, and on this project the take column runs the other way, from 687.4682 at rank 1 to 1316.6067 at rank 6.'::text),
      ('advanced', 'module', 'm04-the-insights'::text, 11, 'On ODIDI the price verdict calls Brazil - Concession the most progressive, rising 7.5 percentage points. What does winning on that number say about the field?', '["Brazil - Concession is a progressive regime, a property of its four instruments that the sweep has now measured on a second field.", "The climb is small because the sweep scales oil only, and ODIDI carries gas at 40 Mscf/d and NGL at 900 bbl/d that never move.", "Half the field is going the other way: only Ghana - Deepwater at 1.9971 and Nigeria - PIA (2021) at 0.1968 climb beside it, and the other three fall.", "Seven percentage points is the smallest climb the verdict will report, below which the sentence is omitted for want of separation."]'::jsonb, 2, 'The three falling climbs run as far down as -37.6994 for USA - Gulf of Mexico, so the winner leads a field on which half the regimes hand the state a shrinking fraction as price rises.'::text, 'On ODIDI the price verdict calls Brazil - Concession the most progressive, rising 7.5 percentage points. What does winning on that number say about the field?', '["Brazil - Concession is a progressive regime, a property of its four instruments that the sweep has now measured on a second field.", "The climb is small because the sweep scales oil only, and ODIDI carries gas at 40 Mscf/d and NGL at 900 bbl/d that never move.", "Most of the field is going the other way: only Ghana - Deepwater at 1.9971 climbs beside it, and the other four fall.", "Seven percentage points is the smallest climb the verdict will report, below which the sentence is omitted for want of separation."]'::jsonb, 2, 'The four falling climbs run from -6.0087 for Nigeria - PIA (2021) down to -37.6994 for USA - Gulf of Mexico, so the winner leads a field on which four of six regimes hand the state a shrinking fraction as price rises.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 1, 'Nigeria - PIA (2021) on the default project reads 59.6432 as government share of net revenue in the summary table and 76.7282 as government take on the price sweep at 70 USD per bbl. What separates the two?', '["The summary is computed on discounted cash flows at 10 percent while the sweep totals the same ledger undiscounted, so the two answer the same question at different dates.", "The sweep re-ran the comparison at a higher oil price than the deck''s own, so 76.7282 belongs to a later point of the nine, not the base case.", "The summary adds total capex back into the contractor side of the denominator and the sweep does not, on the same cash flows over the same 25 years.", "The summary counts royalty inside government cash flow and the sweep counts only profit oil and tax, which is why the sweep reads the higher of the two."]'::jsonb, 2, 'Both come out of one call to `runFiscalComparison` an earlier build gave them one label, and 17.0850 percentage points separate them.'::text, 'Nigeria - PIA (2021) on the default project reads 30.6156 as government share of net revenue in the summary table and 39.3855 as government take on the price sweep at 70 USD per bbl. What separates the two?', '["The summary is computed on discounted cash flows at 10 percent while the sweep totals the same ledger undiscounted, so the two answer the same question at different dates.", "The sweep re-ran the comparison at a higher oil price than the deck''s own, so 39.3855 belongs to a later point of the nine and describes another case.", "The summary adds total capex back into the contractor side of the denominator and the sweep does not, on the same cash flows over the same 25 years.", "The summary counts royalty inside government cash flow and the sweep counts only profit oil and tax, which is why the sweep reads the higher of the two."]'::jsonb, 2, 'Both come out of one call to `runFiscalComparison`, and 8.7699 percentage points separate them.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 2, 'A reader proposes to translate between government take and government share of net revenue with a fixed offset, because the chart runs about ten points above the table. Why does that fail?', '["The gap is not fixed: on one comparison at one price it runs from 9.6793 percentage points for Generic Royalty/Tax to 17.0850 for Nigeria - PIA (2021), and it grows with the share itself.", "The gap changes with the swept price, so an offset taken at 70 USD per bbl is wrong at every other one of the nine points.", "The offset is stable in percentage points and unstable in money, so it can be carried between rates but never between takes.", "The two rates are computed from different ledgers, so no arithmetic relation between them exists to be approximated by an offset."]'::jsonb, 0, 'Government take is government share of net revenue times 1.286453 on this project, so the gap is proportional to the share: Ghana - Deepwater shows 16.7958 where Generic Royalty/Tax shows 9.6793.'::text, 'A reader proposes to translate between government take and government share of net revenue with a fixed offset, because the chart runs about ten points above the table. Why does that fail?', '["The gap is proportional to the share: here government take is the share times 1.286453, so a larger share carries a larger gap.", "The gap changes with the swept price, so an offset taken at 70 USD per bbl is wrong at every other one of the nine points.", "The offset is stable in percentage points and unstable in money, so it can be carried between rates but never between takes.", "The two rates are computed from different ledgers, so no arithmetic relation between them exists to be approximated by an offset."]'::jsonb, 0, 'Revenue less opex and capex do not depend on the regime, so the factor is one number for the whole comparison: Ghana - Deepwater''s share of 58.6335 becomes a take of 75.4293, while Nigeria - PIA (2021) goes from 30.6156 to 39.3855.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 5, 'Until the 2026-09-15 repair the capex sweep was a loop from a multiplier of 0.8 to 1.5 in steps of 0.1 that returned seven points. What ended it early, and what replaced it?', '["The engine capped the sweep at seven points to hold the comparison inside its time budget, and the cap was later raised to eight.", "The eighth point was skipped because a multiplier of 1.5 makes the contractor NPV negative for several templates, and the axis was rescaled instead.", "The accumulating multiplier reached 1.5000000000000004, which fails the test that it be at most 1.5, and an integer step count replaced the accumulation.", "The loop tested the rounded label rather than the accumulator, so a label of 1.5 was never produced, and the label is now read from the loop bound."]'::jsonb, 2, 'The engine returns the labels 0.8, 0.9, 1.0, 1.1, 1.2, 1.3, 1.4 and 1.5, and the last swept value equals the engine called directly at 1.5 on every regime.'::text, 'The capex sweep''s axis runs from a multiplier of 0.8 to 1.5. What confirms that the sweep''s last point is really the 1.5 point?', '["The chart''s last tick label reads 1.5, and a label is written from the same multiplier the point was computed at.", "The loss the resilience verdict quotes is larger than the last step alone, which can only happen when the range is complete.", "The last swept point equals the engine called directly at a multiplier of 1.5, on every regime, to the last printed digit.", "The sweep returns as many points as the published capex cases, nine, so the grid and the golden describe one range."]'::jsonb, 2, 'On the default project Nigeria - PIA (2021) returns 255.8175 million USD at the last swept point and 255.8175 when the engine is called directly at 1.5; the grid is `CAPEX_SWEEP_MULTIPLIERS`, eight points written from a step count.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 8, 'The nine published capex cases run multipliers of 0.7 to 1.5 and return NPVs from 220.1703 down to 41.2671 million USD. Which regime do they run?', '["The Designer''s own default regime, the one the price cases also use, which is not the Nigeria - PIA (2021) template despite sharing a country with it.", "The Nigeria - PIA (2021) template, which is why the case at a multiplier of 1.0 returns the same NPV as that template''s summary row.", "All six templates at once, with the case reporting the best contractor NPV of the six at each multiplier.", "The Brazil - Concession template, the regime whose resource rent tax makes a capex sweep worth publishing at all."]'::jsonb, 0, 'Two ranges live in one engine: the sweep visits 0.8 to 1.5 on the six templates and the published cases 0.7 to 1.5 on the Designer''s own regime, where payback slips from year 3 to year 6.'::text, 'The nine published capex cases run multipliers of 0.7 to 1.5 and return NPVs from 220.1703 down to 41.2671 million USD. Which regime do they run?', '["The Designer''s sample PSC regime, the one the price cases also use, which is not the Nigeria - PIA (2021) template despite the country in its engine name.", "The Nigeria - PIA (2021) template, which is why the case at a multiplier of 1.0 returns the same NPV as that template''s summary row on the default project, 432.0925 million USD.", "All six templates at once, with the case reporting the best contractor NPV of the six at each multiplier, which is why its NPV falls more slowly than any one template''s.", "The Brazil - Concession template, the regime whose resource rent tax makes a capex sweep worth publishing at all, since its uplifted pool is the one quantity a capex multiplier scales."]'::jsonb, 0, 'Two ranges live in one engine: the sweep visits 0.8 to 1.5 on the six templates and the published cases 0.7 to 1.5 on the Designer''s sample PSC regime, where payback slips from year 3 to year 6.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 10, 'On flows of -1 in year 1 and 2000 in year 2 the retired bisection reported 102400 percent. What does `calculateIRR` return now?', '["102400 percent still, the top of a doubling bracket that the band from -99 to 1000 percent does not change.", "Null, with the status above-clamp and `irrRootAboveBand` true, because the only root is 199900 percent.", "199900.0000 percent, the true root, which the widened search now reaches.", "1000.0000 percent, the top of the band, reported as a clamp in the way the screening engine reports its own."]'::jsonb, 1, 'The NPV at 102400 percent is 0.0009, small, positive and not zero, so the retired value was the edge of a search and never a root.'::text, 'On flows of -1 in year 1 and 2000 in year 2 the NPV at 102400 percent is 0.0009. What does `calculateIRR` return?', '["102400 percent, the rate at which the NPV first falls below a thousandth of a million USD on these flows.", "Null, with the status above-clamp and `irrRootAboveBand` true, because the only root is 199900 percent.", "199900.0000 percent, the true root, which the widened search now reaches.", "1000.0000 percent, the top of the band, reported as a clamp in the way the screening engine reports its own."]'::jsonb, 1, 'The NPV at 102400 percent is 0.0009, small, positive and above zero, so 102400 is no root; the only root, 199900 percent, lies above the band.'::text),
      ('advanced', 'module', 'm05-numbers-to-distrust'::text, 11, 'Two solvers in this package once reported suspiciously round rates, 102400 percent and 1000 percent. What is the tell a reader should carry?', '["Size rather than roundness, since no real project returns a rate in the thousands of percent and any such value is the edge of a search.", "A rate quoted to four decimal places, which is the format the bisection uses and the Newton iteration does not.", "An IRR reported beside a negative NPV, which is the only combination that a bracket return can produce in either engine.", "Roundness rather than size, because both numbers were the edge of a search."]'::jsonb, 3, 'On the published `capex_multiplier_0_7` case 1095.4783 percent is a real root and 102400 never was one, and the engine now returns null with a status rather than either.'::text, 'A rate of exactly 102400 percent or exactly 1000 percent appears where an IRR should be. What is the tell a reader should carry?', '["Size rather than roundness, since no real project returns a rate in the thousands of percent and any such value is the edge of a search.", "A rate quoted to four decimal places, which is the format the bisection uses and the Newton iteration does not.", "An IRR reported beside a negative NPV, which is the only combination that a bracket return can produce in either engine.", "Roundness rather than size, because both numbers were the edge of a search."]'::jsonb, 3, 'On the published `capex_multiplier_0_7` case 1095.4783 percent is a real root and 102400 is no root at all; the engine returns null with a status rather than either, and a round figure is the mark of a search edge.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 4, 'The ODIDI summary is headed by Brazil - Concession at -5.8662 million USD. What does rank 1 mean there?', '["Best on the sort''s two keys, contractor NPV first and payback year second, which is what puts a year 6 regime at the head of the table.", "Break even, since a value that small sits inside the precision the summary reports.", "Least bad, since all six ODIDI NPVs at 12 percent are negative, down to -58.1813 million USD.", "Best for the contractor and best for the government at once, because on ODIDI the take column runs opposite to the NPV column."]'::jsonb, 2, 'The verdict names it best for the contractor at -5.9 million USD, and the sentence is correct while the project is still a loss.'::text, 'The ODIDI summary is headed by Nigeria - PIA (2021) at 1.7389 million USD. What does rank 1 mean there?', '["Best on the sort''s two keys, contractor NPV first and payback year second, which is what puts a year 7 regime at the head of the table.", "Break even, since a value that small sits inside the precision the summary reports.", "The only contractor NPV of the six that clears 12 percent, and a thin one, while the rest run down to -58.1813 million USD.", "Best for the contractor and best for the government at once, because on ODIDI the take column runs opposite to the NPV column."]'::jsonb, 2, 'The verdict names it best for the contractor at 1.7 million USD, and it is the one regime whose NPV is positive at that rate; the other five are losses at 12 percent.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 5, 'On ODIDI which regime collects the most for the government, and where does it sit in the summary?', '["Angola - Deepwater PSC, 316.7898 million USD, at rank 6.", "Nigeria - PIA (2021), 312.9610 million USD, at rank 5, the highest take on the field and the reason it ranks below the concessions.", "Generic Royalty/Tax, 242.1194 million USD, at rank 2, which is the row the sort puts next to the contractor''s own best.", "Brazil - Concession, 232.9950 million USD, at rank 1, since the regime that leaves the contractor most also runs the largest revenue base."]'::jsonb, 0, 'The summary is sorted by contractor NPV descending and by nothing else, so the take column has to be read from the take column.'::text, 'On ODIDI which regime collects the most for the government, and where does it sit in the summary?', '["Angola - Deepwater PSC, 316.7898 million USD, at rank 6.", "Nigeria - PIA (2021), 196.0260 million USD, at rank 1, the highest take on the field and the reason it heads the summary.", "Generic Royalty/Tax, 242.1194 million USD, at rank 3, the middle of the table where a balanced regime would be expected to sit.", "Brazil - Concession, 232.9950 million USD, at rank 2, since the regime that leaves the contractor most also runs the largest revenue base."]'::jsonb, 0, 'The summary is sorted by contractor NPV descending and by nothing else, so the take column has to be read from the take column.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 6, 'On ODIDI, Ghana - Deepwater reads a government share of net revenue of 36.5071 at rank 3 and USA - Gulf of Mexico reads 32.8219 at rank 4. What does that show?', '["That the two rows were computed at different discount rates, since the summary discounts each regime at the rate its template carries.", "That government share of net revenue does not follow the sort either.", "That the column shows government take on those two rows, which is the definition that has no capex added back.", "That the sort has a secondary key on government share of net revenue ascending, which only shows itself when two NPVs are close together."]'::jsonb, 1, 'The ratio is government cash flow over government cash flow plus contractor take with capex added back, both totals undiscounted, while the sort key is discounted at 12 percent.'::text, 'On ODIDI, Ghana - Deepwater reads a government share of net revenue of 36.5071 at rank 4 and USA - Gulf of Mexico reads 32.8219 at rank 5. What does that show?', '["That the two rows were computed at different discount rates, since the summary discounts each regime at the rate its template carries.", "That government share of net revenue does not follow the sort either.", "That the column shows government take on those two rows, which is the definition that has no capex added back.", "That the sort has a secondary key on government share of net revenue ascending, which only shows itself when two NPVs are close together."]'::jsonb, 1, 'The ratio is government cash flow over government cash flow plus contractor take with capex added back, both totals undiscounted, while the sort key is discounted at 12 percent.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 7, 'A regime in this sandbox is four fields. Which are they?', '["The royalty, the discount rate, the profit split and the tax block, since the rate is what turns a regime''s timing into a value.", "The royalty, the cost recovery limit, the capex schedule and the tax block, because when capital is spent decides what is recovered.", "The royalty, flat or sliding on the oil price; the cost recovery limit as a percent of revenue after royalty; the profit split, flat or tiered on the R factor; and the tax block.", "The royalty, the cost recovery limit, the profit split and the production forecast, which is what makes one regime harsher than another."]'::jsonb, 2, 'The tax block holds corporate income tax, the resource rent tax, a minimum tax and an `rrtUpliftPct` that defaults to 20 when the field is absent.'::text, 'A regime in this sandbox is four fields. Which are they?', '["The royalty, the discount rate, the profit split and the tax block, since the rate is what turns a regime''s timing into a value and each template carries the rate it was written for.", "The royalty, the cost recovery limit, the capex schedule and the tax block, because when capital is spent decides what is recovered, and a regime that moved capex to year 3 would recover it later.", "The royalty, flat, sliding on price or the PIA 2021 royalty; the cost recovery limit and its base; the profit split, flat, tiered on the R factor or by cumulative production; and the tax block.", "The royalty, the cost recovery limit, the profit split and the production forecast, which is what makes one regime harsher than another, since a regime that shortens the forecast shortens the government''s collection too."]'::jsonb, 2, 'The tax block holds corporate income tax, the resource rent tax, a minimum tax and an `rrtUpliftPct` that defaults to 20 when the field is absent.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 12, 'Under the PIA template on ODIDI, cumulative contractor net cash flow first turns positive in year 7 at 6.1264 million USD, against capex of 420.0000. What does the payback year say?', '["That the contractor had recovered the whole 420.0000 million USD of capex, and 6.1264 million USD of profit on top of it, by the end of year 7 discounted at 12 percent.", "That the project is viable, since a payback inside the first third of a 25 year life is what the summary''s payback column is there to show.", "Only that the cumulative crossed zero in that year, on a field where the cumulative later peaks at 138.3627 and falls back to 113.0236 million USD by year 25.", "That year 7 is the best year of the ledger, because it is the year the contractor''s own cash position stopped falling and began to rise."]'::jsonb, 2, 'Payback is undiscounted and is a first crossing rather than a maximum, and the same ledger returns an NPV of -43.7842 million USD at 12 percent.'::text, 'Under the PIA template on ODIDI, cumulative contractor net cash flow first turns positive in year 7 at 43.8352 million USD, against capex of 420.0000. What does the payback year say?', '["That the contractor had recovered the whole 420.0000 million USD of capex, and 43.8352 million USD of profit on top of it, by the end of year 7 discounted at 12 percent.", "The project is viable, since a payback inside the first third of a 25 year life is what the summary''s payback column is there to show.", "Only that the cumulative crossed zero in that year, on a field where the cumulative later peaks at 250.9149 and falls back to 229.9586 million USD by year 25.", "Year 7 is the best year of the ledger, because it is the year the contractor''s own cash position stopped falling and began to rise."]'::jsonb, 2, 'Payback is undiscounted and is a first crossing rather than a maximum, and the same ledger returns an NPV of only 1.7389 million USD at 12 percent.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 13, 'ODIDI returns contractor net cash flow of 113.0236 million USD under the PIA template and 148.3166 under USA - Gulf of Mexico, on one revenue of 1236.1983. Where did the difference go?', '["To the government, whose take is 312.9610 against 277.6679 million USD on the same two runs.", "To cost recovery, which is 779.6254 under the PIA template against 785.9313 and is the larger of the two differences between the runs.", "To opex and capex, which the PIA template charges against the contractor''s line while a concession charges them against profit oil.", "To the discount rate, since the two regimes return different NPVs at 12 percent."]'::jsonb, 0, 'Opex plus capex is the same 810.2137 million USD in both ledgers, so nothing but the four instruments separates the two contractor totals.'::text, 'ODIDI returns contractor net cash flow of 229.9586 million USD under the PIA template and 148.3166 under USA - Gulf of Mexico, on one revenue of 1236.1983. Where did the difference come from?', '["From the government, whose take is 196.0260 against 277.6679 million USD on the same two runs.", "From cost recovery, which is 777.9904 under the PIA template against 785.9313 and is the larger of the two differences between the runs.", "From opex and capex, which the PIA template charges against profit oil while a concession charges them against the contractor''s line.", "From the discount rate, since the two regimes return different NPVs at 12 percent."]'::jsonb, 0, 'Opex plus capex is the same 810.2137 million USD in both ledgers, so nothing but the four instruments separates the two contractor totals.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 14, 'Under the PIA template the ODIDI royalty runs 5.7145 million USD in year 5 and 9.3986 in year 6, on gross revenue of 76.1939 and 93.9859. What moved?', '["The R factor passed 1.0 in year 6, and the royalty rate in this template is keyed to the R factor tranche the year selects.", "Cost recovery closed the pool in year 6, and royalty is charged on revenue after cost recovery once the pool has cleared.", "Production rose in year 6, lifting revenue and royalty together.", "The deck stepped at year 6 and carried the oil price over a sliding royalty threshold."]'::jsonb, 3, 'The royalty tier changing inside a project''s life is the one thing none of the published template cases do, and it is why the ODIDI royalty column moves for two reasons.'::text, 'Under the PIA template the ODIDI royalty runs 3.8097 million USD in year 5 and 4.9025 in year 6, on gross revenue of 76.1939 and 93.9859. What moved?', '["The R factor passed 1.0 in year 6, and the royalty rate in this template is keyed to the R factor tranche the year selects.", "Cost recovery closed the pool in year 6, and royalty is charged on revenue after cost recovery once the pool has cleared.", "Production rose in year 6, lifting revenue and royalty together.", "The deck stepped at year 6 and lifted the oil price above that year''s low benchmark, so the royalty by price began."]'::jsonb, 3, 'ODIDI produces well under 50,000 bopd, so the production royalty stays at 5 percent; at 65 USD/bbl against a year 6 low benchmark of 62.1700 the royalty by price adds 0.002276. The benchmarks are the Regulations (2021) base, the engine default, and no published template case shows that start inside a field''s life.'::text),
      ('advanced', 'module', 'm06-the-expert-reading'::text, 15, 'Nigeria - PIA (2021) has a capex resilience of 118.3685 million USD and also of 216.2236. Which is right?', '["The first, because the second was measured on a field whose NPVs are all negative, and a loss between two negative numbers is not a resilience figure.", "Both, each for its own field: 118.3685 is the loss on the default project and 216.2236 the loss on ODIDI, over the same eight multipliers.", "The second, because a figure quoted on the Designer''s own defaults understates what an overrun costs on a real field.", "Neither, because a loss between two endpoints is not a resilience figure at all when the curve between them is not a straight line."]'::jsonb, 1, 'A number without its definition is not a number, which is the same lesson as one regime reading 59.6432 as government share of net revenue and 76.7282 as government take.'::text, 'Nigeria - PIA (2021) has a capex resilience of 243.6525 million USD and also of 244.8503. Which is right?', '["The first, because the second was measured on a field where five of the six NPVs are negative, and a loss between two negative numbers is not a resilience figure.", "Both, each for its own field: 243.6525 is the loss on the default project and 244.8503 the loss on ODIDI, over the same eight multipliers.", "The second, because a figure quoted on the Designer''s own defaults understates what an overrun costs on a real field.", "Neither, because a loss between two endpoints is not a resilience figure at all when the curve between them is not a straight line."]'::jsonb, 1, 'A number without its definition is not a number, which is the same lesson as one regime reading 30.6156 as government share of net revenue and 39.3855 as government take.'::text)
    ) as t(tier, scope, module_key, ord, old_prompt, old_options, old_answer, old_expl, new_prompt, new_options, new_answer, new_expl)
  loop
    select case
             when q.prompt = r.old_prompt and q.options = r.old_options and q.answer_index = r.old_answer and q.explanation is not distinct from r.old_expl then 'old'
             when q.prompt = r.new_prompt and q.options = r.new_options and q.answer_index = r.new_answer and q.explanation is not distinct from r.new_expl then 'new'
             else 'other' end
      into v_state
      from public.academy_quiz_questions q
     where q.app_slug = 'fiscal' and q.active and q.tier = r.tier and q.scope = r.scope
       and q.module_key is not distinct from r.module_key and q.ord = r.ord;
    get diagnostics v_count = row_count;
    if v_count <> 1 then
      raise exception 'ec7 pia recut refused: fiscal/%/%/%/ord % matched % active rows, expected 1', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord, v_count;
    end if;
    if v_state = 'other' then
      raise exception 'ec7 pia recut refused: fiscal/%/%/%/ord % carries neither its published text nor the recut text', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord;
    end if;
    if v_state = 'old' then
      update public.academy_quiz_questions q
         set prompt = r.new_prompt, options = r.new_options, answer_index = r.new_answer, explanation = r.new_expl
       where q.app_slug = 'fiscal' and q.active and q.tier = r.tier and q.scope = r.scope
         and q.module_key is not distinct from r.module_key and q.ord = r.ord;
      get diagnostics v_count = row_count;
      if v_count <> 1 then
        raise exception 'ec7 pia recut refused: fiscal/%/%/%/ord % update touched % rows', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord, v_count;
      end if;
      v_updated := v_updated + 1;
    else
      v_done := v_done + 1;
    end if;
  end loop;

  for r in select t as tier from unnest(array['beginner', 'intermediate', 'advanced']) t loop
    select count(*) into v_count from public.academy_quiz_questions where app_slug = 'fiscal' and active and tier = r.tier;
    if v_count <> 132 then
      raise exception 'ec7 pia recut refused: fiscal/% holds % active questions, expected 132', r.tier, v_count;
    end if;
  end loop;
  select count(*) into v_count from public.academy_quiz_questions where app_slug = 'fiscal' and active;
  if v_count <> 396 then
    raise exception 'ec7 pia recut refused: fiscal holds % active questions, expected 396', v_count;
  end if;
  raise notice 'ec7 pia recut: fiscal questions, % updated, % already recut, of 110', v_updated, v_done;
end $$;

-- ----------------------------------------------------------------------------
-- 2. cashflow intermediate capstone: prompt only (copy rule), fields unchanged.
-- ----------------------------------------------------------------------------
do $$
declare
  v_state text;
  v_count integer;
begin
  select case
           when c.title = 'Put a time value on the ledger'
            and c.dataset = 'the IKPOTO joint venture ledger valued in time: two discounting conventions, a real basis, and the price at which the value is nought'
            and c.cert_tier = 'professional'
            and c.prompt = 'Six values for the same IKPOTO joint venture run as the Associate capstone (identical rows and terms), now valued at a 9 percent NOMINAL discount rate on the REAL basis with 2.5 percent inflation, valuation year equal to the 2031 base year, nothing sunk. Report: (1) the NPV under END-YEAR discounting; (2) the NPV under MID-YEAR discounting; (3) the INTERNAL RATE OF RETURN in percent; (4) the DISCOUNTED PAYBACK in years; (5) the DPI (NPV over the present value of capex); and (6) the BREAKEVEN flat oil price in USD/bbl at which the end-year NPV is nought. Traps. The applied rate is the Fisher REAL rate, (1.09 / 1.025) - 1, not 9 percent, and the flows it discounts are the DEFLATED flows; discounting the nominal flows at 9 percent gives the same NPV, which is the point, but discounting the deflated flows at 9 percent does not. Mid-year adds one half to every exponent including the first. IRR is solved on the NOMINAL flows and does not depend on the basis. DPI here is NPV over PV(capex), which is the profitability index MINUS ONE; report the engine''s definition. The breakeven is the FLAT price with the 1.5 percent escalator still applied from it, found by bisection to the cent.'
            and (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements(c.fields) with ordinality as e(f, n)) = (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements('[{"key": "jv_npv_real_usd", "tol": 1, "unit": "USD", "label": "NPV, real basis, end year", "expected": 20656337.21686185}, {"key": "jv_npv_mid_year_usd", "tol": 1, "unit": "USD", "label": "NPV, real basis, mid year", "expected": 20030970.834339857}, {"key": "jv_irr_pct", "tol": 0.0001, "unit": "percent", "label": "Internal rate of return", "expected": 23.719272956750835}, {"key": "jv_discounted_payback_years", "tol": 0.0001, "unit": "years", "label": "Discounted payback", "expected": 3.9696530221864026}, {"key": "jv_dpi", "tol": 1e-06, "unit": "ratio", "label": "Discounted profitability index", "expected": 0.17502648916650668}, {"key": "jv_breakeven_oil_price_usd_bbl", "tol": 0.005, "unit": "USD/bbl", "label": "Breakeven oil price", "expected": 66.10100889205933}]'::jsonb) with ordinality as e(f, n)) then 'old'
           when c.title = 'Put a time value on the ledger'
            and c.dataset = 'the IKPOTO joint venture ledger valued in time: two discounting conventions, a real basis, and the price at which the value is nought'
            and c.cert_tier = 'professional'
            and c.prompt = 'Six values for the same IKPOTO joint venture run as the Associate capstone (identical rows and terms), now valued at a 9 percent NOMINAL discount rate on the REAL basis with 2.5 percent inflation, valuation year equal to the 2031 base year, nothing sunk. Report: (1) the NPV under END-YEAR discounting; (2) the NPV under MID-YEAR discounting; (3) the INTERNAL RATE OF RETURN in percent; (4) the DISCOUNTED PAYBACK in years; (5) the DPI (NPV over the present value of capex); and (6) the BREAKEVEN flat oil price in USD/bbl at which the end-year NPV is nought. Traps. The applied rate is the Fisher REAL rate, (1.09 / 1.025) - 1, which is below 9 percent, and the flows it discounts are the DEFLATED flows; discounting the nominal flows at 9 percent gives the same NPV, which is the point, but discounting the deflated flows at 9 percent does not. Mid-year adds one half to every exponent including the first. IRR is solved on the NOMINAL flows and does not depend on the basis. DPI here is NPV over PV(capex), which is the profitability index MINUS ONE; report the engine''s definition. The breakeven is the FLAT price with the 1.5 percent escalator still applied from it, found by bisection to the cent.'
            and (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements(c.fields) with ordinality as e(f, n)) = (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements('[{"key": "jv_npv_real_usd", "tol": 1, "unit": "USD", "label": "NPV, real basis, end year", "expected": 20656337.21686185}, {"key": "jv_npv_mid_year_usd", "tol": 1, "unit": "USD", "label": "NPV, real basis, mid year", "expected": 20030970.834339857}, {"key": "jv_irr_pct", "tol": 0.0001, "unit": "percent", "label": "Internal rate of return", "expected": 23.719272956750835}, {"key": "jv_discounted_payback_years", "tol": 0.0001, "unit": "years", "label": "Discounted payback", "expected": 3.9696530221864026}, {"key": "jv_dpi", "tol": 1e-06, "unit": "ratio", "label": "Discounted profitability index", "expected": 0.17502648916650668}, {"key": "jv_breakeven_oil_price_usd_bbl", "tol": 0.005, "unit": "USD/bbl", "label": "Breakeven oil price", "expected": 66.10100889205933}]'::jsonb) with ordinality as e(f, n)) then 'new'
           else 'other' end
    into v_state
    from public.academy_capstones c where c.app_slug = 'cashflow' and c.tier = 'intermediate' and c.active;
  get diagnostics v_count = row_count;
  if v_count <> 1 then
    raise exception 'ec7 pia recut refused: cashflow/intermediate has % active capstones, expected 1', v_count;
  end if;
  if v_state = 'other' then
    raise exception 'ec7 pia recut refused: the cashflow/intermediate capstone carries neither its published title, dataset, prompt and fields nor the recut ones';
  end if;
  if v_state = 'old' then
    update public.academy_capstones
       set dataset = 'the IKPOTO joint venture ledger valued in time: two discounting conventions, a real basis, and the price at which the value is nought',
           prompt = 'Six values for the same IKPOTO joint venture run as the Associate capstone (identical rows and terms), now valued at a 9 percent NOMINAL discount rate on the REAL basis with 2.5 percent inflation, valuation year equal to the 2031 base year, nothing sunk. Report: (1) the NPV under END-YEAR discounting; (2) the NPV under MID-YEAR discounting; (3) the INTERNAL RATE OF RETURN in percent; (4) the DISCOUNTED PAYBACK in years; (5) the DPI (NPV over the present value of capex); and (6) the BREAKEVEN flat oil price in USD/bbl at which the end-year NPV is nought. Traps. The applied rate is the Fisher REAL rate, (1.09 / 1.025) - 1, which is below 9 percent, and the flows it discounts are the DEFLATED flows; discounting the nominal flows at 9 percent gives the same NPV, which is the point, but discounting the deflated flows at 9 percent does not. Mid-year adds one half to every exponent including the first. IRR is solved on the NOMINAL flows and does not depend on the basis. DPI here is NPV over PV(capex), which is the profitability index MINUS ONE; report the engine''s definition. The breakeven is the FLAT price with the 1.5 percent escalator still applied from it, found by bisection to the cent.',
           fields = '[{"key": "jv_npv_real_usd", "tol": 1, "unit": "USD", "label": "NPV, real basis, end year", "expected": 20656337.21686185}, {"key": "jv_npv_mid_year_usd", "tol": 1, "unit": "USD", "label": "NPV, real basis, mid year", "expected": 20030970.834339857}, {"key": "jv_irr_pct", "tol": 0.0001, "unit": "percent", "label": "Internal rate of return", "expected": 23.719272956750835}, {"key": "jv_discounted_payback_years", "tol": 0.0001, "unit": "years", "label": "Discounted payback", "expected": 3.9696530221864026}, {"key": "jv_dpi", "tol": 1e-06, "unit": "ratio", "label": "Discounted profitability index", "expected": 0.17502648916650668}, {"key": "jv_breakeven_oil_price_usd_bbl", "tol": 0.005, "unit": "USD/bbl", "label": "Breakeven oil price", "expected": 66.10100889205933}]'::jsonb
     where app_slug = 'cashflow' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then
      raise exception 'ec7 pia recut refused: the cashflow/intermediate capstone update touched % rows', v_count;
    end if;
  end if;
  select jsonb_array_length(fields) into v_count from public.academy_capstones where app_slug = 'cashflow' and tier = 'intermediate' and active;
  if v_count <> 6 then
    raise exception 'ec7 pia recut refused: the cashflow/intermediate capstone holds % fields, expected 6', v_count;
  end if;
  raise notice 'ec7 pia recut: cashflow/intermediate capstone %', case when v_state = 'old' then 'recut' else 'already recut' end;
end $$;

-- ----------------------------------------------------------------------------
-- 2. cashflow advanced capstone: dataset, prompt and six graded fields.
-- ----------------------------------------------------------------------------
do $$
declare
  v_state text;
  v_count integer;
begin
  select case
           when c.title = 'Run the same rows through the cascade'
            and c.dataset = 'the IKPOTO rows under the Petroleum Industry Act: a new shallow-water lease crossing the allowance cap in its second year, a CPR limit that defers cost, the 2025 framework, and a terminal abandonment'
            and c.cert_tier = 'expert'
            and c.prompt = 'Six values for IKPOTO run under the PIA with the SAME production, capex and opex rows and the same prices, escalators, inflation, base year and 9 percent nominal rate as the Professional capstone. Fiscal terms: shallow water at 45 m, PML, NEW lease, not a pre-2021 marginal field, 80 percent working interest, no HCT override, CIT 30 percent, TET 2.5 percent, NDDC 3 percent of opex, no prior-year opex, capital allowance over FOUR years, CPR limit 35 percent, production allowance 8 USD/bbl for a new lease capped at 20 percent of the oil price, framework override auto, prior cumulative production 97,612,500 bbl, and a 40,000,000 USD post-tax abandonment lump sum in the final modeled year. Report: (1) the PRICE ROYALTY in 2032; (2) the allowance-ELIGIBLE barrels in 2032; (3) the cost DEFERRED by the CPR cap at the end of 2031; (4) the TOTAL hydrocarbon tax; (5) the DEVELOPMENT LEVY in 2033; and (6) the NPV on the real basis. Traps. The 2031 base year is at or past 2026, so the framework is NTA 2025: the development levy at 4 percent replaces TET and TET is nought in every year. The royalty tiers, the price-royalty anchors (escalating 2 percent a year from 2021) and the allowance volume cap are FIELD-LEVEL and are applied before the 80 percent share; the cap is 100 MMbbl for shallow water, the prior production counts against it, and 2031 crosses it, so field 2 is the room the cap leaves for 2032 once every earlier barrel is counted. The CPR cap is 35 percent of GROSS revenue and cost claims opex first, then the capital allowance; what does not fit is field 3 and carries. HCT is charged on liquids only at the shallow-water PML rate; field 4 sums it over every year. The abandonment is post-tax and moves field 6 but no tax line.'
            and (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements(c.fields) with ordinality as e(f, n)) = (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements('[{"key": "pia_2032_price_royalty_usd", "tol": 1, "unit": "USD", "label": "Price royalty in 2032", "expected": 951123.1830656304}, {"key": "pia_2032_prod_alw_eligible_bbl", "tol": 1, "unit": "bbl", "label": "Allowance-eligible barrels in 2032", "expected": 787500}, {"key": "pia_2031_cpr_deferred_usd", "tol": 1, "unit": "USD", "label": "Cost deferred by the CPR cap in 2031", "expected": 3942400}, {"key": "pia_total_hct_usd", "tol": 1, "unit": "USD", "label": "Total hydrocarbon tax", "expected": 51541932.563462615}, {"key": "pia_2033_dev_levy_usd", "tol": 1, "unit": "USD", "label": "Development levy in 2033", "expected": 1331296.587088759}, {"key": "pia_npv_real_usd", "tol": 1, "unit": "USD", "label": "NPV under the PIA, real basis", "expected": -46086957.32549152}]'::jsonb) with ordinality as e(f, n)) then 'old'
           when c.title = 'Run the same rows through the cascade'
            and c.dataset = 'the IKPOTO rows under the Petroleum Industry Act and the Nigeria Tax Act 2025: a new shallow-water lease crossing the allowance cap in its second year, a cost price ratio carry that grows, and a terminal abandonment'
            and c.cert_tier = 'expert'
            and c.prompt = 'Six values for IKPOTO run under the PIA with the SAME production, capex and opex rows and the same prices, escalators, inflation, base year and 9 percent nominal rate as the Professional capstone. Fiscal terms: shallow water at 45 m, PML, a NEW lease granted out of new acreage, no pre-2021 marginal field, 80 percent working interest, no HCT override, CIT 30 percent, no prior-year opex, framework override auto, prior cumulative production 97,612,500 bbl, none of the gas used in-country, so all of it pays the 5 percent gas royalty, and a 40,000,000 USD post-tax abandonment lump sum in the final modeled year. Every other term is the engine''s default, which follows the texts: NDDC at 3 percent of the total annual budget, the capital allowance over the five years the texts fix, the cost price ratio limit of 65 percent, the Sixth Schedule production allowance, and the tertiary education tax at its statutory rate. The texts do not say which hydrocarbon tax rate a PML granted out of new acreage onshore or in shallow water pays, so this capstone states 30 percent as a stated reading; none of the six values depends on it. The royalty by price is read on the Petroleum Royalty Regulations 2022 base, benchmarks of 50, 100 and 150 USD/bbl at 2021 levels, which is the engine''s default. Report: (1) the PRICE ROYALTY in 2032; (2) the PRODUCTION ALLOWANCE in 2032; (3) the NDDC levy in 2031; (4) the TOTAL companies income tax; (5) the DEVELOPMENT LEVY in 2033; and (6) the cost the CPR cap carries out of 2035 into 2036. Traps. The framework is chosen for each year of assessment, and every year from 2031 to 2036 is 2026 or later, so each is an NTA 2025 year: the development levy at 4 percent applies and TET is nought in every year. The production royalty tranches, the price-royalty benchmarks and the allowance volume cap are read at FIELD level and applied before the 80 percent share. The cap is 100 MMbbl for shallow water and the prior production counts against it; the barrels below the cap earn the new-lease allowance and the barrels after it still earn the lower after-cap allowance, each limited to 20 percent of the oil price. NDDC is charged on opex plus capex at your share and is deducted in the hydrocarbon tax base. The CPR cap is 65 percent of crude plus condensate revenue and limits only the costs claimed against the hydrocarbon tax; shared costs enter it at the crude-plus-condensate share, and what does not fit carries to the next year and is claimed there within that year''s cap. Companies income tax deducts the full opex, royalties, HCDT, NDDC and its own capital allowance, and the CPR cap never touches it. The abandonment is post-tax and moves no tax line.'
            and (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements(c.fields) with ordinality as e(f, n)) = (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements('[{"key": "pia_2032_price_royalty_usd", "tol": 1, "unit": "USD", "label": "Price royalty in 2032", "expected": 951174.9189189179}, {"key": "pia_2032_production_allowance_usd", "tol": 1, "unit": "USD", "label": "Production allowance in 2032", "expected": 6616000}, {"key": "pia_2031_nddc_usd", "tol": 1, "unit": "USD", "label": "NDDC levy in 2031", "expected": 3336000}, {"key": "pia_total_cit_usd", "tol": 1, "unit": "USD", "label": "Total companies income tax", "expected": 39056834.778322995}, {"key": "pia_2033_dev_levy_usd", "tol": 1, "unit": "USD", "label": "Development levy in 2033", "expected": 1804107.954906831}, {"key": "pia_2035_cpr_deferred_usd", "tol": 1, "unit": "USD", "label": "Cost the CPR cap carries out of 2035", "expected": 18128786.5348819}]'::jsonb) with ordinality as e(f, n)) then 'new'
           else 'other' end
    into v_state
    from public.academy_capstones c where c.app_slug = 'cashflow' and c.tier = 'advanced' and c.active;
  get diagnostics v_count = row_count;
  if v_count <> 1 then
    raise exception 'ec7 pia recut refused: cashflow/advanced has % active capstones, expected 1', v_count;
  end if;
  if v_state = 'other' then
    raise exception 'ec7 pia recut refused: the cashflow/advanced capstone carries neither its published title, dataset, prompt and fields nor the recut ones';
  end if;
  if v_state = 'old' then
    update public.academy_capstones
       set dataset = 'the IKPOTO rows under the Petroleum Industry Act and the Nigeria Tax Act 2025: a new shallow-water lease crossing the allowance cap in its second year, a cost price ratio carry that grows, and a terminal abandonment',
           prompt = 'Six values for IKPOTO run under the PIA with the SAME production, capex and opex rows and the same prices, escalators, inflation, base year and 9 percent nominal rate as the Professional capstone. Fiscal terms: shallow water at 45 m, PML, a NEW lease granted out of new acreage, no pre-2021 marginal field, 80 percent working interest, no HCT override, CIT 30 percent, no prior-year opex, framework override auto, prior cumulative production 97,612,500 bbl, none of the gas used in-country, so all of it pays the 5 percent gas royalty, and a 40,000,000 USD post-tax abandonment lump sum in the final modeled year. Every other term is the engine''s default, which follows the texts: NDDC at 3 percent of the total annual budget, the capital allowance over the five years the texts fix, the cost price ratio limit of 65 percent, the Sixth Schedule production allowance, and the tertiary education tax at its statutory rate. The texts do not say which hydrocarbon tax rate a PML granted out of new acreage onshore or in shallow water pays, so this capstone states 30 percent as a stated reading; none of the six values depends on it. The royalty by price is read on the Petroleum Royalty Regulations 2022 base, benchmarks of 50, 100 and 150 USD/bbl at 2021 levels, which is the engine''s default. Report: (1) the PRICE ROYALTY in 2032; (2) the PRODUCTION ALLOWANCE in 2032; (3) the NDDC levy in 2031; (4) the TOTAL companies income tax; (5) the DEVELOPMENT LEVY in 2033; and (6) the cost the CPR cap carries out of 2035 into 2036. Traps. The framework is chosen for each year of assessment, and every year from 2031 to 2036 is 2026 or later, so each is an NTA 2025 year: the development levy at 4 percent applies and TET is nought in every year. The production royalty tranches, the price-royalty benchmarks and the allowance volume cap are read at FIELD level and applied before the 80 percent share. The cap is 100 MMbbl for shallow water and the prior production counts against it; the barrels below the cap earn the new-lease allowance and the barrels after it still earn the lower after-cap allowance, each limited to 20 percent of the oil price. NDDC is charged on opex plus capex at your share and is deducted in the hydrocarbon tax base. The CPR cap is 65 percent of crude plus condensate revenue and limits only the costs claimed against the hydrocarbon tax; shared costs enter it at the crude-plus-condensate share, and what does not fit carries to the next year and is claimed there within that year''s cap. Companies income tax deducts the full opex, royalties, HCDT, NDDC and its own capital allowance, and the CPR cap never touches it. The abandonment is post-tax and moves no tax line.',
           fields = '[{"key": "pia_2032_price_royalty_usd", "tol": 1, "unit": "USD", "label": "Price royalty in 2032", "expected": 951174.9189189179}, {"key": "pia_2032_production_allowance_usd", "tol": 1, "unit": "USD", "label": "Production allowance in 2032", "expected": 6616000}, {"key": "pia_2031_nddc_usd", "tol": 1, "unit": "USD", "label": "NDDC levy in 2031", "expected": 3336000}, {"key": "pia_total_cit_usd", "tol": 1, "unit": "USD", "label": "Total companies income tax", "expected": 39056834.778322995}, {"key": "pia_2033_dev_levy_usd", "tol": 1, "unit": "USD", "label": "Development levy in 2033", "expected": 1804107.954906831}, {"key": "pia_2035_cpr_deferred_usd", "tol": 1, "unit": "USD", "label": "Cost the CPR cap carries out of 2035", "expected": 18128786.5348819}]'::jsonb
     where app_slug = 'cashflow' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then
      raise exception 'ec7 pia recut refused: the cashflow/advanced capstone update touched % rows', v_count;
    end if;
  end if;
  select jsonb_array_length(fields) into v_count from public.academy_capstones where app_slug = 'cashflow' and tier = 'advanced' and active;
  if v_count <> 6 then
    raise exception 'ec7 pia recut refused: the cashflow/advanced capstone holds % fields, expected 6', v_count;
  end if;
  raise notice 'ec7 pia recut: cashflow/advanced capstone %', case when v_state = 'old' then 'recut' else 'already recut' end;
end $$;

-- ----------------------------------------------------------------------------
-- 2. fiscal advanced capstone: prompt only (title, dataset and fields unchanged).
-- ----------------------------------------------------------------------------
do $$
declare
  v_prompt text;
  v_before text;
  v_after  text;
  v_count  integer;
begin
  select c.prompt, md5(c.title) || ':' || md5(c.dataset) || ':' || c.cert_tier || ':' || (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements(c.fields) with ordinality as e(f, n)) into v_prompt, v_before from public.academy_capstones c where c.app_slug = 'fiscal' and c.tier = 'advanced' and c.active;
  get diagnostics v_count = row_count;
  if v_count <> 1 then
    raise exception 'ec7 pia recut refused: fiscal/advanced has % active capstones, expected 1', v_count;
  end if;
  if v_prompt is distinct from 'Six values from ONE call of runFiscalComparison on the SAME URUAN project as the other two tiers, with BOTH regimes in it: the concession (royalty flat 14 percent, cost recovery limit 100 percent, profit split flat 100 percent, corporate income tax 28 percent, no resource rent tax, no minimum tax) and the production sharing contract (royalty sliding, 6 percent from 0 USD/bbl and 9.5 percent from 60 USD/bbl; cost recovery limit 65 percent; profit split 65 percent from R 1.0, 45 percent from R 1.4, 32 percent from R 1.65; corporate income tax 32 percent, no resource rent tax, no minimum tax). Report: (1) the NPV of the regime the summary puts FIRST, in millions of USD; (2) the PRODUCTION SHARING CONTRACT''s government share of net revenue (undiscounted) as the SUMMARY TABLE reports it, the engine''s effectiveTaxRate key, in percent; (3) the PRODUCTION SHARING CONTRACT''s government take (undiscounted) on the PRICE SWEEP at 60 USD/bbl, in percent; (4) the contractor NPV the production sharing contract gives up over the LAST TENTH of the capex sweep, the swept point at a multiplier of 1.4 minus the swept point at 1.5, in millions of USD; (5) the loss over the WHOLE swept range, the first swept point minus the engine called directly at a capex multiplier of 1.5, in millions of USD; and (6) the CONCESSION''s climb across the price sweep, last point minus first point, in percentage points. Traps. Fields 2 and 3 are two different ratios of the same government cash flow and they are NOT the same number: government share of net revenue adds TOTAL CAPEX back into contractor take and government take does not, and field 3 is also read at a swept price. Fields 4 and 5 are two different spans of one sweep, so one is much smaller than the other: field 4 is the last step alone and field 5 is the whole range. The sweep now reaches the multiplier its axis is labelled with, so its last swept point and a direct call at 1.5 are the same number; count the points the engine returns before subtracting, and read the last two. Field 6 is negative on this project and that is the answer, not an error: the concession''s line falls as the price rises, and field 6 is the endpoint difference asked for whatever state each endpoint carries. The summary is sorted by contractor NPV descending, so field 1 is a lookup only after the sort. The price sweep reaches each price by a multiplier on the FIRST deck point''s oil price, and that multiplier scales OIL ONLY.' and v_prompt is distinct from 'Six values from ONE call of runFiscalComparison on the SAME URUAN project as the other two tiers, with BOTH regimes in it: the concession (royalty flat 14 percent, cost recovery limit 100 percent, profit split flat 100 percent, corporate income tax 28 percent, no resource rent tax, no minimum tax) and the production sharing contract (royalty sliding, 6 percent from 0 USD/bbl and 9.5 percent from 60 USD/bbl; cost recovery limit 65 percent; profit split 65 percent from R 1.0, 45 percent from R 1.4, 32 percent from R 1.65; corporate income tax 32 percent, no resource rent tax, no minimum tax). Report: (1) the NPV of the regime the summary puts FIRST, in millions of USD; (2) the PRODUCTION SHARING CONTRACT''s government share of net revenue (undiscounted) as the SUMMARY TABLE reports it, the engine''s effectiveTaxRate key, in percent; (3) the PRODUCTION SHARING CONTRACT''s government take (undiscounted) on the PRICE SWEEP at 60 USD/bbl, in percent; (4) the contractor NPV the production sharing contract gives up over the LAST TENTH of the capex sweep, the swept point at a multiplier of 1.4 minus the swept point at 1.5, in millions of USD; (5) the loss over the WHOLE swept range, the first swept point minus the engine called directly at a capex multiplier of 1.5, in millions of USD; and (6) the CONCESSION''s climb across the price sweep, last point minus first point, in percentage points. Traps. Fields 2 and 3 are two different ratios of the same government cash flow and they are NOT the same number: government share of net revenue adds TOTAL CAPEX back into contractor take and government take does not, and field 3 is also read at a swept price. Fields 4 and 5 are two different spans of one sweep, so one is much smaller than the other: field 4 is the last step alone and field 5 is the whole range. The sweep returns eight points, 0.8 to 1.5, so its last swept point and a direct call at 1.5 are the same number; count the points the engine returns before subtracting, and read the last two. Field 6 is negative on this project, and that negative number is the answer: the concession''s line falls as the price rises, and field 6 is the endpoint difference asked for whatever state each endpoint carries. The summary is sorted by contractor NPV descending, so field 1 is a lookup only after the sort. The price sweep reaches each price by a multiplier on the FIRST deck point''s oil price, and that multiplier scales OIL ONLY.' then
    raise exception 'ec7 pia recut refused: the fiscal/advanced prompt is neither its published text nor the recut text';
  end if;
  if v_prompt = 'Six values from ONE call of runFiscalComparison on the SAME URUAN project as the other two tiers, with BOTH regimes in it: the concession (royalty flat 14 percent, cost recovery limit 100 percent, profit split flat 100 percent, corporate income tax 28 percent, no resource rent tax, no minimum tax) and the production sharing contract (royalty sliding, 6 percent from 0 USD/bbl and 9.5 percent from 60 USD/bbl; cost recovery limit 65 percent; profit split 65 percent from R 1.0, 45 percent from R 1.4, 32 percent from R 1.65; corporate income tax 32 percent, no resource rent tax, no minimum tax). Report: (1) the NPV of the regime the summary puts FIRST, in millions of USD; (2) the PRODUCTION SHARING CONTRACT''s government share of net revenue (undiscounted) as the SUMMARY TABLE reports it, the engine''s effectiveTaxRate key, in percent; (3) the PRODUCTION SHARING CONTRACT''s government take (undiscounted) on the PRICE SWEEP at 60 USD/bbl, in percent; (4) the contractor NPV the production sharing contract gives up over the LAST TENTH of the capex sweep, the swept point at a multiplier of 1.4 minus the swept point at 1.5, in millions of USD; (5) the loss over the WHOLE swept range, the first swept point minus the engine called directly at a capex multiplier of 1.5, in millions of USD; and (6) the CONCESSION''s climb across the price sweep, last point minus first point, in percentage points. Traps. Fields 2 and 3 are two different ratios of the same government cash flow and they are NOT the same number: government share of net revenue adds TOTAL CAPEX back into contractor take and government take does not, and field 3 is also read at a swept price. Fields 4 and 5 are two different spans of one sweep, so one is much smaller than the other: field 4 is the last step alone and field 5 is the whole range. The sweep now reaches the multiplier its axis is labelled with, so its last swept point and a direct call at 1.5 are the same number; count the points the engine returns before subtracting, and read the last two. Field 6 is negative on this project and that is the answer, not an error: the concession''s line falls as the price rises, and field 6 is the endpoint difference asked for whatever state each endpoint carries. The summary is sorted by contractor NPV descending, so field 1 is a lookup only after the sort. The price sweep reaches each price by a multiplier on the FIRST deck point''s oil price, and that multiplier scales OIL ONLY.' then
    update public.academy_capstones set prompt = 'Six values from ONE call of runFiscalComparison on the SAME URUAN project as the other two tiers, with BOTH regimes in it: the concession (royalty flat 14 percent, cost recovery limit 100 percent, profit split flat 100 percent, corporate income tax 28 percent, no resource rent tax, no minimum tax) and the production sharing contract (royalty sliding, 6 percent from 0 USD/bbl and 9.5 percent from 60 USD/bbl; cost recovery limit 65 percent; profit split 65 percent from R 1.0, 45 percent from R 1.4, 32 percent from R 1.65; corporate income tax 32 percent, no resource rent tax, no minimum tax). Report: (1) the NPV of the regime the summary puts FIRST, in millions of USD; (2) the PRODUCTION SHARING CONTRACT''s government share of net revenue (undiscounted) as the SUMMARY TABLE reports it, the engine''s effectiveTaxRate key, in percent; (3) the PRODUCTION SHARING CONTRACT''s government take (undiscounted) on the PRICE SWEEP at 60 USD/bbl, in percent; (4) the contractor NPV the production sharing contract gives up over the LAST TENTH of the capex sweep, the swept point at a multiplier of 1.4 minus the swept point at 1.5, in millions of USD; (5) the loss over the WHOLE swept range, the first swept point minus the engine called directly at a capex multiplier of 1.5, in millions of USD; and (6) the CONCESSION''s climb across the price sweep, last point minus first point, in percentage points. Traps. Fields 2 and 3 are two different ratios of the same government cash flow and they are NOT the same number: government share of net revenue adds TOTAL CAPEX back into contractor take and government take does not, and field 3 is also read at a swept price. Fields 4 and 5 are two different spans of one sweep, so one is much smaller than the other: field 4 is the last step alone and field 5 is the whole range. The sweep returns eight points, 0.8 to 1.5, so its last swept point and a direct call at 1.5 are the same number; count the points the engine returns before subtracting, and read the last two. Field 6 is negative on this project, and that negative number is the answer: the concession''s line falls as the price rises, and field 6 is the endpoint difference asked for whatever state each endpoint carries. The summary is sorted by contractor NPV descending, so field 1 is a lookup only after the sort. The price sweep reaches each price by a multiplier on the FIRST deck point''s oil price, and that multiplier scales OIL ONLY.' where app_slug = 'fiscal' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then
      raise exception 'ec7 pia recut refused: the fiscal/advanced prompt update touched % rows', v_count;
    end if;
    raise notice 'ec7 pia recut: fiscal/advanced capstone prompt recut';
  else
    raise notice 'ec7 pia recut: fiscal/advanced capstone prompt already recut';
  end if;
  select md5(c.title) || ':' || md5(c.dataset) || ':' || c.cert_tier || ':' || (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements(c.fields) with ordinality as e(f, n)) into v_after from public.academy_capstones c where c.app_slug = 'fiscal' and c.tier = 'advanced' and c.active;
  if v_after is distinct from v_before then
    raise exception 'ec7 pia recut refused: the fiscal/advanced title, dataset, cert tier or fields moved';
  end if;
end $$;

-- ----------------------------------------------------------------------------
-- 3. fiscal beginner capstone: con_payback_year_cum_ncf_musd tolerance 0.001 -> 0.0003.
--    lead decision (PIA re-cut leak gate): the Nigeria - PIA (2021) template's year 2 royalty on the Designer's default project, 14.739655314252133, sat 0.000606 from the answer, inside the 0.001 band; at 0.0003 it is 2.02 bands clear. Expected value unchanged. Precedent: psc_y8_royalty_musd, 2026-09-13 recut.
-- ----------------------------------------------------------------------------
do $$
declare
  v_tol      float8;
  v_expected float8;
  v_n        integer;
  v_count    integer;
begin
  select count(*), max((f->>'tol')::float8), max((f->>'expected')::float8) into v_n, v_tol, v_expected
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'fiscal' and c.tier = 'beginner' and c.active and f->>'key' = 'con_payback_year_cum_ncf_musd';
  if v_n <> 1 then
    raise exception 'ec7 pia recut refused: fiscal/beginner has % fields keyed con_payback_year_cum_ncf_musd, expected 1', v_n;
  end if;
  if v_expected is distinct from 14.740261270763284::float8 then
    raise exception 'ec7 pia recut refused: fiscal/beginner.con_payback_year_cum_ncf_musd expects %, not the value this file was generated against', v_expected;
  end if;
  if v_tol not in (0.001::float8, 0.0003::float8) then
    raise exception 'ec7 pia recut refused: fiscal/beginner.con_payback_year_cum_ncf_musd carries tolerance %, neither the published nor the recut one', v_tol;
  end if;
  if v_tol = 0.001::float8 then
    update public.academy_capstones c
       set fields = (select jsonb_agg(case when e.f->>'key' = 'con_payback_year_cum_ncf_musd' then jsonb_set(e.f, '{tol}', to_jsonb(0.0003::float8)) else e.f end order by e.n)
                       from jsonb_array_elements(c.fields) with ordinality as e(f, n))
     where c.app_slug = 'fiscal' and c.tier = 'beginner' and c.active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then
      raise exception 'ec7 pia recut refused: fiscal/beginner tolerance update touched % rows', v_count;
    end if;
  end if;
  select count(*), max((f->>'tol')::float8) into v_n, v_tol
    from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
   where c.app_slug = 'fiscal' and c.tier = 'beginner' and c.active and f->>'key' = 'con_payback_year_cum_ncf_musd';
  if v_n <> 1 or v_tol <> 0.0003::float8 then
    raise exception 'ec7 pia recut refused: fiscal/beginner.con_payback_year_cum_ncf_musd reads back tolerance %', v_tol;
  end if;
  raise notice 'ec7 pia recut: fiscal tolerance in place';
end $$;

-- ----------------------------------------------------------------------------
-- 4. Closing assertions: 3 capstones of 6 fields per course, 18 fields each,
--    and the attempts and certifications untouched.
-- ----------------------------------------------------------------------------
do $$
declare
  v_count integer;
  v_c     text;
begin
  foreach v_c in array array['cashflow', 'fiscal'] loop
    select count(*) into v_count from public.academy_capstones where app_slug = v_c and active;
    if v_count <> 3 then
      raise exception 'ec7 pia recut refused: % has % active capstones, expected 3', v_c, v_count;
    end if;
    select count(*) into v_count from public.academy_capstones k, lateral jsonb_array_elements(k.fields) f where k.app_slug = v_c and k.active;
    if v_count <> 18 then
      raise exception 'ec7 pia recut refused: % capstones carry % graded fields, expected 18', v_c, v_count;
    end if;
  end loop;
  if current_setting('ec7.snapshot', true) is distinct from md5(coalesce((select string_agg(md5(a::text), ',' order by a.id) from public.academy_capstone_attempts a where a.app_slug in ('cashflow', 'fiscal')), '') || '#' || coalesce((select string_agg(md5(c::text), ',' order by md5(c::text)) from public.academy_certifications c where c.app_slug in ('cashflow', 'fiscal')), '')) then
    raise exception 'ec7 pia recut refused: a stored capstone attempt or certification of cashflow or fiscal changed';
  end if;
  raise notice 'ec7 pia recut: done; attempts and certifications untouched';
end $$;
